insert into public.content_versions (lesson_id, hash, body) values
  ($uxg$P01-U01-L01$uxg$, $uxg$5d14ca8b03c43e4a6931dfd5834f60784e3b932965c1fa43767bc3247cab50f3$uxg$, $uxg${"id":"P01-U01-L01","mode":"lesson","minutes":8,"title":{"en":"Every field costs something","ar":"لكل حقل ثمن"},"speaker":"hana","review_labels":{"MC-P01-001":{"en":"Ask for what the task needs now","ar":"اسأل عمّا تحتاجه المهمة الآن"},"MC-P01-002":{"en":"\"Might be useful later\" isn't a reason to ask","ar":"«قد يفيد لاحقًا» ليس سببًا للسؤال"},"MC-P01-005":{"en":"Many optional fields mean too many fields","ar":"كثرة الحقول الاختيارية تعني كثرة الحقول"},"MC-P01-026":{"en":"Shortest isn't the goal; essential is","ar":"الهدف ليس الأقصر؛ بل الضروري"},"MC-P01-027":{"en":"Say why you ask for personal details","ar":"وضّح لماذا تطلب المعلومات الشخصية"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Salma wants to try our gym","ar":"سلمى تريد تجربة نادينا"},"body":{"en":"Salma saw our offer of a free 3-day trial; my gym is near her work. She tapped \"Try it free\" on her phone during her lunch break.\n\nThis is the form she got.","ar":"رأت سلمى عرضنا لتجربة مجانية لمدة 3 أيام، فناديّ قريب من عملها. وضغطت «جرّبه مجانًا» على هاتفها في استراحة الغداء.\n\nوهذا هو النموذج الذي ظهر لها."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U01-01","part":"try","rules":["R12"],"value":{"en":"Try first. EAS framework (NN/g): asking for unnecessary information adds effort and can make people question your intentions. A national ID for a free trial is the clearest case.","ar":"جرّب أولًا. إطار EAS (NN/g): طلب معلومات غير ضرورية يزيد الجهد وقد يجعل الناس يشكّون في نواياك. والرقم القومي لتجربة مجانية أوضح مثال."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Asking for unnecessary information increases user effort and can cause users to question your intentions."},"prompt":{"en":"The gym can remove one field today. Try each one. Which should go first?","ar":"يستطيع النادي حذف حقل واحد اليوم. جرّب كل واحد. أيّها يجب أن يُحذف أولًا؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]},"options":[{"id":"phone","text":{"en":"Remove the mobile number","ar":"احذف رقم الموبايل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"nid","text":{"en":"Remove the national ID number","ar":"احذف الرقم القومي"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"name","text":{"en":"Remove the full name","ar":"احذف الاسم الكامل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Gender","ar":"النوع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Home address","ar":"عنوان السكن"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}}],"answer":["nid"],"misconceptions":[{"id":"MC-P01-001","when":["phone","name"],"feedback":{"en":"The front desk needs to know who Salma is and how to reach her, so those fields earn their place. A national ID for a free 3-day trial is personal, and nothing explains why it's needed.","ar":"يحتاج الاستقبال أن يعرف من هي سلمى وكيف يتواصل معها، فهذان الحقلان لهما مكانهما. أما الرقم القومي لتجربة مجانية لثلاثة أيام فهو شخصي، ولا شيء يوضّح لماذا يُطلب."}}],"hints":[{"en":"Look at what the trial needs: Salma comes in, the gym greets her and can reach her.","ar":"انظر إلى ما تحتاجه التجربة: تأتي سلمى، فيرحّب بها الجيم ويستطيع التواصل معها."},{"en":"Which field does the trial never use, and is also the most personal?","ar":"أي حقل لا تستخدمه التجربة أبدًا، وهو أيضًا الأكثر خصوصية؟"}],"correct":{"en":"The national ID: personal, and the trial doesn't need it.","ar":"الرقم القومي: شخصي، والتجربة لا تحتاجه."},"explain":{"en":"Every field costs time. A personal question the task doesn't explain also costs trust, and people start to wonder what the data is really for.","ar":"كل حقل يكلّف وقتًا. والسؤال الشخصي الذي لا تبرّره المهمة يكلّف ثقة أيضًا، فيبدأ الناس في التساؤل عن الغرض الحقيقي من البيانات."}},{"id":"S03","type":"card","part":"concept","icons":["target","clock","none","idea"],"title":{"en":"A field is a question you make someone answer","ar":"الحقل سؤال تُلزم شخصًا بالإجابة عنه"},"body":{"en":"Each field costs the person time, effort and a little trust. Forms that feel quick get finished. For every field, ask:\n\n- **Is it essential?** If the task can't happen without it, keep it.\n- **Is it needed now?** If it can wait until later, ask later.\n- **Will anyone use it?** If there's no clear use for the answer, don't ask.\n- **Is it personal?** Then say why you're asking and how you'll use it.","ar":"كل حقل يكلّف الشخص وقتًا وجهدًا وقليلًا من الثقة. والنماذج التي تبدو سريعة تُكمَل. لكل حقل، اسأل:\n\n- **هل هو ضروري؟** إذا كانت المهمة لا تتم بدونه، فأبقِه.\n- **هل نحتاجه الآن؟** إذا كان يمكن أن ينتظر، فاسأل عنه لاحقًا.\n- **هل سيستخدمه أحد؟** إذا لم يكن للإجابة استخدام واضح، فلا تسأل.\n- **هل هو شخصي؟** فوضّح لماذا تسأل وكيف ستستخدمه."}},{"id":"S04","type":"tune","skill":"SK-P01-U01-02","part":"guided","rules":["R06","R15"],"value":{"en":"EAS framework (NN/g): not every question needs to be asked immediately. If it can wait, postpone it. Making questions optional still leaves them on the form.","ar":"إطار EAS (NN/g): ليس كل سؤال يجب أن يُطرح فورًا. إذا كان يمكن أن ينتظر، فأجّله. وجعل الأسئلة اختيارية يُبقيها في النموذج رغم ذلك."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"If it can wait, postpone it."},"scenario":{"en":"We do need Salma's national ID and date of birth, but only if she joins as a member after the trial.","ar":"نحتاج فعلًا الرقم القومي لسلمى وتاريخ ميلادها، لكن فقط إذا اشتركت كعضوة بعد التجربة."},"prompt":{"en":"Try each version of the trial form. Which one should ship?","ar":"جرّب كل نسخة من نموذج التجربة. أيّها يجب أن تُطلق؟"},"start":"optional","options":[{"id":"later","text":{"en":"Ask for them on the membership form, if she joins","ar":"اسأل عنهما في نموذج الاشتراك، إن اشتركت"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"},{"kind":"small","text":{"en":"Membership form, later: national ID, date of birth","ar":"نموذج الاشتراك، لاحقًا: الرقم القومي، تاريخ الميلاد"},"gap":"l"}]}},{"id":"optional","text":{"en":"Keep them on the trial form, marked optional","ar":"أبقِهما في نموذج التجربة، مع وسمهما بأنهما اختياريان"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth (optional)","ar":"تاريخ الميلاد (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number (optional)","ar":"الرقم القومي (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"now","text":{"en":"Keep them required on the trial form, so it's done once","ar":"أبقِهما إلزاميين في نموذج التجربة، لتنتهي منهما مرة واحدة"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}}],"answer":["later"],"misconceptions":[{"id":"MC-P01-005","when":["optional"],"feedback":{"en":"Optional fields are still there to read and wonder about, and many people fill them in anyway, just in case. If it can wait, move it.","ar":"الحقول الاختيارية ما زالت موجودة للقراءة والتفكير، وكثير من الناس يملؤونها على أي حال، احتياطًا. إذا كان يمكن أن ينتظر، فانقله."}},{"id":"MC-P01-001","when":["now"],"feedback":{"en":"Most trial visitors never become members, so they'd all give a national ID for nothing. Ask the people who join, when they join.","ar":"أغلب زوّار التجربة لا يصبحون أعضاء، فسيعطي كلهم رقمهم القومي بلا فائدة. اسأل من يشترك، حين يشترك."}}],"hints":[{"en":"When does the gym actually use the ID and the date of birth?","ar":"متى يستخدم الجيم الرقم القومي وتاريخ الميلاد فعلًا؟"},{"en":"If Salma never joins, will the gym ever need these two?","ar":"إذا لم تنضم سلمى أبدًا، هل سيحتاج الجيم هذين الحقلين؟"}],"correct":{"en":"Ask at the moment it's needed.","ar":"اسأل في اللحظة التي تحتاجه فيها."},"explain":{"en":"Moving a question to the right moment loses nothing. The people who join answer it then, and now they have a reason to.","ar":"نقل السؤال إلى اللحظة المناسبة لا يُضيّع شيئًا. من يشترك سيجيب عنه حينها، ولديه الآن سبب لذلك."},"speaker":"hana"},{"id":"S05","type":"tune","skill":"SK-P01-U01-02","part":"guided","rules":["R06","R15"],"value":{"en":"EAS framework (NN/g): start with the bare minimum needed at this stage, then gradually request more. Marketing's question can move after sign-up.","ar":"إطار EAS (NN/g): ابدأ بأقل ما تحتاجه في هذه المرحلة، ثم اطلب المزيد تدريجيًا. وسؤال التسويق يمكن أن ينتقل إلى ما بعد التسجيل."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Start by asking for the bare minimum needed at this stage, then gradually request more, to avoid overwhelming users upfront."},"scenario":{"en":"Our marketing team wants to keep \"How did you hear about us?\" as a required field on the trial form. They do use the answers to plan our ads.","ar":"يريد فريق التسويق عندنا إبقاء «كيف عرفت عنّا؟» حقلًا إلزاميًا في نموذج التجربة. وهم يستخدمون الإجابات فعلًا لتخطيط إعلاناتنا."},"prompt":{"en":"Try each option. Which one should ship?","ar":"جرّب كل خيار. أيّها يجب أن يُطلق؟"},"start":"keep","options":[{"id":"keep","text":{"en":"Keep it required on the form","ar":"أبقِه إلزاميًا في النموذج"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you hear about us?","ar":"كيف عرفت عنّا؟"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"}]}},{"id":"delete","text":{"en":"Delete it and tell marketing no","ar":"احذفه وارفض طلب التسويق"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Free 3-day trial","ar":"تجربة مجانية لمدة 3 أيام"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"},{"kind":"small","text":{"en":"Marketing gets no answers.","ar":"لا يحصل التسويق على أي إجابات."},"gap":"l"}]}},{"id":"after","text":{"en":"Ask it after she's signed up, as an optional one-tap question","ar":"اسأل عنه بعد أن تسجّل، كسؤال اختياري بضغطة واحدة"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"You're booked! See you tomorrow.","ar":"تمّ حجزك! نراك غدًا."}},{"kind":"meta","text":{"en":"One quick question, if you like: how did you hear about us?","ar":"سؤال سريع، إن أحببت: كيف عرفت عنّا؟"},"gap":"m"},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":{"en":"Friend","ar":"صديق"}},{"kind":"chip","text":{"en":"Social media","ar":"مواقع التواصل"}},{"kind":"chip","text":{"en":"Walked past","ar":"مررت بالمكان"}}]}]}}],"answer":["after"],"misconceptions":[{"id":"MC-P01-001","when":["keep"],"feedback":{"en":"The answer helps the gym, not Salma's sign-up. Required, it stands between her and her trial.","ar":"الإجابة تفيد النادي، لا تسجيل سلمى. وإذا كانت إلزامية، فهي تقف بينها وبين تجربتها."}},{"id":"MC-P01-002","when":["delete"],"feedback":{"en":"Marketing really uses the answer, so deleting it loses something. Ask it at a better moment instead.","ar":"التسويق يستخدم الإجابة فعلًا، فحذفها يُضيّع شيئًا. اسأل عنها في لحظة أفضل بدلًا من ذلك."}}],"hints":[{"en":"The answers are useful, but does the trial need them to happen?","ar":"الإجابات مفيدة، لكن هل تحتاجها التجربة لكي تتم؟"},{"en":"Can marketing still get the answer once Salma has signed up?","ar":"هل يمكن أن يحصل التسويق على الإجابة بعد أن تسجّل سلمى؟"}],"correct":{"en":"The minimum first, the extra question after.","ar":"الحد الأدنى أولًا، والسؤال الإضافي بعده."},"explain":{"en":"Salma's sign-up stays short, and marketing still gets answers from people who are happy to tap one.","ar":"يبقى تسجيل سلمى قصيرًا، ويحصل التسويق مع ذلك على إجابات من الناس الذين يسعدهم الضغط على واحدة."},"speaker":"hana"},{"id":"S06","type":"tune","skill":"SK-P01-U01-03","part":"guided","rules":["R06","R15"],"value":{"en":"EAS framework (NN/g): people are more likely to finish a form when they understand how their data will be used. Explain personal fields at the field.","ar":"إطار EAS (NN/g): يزيد احتمال إكمال الناس للنموذج حين يفهمون كيف ستُستخدم بياناتهم. وضّح سبب الحقول الشخصية عند الحقل نفسه."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Users will be more likely to complete the form when they understand how their data will be used."},"scenario":{"en":"Our trial form now asks only for Salma's name and mobile number. She hesitates at the mobile: she doesn't want sales calls.","ar":"نموذج التجربة عندنا يطلب الآن اسم سلمى ورقم موبايلها فقط. لكنها تتردّد عند الموبايل: فهي لا تريد مكالمات بيع."},"prompt":{"en":"Try each version of the mobile field. Which one should ship?","ar":"جرّب كل نسخة من حقل الموبايل. أيّها يجب أن يُطلق؟"},"start":"none","options":[{"id":"none","text":{"en":"Just the label","ar":"التسمية فقط"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":""}]}},{"id":"policy","text":{"en":"Add a link to the privacy policy at the bottom","ar":"أضف رابطًا لسياسة الخصوصية في الأسفل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":""},{"kind":"button","text":{"en":"Start my free trial","ar":"ابدأ تجربتي المجانية"},"gap":"m"},{"kind":"link","text":{"en":"Privacy policy","ar":"سياسة الخصوصية"},"gap":"s"}]}},{"id":"why","text":{"en":"Add a line that says what it's for","ar":"أضف سطرًا يوضّح الغرض منه"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"We'll text you once to confirm your visit. No marketing.","ar":"سنرسل لك رسالة واحدة لتأكيد زيارتك. بدون رسائل تسويقية."}}]}}],"answer":["why"],"misconceptions":[{"id":"MC-P01-027","when":["none"],"feedback":{"en":"Salma has to guess what the number is for, and her guess is sales calls. Tell her, right at the field.","ar":"على سلمى أن تخمّن الغرض من الرقم، وتخمينها هو مكالمات البيع. أخبرها، عند الحقل مباشرة."}},{"id":"MC-P01-027","when":["policy"],"feedback":{"en":"A policy link is useful, but few people open it at the moment they hesitate. One plain line at the field answers her worry.","ar":"رابط السياسة مفيد، لكن قليلين يفتحونه في لحظة التردّد. وسطر واضح واحد عند الحقل يجيب عن قلقها."}}],"hints":[{"en":"Salma's worry is about this one field. Where is she looking when she hesitates?","ar":"قلق سلمى يخصّ هذا الحقل وحده. أين تنظر عندما تتردّد؟"},{"en":"Will she open a policy page, or read a line next to the field?","ar":"هل ستفتح صفحة السياسة، أم ستقرأ سطرًا بجانب الحقل؟"}],"correct":{"en":"Say why, where the question is.","ar":"وضّح السبب، حيث يوجد السؤال."},"explain":{"en":"A short reason at the field turns a worrying question into a fair one. It also stops you asking for things you can't explain.","ar":"السبب القصير عند الحقل يحوّل السؤال المقلق إلى سؤال عادل. كما يمنعك من طلب أشياء لا تستطيع تبريرها."},"speaker":"hana"},{"id":"S07","type":"compare","skill":"SK-P01-U01-01","part":"contrast","speaker":"tarek","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S02 to S05: cutting is not the goal in itself. EAS (NN/g): forms should ask only for essential information. A form that drops an essential field is short and broken.","ar":"مقارنة مع الخطوات 2 إلى 5: الحذف ليس هدفًا في حدّ ذاته. EAS (NN/g): يجب أن تطلب النماذج المعلومات الضرورية فقط. والنموذج الذي يحذف حقلًا ضروريًا قصير ومعطّل."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Forms should only ask for essential information"},"scenario":{"en":"I manage a lunch delivery app. Tamer is ordering lunch to his office, and my team wants the checkout as short as possible.","ar":"أدير تطبيقًا لتوصيل الغداء. يطلب تامر غداءً إلى مكتبه، ويريد فريقي صفحة الدفع أقصر ما يمكن."},"prompt":{"en":"Which delivery form should ship?","ar":"أي نموذج توصيل يجب أن يُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the driver (optional)","ar":"ملاحظة للسائق (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},"answer":"b","reason":{"prompt":{"en":"Why is the longer form better here?","ar":"لماذا النموذج الأطول أفضل هنا؟"},"options":[{"id":"more","text":{"en":"More fields look more professional","ar":"الحقول الأكثر تبدو أكثر احترافية"}},{"id":"need","text":{"en":"The driver needs a way to reach Tamer when he arrives","ar":"يحتاج السائق طريقة للوصول إلى تامر حين يصل"}},{"id":"data","text":{"en":"The restaurant gets more data","ar":"يحصل المطعم على بيانات أكثر"}}],"answer":["need"],"misconceptions":[{"id":"MC-P01-026","when":["more","data"],"feedback":{"en":"Neither is a reason to ask. The phone stays because the delivery fails without it.","ar":"لا هذا ولا ذاك سبب للسؤال. يبقى الهاتف لأن التوصيل يفشل بدونه."}}]},"misconceptions":[{"id":"MC-P01-026","when":["a"],"feedback":{"en":"A is shorter, but the driver can't call Tamer from the lobby, and the lunch goes cold. Keep what the task needs.","ar":"A أقصر، لكن السائق لا يستطيع الاتصال بتامر من مدخل المبنى، فيبرد الغداء. أبقِ ما تحتاجه المهمة."}}],"hints":[{"en":"Picture the driver arriving at Tamer's office building. What does he need?","ar":"تخيّل السائق وهو يصل إلى مبنى مكتب تامر. ماذا يحتاج؟"},{"en":"Short is good only until something the delivery needs goes missing.","ar":"القِصر جيد فقط ما لم ينقص شيء يحتاجه التوصيل."}],"correct":{"en":"Essential, not shortest.","ar":"الضروري، لا الأقصر."},"explain":{"en":"Cut what the task doesn't use, and keep what it can't work without. The optional note stays because it's light and helps the driver.","ar":"احذف ما لا تستخدمه المهمة، وأبقِ ما لا تعمل بدونه. والملاحظة الاختيارية تبقى لأنها خفيفة وتساعد السائق."}},{"id":"S08","type":"tune","skill":"SK-P01-U01-01","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Forms usability (NN/g): first, eliminate as many optional fields as possible. A job title has no use in a lunch order, and a birthday belongs where people share extras.","ar":"حالة جديدة. سهولة استخدام النماذج (NN/g): أولًا، احذف أكبر عدد ممكن من الحقول الاختيارية. المسمّى الوظيفي لا فائدة له في طلب غداء، وعيد الميلاد مكانه حيث يشارك الناس الإضافات."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"First, eliminate as many optional fields as possible"},"scenario":{"en":"Our order form also asks Tamer for his job title, and his birthday \"for a gift\". Nothing in the delivery uses either one.","ar":"يسأل نموذج الطلب عندنا تامر أيضًا عن مسمّاه الوظيفي، وعن عيد ميلاده «لهدية». ولا شيء في التوصيل يستخدم أيًّا منهما."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Job title","ar":"المسمّى الوظيفي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your birthday, for a gift","ar":"عيد ميلادك، لهدية"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]},"options":[{"id":"optional","text":{"en":"Mark the job title and birthday as optional","ar":"اجعل المسمّى الوظيفي وعيد الميلاد اختياريين"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Job title (optional)","ar":"المسمّى الوظيفي (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your birthday, for a gift (optional)","ar":"عيد ميلادك، لهدية (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"profile","text":{"en":"Remove the job title; offer the birthday in his profile","ar":"احذف المسمّى الوظيفي؛ واعرض عيد الميلاد في ملفه الشخصي"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"},{"kind":"small","text":{"en":"Profile, any time: \"Add your birthday and get a gift\"","ar":"الملف الشخصي، في أي وقت: «أضف عيد ميلادك واحصل على هدية»"},"gap":"l"}]}},{"id":"bottom","text":{"en":"Move both below the Place order button","ar":"انقلهما أسفل زر «أكّد الطلب»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery details","ar":"تفاصيل التوصيل"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"},{"kind":"field","label":{"en":"Job title","ar":"المسمّى الوظيفي"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Your birthday, for a gift","ar":"عيد ميلادك، لهدية"},"text":"","gap":"s"}]}}],"answer":["profile"],"misconceptions":[{"id":"MC-P01-005","when":["optional"],"feedback":{"en":"Now the order has two optional questions nobody needs for lunch. Remove what has no use, and move the extra to where it fits.","ar":"الآن في الطلب سؤالان اختياريان لا يحتاجهما أحد للغداء. احذف ما لا فائدة له، وانقل الإضافة إلى المكان المناسب لها."}},{"id":"MC-P01-002","when":["bottom"],"feedback":{"en":"They're still on the order form, and now in a confusing place: is the order placed or not? Take them off the order.","ar":"ما زالا في نموذج الطلب، والآن في مكان مربك: هل تمّ الطلب أم لا؟ أخرِجهما من الطلب."}}],"hints":[{"en":"Does the delivery use either field? Ask the four questions from the lesson.","ar":"هل يستخدم التوصيل أيًّا من الحقلين؟ اطرح الأسئلة الأربعة من الدرس."},{"en":"An optional field still asks. Is there a place outside the order where the birthday fits?","ar":"الحقل الاختياري ما زال يسأل. هل هناك مكان خارج الطلب يناسب عيد الميلاد؟"}],"correct":{"en":"The order stays about lunch.","ar":"يبقى الطلب عن الغداء."},"explain":{"en":"No use, no field. And an extra that some people want, like a birthday gift, goes where they choose to share it.","ar":"لا فائدة، لا حقل. والإضافة التي يريدها بعض الناس، مثل هدية عيد الميلاد، تذهب حيث يختارون مشاركتها."}},{"id":"S09","type":"card","part":"recap","icons":["target","clock","none","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Essential only:** removed the field the task didn't need.\n- **Ask later:** moved membership questions to the membership form.\n- **Minimum first:** asked marketing's question after sign-up.\n- **Say why:** explained the personal field at the field.\n- **Not just short:** kept the field the delivery can't work without.\n\nNext lesson: required or optional, and how to show it.","ar":"- **الضروري فقط:** حذفت الحقل الذي لا تحتاجه المهمة.\n- **اسأل لاحقًا:** نقلت أسئلة الاشتراك إلى نموذج الاشتراك.\n- **الحد الأدنى أولًا:** طرحت سؤال التسويق بعد التسجيل.\n- **وضّح السبب:** شرحت الحقل الشخصي عند الحقل نفسه.\n- **ليس الأقصر فقط:** أبقيت الحقل الذي لا يعمل التوصيل بدونه.\n\nالدرس التالي: إلزامي أم اختياري، وكيف توضّح ذلك."}}]}$uxg$::jsonb),
  ($uxg$P01-U01-L02$uxg$, $uxg$8d88fe731a22dad285797ae11e9dd0a65ff6a03ab34813c0a60be40abc50fa60$uxg$, $uxg${"id":"P01-U01-L02","mode":"lesson","minutes":8,"title":{"en":"Required or optional? Show it on every field","ar":"إلزامي أم اختياري؟ وضّحه في كل حقل"},"speaker":"hana","review_labels":{"MC-P01-001":{"en":"Ask for what the task needs now","ar":"اسأل عمّا تحتاجه المهمة الآن"},"MC-P01-003":{"en":"A style alone doesn't say what's required","ar":"الشكل وحده لا يوضّح ما هو إلزامي"},"MC-P01-004":{"en":"The label and the check must agree","ar":"يجب أن تتّفق التسمية مع التحقق"},"MC-P01-005":{"en":"Many optional fields mean too many fields","ar":"كثرة الحقول الاختيارية تعني كثرة الحقول"},"MC-P01-028":{"en":"Mark every required field, at the field","ar":"ميّز كل حقل إلزامي، عند الحقل نفسه"},"MC-P01-029":{"en":"Unmarked optional fields get filled in anyway","ar":"الحقول الاختيارية غير المميّزة تُملأ على أي حال"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Salma joins","ar":"سلمى تشترك"},"body":{"en":"Salma loved the trial and decided to join. Now we really do need more from her.\n\nSome labels on our form have a star. Some don't. Nothing on the form says what the stars mean.","ar":"أحبّت سلمى التجربة وقرّرت الاشتراك. الآن نحتاج منها معلومات أكثر فعلًا.\n\nبعض التسميات في نموذجنا عليها نجمة، وبعضها لا. ولا شيء في النموذج يوضّح معنى النجوم."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"field","label":{"en":"Full name *","ar":"الاسم الكامل *"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal","ar":"هدفك الرياضي"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U01-04","part":"try","rules":["R12"],"value":{"en":"Try first. Marking required fields (NN/g): be explicit; mark every field that must be completed. Marking optional fields as well is a helpful extra. Marking only the optional ones leaves people assuming.","ar":"جرّب أولًا. تمييز الحقول الإلزامية (NN/g): كن واضحًا؛ ميّز كل حقل يجب ملؤه. وتمييز الحقول الاختيارية أيضًا إضافة مفيدة. أما تمييز الاختيارية وحدها فيترك الناس يفترضون."},"ref":{"url":"https://www.nngroup.com/articles/required-fields/","quote":"Be as explicit and transparent as possible: for every single field that must be completed, mark it as required."},"scenario":{"en":"The emergency contact is required too; someone on my team forgot its star. Only the email and the fitness goal are optional.","ar":"رقم الطوارئ إلزامي أيضًا؛ لكن أحدًا في فريقي نسي نجمته. والحقلان الاختياريان الوحيدان هما البريد الإلكتروني والهدف الرياضي."},"prompt":{"en":"Try each way of marking the form. Which one should ship?","ar":"جرّب كل طريقة لتمييز الحقول. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"field","label":{"en":"Full name *","ar":"الاسم الكامل *"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal","ar":"هدفك الرياضي"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]},"options":[{"id":"optonly","text":{"en":"Remove the stars; mark only the two optional fields","ar":"احذف النجوم؛ وميّز الحقلين الاختياريين فقط"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal (optional)","ar":"هدفك الرياضي (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"note","text":{"en":"Remove the stars; add a note at the top","ar":"احذف النجوم؛ وأضف ملاحظة في الأعلى"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"small","text":{"en":"Name, mobile, national ID and emergency contact are required.","ar":"الاسم والموبايل والرقم القومي ورقم الطوارئ إلزامية."},"gap":"s"},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal","ar":"هدفك الرياضي"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"both","text":{"en":"Star every required field, and mark the optional ones too","ar":"ضع نجمة على كل حقل إلزامي، وميّز الاختيارية أيضًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Become a member","ar":"اشترك في النادي"}},{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"},"gap":"s"},{"kind":"field","label":{"en":"Full name *","ar":"الاسم الكامل *"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number *","ar":"رقم للطوارئ *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal (optional)","ar":"هدفك الرياضي (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}}],"answer":["both"],"misconceptions":[{"id":"MC-P01-028","when":["optonly"],"feedback":{"en":"Salma might not notice the word \"(optional)\" two fields down, and assume nothing is required. Then she finds out from errors. Mark every required field too.","ar":"قد لا تلاحظ سلمى كلمة «(اختياري)» بعد حقلين، فتفترض أن لا شيء إلزامي. ثم تكتشف ذلك من رسائل الخطأ. ميّز كل حقل إلزامي أيضًا."}},{"id":"MC-P01-028","when":["note"],"feedback":{"en":"People skip instructions at the top of a form, and forget them by the fourth field. Put the mark on the field itself.","ar":"يتخطّى الناس التعليمات أعلى النموذج، وينسونها عند الحقل الرابع. ضع العلامة على الحقل نفسه."}}],"hints":[{"en":"Look at the emergency contact: it's required, but nothing shows it.","ar":"انظر إلى رقم الطوارئ: إنه إلزامي، لكن لا شيء يوضّح ذلك."},{"en":"Each field should say for itself whether it's required or optional.","ar":"يجب أن يقول كل حقل بنفسه هل هو إلزامي أم اختياري."}],"correct":{"en":"Every field says what it is.","ar":"كل حقل يوضّح نوعه."},"explain":{"en":"Salma knows, at each field, whether she can skip it. No guessing, and no error message to learn the rules.","ar":"تعرف سلمى، عند كل حقل، هل تستطيع تخطّيه. بلا تخمين، وبلا رسالة خطأ لتتعلّم القواعد."},"speaker":"hana"},{"id":"S03","type":"card","part":"concept","icons":["eye","form","none","idea"],"title":{"en":"No one should have to guess","ar":"لا يجب أن يخمّن أحد"},"body":{"en":"People don't read the instructions at the top of a form, and those who do forget them. So the answer has to be on each field.\n\n- **Required:** put an asterisk (*) on every required field. People know what it means, and it takes little space.\n- **Optional:** add \"(optional)\" to the label. Otherwise many people fill it in anyway.\n- **Few optional fields:** if you have many, the form asks too much. Go back to Lesson 1.\n- **One truth:** the label and the check behind it must say the same thing.","ar":"الناس لا يقرؤون التعليمات أعلى النموذج، ومن يقرؤها ينساها. لذلك يجب أن تكون الإجابة عند كل حقل.\n\n- **الإلزامي:** ضع نجمة (*) على كل حقل إلزامي. الناس يعرفون معناها، وهي لا تأخذ مساحة كبيرة.\n- **الاختياري:** أضف «(اختياري)» إلى التسمية. وإلا سيملؤه كثيرون على أي حال.\n- **حقول اختيارية قليلة:** إذا كانت كثيرة، فالنموذج يطلب أكثر من اللازم. ارجع إلى الدرس 1.\n- **حقيقة واحدة:** يجب أن تقول التسمية والتحقق الذي وراءها الشيء نفسه."}},{"id":"S04","type":"tune","skill":"SK-P01-U01-04","part":"guided","rules":["R06","R15"],"value":{"en":"Marking required fields (NN/g): the asterisk is familiar, takes little space and looks different from the label text. A private style, like bold labels, is a code people have to crack.","ar":"تمييز الحقول الإلزامية (NN/g): النجمة مألوفة، ولا تأخذ مساحة كبيرة، وتبدو مختلفة عن نص التسمية. أما الأسلوب الخاص، مثل التسميات العريضة، فهو رمز على الناس أن يفكّوه."},"ref":{"url":"https://www.nngroup.com/articles/required-fields/","quote":"The asterisk has become very common on the web and users are familiar with its meaning."},"scenario":{"en":"A designer suggested a cleaner way to show the required fields on our form: make their labels bold.","ar":"اقترح مصمّم طريقة أنظف لإظهار الحقول الإلزامية في نموذجنا: أن تكون تسمياتها بخط عريض."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"bold","options":[{"id":"star","text":{"en":"An asterisk on each required label","ar":"نجمة على كل تسمية إلزامية"},"mock":{"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"Full name *","ar":"الاسم الكامل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"}]}},{"id":"bold","text":{"en":"Bold labels for required fields, regular for optional","ar":"تسميات عريضة للحقول الإلزامية، وعادية للاختيارية"},"mock":{"width":300,"blocks":[{"kind":"text","weight":"bold","text":{"en":"Full name","ar":"الاسم الكامل"}},{"kind":"field","text":"","gap":"xs"},{"kind":"text","text":{"en":"Email","ar":"البريد الإلكتروني"},"gap":"s"},{"kind":"field","text":"","gap":"xs"},{"kind":"text","weight":"bold","text":{"en":"National ID number","ar":"الرقم القومي"},"gap":"s"},{"kind":"field","text":"","gap":"xs"}]}},{"id":"red","text":{"en":"Red borders on required fields","ar":"حدود حمراء للحقول الإلزامية"},"mock":{"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","tone":"bad","label":{"en":"National ID number","ar":"الرقم القومي"},"text":"","gap":"s"}]}}],"answer":["star"],"misconceptions":[{"id":"MC-P01-003","when":["bold"],"feedback":{"en":"Bold doesn't mean \"required\" anywhere else, so Salma has to work out the code, and the difference is easy to miss. Use the mark people already know.","ar":"الخط العريض لا يعني «إلزامي» في أي مكان آخر، فعلى سلمى أن تفكّ الرمز، والفرق سهل أن يفوتها. استخدم العلامة التي يعرفها الناس."}},{"id":"MC-P01-003","when":["red"],"feedback":{"en":"A red border looks like an error before Salma has typed anything, and colour alone isn't seen by everyone. Use the asterisk.","ar":"الحدود الحمراء تبدو كخطأ قبل أن تكتب سلمى أي شيء، واللون وحده لا يراه الجميع. استخدم النجمة."}}],"hints":[{"en":"Which mark do people already know means required?","ar":"أي علامة يعرف الناس مسبقًا أنها تعني إلزامي؟"},{"en":"Bold and red can mean other things. Which one needs no explaining?","ar":"الخط العريض واللون الأحمر قد يعنيان أشياء أخرى. أيّها لا يحتاج شرحًا؟"}],"correct":{"en":"The familiar mark, on the label.","ar":"العلامة المألوفة، على التسمية."},"explain":{"en":"An asterisk is short, familiar, and stands out from the label. It works without a legend for most people, and a short one at the top helps the rest.","ar":"النجمة قصيرة ومألوفة وتبرز عن التسمية. وهي تعمل دون شرح لأغلب الناس، والشرح القصير في الأعلى يساعد الباقين."},"speaker":"hana"},{"id":"S05","type":"tune","skill":"SK-P01-U01-05","part":"guided","rules":["R06","R15"],"value":{"en":"Cognitive load in forms (NN/g): communicate requirements and set expectations upfront. A label that says optional sets an expectation; the check must keep it.","ar":"العبء الذهني في النماذج (NN/g): وضّح المتطلبات وحدّد التوقعات مسبقًا. والتسمية التي تقول اختياري تصنع توقّعًا؛ ويجب أن يلتزم به التحقق."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"Communicate requirements and set expectations upfront."},"scenario":{"en":"Salma left \"Email (optional)\" empty and pressed Join now. The form stopped her. We send everything by text message; we never use the email.","ar":"تركت سلمى «البريد الإلكتروني (اختياري)» فارغًا وضغطت «اشترك الآن». فأوقفها النموذج. ونحن نرسل كل شيء برسائل نصية؛ ولا نستخدم البريد أبدًا."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","error":{"en":"Email is required.","ar":"البريد الإلكتروني إلزامي."}},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]},"options":[{"id":"label","text":{"en":"Change the label to \"Email *\"","ar":"غيّر التسمية إلى «البريد الإلكتروني *»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Email *","ar":"البريد الإلكتروني *"},"text":""},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep both; the error tells her what to do","ar":"أبقِ الاثنين؛ فرسالة الخطأ تخبرها بما تفعل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","error":{"en":"Email is required.","ar":"البريد الإلكتروني إلزامي."}},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"}]}},{"id":"check","text":{"en":"Fix the check, so an empty email goes through","ar":"أصلِح التحقق، ليمرّ البريد الفارغ"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":""},{"kind":"button","text":{"en":"Join now","ar":"اشترك الآن"},"gap":"m"},{"kind":"small","color":"green","text":{"en":"Welcome to the gym, Salma!","ar":"أهلًا بك في النادي يا سلمى!"},"gap":"s"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-004","when":["label"],"feedback":{"en":"Now the label matches the check, but the gym never uses the email. You'd be asking for a field it doesn't need. Fix the check instead.","ar":"الآن تتّفق التسمية مع التحقق، لكن النادي لا يستخدم البريد أبدًا. فأنت تطلب حقلًا لا يحتاجه. أصلِح التحقق بدلًا من ذلك."}},{"id":"MC-P01-004","when":["keep"],"feedback":{"en":"The form promised one thing and did another. Salma learns the rules by failing, and stops trusting the other labels.","ar":"وعد النموذج بشيء وفعل غيره. فتتعلّم سلمى القواعد بالفشل، وتتوقّف عن الثقة في التسميات الأخرى."}}],"hints":[{"en":"The label and the check disagree. Which one matches what the gym needs?","ar":"التسمية والتحقّق لا يتّفقان. أيهما يطابق ما يحتاجه الجيم؟"},{"en":"The gym never uses the email. Should an empty email stop her, then?","ar":"الجيم لا يستخدم البريد الإلكتروني أبدًا. فهل يجب أن يوقفها بريد فارغ؟"}],"correct":{"en":"Decide what's needed, then make both agree.","ar":"قرّر ما تحتاجه، ثم اجعل الاثنين يتّفقان."},"explain":{"en":"This often happens when design and development set the required fields separately. Decide once, from the task, and write it in one place in the spec.","ar":"يحدث هذا كثيرًا حين يحدّد التصميم والتطوير الحقول الإلزامية كلٌّ على حدة. قرّر مرة واحدة، بناءً على المهمة، واكتبه في مكان واحد في المواصفات."},"speaker":"hana"},{"id":"S06","type":"tune","skill":"SK-P01-U01-01","part":"guided","speaker":"nour","rules":["R06","R15"],"value":{"en":"Forms usability (NN/g): limit the form to only one or two optional fields, and clearly label them. Four optional fields means the form asks too much.","ar":"سهولة استخدام النماذج (NN/g): اقتصر على حقل أو حقلين اختياريين فقط، وميّزهما بوضوح. وأربعة حقول اختيارية تعني أن النموذج يطلب أكثر من اللازم."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Limit the form to only 1 or 2 optional fields, and clearly label them as optional."},"scenario":{"en":"My clinic's booking form has four required fields and four optional ones. We use the insurance company and the note for the doctor. Nobody uses the other two.","ar":"نموذج الحجز في عيادتي فيه أربعة حقول إلزامية وأربعة اختيارية. ونحن نستخدم شركة التأمين والملاحظة للطبيب. ولا أحد يستخدم الحقلين الآخرين."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"mark","options":[{"id":"mark","text":{"en":"Keep all four, clearly marked optional","ar":"أبقِ الأربعة، مع تمييزها بوضوح كاختيارية"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Patient name *","ar":"اسم المريض *"},"text":""},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Doctor *","ar":"الطبيب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date and time *","ar":"التاريخ والوقت *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Insurance company (optional)","ar":"شركة التأمين (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the doctor (optional)","ar":"ملاحظة للطبيب (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you find us? (optional)","ar":"كيف وجدتنا؟ (اختياري)"},"text":"","gap":"s"}]}},{"id":"trim","text":{"en":"Remove the two nobody uses; mark the other two optional","ar":"احذف الحقلين اللذين لا يستخدمهما أحد؛ وميّز الآخرين كاختياريين"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Patient name *","ar":"اسم المريض *"},"text":""},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Doctor *","ar":"الطبيب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date and time *","ar":"التاريخ والوقت *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Insurance company (optional)","ar":"شركة التأمين (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the doctor (optional)","ar":"ملاحظة للطبيب (اختياري)"},"text":"","gap":"s"}]}},{"id":"required","text":{"en":"Make all eight required, so nothing needs a mark","ar":"اجعل الثمانية إلزامية، فلا يحتاج شيء إلى تمييز"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Patient name *","ar":"اسم المريض *"},"text":""},{"kind":"field","label":{"en":"Mobile number *","ar":"رقم الموبايل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Doctor *","ar":"الطبيب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date and time *","ar":"التاريخ والوقت *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Insurance company *","ar":"شركة التأمين *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the doctor *","ar":"ملاحظة للطبيب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email *","ar":"البريد الإلكتروني *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"How did you find us? *","ar":"كيف وجدتنا؟ *"},"text":"","gap":"s"}]}}],"answer":["trim"],"misconceptions":[{"id":"MC-P01-005","when":["mark"],"feedback":{"en":"The marks are clear, but people still read and think about four extra questions, two of them useless. Trim first, then mark.","ar":"العلامات واضحة، لكن الناس ما زالوا يقرؤون أربعة أسئلة إضافية ويفكّرون فيها، اثنان منها بلا فائدة. احذف أولًا، ثم ميّز."}},{"id":"MC-P01-001","when":["required"],"feedback":{"en":"Now people without insurance, or with nothing to tell the doctor, are stuck. Required means the task can't happen without it.","ar":"الآن من ليس لديه تأمين، أو ليس لديه ما يقوله للطبيب، سيتعطّل. والإلزامي يعني أن المهمة لا تتم بدونه."}}],"hints":[{"en":"Before marking anything, ask: does anyone use all eight fields?","ar":"قبل وضع أي علامة، اسأل: هل يستخدم أحد الحقول الثمانية كلها؟"},{"en":"A field nobody uses doesn't need a better mark.","ar":"الحقل الذي لا يستخدمه أحد لا يحتاج علامة أفضل."}],"correct":{"en":"Trim first, then mark what's left.","ar":"احذف أولًا، ثم ميّز ما تبقّى."},"explain":{"en":"Many optional fields are a warning sign. Remove the ones nobody uses; then one or two clearly marked extras are easy to skip.","ar":"كثرة الحقول الاختيارية علامة تحذير. احذف ما لا يستخدمه أحد؛ وحينها يسهل تخطّي إضافة أو إضافتين مميّزتين بوضوح."}},{"id":"S07","type":"compare","skill":"SK-P01-U01-04","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S04: stars on the required fields are needed, but not the whole job. Cognitive load in forms (NN/g): when marking isn't clear enough, many people feel obliged to answer optional questions.","ar":"مقارنة مع الخطوة 4: النجوم على الحقول الإلزامية ضرورية، لكنها ليست كل شيء. العبء الذهني في النماذج (NN/g): حين لا يكون التمييز واضحًا بما يكفي، يشعر كثيرون بأنهم ملزمون بالإجابة عن الأسئلة الاختيارية."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"When marking is not clear enough, many people feel obligated to answer optional questions."},"scenario":{"en":"Both versions of our form put a star on every required field. Salma has no fitness goal in mind yet.","ar":"النسختان من نموذجنا تضعان نجمة على كل حقل إلزامي. وليس لدى سلمى هدف رياضي محدّد بعد."},"prompt":{"en":"In which version can Salma see that she may skip the fitness goal?","ar":"في أي نسخة تستطيع سلمى أن ترى أنها يمكنها تخطّي الهدف الرياضي؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number *","ar":"رقم للطوارئ *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal","ar":"هدفك الرياضي"},"text":"","gap":"s"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"National ID number *","ar":"الرقم القومي *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Emergency contact number *","ar":"رقم للطوارئ *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your fitness goal (optional)","ar":"هدفك الرياضي (اختياري)"},"text":"","gap":"s"}]}},"answer":"b","reason":{"prompt":{"en":"Why doesn't the missing star in A tell her enough?","ar":"لماذا لا يكفي غياب النجمة في A لإخبارها؟"},"options":[{"id":"absence","text":{"en":"A missing mark is easy to overlook; a word she can read is not","ar":"غياب العلامة سهل أن يفوت؛ أما كلمة تقرؤها فلا"}},{"id":"longer","text":{"en":"Longer labels are always clearer","ar":"التسميات الأطول أوضح دائمًا"}},{"id":"trust","text":{"en":"The star in A is the wrong colour","ar":"النجمة في A بلون خاطئ"}}],"answer":["absence"],"misconceptions":[{"id":"MC-P01-029","when":["longer","trust"],"feedback":{"en":"The stars are the same in both. B wins because \"(optional)\" says it out loud, instead of relying on a star that isn't there.","ar":"النجوم واحدة في النسختين. B تفوز لأن «(اختياري)» تقولها صراحة، بدل الاعتماد على نجمة غير موجودة."}}]},"misconceptions":[{"id":"MC-P01-029","when":["a"],"feedback":{"en":"In A, Salma has to notice that a star is missing. Many people won't, and they'll invent a goal just to be safe.","ar":"في A، على سلمى أن تلاحظ أن نجمة غير موجودة. وكثيرون لن يلاحظوا، فسيخترعون هدفًا احتياطًا."}}],"hints":[{"en":"Look at the fitness goal label in each version.","ar":"انظر إلى تسمية الهدف الرياضي في كل نسخة."},{"en":"Does a missing star tell Salma as much as a word she can read?","ar":"هل يخبر غياب النجمة سلمى بقدر ما تخبرها كلمة تقرؤها؟"}],"correct":{"en":"Say \"optional\" in words too.","ar":"قل «اختياري» بالكلمات أيضًا."},"explain":{"en":"Stars tell people what they must fill in. \"(optional)\" tells them what they may skip. Together, nobody has to guess.","ar":"النجوم تخبر الناس بما يجب ملؤه. و«(اختياري)» تخبرهم بما يمكن تخطّيه. ومعًا، لا يحتاج أحد إلى التخمين."},"speaker":"hana"},{"id":"S08","type":"tune","skill":"SK-P01-U01-04","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Mobile input checklist (NN/g): is each field marked as required (*) or optional? Tamer's order has three required and two optional fields.","ar":"حالة جديدة. قائمة تحقّق حقول الهاتف (NN/g): هل كل حقل مميّز بأنه إلزامي (*) أو اختياري؟ في طلب تامر ثلاثة حقول إلزامية واثنان اختياريان."},"ref":{"url":"https://www.nngroup.com/articles/mobile-input-checklist/","quote":"Is the field marked as required (*) or optional?"},"scenario":{"en":"In our app, Tamer's lunch order needs the address, the phone and the payment method. The note for the driver and the promo code are optional.","ar":"في تطبيقنا، يحتاج طلب غداء تامر العنوان والهاتف وطريقة الدفع. أما الملاحظة للسائق وكود الخصم فاختياريان."},"prompt":{"en":"Try each version of the order form. Which one should ship?","ar":"جرّب كل نسخة من نموذج الطلب. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":""},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Payment method","ar":"طريقة الدفع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the driver","ar":"ملاحظة للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code","ar":"كود الخصم"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]},"options":[{"id":"gray","text":{"en":"Gray out the optional fields","ar":"اجعل الحقول الاختيارية رمادية باهتة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":""},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Payment method","ar":"طريقة الدفع"},"text":"","gap":"s"},{"kind":"text","color":"faint","text":{"en":"Note for the driver","ar":"ملاحظة للسائق"},"gap":"s"},{"kind":"field","text":"","gap":"xs"},{"kind":"text","color":"faint","text":{"en":"Promo code","ar":"كود الخصم"},"gap":"s"},{"kind":"field","text":"","gap":"xs"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"marked","text":{"en":"Star the three required; mark the other two optional","ar":"ضع نجمة على الثلاثة الإلزامية؛ وميّز الاثنين الآخرين كاختياريين"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"Delivery address *","ar":"عنوان التوصيل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Phone for the driver *","ar":"رقم هاتف للسائق *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Payment method *","ar":"طريقة الدفع *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the driver (optional)","ar":"ملاحظة للسائق (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code (optional)","ar":"كود الخصم (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"top","text":{"en":"Add \"Fields 1 to 3 are required\" above the form","ar":"أضف «الحقول من 1 إلى 3 إلزامية» أعلى النموذج"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"Fields 1 to 3 are required.","ar":"الحقول من 1 إلى 3 إلزامية."}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Payment method","ar":"طريقة الدفع"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Note for the driver","ar":"ملاحظة للسائق"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code","ar":"كود الخصم"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}}],"answer":["marked"],"misconceptions":[{"id":"MC-P01-003","when":["gray"],"feedback":{"en":"Faded fields look disabled, so Tamer may think he can't type a note at all. And the faint labels are hard to read. Say it in words.","ar":"الحقول الباهتة تبدو معطّلة، فقد يظن تامر أنه لا يستطيع كتابة ملاحظة أصلًا. والتسميات الباهتة صعبة القراءة. قلها بالكلمات."}},{"id":"MC-P01-028","when":["top"],"feedback":{"en":"Tamer has to count fields and remember the rule. Most people skip that line anyway. Mark each field.","ar":"على تامر أن يعدّ الحقول ويتذكّر القاعدة. وأغلب الناس يتخطّون هذا السطر على أي حال. ميّز كل حقل."}}],"hints":[{"en":"Check each field: can Tamer tell from the field itself whether he must fill it?","ar":"افحص كل حقل: هل يعرف تامر من الحقل نفسه إن كان عليه ملؤه؟"},{"en":"Gray looks disabled, and a note at the top is easy to miss.","ar":"اللون الرمادي يبدو معطّلًا، والملاحظة في الأعلى سهلة التجاهل."}],"correct":{"en":"Each field says it: * or (optional).","ar":"كل حقل يقولها: * أو (اختياري)."},"explain":{"en":"The same rule works on every form: a star on each required field, and \"(optional)\" on the few that aren't.","ar":"القاعدة نفسها تعمل في كل نموذج: نجمة على كل حقل إلزامي، و«(اختياري)» على القليل غير الإلزامي."}},{"id":"S09","type":"card","part":"recap","icons":["eye","form","none","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Mark it on the field:** a star on every required field, not a note at the top.\n- **The familiar mark:** used the asterisk, not bold, colour or gray.\n- **One truth:** made the label and the check agree.\n- **Trim first:** cut unused optional fields, then marked the rest.\n- **Say optional:** wrote \"(optional)\" so people know what they can skip.\n\nNext lesson: asking in a way people can answer.","ar":"- **ميّزه عند الحقل:** نجمة على كل حقل إلزامي، لا ملاحظة في الأعلى.\n- **العلامة المألوفة:** استخدمت النجمة، لا الخط العريض أو اللون أو الرمادي.\n- **حقيقة واحدة:** جعلت التسمية والتحقق يتّفقان.\n- **احذف أولًا:** حذفت الحقول الاختيارية غير المستخدمة، ثم ميّزت الباقي.\n- **قل اختياري:** كتبت «(اختياري)» ليعرف الناس ما يمكنهم تخطّيه.\n\nالدرس التالي: كيف تسأل بطريقة يستطيع الناس الإجابة عنها."}}]}$uxg$::jsonb),
  ($uxg$P01-U01-L03$uxg$, $uxg$fde41a61922f11ac82300eb3dd640665c40f9da86efab1a8d5f153f36958a7ab$uxg$, $uxg${"id":"P01-U01-L03","mode":"lesson","minutes":8,"title":{"en":"Ask so people can answer","ar":"اسأل بطريقة يستطيع الناس الإجابة عنها"},"speaker":"sara","review_labels":{"MC-P01-006":{"en":"Not everyone's name has a first and last part","ar":"ليس لكل اسم جزء أول وجزء أخير"},"MC-P01-007":{"en":"Let the system clean up the format, not the person","ar":"دع النظام ينظّف الصيغة، لا الشخص"},"MC-P01-008":{"en":"Ask about the real need, in everyday words","ar":"اسأل عن الحاجة الفعلية بكلمات يومية"},"MC-P01-030":{"en":"Write the month as a word","ar":"اكتب الشهر بالحروف"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Abdelrahman's library card","ar":"بطاقة مكتبة عبد الرحمن"},"body":{"en":"I'm redesigning the city library's sign-up form. Abdelrahman Mohamed El-Sayed Hassan is getting a library card. His ID shows four names: his own, his father's, his grandfather's and the family name.\n\nOur form gives him two boxes.","ar":"أعيد تصميم نموذج التسجيل في مكتبة المدينة. يستخرج عبد الرحمن محمد السيد حسن بطاقة مكتبة، وبطاقة هويته فيها أربعة أسماء: اسمه، واسم أبيه، واسم جدّه، واسم العائلة.\n\nونموذجنا يعطيه خانتين."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Last name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U01-06","part":"try","rules":["R12"],"value":{"en":"Try first. International sites (NN/g): separate first-name and last-name fields are a prescription for confusion; some people have one name, others several. One full-name field fits every pattern.","ar":"جرّب أولًا. المواقع الدولية (NN/g): الحقول المنفصلة للاسم الأول واسم العائلة وصفة للارتباك؛ فبعض الناس لهم اسم واحد، وآخرون عدة أسماء. وحقل واحد للاسم الكامل يناسب كل الأنماط."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"Offering separate fields for first name and last name is a prescription for confusion."},"prompt":{"en":"Try each way of asking for his name. Which one should ship?","ar":"جرّب كل طريقة لطلب اسمه. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Last name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]},"options":[{"id":"four","text":{"en":"Four boxes: name, father, grandfather, family","ar":"أربع خانات: الاسم، الأب، الجد، العائلة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Father's name","ar":"اسم الأب"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Grandfather's name","ar":"اسم الجد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Family name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]}},{"id":"full","text":{"en":"One field: \"Full name, as on your ID\"","ar":"حقل واحد: «الاسم الكامل، كما في بطاقتك»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"Full name, as on your ID","ar":"الاسم الكامل، كما في بطاقتك"},"filled":true,"text":{"en":"Abdelrahman Mohamed El-Sayed Hassan","ar":"عبد الرحمن محمد السيد حسن"},"gap":"m"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]}},{"id":"rename","text":{"en":"Keep two boxes, renamed \"Given name\" and \"Family name\"","ar":"أبقِ خانتين، باسم «الاسم» و«اسم العائلة»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Get a library card","ar":"احصل على بطاقة مكتبة"}},{"kind":"field","label":{"en":"Given name","ar":"الاسم"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Family name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Get my card","ar":"أصدر بطاقتي"},"gap":"m"}]}}],"answer":["full"],"misconceptions":[{"id":"MC-P01-006","when":["four"],"feedback":{"en":"Four boxes fit Abdelrahman, and break for the next person: someone with two names, or five. One field fits everyone.","ar":"أربع خانات تناسب عبد الرحمن، وتفشل مع الشخص التالي: من له اسمان، أو خمسة. والحقل الواحد يناسب الجميع."}},{"id":"MC-P01-006","when":["rename"],"feedback":{"en":"New names, same problem. Where do \"Mohamed El-Sayed\" go? He has to guess, and may not match his ID.","ar":"أسماء جديدة، والمشكلة نفسها. أين يكتب «محمد السيد»؟ عليه أن يخمّن، وقد لا يطابق ما يكتبه بطاقته."}}],"hints":[{"en":"Count the names on his ID, then count the boxes.","ar":"عُدّ الأسماء في بطاقته، ثم عُدّ المربعات."},{"en":"People have different numbers of names. What fits them all?","ar":"يختلف عدد الأسماء من شخص لآخر. ما الذي يناسبهم جميعًا؟"}],"correct":{"en":"One field, typed as on his ID.","ar":"حقل واحد، يُكتب كما في بطاقته."},"explain":{"en":"Names come in many shapes. One field lets each person write theirs exactly, and the library can still ask \"What should we call you?\" if it wants a short name.","ar":"الأسماء تأتي بأشكال كثيرة. والحقل الواحد يتيح لكل شخص كتابة اسمه كما هو تمامًا، وتستطيع المكتبة مع ذلك أن تسأل «بماذا نناديك؟» إذا أرادت اسمًا قصيرًا."}},{"id":"S03","type":"card","part":"concept","icons":["form","idea","eye","clock"],"title":{"en":"Fit the question to the answer people have","ar":"اجعل السؤال يناسب الإجابة التي لدى الناس"},"body":{"en":"A question is easy when it matches how people already hold the answer.\n\n- **Names:** one \"Full name\" field fits every naming pattern.\n- **Formats:** let people type a phone number the way they write it, with spaces, dashes or a country code. The system tidies it.\n- **Words:** labels should make sense at first read. If someone has to look a word up, change the word.\n- **Dates:** write the month as a word. 03/04 could be March or April.","ar":"يكون السؤال سهلًا حين يطابق الطريقة التي يحمل بها الناس الإجابة.\n\n- **الأسماء:** حقل واحد «الاسم الكامل» يناسب كل أنماط الأسماء.\n- **الصيغ:** دع الناس يكتبون رقم الهاتف كما يكتبونه عادة، بمسافات أو شرطات أو رمز الدولة. والنظام يرتّبه.\n- **الكلمات:** يجب أن تُفهم التسميات من أول قراءة. إذا احتاج أحد أن يبحث عن معنى كلمة، فغيّر الكلمة.\n- **التواريخ:** اكتب الشهر بالحروف. فـ 03/04 قد تعني مارس أو أبريل."}},{"id":"S04","type":"tune","skill":"SK-P01-U01-07","part":"guided","rules":["R06","R15"],"value":{"en":"Mobile input checklist (NN/g): let users enter a phone number in whatever format they like, and autoformat it for them. Rejecting spaces makes people do the system's work.","ar":"قائمة تحقّق حقول الهاتف (NN/g): دع المستخدمين يُدخلون رقم الهاتف بأي صيغة يريدونها، ونسّقه لهم تلقائيًا. ورفض المسافات يجعل الناس يقومون بعمل النظام."},"ref":{"url":"https://www.nngroup.com/articles/mobile-input-checklist/","quote":"Do you allow users to enter it in whatever format they like?"},"scenario":{"en":"In testing, Abdelrahman copied his number from his contacts: ⁦010 1234 5678⁩. Our form rejected it because of the spaces.","ar":"في الاختبار، نسخ عبد الرحمن رقمه من جهات الاتصال: ⁦010 1234 5678⁩. فرفضه نموذجنا بسبب المسافات."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 1234 5678⁩","error":{"en":"Invalid number.","ar":"رقم غير صالح."}}]},"options":[{"id":"hint","text":{"en":"Add a hint: \"Digits only, no spaces\"","ar":"أضف تلميحًا: «أرقام فقط، بدون مسافات»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"Digits only, no spaces.","ar":"أرقام فقط، بدون مسافات."}}]}},{"id":"boxes","text":{"en":"Split it into three boxes: 3, 4 and 4 digits","ar":"قسّمه إلى ثلاث خانات: 3 و4 و4 أرقام"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"Mobile number","ar":"رقم الموبايل"}},{"kind":"row","gap":"s","blocks":[{"kind":"field","text":"010"},{"kind":"field","text":""},{"kind":"field","text":""}]}]}},{"id":"accept","text":{"en":"Accept it as typed; the system removes the spaces","ar":"اقبله كما كُتب؛ والنظام يحذف المسافات"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 1234 5678⁩"},{"kind":"small","color":"green","text":{"en":"✓ Saved as 01012345678","ar":"✓ حُفظ هكذا: 01012345678"},"gap":"xs"}]}}],"answer":["accept"],"misconceptions":[{"id":"MC-P01-007","when":["hint"],"feedback":{"en":"The number was never wrong. Now Abdelrahman has to delete the spaces by hand, on a phone keyboard. Let the system do it.","ar":"الرقم لم يكن خاطئًا أصلًا. والآن على عبد الرحمن أن يحذف المسافات بيده، على لوحة مفاتيح الهاتف. دع النظام يفعل ذلك."}},{"id":"MC-P01-007","when":["boxes"],"feedback":{"en":"He can't paste the number in one go any more, and he has to jump between boxes. One field, any format.","ar":"لم يعد يستطيع لصق الرقم دفعة واحدة، وعليه أن يتنقّل بين الخانات. حقل واحد، بأي صيغة."}}],"hints":[{"en":"Who should remove the spaces: Abdelrahman or the system?","ar":"من يجب أن يزيل المسافات: عبد الرحمن أم النظام؟"},{"en":"A hint or extra boxes still make him change the way he writes it.","ar":"التلميح أو المربعات الإضافية ما زالت تجبره على تغيير طريقة كتابته."}],"correct":{"en":"Accept the way people write it.","ar":"اقبل الطريقة التي يكتب بها الناس."},"explain":{"en":"People copy numbers from contacts and messages, spaces included. Removing spaces is a simple job for the system and an annoying one for a person.","ar":"ينسخ الناس الأرقام من جهات الاتصال والرسائل، بالمسافات. وحذف المسافات مهمة بسيطة للنظام ومزعجة للإنسان."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U01-08","part":"guided","rules":["R06","R15"],"value":{"en":"Cognitive load in forms (NN/g): labels and instructions should be immediately understandable; plain language helps everyone. Internal terms need a translation, not a tooltip.","ar":"العبء الذهني في النماذج (NN/g): يجب أن تُفهم التسميات والتعليمات فورًا؛ واللغة البسيطة تساعد الجميع. والمصطلحات الداخلية تحتاج إلى ترجمة، لا إلى تلميح منبثق."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"Form labels and instructions should be immediately understandable."},"scenario":{"en":"The library's form asks for a \"Patron classification\": A, B or C. The staff told me B means students and under-18s, who get the card free.","ar":"يطلب نموذج المكتبة «تصنيف المستفيد»: A أو B أو C. وأخبرني الموظفون أن B تعني الطلاب ومن هم دون 18 عامًا، وهؤلاء يحصلون على البطاقة مجانًا."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"code","options":[{"id":"plain","text":{"en":"Ask the real question in everyday words","ar":"اطرح السؤال الحقيقي بكلمات يومية"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Are you a student, or under 18?","ar":"هل أنت طالب، أو عمرك أقل من 18 عامًا؟"}},{"kind":"small","text":{"en":"If yes, your card is free.","ar":"إذا كانت الإجابة نعم، فبطاقتك مجانية."},"gap":"xs"},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":{"en":"Yes","ar":"نعم"}},{"kind":"chip","text":{"en":"No","ar":"لا"}}]}]}},{"id":"code","text":{"en":"Keep the classification, with an ⓘ that explains it","ar":"أبقِ التصنيف، مع ⓘ يشرحه"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Patron classification ⓘ","ar":"تصنيف المستفيد ⓘ"}},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":"A"},{"kind":"chip","text":"B"},{"kind":"chip","text":"C"}]}]}},{"id":"table","text":{"en":"Keep it, with a table of the categories above","ar":"أبقِه، مع جدول للتصنيفات في الأعلى"},"mock":{"width":300,"blocks":[{"kind":"small","text":{"en":"A: adults · B: students and under-18s · C: visitors from other cities","ar":"A: البالغون · B: الطلاب ومن هم دون 18 · C: الزوّار من مدن أخرى"}},{"kind":"small","weight":"bold","text":{"en":"Patron classification","ar":"تصنيف المستفيد"},"gap":"s"},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":"A"},{"kind":"chip","text":"B"},{"kind":"chip","text":"C"}]}]}}],"answer":["plain"],"misconceptions":[{"id":"MC-P01-008","when":["code"],"feedback":{"en":"The label still means nothing until Abdelrahman finds and opens the ⓘ. Ask in words he already understands.","ar":"التسمية ما زالت بلا معنى حتى يجد عبد الرحمن الـ ⓘ ويفتحه. اسأل بكلمات يفهمها بالفعل."}},{"id":"MC-P01-008","when":["table"],"feedback":{"en":"Now he reads a table, translates it, and remembers the letter. The library only needs to know one thing: student or under 18?","ar":"الآن يقرأ جدولًا، ويترجمه، ويتذكّر الحرف. والمكتبة تحتاج معرفة شيء واحد فقط: طالب أو دون 18؟"}}],"hints":[{"en":"Would Abdelrahman understand this classification at first read?","ar":"هل سيفهم عبد الرحمن هذا التصنيف من أول قراءة؟"},{"en":"What does the library really want to know about him?","ar":"ما الذي تريد المكتبة معرفته عنه فعلًا؟"}],"correct":{"en":"Ask what you need to know, in his words.","ar":"اسأل عمّا تحتاج معرفته، بكلماته هو."},"explain":{"en":"Internal codes make sense to staff. A plain question gets the same answer, faster, and tells him why it matters: the card is free.","ar":"الرموز الداخلية مفهومة للموظفين. والسؤال البسيط يحصل على الإجابة نفسها، أسرع، ويخبره لماذا يهم: البطاقة مجانية."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U01-08","part":"guided","rules":["R06","R15"],"value":{"en":"International sites (NN/g): for dates, always spell out the name of the month. A numeric date like 03/04 reads as March or April depending on where you're from.","ar":"المواقع الدولية (NN/g): في التواريخ، اكتب اسم الشهر دائمًا. فالتاريخ الرقمي مثل 03/04 يُقرأ مارس أو أبريل حسب بلدك."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"For dates, the main guideline is: Always spell out the name of the month."},"scenario":{"en":"I watched Abdelrahman pick his date of birth, 3 April 2005, from a calendar. The field then shows the date he picked, so he can check it.","ar":"شاهدت عبد الرحمن يختار تاريخ ميلاده، 3 أبريل 2005، من تقويم. ثم يعرض الحقل التاريخ الذي اختاره ليتحقّق منه."},"prompt":{"en":"Try each way of showing the date. Which one should ship?","ar":"جرّب كل طريقة لعرض التاريخ. أيّها يجب أن تُطلق؟"},"start":"slash","options":[{"id":"slash","text":{"en":"03/04/2005","ar":"03/04/2005"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"text":"03/04/2005"}]}},{"id":"iso","text":{"en":"2005-04-03","ar":"2005-04-03"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"text":"2005-04-03"}]}},{"id":"words","text":{"en":"3 April 2005","ar":"3 أبريل 2005"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"text":{"en":"3 April 2005","ar":"3 أبريل 2005"}}]}}],"answer":["words"],"misconceptions":[{"id":"MC-P01-030","when":["slash"],"feedback":{"en":"Is that 3 April or 4 March? It depends on the country the reader learned dates in. He can't be sure he picked the right day.","ar":"هل هو 3 أبريل أم 4 مارس؟ يعتمد ذلك على البلد الذي تعلّم فيه القارئ التواريخ. فلا يستطيع التأكّد أنه اختار اليوم الصحيح."}},{"id":"MC-P01-030","when":["iso"],"feedback":{"en":"Clear to a database, but most people don't read dates that way, and the middle number still needs decoding. Write the month.","ar":"واضح لقاعدة البيانات، لكن أغلب الناس لا يقرؤون التواريخ هكذا، والرقم الأوسط ما زال يحتاج إلى فكّ. اكتب الشهر."}}],"hints":[{"en":"Read 03/04/2005 the way someone from another country might.","ar":"اقرأ 03/04/2005 كما قد يقرؤها شخص من بلد آخر."},{"en":"Which format can be read only one way?","ar":"أي صيغة لا تُقرأ إلا بطريقة واحدة؟"}],"correct":{"en":"Write the month as a word.","ar":"اكتب الشهر بالحروف."},"explain":{"en":"\"3 April 2005\" has only one reading, in any country. It costs a few more characters and removes all doubt.","ar":"«3 أبريل 2005» لها قراءة واحدة فقط، في أي بلد. وتكلّف حروفًا قليلة إضافية وتُزيل كل شك."},"speaker":"sara"},{"id":"S07","type":"compare","skill":"SK-P01-U01-07","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S04: accepting spaces is not the whole job. International sites (NN/g): allow international phone numbers with a varying number of digits and a country code.","ar":"مقارنة مع الخطوة 4: قبول المسافات ليس كل المطلوب. المواقع الدولية (NN/g): اسمح بأرقام الهواتف الدولية بعدد أرقام متغيّر ورمز دولة."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"For phone numbers, allow for international numbers containing a varying number of digits and a country code."},"scenario":{"en":"The library asks for an emergency contact. Abdelrahman's brother works abroad, and his number starts with a country code. Both of my versions accept spaces.","ar":"تطلب المكتبة رقمًا للطوارئ. وأخو عبد الرحمن يعمل في الخارج، ورقمه يبدأ برمز دولة. والنسختان اللتان صمّمتهما تقبلان المسافات."},"prompt":{"en":"Which emergency contact field should ship?","ar":"أي حقل لرقم الطوارئ يجب أن يُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"filled":true,"text":"⁦+971 50 123 4567⁩","error":{"en":"Use 11 digits starting with 0.","ar":"استخدم 11 رقمًا تبدأ بـ 0."}}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Emergency contact number","ar":"رقم للطوارئ"},"filled":true,"text":"⁦+971 50 123 4567⁩"},{"kind":"small","color":"green","text":{"en":"✓ Saved","ar":"✓ تم الحفظ"},"gap":"xs"}]}},"answer":"b","reason":{"prompt":{"en":"What does A get wrong, even though it accepts spaces?","ar":"ما خطأ A، مع أنه يقبل المسافات؟"},"options":[{"id":"local","text":{"en":"It assumes every number is a local mobile","ar":"يفترض أن كل رقم موبايل محلي"}},{"id":"plus","text":{"en":"The + sign is not a digit","ar":"علامة + ليست رقمًا"}},{"id":"long","text":{"en":"The error message is too long","ar":"رسالة الخطأ طويلة جدًا"}}],"answer":["local"],"misconceptions":[{"id":"MC-P01-007","when":["plus","long"],"feedback":{"en":"The real problem is the rule: 11 digits starting with 0 fits only local numbers. Real contacts can be anywhere.","ar":"المشكلة الحقيقية هي القاعدة: 11 رقمًا تبدأ بـ 0 تناسب الأرقام المحلية فقط. وجهات الاتصال الحقيقية قد تكون في أي مكان."}}]},"misconceptions":[{"id":"MC-P01-007","when":["a"],"feedback":{"en":"A is flexible about spaces but still rejects a real number. Abdelrahman can't give the contact he actually has.","ar":"A مرن مع المسافات لكنه ما زال يرفض رقمًا حقيقيًا. فلا يستطيع عبد الرحمن إعطاء جهة الاتصال التي لديه فعلًا."}}],"hints":[{"en":"Look at his brother's number: how does it start, and how long is it?","ar":"انظر إلى رقم أخيه: بماذا يبدأ، وكم طوله؟"},{"en":"Both accept spaces. What else does a number from abroad need?","ar":"كلا النموذجين يقبل المسافات. ماذا يحتاج الرقم من الخارج أيضًا؟"}],"correct":{"en":"Flexible format and flexible length.","ar":"صيغة مرنة وطول مرن."},"explain":{"en":"Check that a number is a phone number, not that it looks like yours. Country codes and different lengths are normal.","ar":"تحقّق من أن الرقم رقم هاتف، لا من أنه يشبه أرقام بلدك. فرموز الدول والأطوال المختلفة أمر طبيعي."},"speaker":"sara"},{"id":"S08","type":"tune","skill":"SK-P01-U01-08","part":"independent","rules":["R14","R19"],"value":{"en":"New case. Cognitive load in forms (NN/g): ambiguity slows users down. Laila's booking form mixes an internal term, a strict phone format and split name fields.","ar":"حالة جديدة. العبء الذهني في النماذج (NN/g): الغموض يُبطئ المستخدمين. ونموذج حجز ليلى يجمع مصطلحًا داخليًا وصيغة هاتف صارمة وحقلين منفصلين للاسم."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"Ambiguity slows users down."},"scenario":{"en":"My next client is a home cleaning company. Laila is booking a cleaning, and the company needs her name, her phone, and the size of her flat to send the right team.","ar":"عميلي التالي شركة تنظيف منزلي. تحجز ليلى تنظيفًا، وتحتاج الشركة اسمها وهاتفها وحجم شقتها لترسل الفريق المناسب."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":""},{"kind":"field","label":{"en":"Last name","ar":"اسم العائلة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"Format: 01XXXXXXXXX","ar":"الصيغة: 01XXXXXXXXX"},"gap":"s"},{"kind":"field","label":{"en":"Unit typology","ar":"تصنيف الوحدة"},"text":"","gap":"s"}]},"options":[{"id":"help","text":{"en":"Keep the fields; add help text under each one","ar":"أبقِ الحقول؛ وأضف نصًا توضيحيًا تحت كل واحد"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"First name","ar":"الاسم الأول"},"text":"","hint":{"en":"Your first given name","ar":"اسمك الأول"}},{"kind":"field","label":{"en":"Last name","ar":"اسم العائلة"},"text":"","hint":{"en":"Your family name only","ar":"اسم العائلة فقط"},"gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"Format: 01XXXXXXXXX, no spaces","ar":"الصيغة: 01XXXXXXXXX، بدون مسافات"},"gap":"s"},{"kind":"field","label":{"en":"Unit typology","ar":"تصنيف الوحدة"},"text":"","hint":{"en":"S1, S2 or S3, by floor area","ar":"S1 أو S2 أو S3، حسب المساحة"},"gap":"s"}]}},{"id":"name","text":{"en":"Fix only the name; one Full name field","ar":"أصلِح الاسم فقط؛ حقل واحد للاسم الكامل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","hint":{"en":"Format: 01XXXXXXXXX","ar":"الصيغة: 01XXXXXXXXX"},"gap":"s"},{"kind":"field","label":{"en":"Unit typology","ar":"تصنيف الوحدة"},"text":"","gap":"s"}]}},{"id":"plain","text":{"en":"One name field, any phone format, and ask how many bedrooms","ar":"حقل اسم واحد، وأي صيغة للهاتف، واسأل عن عدد غرف النوم"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"small","weight":"bold","text":{"en":"How many bedrooms?","ar":"كم عدد غرف النوم؟"},"gap":"s"},{"kind":"row","gap":"s","blocks":[{"kind":"chip","text":"1"},{"kind":"chip","text":"2"},{"kind":"chip","text":"3"},{"kind":"chip","text":"4+"}]}]}}],"answer":["plain"],"misconceptions":[{"id":"MC-P01-008","when":["help"],"feedback":{"en":"Help text explains the problems instead of removing them. Laila still has to split her name, strip spaces and decode \"S2\".","ar":"النص التوضيحي يشرح المشكلات بدل أن يُزيلها. فما زال على ليلى أن تقسم اسمها، وتحذف المسافات، وتفكّ «S2»."}},{"id":"MC-P01-008","when":["name"],"feedback":{"en":"The name is fixed, but \"Unit typology\" still means nothing to her, and the phone still has to be typed the system's way.","ar":"الاسم أُصلح، لكن «تصنيف الوحدة» ما زال بلا معنى لها، والهاتف ما زال يجب أن يُكتب بطريقة النظام."}}],"hints":[{"en":"Check all three questions, not just one: name, phone and flat size.","ar":"افحص الأسئلة الثلاثة لا سؤالًا واحدًا: الاسم والهاتف ومساحة الشقة."},{"en":"Help text explains a hard question. Could the questions be easy instead?","ar":"النص المساعد يشرح سؤالًا صعبًا. هل يمكن أن تكون الأسئلة سهلة بدلًا من ذلك؟"}],"correct":{"en":"Every question in her words.","ar":"كل سؤال بكلماتها هي."},"explain":{"en":"Laila knows her name, her number and how many bedrooms she has. The company turns that into its own codes behind the scenes.","ar":"تعرف ليلى اسمها ورقمها وعدد غرف نومها. والشركة تحوّل ذلك إلى رموزها الخاصة في الخلفية."},"speaker":"sara"},{"id":"S09","type":"card","part":"recap","icons":["form","idea","eye","clock"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **One name field:** let every name fit, as written on the ID.\n- **Any format:** accepted the phone number as typed, and let the system tidy it.\n- **Everyday words:** replaced an internal code with the real question.\n- **Months in words:** wrote dates that have only one reading.\n- **Any country:** accepted country codes and different lengths.\n\nNext: the unit skill check.","ar":"- **حقل اسم واحد:** جعلت كل اسم يتّسع، كما هو مكتوب في البطاقة.\n- **أي صيغة:** قبلت رقم الهاتف كما كُتب، وتركت النظام يرتّبه.\n- **كلمات يومية:** استبدلت رمزًا داخليًا بالسؤال الحقيقي.\n- **الشهر بالحروف:** كتبت تواريخ لها قراءة واحدة فقط.\n- **أي بلد:** قبلت رموز الدول والأطوال المختلفة.\n\nالتالي: اختبار المهارة للوحدة."}}]}$uxg$::jsonb),
  ($uxg$P01-U01-L04$uxg$, $uxg$353030358ebf1b930c331972aebf582ad38ba9ad0c4470f72e43e418eccd0d0c$uxg$, $uxg${"id":"P01-U01-L04","mode":"check","minutes":7,"title":{"en":"Skill check: ask only what you need","ar":"اختبار المهارة: اسأل فقط عمّا تحتاجه"},"speaker":"sara","steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Samir's football camp form","ar":"نموذج معسكر كرة القدم لسمير"},"body":{"en":"A football academy asked me to fix its sign-up form. Samir wants to register his 9-year-old son, Ziad, for a summer camp, and this is the form he gets.\n\nYour job: help me fix it, one decision at a time.\n\nThis is a skill check: no hints, and you'll see how you did at the end.","ar":"طلبت مني أكاديمية لكرة القدم إصلاح نموذج التسجيل. يريد سمير تسجيل ابنه زياد، 9 سنوات، في معسكر صيفي، وهذا هو النموذج الذي يظهر له.\n\nمهمّتك: ساعدني على إصلاحه، قرارًا بعد قرار.\n\nهذا اختبار مهارة: بدون تلميحات، وسترى نتيجتك في النهاية."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"School name","ar":"اسم المدرسة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Monthly family income","ar":"دخل الأسرة الشهري"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Photo of the child","ar":"صورة الطفل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U01-01","part":"check","rules":["R19"],"value":{"en":"Skill check, EAS framework (NN/g): ask whether each question is needed now. Income has no use; the school isn't used; the badge photo can wait until the first day.","ar":"اختبار مهارة، إطار EAS (NN/g): اسأل هل كل سؤال مطلوب الآن. الدخل لا فائدة له؛ والمدرسة لا تُستخدم؛ وصورة البطاقة يمكن أن تنتظر حتى اليوم الأول."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"Do we need this information now?"},"scenario":{"en":"The academy told me what it needs to register a child: who Ziad is, his age group, a parent to call, and any health needs. The badge photo is taken on the first day. Nothing uses the school or the income.","ar":"أخبرتني الأكاديمية بما تحتاجه لتسجيل الطفل: من هو زياد، وفئته العمرية، ووليّ أمر للاتصال به، وأي احتياجات صحية. وصورة البطاقة تُلتقط في اليوم الأول. ولا شيء يستخدم المدرسة أو الدخل."},"prompt":{"en":"Try each version of the form. Which one should ship?","ar":"جرّب كل نسخة من النموذج. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"School name","ar":"اسم المدرسة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Monthly family income","ar":"دخل الأسرة الشهري"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Photo of the child","ar":"صورة الطفل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]},"options":[{"id":"optional","text":{"en":"Keep all seven; mark school, income and photo optional","ar":"أبقِ السبعة؛ واجعل المدرسة والدخل والصورة اختيارية"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"School name (optional)","ar":"اسم المدرسة (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Monthly family income (optional)","ar":"دخل الأسرة الشهري (اختياري)"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Photo of the child (optional)","ar":"صورة الطفل (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"income","text":{"en":"Remove the income only","ar":"احذف الدخل فقط"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"School name","ar":"اسم المدرسة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Photo of the child","ar":"صورة الطفل"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"needed","text":{"en":"Keep the four it needs now; the photo on day one","ar":"أبقِ الأربعة المطلوبة الآن؛ والصورة في اليوم الأول"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Register for the summer football camp","ar":"سجّل في معسكر كرة القدم الصيفي"}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"},{"kind":"small","text":{"en":"Day one: badge photo at the gate","ar":"اليوم الأول: صورة البطاقة عند البوابة"},"gap":"l"}]}}],"answer":["needed"],"misconceptions":[{"id":"MC-P01-005","when":["optional"],"feedback":{"en":"Marked optional, they're still on the form, and many parents will fill them in just in case. Remove what has no use; move what can wait.","ar":"حتى مع وسمها كاختيارية، ما زالت في النموذج، وسيملؤها كثير من الآباء احتياطًا. احذف ما لا فائدة له؛ وانقل ما يمكن أن ينتظر."}},{"id":"MC-P01-002","when":["income"],"feedback":{"en":"A good start, but the school is never used, and the photo isn't needed until the first day. Ask only what registering needs.","ar":"بداية جيدة، لكن المدرسة لا تُستخدم أبدًا، والصورة لا تلزم قبل اليوم الأول. اسأل فقط عمّا يحتاجه التسجيل."}}],"explain":{"en":"From Lesson 1: keep what the task needs now, move what can wait, and remove what nobody uses.","ar":"من الدرس 1: أبقِ ما تحتاجه المهمة الآن، وانقل ما يمكن أن ينتظر، واحذف ما لا يستخدمه أحد."},"speaker":"sara"},{"id":"S03","type":"tune","skill":"SK-P01-U01-03","part":"check","rules":["R19"],"value":{"en":"Skill check, EAS framework (NN/g): a simple, clear explanation reassures people and builds trust. Health details are personal; say who sees them and why.","ar":"اختبار مهارة، إطار EAS (NN/g): الشرح البسيط الواضح يطمئن الناس ويبني الثقة. والتفاصيل الصحية شخصية؛ فوضّح من يراها ولماذا."},"ref":{"url":"https://www.nngroup.com/articles/eas-framework-simplify-forms/","quote":"A simple, clear explanation reassures users, builds trust, and helps them understand the rationale behind each question."},"scenario":{"en":"Ziad has a mild nut allergy. Samir told me he isn't sure he wants to write it down for an academy he doesn't know yet.","ar":"لدى زياد حساسية خفيفة من المكسّرات. وأخبرني سمير أنه لا يعرف هل يريد كتابتها لأكاديمية لا يعرفها بعد."},"prompt":{"en":"Try each version of the health field. Which one should ship?","ar":"جرّب كل نسخة من حقل الصحة. أيّها يجب أن يُطلق؟"},"start":"bare","options":[{"id":"why","text":{"en":"Say who sees it and what it's for","ar":"وضّح من يراه وما الغرض منه"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","hint":{"en":"Only Ziad's coaches see this, so they know what to do in an emergency.","ar":"لا يرى هذا إلا مدرّبو زياد، ليعرفوا ماذا يفعلون في حالة طارئة."}}]}},{"id":"bare","text":{"en":"Just the label","ar":"التسمية فقط"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":""}]}},{"id":"legal","text":{"en":"Add \"We collect this as required by our policies\"","ar":"أضف «نجمع هذا وفقًا لسياساتنا»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","hint":{"en":"We collect this as required by our policies.","ar":"نجمع هذا وفقًا لسياساتنا."}}]}}],"answer":["why"],"misconceptions":[{"id":"MC-P01-027","when":["bare"],"feedback":{"en":"Samir has to guess who reads it and why. A worried parent may leave it vague, which is the worst outcome for Ziad.","ar":"على سمير أن يخمّن من يقرؤه ولماذا. والوالد القلق قد يكتبه بشكل مبهم، وهذه أسوأ نتيجة لزياد."}},{"id":"MC-P01-027","when":["legal"],"feedback":{"en":"That says the academy wants it, not why it helps Ziad. Name who sees it and what they'll do with it.","ar":"هذا يقول إن الأكاديمية تريده، لا لماذا يساعد زياد. اذكر من يراه وماذا سيفعل به."}}],"explain":{"en":"From Lesson 1: when you ask something personal, say why, right at the field.","ar":"من الدرس 1: حين تسأل عن شيء شخصي، وضّح السبب، عند الحقل مباشرة."},"speaker":"sara"},{"id":"S04","type":"tune","skill":"SK-P01-U01-04","part":"check","rules":["R19"],"value":{"en":"Skill check, marking required fields (NN/g): mark every required field, and label the few optional ones. A note at the top is skipped or forgotten.","ar":"اختبار مهارة، تمييز الحقول الإلزامية (NN/g): ميّز كل حقل إلزامي، وسمِّ القليل الاختياري. والملاحظة في الأعلى تُتخطّى أو تُنسى."},"ref":{"url":"https://www.nngroup.com/articles/required-fields/","quote":"People don’t read instructions at the top of forms."},"scenario":{"en":"After my trimming, every field is required except a new one: \"What should the coaches call him?\"","ar":"بعد ما حذفته، كل الحقول إلزامية إلا حقلًا جديدًا: «بماذا يناديه المدرّبون؟»"},"prompt":{"en":"Try each way of marking the form. Which one should ship?","ar":"جرّب كل طريقة لتمييز الحقول. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":""},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"What should the coaches call him?","ar":"بماذا يناديه المدرّبون؟"},"text":"","gap":"s"}]},"options":[{"id":"note","text":{"en":"A note at the top: \"All fields required except the last\"","ar":"ملاحظة في الأعلى: «كل الحقول إلزامية ما عدا الأخير»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"All fields are required except the last one.","ar":"كل الحقول إلزامية ما عدا الأخير."}},{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"What should the coaches call him?","ar":"بماذا يناديه المدرّبون؟"},"text":"","gap":"s"}]}},{"id":"both","text":{"en":"A star on each required field, \"(optional)\" on the last","ar":"نجمة على كل حقل إلزامي، و«(اختياري)» على الأخير"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"* Required","ar":"* إلزامي"}},{"kind":"field","label":{"en":"Child's full name *","ar":"اسم الطفل الكامل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Child's date of birth *","ar":"تاريخ ميلاد الطفل *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number *","ar":"رقم موبايل وليّ الأمر *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions *","ar":"حساسية أو حالات طبية *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":"","gap":"s"}]}},{"id":"optonly","text":{"en":"Only \"(optional)\" on the last field","ar":"«(اختياري)» على الحقل الأخير فقط"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Child's full name","ar":"اسم الطفل الكامل"},"text":""},{"kind":"field","label":{"en":"Child's date of birth","ar":"تاريخ ميلاد الطفل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Allergies or medical conditions","ar":"حساسية أو حالات طبية"},"text":"","gap":"s"},{"kind":"field","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":"","gap":"s"}]}}],"answer":["both"],"misconceptions":[{"id":"MC-P01-028","when":["note"],"feedback":{"en":"Samir may skip the note, or forget it by the last field. Put the answer on each field.","ar":"قد يتخطّى سمير الملاحظة، أو ينساها عند الحقل الأخير. ضع الإجابة عند كل حقل."}},{"id":"MC-P01-028","when":["optonly"],"feedback":{"en":"Nothing tells Samir that the other four must be filled in. If he doesn't notice the word at the end, he guesses. Star the required ones too.","ar":"لا شيء يخبر سمير أن الأربعة الأخرى يجب ملؤها. وإذا لم يلاحظ الكلمة في النهاية، فسيخمّن. ضع نجمة على الإلزامية أيضًا."}}],"explain":{"en":"From Lesson 2: a star on every required field, and \"(optional)\" on the ones people may skip.","ar":"من الدرس 2: نجمة على كل حقل إلزامي، و«(اختياري)» على الحقول التي يمكن تخطّيها."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U01-05","part":"check","rules":["R19"],"value":{"en":"Skill check, cognitive load in forms (NN/g): communicate requirements and set expectations upfront. The coaches only use the nickname if a parent gives one, so the check is wrong, not the label.","ar":"اختبار مهارة، العبء الذهني في النماذج (NN/g): وضّح المتطلبات وحدّد التوقعات مسبقًا. والمدرّبون يستخدمون اسم الدلع فقط إذا أعطاه الوالد، فالتحقق هو الخطأ، لا التسمية."},"ref":{"url":"https://www.nngroup.com/articles/4-principles-reduce-cognitive-load/","quote":"Communicate requirements and set expectations upfront."},"scenario":{"en":"In testing, Samir left the nickname empty and pressed Register. The coaches only use a nickname if a parent gives one.","ar":"في الاختبار، ترك سمير اسم الدلع فارغًا وضغط «سجّل». والمدرّبون يستخدمون اسم الدلع فقط إذا أعطاه الوالد."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":"","error":{"en":"This field is required.","ar":"هذا الحقل إلزامي."}},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]},"options":[{"id":"star","text":{"en":"Make the label required: add a star","ar":"اجعل التسمية إلزامية: أضف نجمة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"What should the coaches call him? *","ar":"بماذا يناديه المدرّبون؟ *"},"text":""},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep it; the error explains what to do","ar":"أبقِه؛ فرسالة الخطأ توضّح ما يجب فعله"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":"","error":{"en":"This field is required.","ar":"هذا الحقل إلزامي."}},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"}]}},{"id":"check","text":{"en":"Fix the check so an empty nickname goes through","ar":"أصلِح التحقق ليمرّ اسم الدلع الفارغ"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"What should the coaches call him? (optional)","ar":"بماذا يناديه المدرّبون؟ (اختياري)"},"text":""},{"kind":"button","text":{"en":"Register","ar":"سجّل"},"gap":"m"},{"kind":"small","color":"green","text":{"en":"Ziad is registered!","ar":"تمّ تسجيل زياد!"},"gap":"s"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-004","when":["star"],"feedback":{"en":"The label and the check now agree, but every parent must invent a nickname the academy doesn't need. Fix the check.","ar":"الآن تتّفق التسمية مع التحقق، لكن على كل والد أن يخترع اسم دلع لا تحتاجه الأكاديمية. أصلِح التحقق."}},{"id":"MC-P01-004","when":["keep"],"feedback":{"en":"The label said he could skip it, and the form punished him for trusting it. Make them agree.","ar":"قالت التسمية إنه يستطيع تخطّيه، ثم عاقبه النموذج لأنه صدّقها. اجعلهما يتّفقان."}}],"explain":{"en":"From Lesson 2: decide what the task needs, then make the label and the check say the same thing.","ar":"من الدرس 2: قرّر ما تحتاجه المهمة، ثم اجعل التسمية والتحقق يقولان الشيء نفسه."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U01-06","part":"check","rules":["R19"],"value":{"en":"Skill check, international sites (NN/g): separate first and last name fields are a prescription for confusion. One full-name field fits every family.","ar":"اختبار مهارة، المواقع الدولية (NN/g): الحقول المنفصلة للاسم الأول واسم العائلة وصفة للارتباك. وحقل واحد للاسم الكامل يناسب كل عائلة."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"Offering separate fields for first name and last name is a prescription for confusion."},"scenario":{"en":"The academy's developer wants to split the child's name so the system can sort by family name.","ar":"يريد مطوّر الأكاديمية تقسيم اسم الطفل ليتمكّن النظام من الترتيب حسب اسم العائلة."},"prompt":{"en":"Try each way of asking for Ziad's name. Which one should ship?","ar":"جرّب كل طريقة لطلب اسم زياد. أيّها يجب أن تُطلق؟"},"start":"split","options":[{"id":"one","text":{"en":"One field: \"Child's full name, as on his birth certificate\"","ar":"حقل واحد: «اسم الطفل الكامل، كما في شهادة الميلاد»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Child's full name, as on his birth certificate *","ar":"اسم الطفل الكامل، كما في شهادة الميلاد *"},"filled":true,"text":{"en":"Ziad Samir Abdelaziz Farid","ar":"زياد سمير عبد العزيز فريد"}}]}},{"id":"split","text":{"en":"Two fields: first name and last name","ar":"حقلان: الاسم الأول واسم العائلة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Child's first name *","ar":"الاسم الأول للطفل *"},"text":""},{"kind":"field","label":{"en":"Child's last name *","ar":"اسم عائلة الطفل *"},"text":"","gap":"s"}]}},{"id":"three","text":{"en":"Three fields: name, father's name, family name","ar":"ثلاثة حقول: الاسم، اسم الأب، اسم العائلة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Child's name *","ar":"اسم الطفل *"},"text":""},{"kind":"field","label":{"en":"Father's name *","ar":"اسم الأب *"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Family name *","ar":"اسم العائلة *"},"text":"","gap":"s"}]}}],"answer":["one"],"misconceptions":[{"id":"MC-P01-006","when":["split"],"feedback":{"en":"Samir has to decide where \"Samir Abdelaziz\" goes, and the next family's names won't fit two boxes either. One field.","ar":"على سمير أن يقرّر أين يكتب «سمير عبد العزيز»، وأسماء العائلة التالية لن تناسب خانتين أيضًا. حقل واحد."}},{"id":"MC-P01-006","when":["three"],"feedback":{"en":"This fits some families and fails others. Names don't share one structure; let each family type theirs.","ar":"هذا يناسب بعض العائلات ويفشل مع غيرها. الأسماء ليس لها بنية واحدة؛ فدع كل عائلة تكتب اسمها."}}],"explain":{"en":"From Lesson 3: one full-name field, typed as on the official document, fits every naming pattern.","ar":"من الدرس 3: حقل واحد للاسم الكامل، يُكتب كما في الوثيقة الرسمية، يناسب كل أنماط الأسماء."},"speaker":"sara"},{"id":"S07","type":"tune","skill":"SK-P01-U01-07","part":"check","rules":["R19"],"value":{"en":"Skill check, international sites (NN/g): allow phone numbers with a country code and a varying number of digits. ⁦+20 10 1234 5678⁩ is the same number as ⁦010 1234 5678⁩.","ar":"اختبار مهارة، المواقع الدولية (NN/g): اسمح بأرقام الهواتف مع رمز الدولة وبعدد أرقام متغيّر. والرقم ‎⁦+20 10 1234 5678⁩ هو نفسه ⁦010 1234 5678⁩."},"ref":{"url":"https://www.nngroup.com/articles/international-sites-requirements/","quote":"For phone numbers, allow for international numbers containing a varying number of digits and a country code."},"scenario":{"en":"In testing, Samir pasted his number from his contacts, with the country code. The form rejected it.","ar":"في الاختبار، لصق سمير رقمه من جهات الاتصال، مع رمز الدولة. فرفضه النموذج."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"filled":true,"text":"⁦+20 10 1234 5678⁩","error":{"en":"Use 11 digits starting with 0.","ar":"استخدم 11 رقمًا تبدأ بـ 0."}}]},"options":[{"id":"hint","text":{"en":"Add a hint: \"Start with 0, no country code\"","ar":"أضف تلميحًا: «ابدأ بـ 0، بدون رمز الدولة»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"text":"","hint":{"en":"Start with 0, no country code, no spaces.","ar":"ابدأ بـ 0، بدون رمز الدولة، بدون مسافات."}}]}},{"id":"accept","text":{"en":"Accept it with or without the country code and spaces","ar":"اقبله برمز الدولة أو بدونه، وبالمسافات"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"},"filled":true,"text":"⁦+20 10 1234 5678⁩"},{"kind":"small","color":"green","text":{"en":"✓ Saved","ar":"✓ تم الحفظ"},"gap":"xs"}]}},{"id":"picker","text":{"en":"Split it: a country box and an 11-digit box","ar":"قسّمه: خانة للدولة وخانة من 11 رقمًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"Parent's mobile number","ar":"رقم موبايل وليّ الأمر"}},{"kind":"row","gap":"s","blocks":[{"kind":"field","text":"⁦+20⁩"},{"kind":"field","tone":"bad","filled":true,"text":"⁦10 1234 5678⁩"}]},{"kind":"small","color":"red","text":{"en":"Use 11 digits starting with 0.","ar":"استخدم 11 رقمًا تبدأ بـ 0."},"gap":"xs"}]}}],"answer":["accept"],"misconceptions":[{"id":"MC-P01-007","when":["hint"],"feedback":{"en":"The number was right. Now Samir has to edit a pasted number by hand on his phone. Let the system tidy it.","ar":"الرقم كان صحيحًا. والآن على سمير أن يعدّل رقمًا ملصوقًا بيده على هاتفه. دع النظام يرتّبه."}},{"id":"MC-P01-007","when":["picker"],"feedback":{"en":"Splitting it still forces one exact shape, and his pasted number breaks again. Accept the number as people write it.","ar":"التقسيم ما زال يفرض شكلًا واحدًا محدّدًا، فيفشل رقمه الملصوق مرة أخرى. اقبل الرقم كما يكتبه الناس."}}],"explain":{"en":"From Lesson 3: accept the formats people actually use, country codes included, and tidy them in the system.","ar":"من الدرس 3: اقبل الصيغ التي يستخدمها الناس فعلًا، بما فيها رموز الدول، ورتّبها في النظام."},"speaker":"sara"}]}$uxg$::jsonb),
  ($uxg$P01-U02-L01$uxg$, $uxg$0b665d175904322987fd233ec4a757bcfc1913e993f18bf9fd0a956cb62595c6$uxg$, $uxg${"id":"P01-U02-L01","mode":"lesson","minutes":8,"title":{"en":"One, many, or a toggle","ar":"خيار واحد، أم عدة خيارات، أم Toggle؟"},"speaker":"nour","review_labels":{"MC-P01-015":{"en":"Don't preselect a guess for a personal answer","ar":"لا تحدّد تخمينًا مسبقًا لإجابة شخصية"},"MC-P01-018":{"en":"A toggle acts now; a checkbox waits for submit","ar":"الـ Toggle يعمل فورًا، والـ Checkbox ينتظر الإرسال"},"MC-P01-031":{"en":"Show a few options; don't hide them in a dropdown","ar":"اعرض الخيارات القليلة؛ لا تُخفِها في قائمة منسدلة"},"MC-P01-032":{"en":"One answer: radio buttons; several: checkboxes","ar":"إجابة واحدة: Radio buttons؛ عدة إجابات: Checkboxes"},"MC-P01-033":{"en":"A safe, common default saves a step","ar":"القيمة الافتراضية الشائعة والآمنة توفّر خطوة"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Ahmed's reminders","ar":"تذكيرات أحمد"},"body":{"en":"Ahmed, one of our patients, opened his profile in our clinic app to update his phone number. On the same screen, he switched visit reminders off. Then he closed the app without pressing Save.\n\nThe reminders kept coming.","ar":"فتح أحمد، أحد مرضانا، ملفه الشخصي في تطبيق عيادتنا لتحديث رقم هاتفه. وفي الشاشة نفسها، أطفأ تذكيرات المواعيد. ثم أغلق التطبيق دون أن يضغط «حفظ».\n\nوظلّت التذكيرات تصل."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"toggle","text":{"en":"Visit reminders","ar":"تذكيرات المواعيد"},"gap":"m"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U02-01","part":"try","rules":["R12"],"value":{"en":"Try first. Toggle switches (NN/g): toggles should give immediate results. A toggle inside a form with a Save button leaves people unsure whether it took effect; separate instant controls from ones that wait for a button.","ar":"جرّب أولًا. الـ Toggle switches (NN/g): يجب أن يعطي الـ Toggle نتيجة فورية. ووضعه داخل نموذج فيه زر «حفظ» يترك الناس غير متأكّدين هل نُفّذ التغيير؛ فافصل العناصر الفورية عن تلك التي تنتظر زرًا."},"ref":{"url":"https://www.nngroup.com/articles/toggle-switch-guidelines/","quote":"Separate controls that produce instant results from those that require clicking a command button."},"scenario":{"en":"Our profile screen needs its Save button for the phone number. My team wants to keep the reminders setting on the same screen.","ar":"شاشة الملف الشخصي عندنا تحتاج زر «حفظ» من أجل رقم الهاتف. ويريد فريقي إبقاء إعداد التذكيرات في الشاشة نفسها."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"toggle","text":{"en":"Visit reminders","ar":"تذكيرات المواعيد"},"gap":"m"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"m"}]},"options":[{"id":"note","text":{"en":"Keep the toggle; add \"Press Save to apply changes\"","ar":"أبقِ الـ Toggle؛ وأضف «اضغط حفظ لتطبيق التغييرات»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"toggle","text":{"en":"Visit reminders","ar":"تذكيرات المواعيد"},"gap":"m"},{"kind":"small","text":{"en":"Press Save to apply changes.","ar":"اضغط «حفظ» لتطبيق التغييرات."},"gap":"s"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"s"}]}},{"id":"check","text":{"en":"Use a checkbox that's saved with the form","ar":"استخدم Checkbox يُحفظ مع النموذج"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"check","selected":true,"text":{"en":"Send me visit reminders","ar":"أرسل لي تذكيرات المواعيد"},"gap":"m"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep it as it is; people know to press Save","ar":"أبقِه كما هو؛ فالناس يعرفون أن يضغطوا «حفظ»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"My profile","ar":"ملفي الشخصي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦010 9876 5432⁩","gap":"m"},{"kind":"toggle","text":{"en":"Visit reminders","ar":"تذكيرات المواعيد"},"gap":"m"},{"kind":"button","text":{"en":"Save","ar":"حفظ"},"gap":"m"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-018","when":["keep"],"feedback":{"en":"A toggle looks like a light switch, so Ahmed expected it to work the moment he flipped it. On a screen that waits for Save, it breaks that promise.","ar":"الـ Toggle يشبه مفتاح الإضاءة، فتوقّع أحمد أن يعمل لحظة تحريكه. وفي شاشة تنتظر «حفظ»، يُخلف هذا الوعد."}},{"id":"MC-P01-018","when":["note"],"feedback":{"en":"The note fights the control. The toggle still says \"done\"; few people read the line under it. Use a control that waits, like a checkbox.","ar":"الملاحظة تعارض العنصر. فالـ Toggle ما زال يقول «تمّ»؛ وقليلون يقرؤون السطر تحته. استخدم عنصرًا ينتظر، مثل الـ Checkbox."}}],"hints":[{"en":"When does the reminders change happen: at once, or when Ahmed presses Save?","ar":"متى يحدث تغيير التذكيرات: فورًا، أم عندما يضغط أحمد «حفظ»؟"},{"en":"A toggle promises \"right now\". Does this screen keep that promise?","ar":"الـ Toggle يعد بالتنفيذ «الآن». هل تفي هذه الشاشة بهذا الوعد؟"}],"correct":{"en":"In a form that waits for Save, use a checkbox.","ar":"في نموذج ينتظر «حفظ»، استخدم Checkbox."},"explain":{"en":"A checkbox doesn't promise instant action, so it fits a form that applies changes on Save. Keep toggles for settings that work the moment you flip them.","ar":"الـ Checkbox لا يَعِد بتنفيذ فوري، لذلك يناسب نموذجًا يطبّق التغييرات عند «حفظ». واحتفظ بالـ Toggle للإعدادات التي تعمل لحظة تحريكها."},"speaker":"nour"},{"id":"S03","type":"card","part":"concept","icons":["form","list","clock","idea"],"title":{"en":"Each control makes a promise","ar":"كل عنصر تحكّم يَعِد بشيء"},"body":{"en":"People read a control's shape before its label. Pick the one whose promise matches what happens.\n\n- **Radio buttons:** pick exactly one. All the choices are visible.\n- **Checkboxes:** pick any number, including none. Each box works on its own.\n- **Toggle:** on or off, right now. Use it for settings that apply instantly.\n- **Dropdown:** hides the choices behind a tap. With only a few options, show them as radio buttons instead.\n- **A default choice** saves a step when one answer is common and safe. Don't preselect a guess about someone's personal life.","ar":"يقرأ الناس شكل العنصر قبل تسميته. فاختر العنصر الذي يطابق وعدُه ما يحدث فعلًا.\n\n- **الـ Radio buttons:** اختر واحدًا فقط. وكل الخيارات ظاهرة.\n- **الـ Checkboxes:** اختر أي عدد، حتى لا شيء. وكل مربع يعمل وحده.\n- **الـ Toggle:** تشغيل أو إيقاف، الآن. استخدمه للإعدادات التي تُطبَّق فورًا.\n- **القائمة المنسدلة (Dropdown):** تُخفي الخيارات خلف ضغطة. ومع خيارات قليلة، اعرضها كـ Radio buttons بدلًا منها.\n- **الخيار الافتراضي** يوفّر خطوة حين تكون إجابة واحدة شائعة وآمنة. ولا تحدّد مسبقًا تخمينًا عن حياة شخص الخاصة."}},{"id":"S04","type":"tune","skill":"SK-P01-U02-02","part":"guided","rules":["R06","R15"],"value":{"en":"Dropdown lists (NN/g): when a handful of options fits on screen, a dropdown adds more friction than value. Radio buttons show every choice and take one tap.","ar":"القوائم المنسدلة (NN/g): حين تتّسع الشاشة لعدد قليل من الخيارات، تضيف القائمة المنسدلة عناءً أكثر من فائدتها. والـ Radio buttons تعرض كل خيار وتحتاج ضغطة واحدة."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"When a handful of options can comfortably fit on screen, a dropdown adds more friction than real value."},"scenario":{"en":"Ahmed is booking a visit with us. It can be in person or a video call, never both.","ar":"يحجز أحمد موعدًا عندنا. ويمكن أن يكون حضوريًا أو مكالمة فيديو، ولا يكون الاثنين معًا."},"prompt":{"en":"Try each control for the visit type. Which one should ship?","ar":"جرّب كل عنصر لنوع الزيارة. أيّها يجب أن يُطلق؟"},"start":"dropdown","options":[{"id":"dropdown","text":{"en":"A dropdown","ar":"قائمة منسدلة"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Visit type","ar":"نوع الزيارة"},"text":{"en":"Select…","ar":"اختر…"}}]}},{"id":"checks","text":{"en":"Two checkboxes","ar":"مربّعا Checkbox"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Visit type","ar":"نوع الزيارة"}},{"kind":"check","text":{"en":"In person","ar":"حضوري"},"gap":"xs"},{"kind":"check","text":{"en":"Video call","ar":"مكالمة فيديو"},"gap":"xs"}]}},{"id":"radios","text":{"en":"Two radio buttons","ar":"زرّا Radio"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Visit type","ar":"نوع الزيارة"}},{"kind":"radio","text":{"en":"In person","ar":"حضوري"},"gap":"xs"},{"kind":"radio","text":{"en":"Video call","ar":"مكالمة فيديو"},"gap":"xs"}]}}],"answer":["radios"],"misconceptions":[{"id":"MC-P01-031","when":["dropdown"],"feedback":{"en":"Ahmed has to open it to find out there are only two choices, then tap again. Two options fit on screen; show them.","ar":"على أحمد أن يفتحها ليكتشف أن هناك خيارين فقط، ثم يضغط مرة أخرى. والخياران يتّسعان على الشاشة؛ فاعرضهما."}},{"id":"MC-P01-032","when":["checks"],"feedback":{"en":"Checkboxes say \"pick any\", so Ahmed could tick both, or neither. A visit is one or the other: that's a radio choice.","ar":"الـ Checkboxes تقول «اختر أيًّا منها»، فقد يحدّد أحمد الاثنين، أو لا شيء. والزيارة إما هذا أو ذاك: وهذا اختيار Radio."}}],"hints":[{"en":"Can a visit be in person and a video call at the same time?","ar":"هل يمكن أن تكون الزيارة حضورية ومكالمة فيديو في الوقت نفسه؟"},{"en":"With just two choices, should Ahmed have to tap to see them?","ar":"مع خيارين فقط، هل يجب أن يضغط أحمد لكي يراهما؟"}],"correct":{"en":"One of a few: radio buttons.","ar":"واحد من خيارات قليلة: Radio buttons."},"explain":{"en":"Radio buttons show every choice at once and allow exactly one. For two to about five options, they're the fastest and clearest.","ar":"الـ Radio buttons تعرض كل الخيارات مرة واحدة وتسمح باختيار واحد فقط. ومن خيارين إلى نحو خمسة، هي الأسرع والأوضح."},"speaker":"nour"},{"id":"S05","type":"tune","skill":"SK-P01-U02-02","part":"guided","rules":["R06","R15"],"value":{"en":"Checkboxes (NN/g): a checkbox list lets people select one, several, all, or none. Allergies are any number, so radio buttons or a single-select dropdown lose answers.","ar":"الـ Checkboxes (NN/g): قائمة الـ Checkboxes تتيح اختيار واحد أو عدة أو الكل أو لا شيء. والحساسية قد تكون أي عدد، فالـ Radio buttons أو القائمة المنسدلة ذات الاختيار الواحد تُضيّع إجابات."},"ref":{"url":"https://www.nngroup.com/articles/checkboxes-design-guidelines/","quote":"A checkbox list allows users the unique ability to select one, several, all, or no items from a list."},"scenario":{"en":"Ahmed is allergic to penicillin and to nuts. Our health form asks about common allergies.","ar":"لدى أحمد حساسية من البنسلين ومن المكسّرات. ونموذج الصحة عندنا يسأل عن أنواع الحساسية الشائعة."},"prompt":{"en":"Try each control. Which one lets Ahmed tell the doctor everything?","ar":"جرّب كل عنصر. أيّها يتيح لأحمد أن يخبر الطبيب بكل شيء؟"},"start":"radio","options":[{"id":"radio","text":{"en":"Radio buttons","ar":"Radio buttons"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Allergies","ar":"الحساسية"}},{"kind":"radio","selected":true,"text":{"en":"Penicillin","ar":"البنسلين"},"gap":"xs"},{"kind":"radio","text":{"en":"Nuts","ar":"المكسّرات"},"gap":"xs"},{"kind":"radio","text":{"en":"Latex","ar":"اللاتكس"},"gap":"xs"}]}},{"id":"check","text":{"en":"Checkboxes","ar":"Checkboxes"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Allergies (tick all that apply)","ar":"الحساسية (حدّد كل ما ينطبق)"}},{"kind":"check","selected":true,"text":{"en":"Penicillin","ar":"البنسلين"},"gap":"xs"},{"kind":"check","selected":true,"text":{"en":"Nuts","ar":"المكسّرات"},"gap":"xs"},{"kind":"check","text":{"en":"Latex","ar":"اللاتكس"},"gap":"xs"}]}},{"id":"select","text":{"en":"A dropdown","ar":"قائمة منسدلة"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Allergies","ar":"الحساسية"},"filled":true,"text":{"en":"Penicillin","ar":"البنسلين"}}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-032","when":["radio","select"],"feedback":{"en":"This control allows one answer. When Ahmed picks nuts, penicillin disappears, and the doctor never learns about it.","ar":"هذا العنصر يسمح بإجابة واحدة. فحين يختار أحمد المكسّرات، يختفي البنسلين، ولا يعرف الطبيب به أبدًا."}}],"hints":[{"en":"How many allergies does Ahmed have?","ar":"كم حساسية لدى أحمد؟"},{"en":"Which control lets him pick more than one answer?","ar":"أي عنصر يسمح له باختيار أكثر من إجابة؟"}],"correct":{"en":"Any number of answers: checkboxes.","ar":"أي عدد من الإجابات: Checkboxes."},"explain":{"en":"Each checkbox works on its own, so Ahmed can tick both allergies. The label \"tick all that apply\" removes any doubt.","ar":"كل Checkbox يعمل وحده، فيستطيع أحمد تحديد نوعي الحساسية. وعبارة «حدّد كل ما ينطبق» تُزيل أي شك."},"speaker":"nour"},{"id":"S06","type":"tune","skill":"SK-P01-U02-03","part":"guided","rules":["R06","R15"],"value":{"en":"Radio-button defaults (NN/g): a presumptuous or alienating choice is the most valid reason not to preselect. A guessed marital status is presumptuous, wrong for many, and easy to leave unchanged.","ar":"الخيار الافتراضي في الـ Radio buttons (NN/g): الاختيار المتسرّع في الافتراض أو المنفّر هو أقوى سبب لعدم التحديد المسبق. والحالة الاجتماعية المخمّنة افتراض متسرّع، وخاطئة لكثيرين، وسهل أن تُترك دون تغيير."},"ref":{"url":"https://www.nngroup.com/articles/radio-buttons-default-selection/","quote":"This is probably the most valid reason for not selecting a radio button by default."},"scenario":{"en":"Our doctor needs Ahmed's marital status for some treatments. Most of our patients are married, so the form preselects \"Married\".","ar":"يحتاج طبيبنا الحالة الاجتماعية لأحمد لبعض العلاجات. وأغلب مرضانا متزوّجون، فيحدّد النموذج «متزوّج» مسبقًا."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Marital status","ar":"الحالة الاجتماعية"}},{"kind":"radio","selected":true,"text":{"en":"Married","ar":"متزوّج"},"gap":"xs"},{"kind":"radio","text":{"en":"Single","ar":"أعزب"},"gap":"xs"},{"kind":"radio","text":{"en":"Divorced","ar":"مطلّق"},"gap":"xs"},{"kind":"radio","text":{"en":"Widowed","ar":"أرمل"},"gap":"xs"}]},"options":[{"id":"none","text":{"en":"No option selected; he chooses","ar":"بلا خيار محدّد؛ وهو يختار"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Marital status","ar":"الحالة الاجتماعية"}},{"kind":"radio","text":{"en":"Married","ar":"متزوّج"},"gap":"xs"},{"kind":"radio","text":{"en":"Single","ar":"أعزب"},"gap":"xs"},{"kind":"radio","text":{"en":"Divorced","ar":"مطلّق"},"gap":"xs"},{"kind":"radio","text":{"en":"Widowed","ar":"أرمل"},"gap":"xs"}]}},{"id":"keep","text":{"en":"Keep \"Married\" preselected; it's the most common","ar":"أبقِ «متزوّج» محدّدًا مسبقًا؛ فهو الأكثر شيوعًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Marital status","ar":"الحالة الاجتماعية"}},{"kind":"radio","selected":true,"text":{"en":"Married","ar":"متزوّج"},"gap":"xs"},{"kind":"radio","text":{"en":"Single","ar":"أعزب"},"gap":"xs"},{"kind":"radio","text":{"en":"Divorced","ar":"مطلّق"},"gap":"xs"},{"kind":"radio","text":{"en":"Widowed","ar":"أرمل"},"gap":"xs"}]}},{"id":"hide","text":{"en":"Move it into a dropdown, with \"Married\" showing","ar":"انقله إلى قائمة منسدلة، تظهر فيها «متزوّج»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"select","label":{"en":"Marital status","ar":"الحالة الاجتماعية"},"filled":true,"text":{"en":"Married","ar":"متزوّج"}}]}}],"answer":["none"],"misconceptions":[{"id":"MC-P01-015","when":["keep"],"feedback":{"en":"For a single patient in a hurry, \"Married\" stays and the doctor's record is wrong. A personal answer shouldn't start as a guess.","ar":"إذا كان المريض أعزب ومستعجلًا، فستبقى «متزوّج» ويصبح سجل الطبيب خاطئًا. والإجابة الشخصية لا يجب أن تبدأ بتخمين."}},{"id":"MC-P01-015","when":["hide"],"feedback":{"en":"Same guess, now harder to see: a filled dropdown looks already answered. People rarely open it to check.","ar":"التخمين نفسه، لكنه الآن أصعب في الرؤية: القائمة المنسدلة الممتلئة تبدو مُجابة بالفعل. ونادرًا ما يفتحها الناس للتحقّق."}}],"hints":[{"en":"Whose answer is this: the clinic's guess, or Ahmed's?","ar":"إجابة من هذه: تخمين العيادة، أم إجابة أحمد؟"},{"en":"If he skims past a wrong preselected answer, what does the doctor see?","ar":"إذا مرّ أحمد سريعًا على إجابة محدّدة مسبقًا وخاطئة، ماذا سيرى الطبيب؟"}],"correct":{"en":"Let him choose a personal answer.","ar":"دعه يختار الإجابة الشخصية."},"explain":{"en":"A default is a suggestion, and people often keep suggestions. For something personal, no suggestion is the respectful and accurate choice.","ar":"الخيار الافتراضي اقتراح، والناس كثيرًا ما يُبقون الاقتراحات. وفي الأمور الشخصية، عدم الاقتراح هو الخيار المحترم والدقيق."},"speaker":"nour"},{"id":"S07","type":"compare","skill":"SK-P01-U02-03","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S06: defaults aren't bad in general. Radio-button defaults (NN/g): select one by default in most cases. A common, harmless setting like reminder timing should start on the usual choice.","ar":"مقارنة مع الخطوة 6: الخيار الافتراضي ليس سيئًا بشكل عام. الخيار الافتراضي في الـ Radio buttons (NN/g): حدّد خيارًا افتراضيًا في أغلب الحالات. والإعداد الشائع غير الضار، مثل توقيت التذكير، يجب أن يبدأ بالاختيار المعتاد."},"ref":{"url":"https://www.nngroup.com/articles/radio-buttons-default-selection/","quote":"Select a single radio button by default in most cases."},"scenario":{"en":"Ahmed turns reminders on. Almost everyone wants theirs one day before; either choice is easy to change later.","ar":"يشغّل أحمد التذكيرات. وأغلب الناس يريدون التذكير قبل يوم؛ وأي اختيار سهل التغيير لاحقًا."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Remind me","ar":"ذكّرني"}},{"kind":"radio","text":{"en":"1 day before","ar":"قبل الموعد بيوم"},"gap":"xs"},{"kind":"radio","text":{"en":"2 hours before","ar":"قبل الموعد بساعتين"},"gap":"xs"},{"kind":"radio","text":{"en":"Both","ar":"الاثنان"},"gap":"xs"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Remind me","ar":"ذكّرني"}},{"kind":"radio","selected":true,"text":{"en":"1 day before","ar":"قبل الموعد بيوم"},"gap":"xs"},{"kind":"radio","text":{"en":"2 hours before","ar":"قبل الموعد بساعتين"},"gap":"xs"},{"kind":"radio","text":{"en":"Both","ar":"الاثنان"},"gap":"xs"}]}},"answer":"b","reason":{"prompt":{"en":"Why is a default right here, but wrong for marital status?","ar":"لماذا يصحّ الخيار الافتراضي هنا، ويخطئ في الحالة الاجتماعية؟"},"options":[{"id":"safe","text":{"en":"It's the usual choice, and leaving it costs nothing","ar":"إنه الاختيار المعتاد، وتركه لا يكلّف شيئًا"}},{"id":"always","text":{"en":"Radio buttons always need a default","ar":"الـ Radio buttons تحتاج دائمًا خيارًا افتراضيًا"}},{"id":"short","text":{"en":"The list is shorter","ar":"القائمة أقصر"}}],"answer":["safe"],"misconceptions":[{"id":"MC-P01-033","when":["always","short"],"feedback":{"en":"Length and habit aren't the reason. It's about the cost of a wrong default: here it's a slightly early reminder; there it's a wrong medical record.","ar":"الطول والعادة ليسا السبب. السبب هو كلفة الخيار الافتراضي الخاطئ: هنا تذكير أبكر قليلًا؛ وهناك سجل طبي خاطئ."}}]},"misconceptions":[{"id":"MC-P01-033","when":["a"],"feedback":{"en":"A makes everyone choose, though nearly all pick \"1 day before\". With a safe, common answer, start there.","ar":"A تجعل الجميع يختارون، مع أن أغلبهم يختار «قبل الموعد بيوم». ومع إجابة شائعة وآمنة، ابدأ بها."}}],"hints":[{"en":"Is this a personal answer, or a common and harmless setting?","ar":"هل هذه إجابة شخصية، أم إعداد شائع ولا ضرر منه؟"},{"en":"If almost everyone picks the same one and it's easy to change, does it need an empty start?","ar":"إذا اختار الجميع تقريبًا الخيار نفسه وكان تغييره سهلًا، فهل يحتاج أن يبدأ فارغًا؟"}],"correct":{"en":"Common and harmless: preselect it.","ar":"شائع وغير ضار: حدّده مسبقًا."},"explain":{"en":"Ask what happens if someone leaves the default. If the answer is \"nothing bad\", a default saves a step. If it's a wrong record, let them choose.","ar":"اسأل ماذا يحدث إذا ترك أحد الخيار الافتراضي. إذا كانت الإجابة «لا شيء سيئ»، فالخيار الافتراضي يوفّر خطوة. وإذا كانت سجلًا خاطئًا، فدعه يختار."},"speaker":"nour"},{"id":"S08","type":"tune","skill":"SK-P01-U02-01","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Toggle switches (NN/g): a toggle inside a form that waits for a button leaves people unsure whether their choice took effect. Tamer's checkout only applies choices on Place order.","ar":"حالة جديدة. الـ Toggle switches (NN/g): الـ Toggle داخل نموذج ينتظر زرًا يترك الناس غير متأكّدين هل نُفّذ اختيارهم. وصفحة الدفع عند تامر تطبّق الاختيارات فقط عند «أكّد الطلب»."},"ref":{"url":"https://www.nngroup.com/articles/toggle-switch-guidelines/","quote":"This scenario confuses users because they can’t be sure whether their toggle choice will take immediate effect."},"scenario":{"en":"In our lunch app, Tamer's checkout has a \"Leave it at the door\" toggle above Place order. Nothing is sent to the driver until he places the order.","ar":"في تطبيق الغداء عندنا، فيه Toggle «اتركه عند الباب» فوق «أكّد الطلب» في صفحة الدفع عند تامر. ولا يُرسل شيء للسائق حتى يؤكّد الطلب."},"prompt":{"en":"Try each control. Which one should ship?","ar":"جرّب كل عنصر. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"12 Nile St, 3rd floor","ar":"12 شارع النيل، الدور الثالث"}},{"kind":"toggle","text":{"en":"Leave it at the door","ar":"اتركه عند الباب"},"gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]},"options":[{"id":"select","text":{"en":"A dropdown: Yes / No","ar":"قائمة منسدلة: نعم / لا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"12 Nile St, 3rd floor","ar":"12 شارع النيل، الدور الثالث"}},{"kind":"select","label":{"en":"Leave it at the door?","ar":"تتركه عند الباب؟"},"text":{"en":"Select…","ar":"اختر…"},"gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep the toggle","ar":"أبقِ الـ Toggle"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"12 Nile St, 3rd floor","ar":"12 شارع النيل، الدور الثالث"}},{"kind":"toggle","text":{"en":"Leave it at the door","ar":"اتركه عند الباب"},"gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"check","text":{"en":"A checkbox, sent with the order","ar":"Checkbox يُرسل مع الطلب"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"12 Nile St, 3rd floor","ar":"12 شارع النيل، الدور الثالث"}},{"kind":"check","text":{"en":"Leave it at the door","ar":"اتركه عند الباب"},"gap":"m"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-018","when":["keep"],"feedback":{"en":"Flipping the toggle looks like it's done. Tamer might flip it, change his mind about ordering, and wonder whether the driver was told.","ar":"تحريك الـ Toggle يبدو كأن الأمر تمّ. وقد يحرّكه تامر، ثم يغيّر رأيه في الطلب، ويتساءل هل أُبلغ السائق."}},{"id":"MC-P01-031","when":["select"],"feedback":{"en":"A yes/no hidden in a dropdown takes two taps and hides the choice. One checkbox says it in one tap.","ar":"سؤال نعم/لا مخفي في قائمة منسدلة يحتاج ضغطتين ويُخفي الاختيار. وCheckbox واحد يقولها بضغطة واحدة."}}],"hints":[{"en":"When does the driver get this choice: when Tamer flips it, or when he places the order?","ar":"متى يصل هذا الاختيار إلى السائق: عندما يغيّره تامر، أم عندما يرسل الطلب؟"},{"en":"Which control says \"this is saved with the form\"?","ar":"أي عنصر يقول «هذا يُحفظ مع النموذج»؟"}],"correct":{"en":"Part of the order: a checkbox.","ar":"جزء من الطلب: Checkbox."},"explain":{"en":"The choice only matters once he places the order, so it belongs with the order. A checkbox waits for the button, like the rest of the form.","ar":"الاختيار لا يهم إلا عند تأكيد الطلب، فمكانه مع الطلب. والـ Checkbox ينتظر الزر، مثل باقي النموذج."}},{"id":"S09","type":"card","part":"recap","icons":["form","list","clock","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Toggle or checkbox:** used checkboxes in forms that wait for Save or a submit button.\n- **One of a few:** showed two choices as radio buttons, not a dropdown.\n- **Any number:** used checkboxes so every allergy reached the doctor.\n- **Personal answers:** left them unselected.\n- **Safe, common choices:** preselected them to save a step.\n\nNext lesson: typing, picking, and the controls in between.","ar":"- **Toggle أم Checkbox:** استخدمت الـ Checkboxes في النماذج التي تنتظر «حفظ» أو زر إرسال.\n- **واحد من خيارات قليلة:** عرضت خيارين كـ Radio buttons، لا كقائمة منسدلة.\n- **أي عدد:** استخدمت الـ Checkboxes لتصل كل أنواع الحساسية إلى الطبيب.\n- **الإجابات الشخصية:** تركتها دون تحديد.\n- **الاختيارات الشائعة والآمنة:** حدّدتها مسبقًا لتوفير خطوة.\n\nالدرس التالي: الكتابة والاختيار والعناصر بينهما."}}]}$uxg$::jsonb),
  ($uxg$P01-U02-L02$uxg$, $uxg$1c58efc6ee9eb14fb4b4dcdb5fb1c4e910dc9adbf8313eb470ec11a28d3a62c3$uxg$, $uxg${"id":"P01-U02-L02","mode":"lesson","minutes":8,"title":{"en":"Type, pick, or step","ar":"تكتب، أم تختار، أم تزيد وتنقص؟"},"speaker":"nour","review_labels":{"MC-P01-012":{"en":"Let people type what they know by heart","ar":"دع الناس يكتبون ما يحفظونه"},"MC-P01-013":{"en":"Let people pick what only the system knows","ar":"دع الناس يختارون ما لا يعرفه إلا النظام"},"MC-P01-021":{"en":"IDs and codes are text made of digits","ar":"الأرقام التعريفية والرموز نص مكوّن من أرقام"},"MC-P01-022":{"en":"Sliders are for rough values","ar":"الـ Slider للقيم التقريبية"},"MC-P01-023":{"en":"Small counts near a default: a stepper","ar":"الأعداد الصغيرة القريبة من قيمة شائعة: Stepper"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Ahmed's date of birth","ar":"تاريخ ميلاد أحمد"},"body":{"en":"We ask for Ahmed's date of birth. Tapping the field opens a calendar on today's month, October 2026.\n\nAhmed was born in March 1991.","ar":"نطلب تاريخ ميلاد أحمد. والضغط على الحقل يفتح تقويمًا على الشهر الحالي، أكتوبر 2026.\n\nوأحمد مولود في مارس 1991."},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"text","text":"‹"},{"kind":"text","weight":"bold","text":{"en":"October 2026","ar":"أكتوبر 2026"}},{"kind":"text","text":"›"}]},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":"1"},{"kind":"chip","tone":"off","text":"2"},{"kind":"chip","tone":"off","text":"3"},{"kind":"chip","tone":"off","text":"4"},{"kind":"chip","tone":"off","text":"5"},{"kind":"chip","tone":"off","text":"6"},{"kind":"chip","tone":"off","text":"7"}]}]}},{"id":"S02","type":"tune","skill":"SK-P01-U02-04","part":"try","rules":["R12"],"value":{"en":"Try first. Date input (NN/g): calendar pickers suit dates close to now, within a year. Split dropdowns for day, month and year take many unnecessary steps. Let people type a date they know.","ar":"جرّب أولًا. إدخال التاريخ (NN/g): التقويم يناسب التواريخ القريبة من الآن، خلال سنة. والقوائم المنسدلة المنفصلة لليوم والشهر والسنة تحتاج خطوات كثيرة غير ضرورية. دع الناس يكتبون تاريخًا يعرفونه."},"ref":{"url":"https://www.nngroup.com/articles/date-input/","quote":"Calendar pickers should be used for events close to the present time — within less than a year."},"prompt":{"en":"Try each way of asking for his date of birth. Which one should ship?","ar":"جرّب كل طريقة لطلب تاريخ ميلاده. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"text","text":"‹"},{"kind":"text","weight":"bold","text":{"en":"October 2026","ar":"أكتوبر 2026"}},{"kind":"text","text":"›"}]},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":"1"},{"kind":"chip","tone":"off","text":"2"},{"kind":"chip","tone":"off","text":"3"},{"kind":"chip","tone":"off","text":"4"},{"kind":"chip","tone":"off","text":"5"},{"kind":"chip","tone":"off","text":"6"},{"kind":"chip","tone":"off","text":"7"}]}]},"options":[{"id":"dropdowns","text":{"en":"Three dropdowns: day, month, year","ar":"ثلاث قوائم منسدلة: اليوم، الشهر، السنة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"select","label":{"en":"Day","ar":"اليوم"},"text":"1"},{"kind":"select","label":{"en":"Month","ar":"الشهر"},"text":{"en":"Jan","ar":"يناير"}},{"kind":"select","label":{"en":"Year","ar":"السنة"},"text":"2026"}]},{"kind":"small","text":{"en":"Year list: 2026 down to 1926","ar":"قائمة السنوات: من 2026 حتى 1926"},"gap":"xs"}]}},{"id":"typed","text":{"en":"Three short fields he types into","ar":"ثلاثة حقول قصيرة يكتب فيها"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"field","label":{"en":"Day","ar":"اليوم"},"filled":true,"text":"14"},{"kind":"field","label":{"en":"Month","ar":"الشهر"},"filled":true,"text":"3"},{"kind":"field","label":{"en":"Year","ar":"السنة"},"filled":true,"text":"1991"}]}]}},{"id":"year","text":{"en":"Keep the calendar; add a year dropdown on top","ar":"أبقِ التقويم؛ وأضف قائمة منسدلة للسنة فوقه"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Date of birth","ar":"تاريخ الميلاد"}},{"kind":"row","gap":"s","blocks":[{"kind":"select","text":{"en":"October","ar":"أكتوبر"}},{"kind":"select","text":"2026"}]},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":"1"},{"kind":"chip","tone":"off","text":"2"},{"kind":"chip","tone":"off","text":"3"},{"kind":"chip","tone":"off","text":"4"},{"kind":"chip","tone":"off","text":"5"},{"kind":"chip","tone":"off","text":"6"},{"kind":"chip","tone":"off","text":"7"}]}]}}],"answer":["typed"],"misconceptions":[{"id":"MC-P01-012","when":["dropdowns"],"feedback":{"en":"Each dropdown is a tap, a scroll and another tap, and the year list is a hundred items long. He knows the answer; let him type it.","ar":"كل قائمة منسدلة ضغطة وتمرير وضغطة أخرى، وقائمة السنوات طولها مئة عنصر. وهو يعرف الإجابة؛ فدعه يكتبها."}},{"id":"MC-P01-012","when":["year"],"feedback":{"en":"Better than going back 427 months, but he still scrolls 35 years, picks a month, then finds the day. Three typed numbers are faster.","ar":"أفضل من الرجوع 427 شهرًا، لكنه ما زال يمرّر 35 سنة، ويختار الشهر، ثم يبحث عن اليوم. وثلاثة أرقام مكتوبة أسرع."}}],"hints":[{"en":"Where does Ahmed's date of birth live: in the system, or in his head?","ar":"أين يوجد تاريخ ميلاد أحمد: في النظام، أم في ذهنه؟"},{"en":"How many taps does each version need to reach March 1991?","ar":"كم ضغطة تحتاج كل نسخة للوصول إلى مارس 1991؟"}],"correct":{"en":"He knows it by heart: let him type it.","ar":"يحفظه عن ظهر قلب: فدعه يكتبه."},"explain":{"en":"Typing 14, 3, 1991 takes seconds. Labelled Day, Month and Year fields remove any doubt about the order. Calendars are for dates people don't know yet.","ar":"كتابة 14 و3 و1991 تأخذ ثواني. والحقول المسمّاة اليوم والشهر والسنة تُزيل أي شك في الترتيب. والتقويم للتواريخ التي لا يعرفها الناس بعد."}},{"id":"S03","type":"card","part":"concept","icons":["form","clock","list","idea"],"title":{"en":"Who knows the answer?","ar":"من يعرف الإجابة؟"},"body":{"en":"Choose the control by asking where the answer lives.\n\n- **In the person's head:** let them type. A date of birth fits three labelled fields.\n- **Only in the system:** let them pick, like free appointment days. Gray out and disable what isn't available.\n- **A small count with a usual value:** a **stepper** (− and +), starting at that value.\n- **Exact numbers:** a text field. A **slider** is for exploring a range, and pairs well with fields for exact values.\n- **IDs and codes:** a text field that opens the number pad. They're labels made of digits, not amounts.","ar":"اختر العنصر بسؤال: أين توجد الإجابة؟\n\n- **في رأس الشخص:** دعه يكتب. وتاريخ الميلاد يناسبه ثلاثة حقول مسمّاة.\n- **في النظام فقط:** دعه يختار، مثل أيام المواعيد المتاحة. واجعل غير المتاح رماديًا ومعطّلًا.\n- **عدد صغير له قيمة معتادة:** **Stepper** (− و+)، يبدأ من تلك القيمة.\n- **الأرقام الدقيقة:** حقل نص. والـ **Slider** لاستكشاف مدى، ويعمل جيدًا مع حقول للقيم الدقيقة.\n- **الأرقام التعريفية والرموز:** حقل نص يفتح لوحة الأرقام. فهي تسميات مكوّنة من أرقام، لا كميات."}},{"id":"S04","type":"tune","skill":"SK-P01-U02-05","part":"guided","rules":["R06","R15"],"value":{"en":"Date input (NN/g): make choices clear by disabling and graying out options that aren't available. Only the clinic knows which days the doctor works.","ar":"إدخال التاريخ (NN/g): وضّح الاختيارات بتعطيل الخيارات غير المتاحة وجعلها رمادية. والعيادة وحدها تعرف الأيام التي يعمل فيها الطبيب."},"ref":{"url":"https://www.nngroup.com/articles/date-input/","quote":"Make the choices clear by disabling and graying out options that are not available or are illogical pairs."},"scenario":{"en":"Ahmed needs a visit next week. Dr. Hany, one of our doctors, sees patients only on Sundays and Wednesdays.","ar":"يحتاج أحمد موعدًا الأسبوع القادم. ود. هاني، أحد أطبائنا، يستقبل المرضى يومي الأحد والأربعاء فقط."},"prompt":{"en":"Try each way of picking the day. Which one should ship?","ar":"جرّب كل طريقة لاختيار اليوم. أيّها يجب أن تُطلق؟"},"start":"field","options":[{"id":"field","text":{"en":"A date field he types into","ar":"حقل تاريخ يكتب فيه"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Visit date","ar":"تاريخ الزيارة"},"filled":true,"text":{"en":"Tue 3 November","ar":"الثلاثاء 3 نوفمبر"}},{"kind":"small","color":"red","text":{"en":"Dr. Hany isn't available on this day.","ar":"د. هاني غير متاح في هذا اليوم."},"gap":"xs"}]}},{"id":"all","text":{"en":"A calendar with every day open; check after he picks","ar":"تقويم كل أيامه مفتوحة؛ والتحقق بعد أن يختار"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"November 2026","ar":"نوفمبر 2026"}},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","text":{"en":"Sun 1","ar":"أحد 1"}},{"kind":"chip","text":{"en":"Mon 2","ar":"اثنين 2"}},{"kind":"chip","tone":"dark","text":{"en":"Tue 3","ar":"ثلاثاء 3"}},{"kind":"chip","text":{"en":"Wed 4","ar":"أربعاء 4"}}]},{"kind":"small","color":"red","text":{"en":"Dr. Hany isn't available on this day.","ar":"د. هاني غير متاح في هذا اليوم."},"gap":"s"}]}},{"id":"blocked","text":{"en":"A calendar where only Sundays and Wednesdays can be picked","ar":"تقويم لا يمكن فيه اختيار إلا الأحد والأربعاء"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"November 2026","ar":"نوفمبر 2026"}},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","text":{"en":"Sun 1","ar":"أحد 1"}},{"kind":"chip","tone":"off","text":{"en":"Mon 2","ar":"اثنين 2"}},{"kind":"chip","tone":"off","text":{"en":"Tue 3","ar":"ثلاثاء 3"}},{"kind":"chip","text":{"en":"Wed 4","ar":"أربعاء 4"}}]},{"kind":"small","text":{"en":"Dr. Hany sees patients on Sundays and Wednesdays.","ar":"يستقبل د. هاني المرضى يومي الأحد والأربعاء."},"gap":"s"}]}}],"answer":["blocked"],"misconceptions":[{"id":"MC-P01-013","when":["field","all"],"feedback":{"en":"Ahmed can't know the doctor's days, so he guesses and gets an error. Show him what's possible before he picks.","ar":"لا يستطيع أحمد معرفة أيام الطبيب، فيخمّن ويحصل على خطأ. أرِه الممكن قبل أن يختار."}}],"hints":[{"en":"Who knows which days Dr. Hany works: Ahmed or the system?","ar":"من يعرف أيام عمل د. هاني: أحمد أم النظام؟"},{"en":"Should Ahmed find out a day is closed before he picks it, or after?","ar":"هل يجب أن يعرف أحمد أن اليوم غير متاح قبل أن يختاره، أم بعده؟"}],"correct":{"en":"Only the system knows: let him pick, and block the rest.","ar":"النظام وحده يعرف: دعه يختار، واحجب الباقي."},"explain":{"en":"Grayed-out days show the doctor's pattern at a glance, and one line says why, so the calendar doesn't look broken.","ar":"الأيام الرمادية تُظهر نمط عمل الطبيب بنظرة واحدة، وسطر واحد يوضّح السبب، فلا يبدو التقويم معطّلًا."},"speaker":"nour"},{"id":"S05","type":"tune","skill":"SK-P01-U02-06","part":"guided","speaker":"sara","rules":["R06","R15"],"value":{"en":"Input steppers (NN/g): use steppers for numeric fields with a clear most-frequent value, and set that value as the default. Most bookings are for two adults.","ar":"الـ Stepper (NN/g): استخدمه للحقول الرقمية التي لها قيمة شائعة واضحة، واجعل تلك القيمة هي الافتراضية. وأغلب الحجوزات لشخصين بالغين."},"ref":{"url":"https://www.nngroup.com/articles/input-steppers/","quote":"Use steppers for numerical fields with a clear most frequently selected value."},"scenario":{"en":"I'm designing a booking form for holiday flats. Hossam is booking one. Adults: 1 to 8, and almost always 2.","ar":"أصمّم نموذج حجز لشقق العطلات. ويحجز حسام شقة. البالغون: من 1 إلى 8، وغالبًا 2."},"prompt":{"en":"Try each control for the number of adults. Which one should ship?","ar":"جرّب كل عنصر لعدد البالغين. أيّها يجب أن يُطلق؟"},"start":"select","options":[{"id":"stepper","text":{"en":"A stepper starting at 2","ar":"Stepper يبدأ من 2"},"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Adults","ar":"البالغون"},"text":"2"}]}},{"id":"select","text":{"en":"A dropdown from 1 to 8","ar":"قائمة منسدلة من 1 إلى 8"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Adults","ar":"البالغون"},"text":{"en":"Select…","ar":"اختر…"}}]}},{"id":"empty","text":{"en":"An empty number field","ar":"حقل رقم فارغ"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Adults","ar":"البالغون"},"text":""}]}}],"answer":["stepper"],"misconceptions":[{"id":"MC-P01-023","when":["select","empty"],"feedback":{"en":"Almost everyone answers 2, yet each of them has to open a list or type it. Start at 2 and let the few adjust with one tap.","ar":"أغلب الناس يجيبون 2، ومع ذلك على كلٍّ منهم أن يفتح قائمة أو يكتب. ابدأ من 2 ودع القلّة يعدّلون بضغطة واحدة."}}],"hints":[{"en":"Look at the usual answer: almost always 2.","ar":"انظر إلى الإجابة المعتادة: 2 في أغلب الأحيان."},{"en":"Which control shows that usual value already, with a quick way to change it?","ar":"أي عنصر يعرض هذه القيمة المعتادة مسبقًا، مع طريقة سريعة لتغييرها؟"}],"correct":{"en":"Usual value showing, one tap to change.","ar":"القيمة المعتادة ظاهرة، وضغطة واحدة للتغيير."},"explain":{"en":"Most people don't touch it at all, and a family of three taps + once. A default is fine here because it's visible and harmless if left.","ar":"أغلب الناس لا يلمسونه أصلًا، والعائلة من ثلاثة أشخاص تضغط + مرة واحدة. والقيمة الافتراضية مناسبة هنا لأنها ظاهرة وغير ضارة إن تُركت."}},{"id":"S06","type":"tune","skill":"SK-P01-U02-07","part":"guided","speaker":"sara","rules":["R06","R15"],"value":{"en":"Mobile input checklist (NN/g): what is the right keyboard for this field? A 14-digit national ID is a code: it needs the number pad, not a number field with arrows that treats it as an amount.","ar":"قائمة تحقّق حقول الهاتف (NN/g): ما لوحة المفاتيح المناسبة لهذا الحقل؟ والرقم القومي من 14 رقمًا رمز: يحتاج لوحة الأرقام، لا حقل رقم بأسهم يعامله ككمية."},"ref":{"url":"https://www.nngroup.com/articles/mobile-input-checklist/","quote":"What is the right keyboard for this field?"},"scenario":{"en":"Back on the library form I'm designing: Abdelrahman's national ID has 14 digits, and we're choosing the field type.","ar":"نعود إلى نموذج المكتبة الذي أصمّمه: الرقم القومي لعبد الرحمن من 14 رقمًا، ونحن نختار نوع الحقل."},"prompt":{"en":"Try each field. Which one should ship?","ar":"جرّب كل حقل. أيّها يجب أن يُطلق؟"},"start":"number","options":[{"id":"number","text":{"en":"A number field with ▲▼ arrows","ar":"حقل رقم بسهمي ▲▼"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"filled":true,"text":"29803121401234 ▲▼"},{"kind":"small","text":{"en":"Treated as an amount: the arrows add or subtract 1.","ar":"يُعامَل ككمية: الأسهم تضيف 1 أو تطرحه."},"gap":"xs"}]}},{"id":"boxes","text":{"en":"Fourteen one-digit boxes","ar":"أربع عشرة خانة، رقم في كل خانة"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"National ID number","ar":"الرقم القومي"}},{"kind":"row","gap":"xs","blocks":[{"kind":"field","text":"2"},{"kind":"field","text":"9"},{"kind":"field","text":"8"},{"kind":"field","text":""},{"kind":"field","text":""},{"kind":"field","text":""},{"kind":"field","text":""}]}]}},{"id":"text","text":{"en":"A text field that opens the number pad","ar":"حقل نص يفتح لوحة الأرقام"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"National ID number","ar":"الرقم القومي"},"filled":true,"text":"29803121401234"},{"kind":"small","text":{"en":"Keyboard: 1 2 3 … 0","ar":"لوحة المفاتيح: 1 2 3 … 0"},"gap":"xs"}]}}],"answer":["text"],"misconceptions":[{"id":"MC-P01-021","when":["number"],"feedback":{"en":"A number field treats the ID as an amount: it may round it, drop a leading zero, or change it with a stray scroll. It's a code.","ar":"حقل الرقم يعامل الرقم القومي ككمية: قد يقرّبه، أو يحذف صفرًا في أوله، أو يغيّره بتمرير عابر. إنه رمز."}},{"id":"MC-P01-021","when":["boxes"],"feedback":{"en":"Boxes break pasting and make it easy to skip one. One text field with the number pad does the job.","ar":"الخانات تمنع اللصق وتجعل تخطّي خانة سهلًا. وحقل نص واحد مع لوحة الأرقام يؤدّي المهمة."}}],"hints":[{"en":"Is the ID an amount you could add or round, or a code?","ar":"هل الرقم القومي كمية يمكن جمعها أو تقريبها، أم رمز؟"},{"en":"Which field gives him the number pad without treating it as an amount?","ar":"أي حقل يعطيه لوحة الأرقام دون أن يعامله ككمية؟"}],"correct":{"en":"Digits, but not an amount: text with the number pad.","ar":"أرقام، لكنها ليست كمية: نص مع لوحة الأرقام."},"explain":{"en":"Use number fields only for amounts you'd count or add. IDs, codes and phone numbers are labels that happen to use digits.","ar":"استخدم حقول الأرقام فقط للكميات التي تُعدّ أو تُجمع. والأرقام التعريفية والرموز وأرقام الهواتف تسميات تتكوّن من أرقام."}},{"id":"S07","type":"compare","skill":"SK-P01-U02-06","part":"contrast","speaker":"tarek","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S05: steppers aren't for every number. Input steppers (NN/g): they aren't suitable for large adjustments. A catering order of about 60 portions needs typing.","ar":"مقارنة مع الخطوة 5: الـ Stepper لا يناسب كل رقم. الـ Stepper (NN/g): لا يناسب التعديلات الكبيرة. وطلب ولائم من نحو 60 وجبة يحتاج إلى الكتابة."},"ref":{"url":"https://www.nngroup.com/articles/input-steppers/","quote":"Steppers are not suitable for a large number adjustments."},"scenario":{"en":"In our lunch app, Tamer is ordering for his whole office: 60 portions. Orders on this page range from 20 to 200.","ar":"في تطبيق الغداء عندنا، يطلب تامر لكل مكتبه: 60 وجبة. والطلبات في هذه الصفحة تتراوح بين 20 و200."},"prompt":{"en":"Which control should ship for the number of portions?","ar":"أي عنصر يجب أن يُطلق لعدد الوجبات؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Portions","ar":"عدد الوجبات"},"text":"20"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Portions","ar":"عدد الوجبات"},"filled":true,"text":"60"}]}},"answer":"b","reason":{"prompt":{"en":"Why not a stepper this time?","ar":"لماذا لا نستخدم Stepper هذه المرة؟"},"options":[{"id":"taps","text":{"en":"There's no usual value, and reaching 60 would take 40 taps","ar":"لا توجد قيمة معتادة، والوصول إلى 60 يحتاج 40 ضغطة"}},{"id":"ugly","text":{"en":"Steppers look old-fashioned","ar":"الـ Stepper يبدو قديم الطراز"}},{"id":"big","text":{"en":"Big numbers need a dropdown","ar":"الأرقام الكبيرة تحتاج قائمة منسدلة"}}],"answer":["taps"],"misconceptions":[{"id":"MC-P01-023","when":["ugly","big"],"feedback":{"en":"It's about effort. A stepper shines when most people keep the default or change it by one or two. Here the value is far and varies a lot.","ar":"المسألة مسألة جهد. الـ Stepper ممتاز حين يُبقي أغلب الناس القيمة الافتراضية أو يغيّرونها بواحد أو اثنين. وهنا القيمة بعيدة وتتغيّر كثيرًا."}}]},"misconceptions":[{"id":"MC-P01-023","when":["a"],"feedback":{"en":"From 20 to 60 is forty taps on +. With no usual value and a wide range, typing is faster.","ar":"من 20 إلى 60 تعني أربعين ضغطة على +. ومع غياب قيمة معتادة ومدى واسع، الكتابة أسرع."}}],"hints":[{"en":"Look at the range: 20 to 200, and Tamer needs 60.","ar":"انظر إلى المدى: من 20 إلى 200، وتامر يحتاج 60."},{"en":"How many taps would it take to reach 60 one at a time?","ar":"كم ضغطة يحتاج للوصول إلى 60 واحدة تلو الأخرى؟"}],"correct":{"en":"Wide range, no usual value: type it.","ar":"مدى واسع بلا قيمة معتادة: اكتبه."},"explain":{"en":"A stepper is for small adjustments around a common value. When answers spread widely, a text field with the number pad wins.","ar":"الـ Stepper للتعديلات الصغيرة حول قيمة شائعة. وحين تتباعد الإجابات كثيرًا، يفوز حقل النص مع لوحة الأرقام."}},{"id":"S08","type":"tune","skill":"SK-P01-U02-06","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Sliders (NN/g): a slider is good for exploring a range, but precise values are hard to hit; add a text box for fine control. Tamer has an exact budget.","ar":"حالة جديدة. الـ Sliders (NN/g): الـ Slider جيد لاستكشاف مدى، لكن الوصول إلى قيم دقيقة صعب؛ فأضف حقل نص للضبط الدقيق. ولدى تامر ميزانية محدّدة."},"ref":{"url":"https://www.nngroup.com/articles/sliders-knobs/","quote":"Then, a text box is added to allow for fine control — selecting a specific value."},"scenario":{"en":"Tamer's budget per person is exactly 80 to 120 pounds. Our restaurant filter uses a price slider from 0 to 500.","ar":"ميزانية تامر للفرد بالضبط من 80 إلى 120 جنيهًا. وفلتر المطاعم عندنا يستخدم Slider للسعر من 0 إلى 500."},"prompt":{"en":"Try each filter. Which one should ship?","ar":"جرّب كل فلتر. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now (try to set 80 to 120)","ar":"الآن (جرّب أن تضبطه من 80 إلى 120)"},"width":300,"blocks":[{"kind":"slider","label":{"en":"Price per person","ar":"السعر للفرد"},"min":0,"max":500,"from":100,"to":325,"format":{"en":"From {a} to {b} pounds","ar":"من {a} إلى {b} جنيهًا"}}]},"options":[{"id":"wide","text":{"en":"Make the slider wider","ar":"اجعل الـ Slider أعرض"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":320,"blocks":[{"kind":"slider","label":{"en":"Price per person","ar":"السعر للفرد"},"min":0,"max":500,"from":100,"to":325,"format":{"en":"From {a} to {b} pounds","ar":"من {a} إلى {b} جنيهًا"}}]}},{"id":"both","text":{"en":"Keep the slider, and add Min and Max fields","ar":"أبقِ الـ Slider، وأضف حقلين للأقل والأعلى"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"slider","label":{"en":"Price per person","ar":"السعر للفرد"},"min":0,"max":500,"from":80,"to":120,"format":{"en":"From {a} to {b} pounds","ar":"من {a} إلى {b} جنيهًا"}},{"kind":"row","gap":"s","blocks":[{"kind":"field","label":{"en":"Min","ar":"الأقل"},"filled":true,"text":"80"},{"kind":"field","label":{"en":"Max","ar":"الأعلى"},"filled":true,"text":"120"}]}]}},{"id":"ranges","text":{"en":"Replace it with fixed ranges","ar":"استبدله بنطاقات ثابتة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Price per person","ar":"السعر للفرد"}},{"kind":"radio","text":{"en":"Under 100","ar":"أقل من 100"},"gap":"xs"},{"kind":"radio","text":{"en":"100 to 200","ar":"من 100 إلى 200"},"gap":"xs"},{"kind":"radio","text":{"en":"Over 200","ar":"أكثر من 200"},"gap":"xs"}]}}],"answer":["both"],"misconceptions":[{"id":"MC-P01-022","when":["wide"],"feedback":{"en":"A few more pixels still means each step jumps a few pounds on a phone. He needs a place to type 80.","ar":"بضع نقاط إضافية تعني أن كل خطوة ما زالت تقفز بضعة جنيهات على الهاتف. يحتاج مكانًا يكتب فيه 80."}},{"id":"MC-P01-022","when":["ranges"],"feedback":{"en":"His 80 to 120 crosses two ranges, so he can't express it at all. Let him set exact values.","ar":"نطاقه من 80 إلى 120 يقع بين نطاقين، فلا يستطيع التعبير عنه أصلًا. دعه يضبط قيمًا دقيقة."}}],"hints":[{"en":"Tamer knows his exact numbers. Can he set exactly 80 and 120 by dragging?","ar":"تامر يعرف أرقامه بالضبط. هل يستطيع ضبط 80 و120 بالضبط بالسحب؟"},{"en":"A slider is good for exploring. What's good for being exact?","ar":"الـ Slider مناسب للاستكشاف. ما المناسب للدقة؟"}],"correct":{"en":"Slider to explore, fields to be exact.","ar":"الـ Slider للاستكشاف، والحقول للدقة."},"explain":{"en":"The slider shows the whole price range at a glance; the fields let Tamer set exactly what he has. Linked together, each serves a different need.","ar":"الـ Slider يعرض مدى الأسعار كله بنظرة؛ والحقول تتيح لتامر ضبط ما لديه بالضبط. ومعًا، يخدم كلٌّ منهما حاجة مختلفة."}},{"id":"S09","type":"card","part":"recap","icons":["form","clock","list","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Known by heart:** let Ahmed type his date of birth.\n- **Known only by the system:** showed the doctor's free days and blocked the rest.\n- **Small usual counts:** used a stepper starting at 2.\n- **Codes:** used a text field with the number pad for the ID.\n- **Large or exact numbers:** typed fields, with a slider only for exploring.\n\nNext lesson: long lists, and search that finds what people type.","ar":"- **ما يُحفظ عن ظهر قلب:** دع أحمد يكتب تاريخ ميلاده.\n- **ما لا يعرفه إلا النظام:** عرضت أيام الطبيب المتاحة وحجبت الباقي.\n- **الأعداد الصغيرة المعتادة:** استخدمت Stepper يبدأ من 2.\n- **الرموز:** استخدمت حقل نص مع لوحة الأرقام للرقم القومي.\n- **الأرقام الكبيرة أو الدقيقة:** حقول للكتابة، والـ Slider للاستكشاف فقط.\n\nالدرس التالي: القوائم الطويلة، والبحث الذي يجد ما يكتبه الناس."}}]}$uxg$::jsonb),
  ($uxg$P01-U02-L03$uxg$, $uxg$48643df20cdd61a745b95a399a74fbada4398f915575731aad44bfe768d1751d$uxg$, $uxg${"id":"P01-U02-L03","mode":"lesson","minutes":8,"title":{"en":"Long lists: let people type","ar":"القوائم الطويلة: دع الناس يكتبون"},"speaker":"sara","review_labels":{"MC-P01-012":{"en":"Let people type what they know by heart","ar":"دع الناس يكتبون ما يحفظونه"},"MC-P01-015":{"en":"Don't preselect a guess for a personal answer","ar":"لا تحدّد تخمينًا مسبقًا لإجابة شخصية"},"MC-P01-016":{"en":"Long lists need a way to search","ar":"القوائم الطويلة تحتاج طريقة للبحث"},"MC-P01-024":{"en":"Search should accept how people really type","ar":"البحث يجب أن يقبل ما يكتبه الناس فعلًا"},"MC-P01-025":{"en":"Pin common options; keep the full list","ar":"ثبّت الخيارات الشائعة في الأعلى، واحتفظ بالقائمة كاملة"},"MC-P01-031":{"en":"Show a few options; don't hide them in a dropdown","ar":"اعرض الخيارات القليلة؛ لا تُخفِها في قائمة منسدلة"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Abdelrahman's nationality","ar":"جنسية عبد الرحمن"},"body":{"en":"The library form I'm designing asks for Abdelrahman's nationality. Tapping the field opens a list of about 195 countries, from A to Z.\n\nEgypt is about a quarter of the way down.","ar":"يسأل نموذج المكتبة الذي أصمّمه عن جنسية عبد الرحمن. والضغط على الحقل يفتح قائمة بنحو 195 دولة، مرتّبة أبجديًا.\n\nومصر في مكان ما بعد ربع القائمة."},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Nationality","ar":"الجنسية"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Afghanistan","ar":"أفغانستان"}},{"kind":"text","text":{"en":"Albania","ar":"ألبانيا"},"gap":"xs"},{"kind":"text","text":{"en":"Algeria","ar":"الجزائر"},"gap":"xs"},{"kind":"text","text":{"en":"Andorra","ar":"أندورا"},"gap":"xs"},{"kind":"small","text":{"en":"… 191 more","ar":"… 191 دولة أخرى"},"gap":"xs"}]}]}},{"id":"S02","type":"tune","skill":"SK-P01-U02-08","part":"try","rules":["R12"],"value":{"en":"Try first. Dropdown lists (NN/g): when a list grows well beyond 15 options, consider a combobox; people type and the list narrows. It works well for long, predictable lists such as countries.","ar":"جرّب أولًا. القوائم المنسدلة (NN/g): حين تتجاوز القائمة 15 خيارًا بكثير، فكّر في Combobox؛ يكتب الناس فتضيق القائمة. وهو يعمل جيدًا مع القوائم الطويلة المتوقّعة مثل الدول."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"This pattern works well for long lists of predictable options such as countries, states, languages, and universities."},"prompt":{"en":"Try each way of choosing a country. Which one should ship?","ar":"جرّب كل طريقة لاختيار الدولة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"select","label":{"en":"Nationality","ar":"الجنسية"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Afghanistan","ar":"أفغانستان"}},{"kind":"text","text":{"en":"Albania","ar":"ألبانيا"},"gap":"xs"},{"kind":"text","text":{"en":"Algeria","ar":"الجزائر"},"gap":"xs"},{"kind":"text","text":{"en":"Andorra","ar":"أندورا"},"gap":"xs"},{"kind":"small","text":{"en":"… 191 more","ar":"… 191 دولة أخرى"},"gap":"xs"}]}]},"options":[{"id":"radios","text":{"en":"Show all 195 as radio buttons","ar":"اعرض الـ 195 كلها كـ Radio buttons"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Nationality","ar":"الجنسية"}},{"kind":"radio","text":{"en":"Afghanistan","ar":"أفغانستان"},"gap":"xs"},{"kind":"radio","text":{"en":"Albania","ar":"ألبانيا"},"gap":"xs"},{"kind":"radio","text":{"en":"Algeria","ar":"الجزائر"},"gap":"xs"},{"kind":"radio","text":{"en":"Andorra","ar":"أندورا"},"gap":"xs"},{"kind":"small","text":{"en":"… 191 more, about 12 screens","ar":"… 191 دولة أخرى، نحو 12 شاشة"},"gap":"xs"}]}},{"id":"split","text":{"en":"Pick a continent first, then the country","ar":"اختر القارة أولًا، ثم الدولة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"select","label":{"en":"Continent","ar":"القارة"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"select","label":{"en":"Nationality","ar":"الجنسية"},"text":{"en":"Select…","ar":"اختر…"},"gap":"s"}]}},{"id":"combo","text":{"en":"A field he types into; the list narrows as he types","ar":"حقل يكتب فيه؛ وتضيق القائمة مع الكتابة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Nationality","ar":"الجنسية"},"filled":true,"text":{"en":"Eg","ar":"مص"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","weight":"bold","text":{"en":"Egypt","ar":"مصر"}}]}]}}],"answer":["combo"],"misconceptions":[{"id":"MC-P01-016","when":["radios"],"feedback":{"en":"Now every choice is visible, but he scrolls through a dozen screens to find Egypt. A long list needs typing, not more scrolling.","ar":"الآن كل الخيارات ظاهرة، لكنه يمرّر عشرات الشاشات ليجد مصر. والقائمة الطويلة تحتاج كتابة، لا مزيدًا من التمرير."}},{"id":"MC-P01-016","when":["split"],"feedback":{"en":"Two lists instead of one, and he has to know how the form groups countries. Typing two letters is faster than both.","ar":"قائمتان بدل واحدة، وعليه أن يعرف كيف يقسّم النموذج الدول. وكتابة حرفين أسرع من الاثنين."}}],"hints":[{"en":"Abdelrahman already knows the answer. What's the quickest way to reach Egypt?","ar":"عبد الرحمن يعرف الإجابة مسبقًا. ما أسرع طريقة للوصول إلى مصر؟"},{"en":"Scrolling 195 options or picking a continent first both take time. What lets him go straight there?","ar":"التمرير بين 195 خيارًا أو اختيار القارة أولًا كلاهما يأخذ وقتًا. ما الذي يوصله مباشرة؟"}],"correct":{"en":"Long, known list: type to filter.","ar":"قائمة طويلة معروفة: اكتب لتضييقها."},"explain":{"en":"Abdelrahman knows the answer. Two letters bring it to the top, and the list still guarantees a valid country.","ar":"عبد الرحمن يعرف الإجابة. وحرفان يُظهرانها في الأعلى، والقائمة تضمن مع ذلك اسم دولة صحيحًا."}},{"id":"S03","type":"card","part":"concept","icons":["list","eye","form","idea"],"title":{"en":"Let the list come to them","ar":"دع القائمة تأتي إليهم"},"body":{"en":"Dropdowns hide their options. That's fine for a short list, and slow for a long one.\n\n- **A handful of options:** show them, as radio buttons.\n- **Well over 15 options people know, like countries:** a field that filters as they type.\n- **Values people know by heart, like a year:** a plain text field.\n- **Forgive spelling:** people rarely type perfectly. Suggest close matches as they type.\n- **Pin, don't preselect:** put the most common choices at the top, but let each person choose. People often keep whatever is already selected.","ar":"القوائم المنسدلة تُخفي خياراتها. وهذا مناسب للقائمة القصيرة، وبطيء للطويلة.\n\n- **خيارات قليلة:** اعرضها، كـ Radio buttons.\n- **أكثر من 15 خيارًا بكثير يعرفها الناس، مثل الدول:** حقل يضيّق القائمة مع الكتابة.\n- **قيم يحفظها الناس، مثل سنة:** حقل نص عادي.\n- **سامح في الإملاء:** نادرًا ما يكتب الناس بدقة. فاقترح أقرب النتائج أثناء الكتابة.\n- **ثبّت ولا تحدّد مسبقًا:** ضع الخيارات الأكثر شيوعًا في الأعلى، لكن دع كل شخص يختار. فالناس كثيرًا ما يُبقون ما هو محدّد بالفعل."}},{"id":"S04","type":"tune","skill":"SK-P01-U02-08","part":"guided","rules":["R06","R15"],"value":{"en":"Site search (NN/g): users often don't formulate perfect queries; spelling suggestions are critical. A filter that needs exact spelling turns a shortcut into a test.","ar":"البحث في الموقع (NN/g): كثيرًا ما لا يصوغ المستخدمون استعلامات مثالية؛ واقتراحات الإملاء ضرورية. والفلتر الذي يطلب إملاءً دقيقًا يحوّل الاختصار إلى اختبار."},"ref":{"url":"https://www.nngroup.com/articles/internal-website-search/","quote":"Users often don’t formulate perfect queries."},"scenario":{"en":"In testing, Abdelrahman typed quickly with one thumb: \"Egipt\".","ar":"في الاختبار، كتب عبد الرحمن بسرعة بإبهام واحد: «مصرر»."},"prompt":{"en":"Try each way the field can respond. Which one should ship?","ar":"جرّب كل طريقة يمكن أن يستجيب بها الحقل. أيّها يجب أن تُطلق؟"},"start":"none","options":[{"id":"close","text":{"en":"Show the closest match","ar":"اعرض أقرب نتيجة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Nationality","ar":"الجنسية"},"filled":true,"text":{"en":"Egipt","ar":"مصرر"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"small","text":{"en":"Did you mean:","ar":"هل تقصد:"}},{"kind":"text","weight":"bold","text":{"en":"Egypt","ar":"مصر"},"gap":"xs"}]}]}},{"id":"none","text":{"en":"Show \"No results\"","ar":"اعرض «لا توجد نتائج»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Nationality","ar":"الجنسية"},"filled":true,"text":{"en":"Egipt","ar":"مصرر"}},{"kind":"small","text":{"en":"No results.","ar":"لا توجد نتائج."},"gap":"xs"}]}},{"id":"all","text":{"en":"Show the whole list again","ar":"اعرض القائمة كلها من جديد"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Nationality","ar":"الجنسية"},"filled":true,"text":{"en":"Egipt","ar":"مصرر"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Afghanistan","ar":"أفغانستان"}},{"kind":"text","text":{"en":"Albania","ar":"ألبانيا"},"gap":"xs"},{"kind":"small","text":{"en":"… 193 more","ar":"… 193 دولة أخرى"},"gap":"xs"}]}]}}],"answer":["close"],"misconceptions":[{"id":"MC-P01-024","when":["none"],"feedback":{"en":"One wrong letter and a dead end. He has to spot the typo himself. The system can see that \"Egipt\" is almost certainly Egypt.","ar":"حرف خاطئ واحد وطريق مسدود. وعليه أن يكتشف الخطأ بنفسه. بينما يستطيع النظام أن يرى أن ما كتبه هو مصر على الأرجح."}},{"id":"MC-P01-024","when":["all"],"feedback":{"en":"His typing is thrown away and he's back to scrolling 195 countries. Use what he typed to guess what he meant.","ar":"ضاعت كتابته وعاد إلى تمرير 195 دولة. استخدم ما كتبه لتخمين ما يقصده."}}],"hints":[{"en":"He made one small typo. Is \"Egipt\" close to a country in the list?","ar":"أخطأ خطأً صغيرًا واحدًا. هل «Egipt» قريبة من دولة في القائمة؟"},{"en":"Which response helps him without making him start again?","ar":"أي استجابة تساعده دون أن تجعله يبدأ من جديد؟"}],"correct":{"en":"Close enough should still land.","ar":"القريب يجب أن يصل أيضًا."},"explain":{"en":"Matching near misses, and saying so, rescues most typos in one tap. People don't need to type perfectly to get the right answer.","ar":"مطابقة الأخطاء القريبة، مع توضيح ذلك، تُنقذ أغلب الأخطاء الإملائية بضغطة واحدة. ولا يحتاج الناس إلى الكتابة بدقة ليصلوا إلى الإجابة الصحيحة."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U02-08","part":"guided","rules":["R06","R15"],"value":{"en":"Dropdown lists (NN/g): users may not explore options beyond the default. Preselecting the common country creates silent errors for everyone else; pinning gives the speed without the risk.","ar":"القوائم المنسدلة (NN/g): قد لا يستكشف المستخدمون خيارات غير الخيار الافتراضي. وتحديد الدولة الشائعة مسبقًا يصنع أخطاء صامتة لكل الآخرين؛ أما التثبيت في الأعلى فيعطي السرعة بلا خطر."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"Users may not interact with the control to explore additional options beyond the default."},"scenario":{"en":"Another client's sign-up form asks for a phone country code. Most of their users are in Egypt or Saudi Arabia. Fadi lives in Jordan and is in a hurry.","ar":"نموذج التسجيل لدى عميل آخر يطلب رمز الدولة للهاتف. وأغلب مستخدميه في مصر أو السعودية. وفادي يعيش في الأردن ومستعجل."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"preset","options":[{"id":"preset","text":{"en":"Preselect Egypt (⁦+20⁩)","ar":"حدّد مصر (‎⁦+20⁩) مسبقًا"},"mock":{"width":300,"blocks":[{"kind":"row","gap":"s","blocks":[{"kind":"select","label":{"en":"Code","ar":"الرمز"},"filled":true,"text":"⁦+20⁩"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦79 123 4567⁩"}]},{"kind":"small","color":"red","text":{"en":"Saved as ⁦+20 79 123 4567⁩: not Fadi's number","ar":"حُفظ هكذا: ‎⁦+20 79 123 4567⁩، وهو ليس رقم فادي"},"gap":"xs"}]}},{"id":"pin","text":{"en":"Pin Egypt and Saudi Arabia at the top; nothing selected","ar":"ثبّت مصر والسعودية في الأعلى؛ دون تحديد أي شيء"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Country code","ar":"رمز الدولة"},"text":{"en":"Choose or type a country","ar":"اختر دولة أو اكتب اسمها"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Egypt ⁦+20⁩","ar":"مصر ‎⁦+20⁩"}},{"kind":"text","text":{"en":"Saudi Arabia ⁦+966⁩","ar":"السعودية ‎⁦+966⁩"},"gap":"xs"},{"kind":"divider","gap":"xs"},{"kind":"text","text":{"en":"Afghanistan ⁦+93⁩","ar":"أفغانستان ‎⁦+93⁩"},"gap":"xs"},{"kind":"small","text":{"en":"… all countries, A to Z","ar":"… كل الدول، أبجديًا"},"gap":"xs"}]}]}},{"id":"az","text":{"en":"Plain A to Z list, nothing pinned or selected","ar":"قائمة أبجدية عادية، دون تثبيت أو تحديد"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Country code","ar":"رمز الدولة"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":{"en":"Afghanistan ⁦+93⁩","ar":"أفغانستان ‎⁦+93⁩"}},{"kind":"text","text":{"en":"Albania ⁦+355⁩","ar":"ألبانيا ‎⁦+355⁩"},"gap":"xs"},{"kind":"small","text":{"en":"… Egypt is about 60 rows down","ar":"… مصر بعد نحو 60 سطرًا"},"gap":"xs"}]}]}}],"answer":["pin"],"misconceptions":[{"id":"MC-P01-015","when":["preset"],"feedback":{"en":"Fadi types his number and never notices ⁦+20⁩. The account gets a wrong number, and nobody knows until a code never arrives.","ar":"يكتب فادي رقمه ولا يلاحظ ‎⁦+20⁩ أبدًا. فيُسجَّل في الحساب رقم خاطئ، ولا يعرف أحد حتى لا يصل رمز التحقق."}},{"id":"MC-P01-025","when":["az"],"feedback":{"en":"Safe for Fadi, but most users scroll past dozens of countries every time. Pin the common ones on top of the full list.","ar":"آمن لفادي، لكن أغلب المستخدمين يمرّرون عشرات الدول في كل مرة. ثبّت الشائعة فوق القائمة الكاملة."}}],"hints":[{"en":"Fadi lives in Jordan. What happens if he doesn't notice a preselected code?","ar":"فادي يعيش في الأردن. ماذا يحدث إن لم ينتبه إلى رمز محدّد مسبقًا؟"},{"en":"How can most people save time without anyone getting a wrong answer by default?","ar":"كيف يوفّر أغلب الناس الوقت دون أن يحصل أحد على إجابة خاطئة تلقائيًا؟"}],"correct":{"en":"Pin the common ones; let each person choose.","ar":"ثبّت الشائعة؛ ودع كل شخص يختار."},"explain":{"en":"Pinning puts most people one tap away without choosing for anyone. Keep the pinned group small, two to five items, or it becomes another long list.","ar":"التثبيت يجعل أغلب الناس على بُعد ضغطة واحدة دون أن يختار عن أحد. واجعل المجموعة المثبّتة صغيرة، من اثنين إلى خمسة، وإلا صارت قائمة طويلة أخرى."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U02-04","part":"guided","rules":["R06","R15"],"value":{"en":"Dropdown lists (NN/g): for readily known values, typing is often faster than selecting from a dropdown. A year has 4 digits and everyone knows theirs.","ar":"القوائم المنسدلة (NN/g): للقيم المعروفة، الكتابة غالبًا أسرع من الاختيار من قائمة منسدلة. والسنة 4 أرقام والكل يعرف سنته."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"For readily known values — ages, birthdates, heights — typing is often faster than selecting from a dropdown."},"scenario":{"en":"The library asks the year Abdelrahman finished school. The dropdown lists every year from 2026 back to 1950. He finished in 2009.","ar":"تسأل المكتبة عن السنة التي أنهى فيها عبد الرحمن الدراسة. والقائمة المنسدلة تعرض كل السنوات من 2026 حتى 1950. وقد أنهاها في 2009."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"list","options":[{"id":"list","text":{"en":"Keep the dropdown of 77 years","ar":"أبقِ القائمة المنسدلة ذات الـ 77 سنة"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Year you finished school","ar":"سنة إنهاء الدراسة"},"text":{"en":"Select…","ar":"اختر…"}}]}},{"id":"combo","text":{"en":"A search field that filters the years","ar":"حقل بحث يضيّق قائمة السنوات"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Year you finished school","ar":"سنة إنهاء الدراسة"},"filled":true,"text":"20"},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","text":"2026"},{"kind":"text","text":"2025","gap":"xs"},{"kind":"small","text":{"en":"… 25 more","ar":"… 25 سنة أخرى"},"gap":"xs"}]}]}},{"id":"type","text":{"en":"A short text field for the year","ar":"حقل نص قصير للسنة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Year you finished school","ar":"سنة إنهاء الدراسة"},"filled":true,"text":"2009"}]}}],"answer":["type"],"misconceptions":[{"id":"MC-P01-012","when":["list"],"feedback":{"en":"He knows the answer, yet has to scroll 17 years to reach it. Four keystrokes are faster than any list.","ar":"يعرف الإجابة، ومع ذلك عليه أن يمرّر 17 سنة ليصل إليها. وأربع ضغطات أسرع من أي قائمة."}},{"id":"MC-P01-012","when":["combo"],"feedback":{"en":"Filtering helps with names people might spell differently. A year has one spelling; just let him type it.","ar":"التضييق يساعد مع الأسماء التي قد تُكتب بأشكال مختلفة. والسنة لها كتابة واحدة؛ فدعه يكتبها فقط."}}],"hints":[{"en":"Does Abdelrahman need to search for 2009, or does he know it by heart?","ar":"هل يحتاج عبد الرحمن إلى البحث عن 2009، أم يعرفها جيدًا؟"},{"en":"A year has one way to write it. What's the fewest steps to enter it?","ar":"السنة تُكتب بطريقة واحدة فقط. ما أقل عدد من الخطوات لإدخالها؟"}],"correct":{"en":"Known value, one spelling: type it.","ar":"قيمة معروفة بكتابة واحدة: تُكتب."},"explain":{"en":"Not every answer needs a list. When people know the value and it can only be written one way, a text field is the fastest control there is.","ar":"ليست كل إجابة تحتاج قائمة. وحين يعرف الناس القيمة ولا تُكتب إلا بطريقة واحدة، فحقل النص هو أسرع عنصر ممكن."},"speaker":"sara"},{"id":"S07","type":"compare","skill":"SK-P01-U02-02","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S02: search is for long lists. Dropdown lists (NN/g): for a handful of options, radio buttons are universally understood, show every choice and take one click.","ar":"مقارنة مع الخطوة 2: البحث للقوائم الطويلة. القوائم المنسدلة (NN/g): مع خيارات قليلة، الـ Radio buttons مفهومة للجميع، وتعرض كل الخيارات وتحتاج ضغطة واحدة."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"They are universally understood, expose all choices immediately, and require only a single click to select an option."},"scenario":{"en":"The library has four branches. Abdelrahman picks the one where he'll collect his card.","ar":"للمكتبة أربعة فروع. ويختار عبد الرحمن الفرع الذي سيستلم منه بطاقته."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Branch","ar":"الفرع"},"text":{"en":"Type a branch name","ar":"اكتب اسم الفرع"}}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Branch","ar":"الفرع"}},{"kind":"radio","text":{"en":"Downtown","ar":"وسط البلد"},"gap":"xs"},{"kind":"radio","text":{"en":"Heliopolis","ar":"مصر الجديدة"},"gap":"xs"},{"kind":"radio","text":{"en":"Maadi","ar":"المعادي"},"gap":"xs"},{"kind":"radio","text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"xs"}]}},"answer":"b","reason":{"prompt":{"en":"Why not a search field here, when it was right for countries?","ar":"لماذا لا نستخدم حقل بحث هنا، مع أنه كان صحيحًا للدول؟"},"options":[{"id":"few","text":{"en":"Four choices fit on screen, and he may not know their names","ar":"أربعة خيارات تتّسع على الشاشة، وقد لا يعرف أسماءها"}},{"id":"modern","text":{"en":"Radio buttons look friendlier","ar":"الـ Radio buttons تبدو ألطف"}},{"id":"type","text":{"en":"Typing is always slower","ar":"الكتابة أبطأ دائمًا"}}],"answer":["few"],"misconceptions":[{"id":"MC-P01-031","when":["modern","type"],"feedback":{"en":"Typing was faster for 195 countries he knows. Here there are four branches he may not know: showing them is faster and teaches him the options.","ar":"الكتابة كانت أسرع مع 195 دولة يعرفها. وهنا أربعة فروع قد لا يعرفها: وعرضها أسرع ويعرّفه بالخيارات."}}]},"misconceptions":[{"id":"MC-P01-031","when":["a"],"feedback":{"en":"He'd have to guess the branch names before he can type one. With four, just show them.","ar":"عليه أن يخمّن أسماء الفروع قبل أن يكتب أحدها. ومع أربعة فروع، اعرضها فقط."}}],"hints":[{"en":"Count the branches.","ar":"عُدّ الفروع."},{"en":"With only four choices, should he have to open anything to see them?","ar":"مع أربعة خيارات فقط، هل يجب أن يفتح شيئًا لكي يراها؟"}],"correct":{"en":"A handful: show them all.","ar":"خيارات قليلة: اعرضها كلها."},"explain":{"en":"The size of the list decides. A few options: show them. Dozens that people know: let them type. A value they know by heart: a plain field.","ar":"حجم القائمة هو ما يحدّد. خيارات قليلة: اعرضها. وعشرات يعرفها الناس: دعهم يكتبون. وقيمة يحفظونها: حقل عادي."},"speaker":"sara"},{"id":"S08","type":"tune","skill":"SK-P01-U02-08","part":"independent","speaker":"tarek","rules":["R14","R19"],"value":{"en":"New case. Site search (NN/g): query suggestions help people fix spelling errors while they are typing. Place names have many spellings across Arabic and English.","ar":"حالة جديدة. البحث في الموقع (NN/g): اقتراحات البحث تساعد الناس على تصحيح الأخطاء الإملائية أثناء الكتابة. وأسماء الأماكن لها كتابات كثيرة بين العربية والإنجليزية."},"ref":{"url":"https://www.nngroup.com/articles/internal-website-search/","quote":"Oftentimes query suggestions will assist users in adjusting spelling errors while they are typing the query."},"scenario":{"en":"Our lunch app delivers to about 300 areas. Tamer types his area the way he says it: \"Zamalik\".","ar":"يوصّل تطبيق الغداء عندنا إلى نحو 300 منطقة. ويكتب تامر منطقته كما ينطقها: «زملك»."},"prompt":{"en":"Try each version of the area field. Which one should ship?","ar":"جرّب كل نسخة من حقل المنطقة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery area","ar":"منطقة التوصيل"},"filled":true,"text":{"en":"Zamalik","ar":"زملك"}},{"kind":"small","text":{"en":"No results.","ar":"لا توجد نتائج."},"gap":"xs"}]},"options":[{"id":"suggest","text":{"en":"Suggest close matches as he types","ar":"اقترح أقرب النتائج أثناء الكتابة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery area","ar":"منطقة التوصيل"},"filled":true,"text":{"en":"Zamal","ar":"زمل"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","weight":"bold","text":{"en":"Zamalek","ar":"الزمالك"}}]}]}},{"id":"hint","text":{"en":"Add \"Type the name exactly as on the map\"","ar":"أضف «اكتب الاسم كما هو على الخريطة تمامًا»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery area","ar":"منطقة التوصيل"},"filled":true,"text":{"en":"Zamalik","ar":"زملك"},"hint":{"en":"Type the name exactly as on the map.","ar":"اكتب الاسم كما هو على الخريطة تمامًا."}},{"kind":"small","text":{"en":"No results.","ar":"لا توجد نتائج."},"gap":"xs"}]}},{"id":"list","text":{"en":"Replace it with a dropdown of all 300 areas","ar":"استبدله بقائمة منسدلة لكل الـ 300 منطقة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"select","label":{"en":"Delivery area","ar":"منطقة التوصيل"},"text":{"en":"Select…","ar":"اختر…"}},{"kind":"small","text":{"en":"300 areas, A to Z","ar":"300 منطقة، أبجديًا"},"gap":"xs"}]}}],"answer":["suggest"],"misconceptions":[{"id":"MC-P01-024","when":["hint"],"feedback":{"en":"Tamer has no way to know the map's spelling. The hint blames him for a problem the search could solve.","ar":"لا يستطيع تامر معرفة كتابة الخريطة. والتلميح يلومه على مشكلة يستطيع البحث حلّها."}},{"id":"MC-P01-016","when":["list"],"feedback":{"en":"He'd scroll through 300 areas to find Z. A long list needs a forgiving search, not a longer scroll.","ar":"سيمرّر 300 منطقة ليصل إلى الزاي. والقائمة الطويلة تحتاج بحثًا متسامحًا، لا تمريرًا أطول."}}],"hints":[{"en":"Tamer typed the name the way he says it. Is it close to a real area?","ar":"كتب تامر الاسم كما ينطقه. هل هو قريب من منطقة حقيقية؟"},{"en":"Should the field ask him to be exact, or help him get there?","ar":"هل يجب أن يطلب منه الحقل الدقة، أم يساعده للوصول؟"}],"correct":{"en":"Meet him halfway while he types.","ar":"قابِله في منتصف الطريق أثناء الكتابة."},"explain":{"en":"Suggestions appear before he finishes, so a near spelling still lands on Zamalek. Fewer dead ends, and no spelling test.","ar":"تظهر الاقتراحات قبل أن ينتهي من الكتابة، فتصل الكتابة القريبة إلى الزمالك. طرق مسدودة أقل، وبلا اختبار إملاء."}},{"id":"S09","type":"card","part":"recap","icons":["list","eye","form","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Long, known lists:** let people type to filter, like countries.\n- **Forgiving search:** suggested close matches instead of \"No results\".\n- **Pin, don't preselect:** put common choices on top and let each person choose.\n- **Known values:** used a plain field for the year.\n- **A handful of options:** showed them as radio buttons.\n\nNext: the unit skill check.","ar":"- **القوائم الطويلة المعروفة:** دع الناس يكتبون لتضييقها، مثل الدول.\n- **بحث متسامح:** اقترحت أقرب النتائج بدل «لا توجد نتائج».\n- **ثبّت ولا تحدّد مسبقًا:** ضع الخيارات الشائعة في الأعلى ودع كل شخص يختار.\n- **القيم المعروفة:** استخدمت حقلًا عاديًا للسنة.\n- **خيارات قليلة:** عرضتها كـ Radio buttons.\n\nالتالي: اختبار المهارة للوحدة."}}]}$uxg$::jsonb),
  ($uxg$P01-U02-L04$uxg$, $uxg$6e8b3ac9bf8741361428a4e81def7c9de70ef1d89cd9c75c02c7dded2be9bb8f$uxg$, $uxg${"id":"P01-U02-L04","mode":"check","minutes":7,"title":{"en":"Skill check: pick the right control","ar":"اختبار المهارة: اختر عنصر التحكّم المناسب"},"speaker":"sara","steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Laila's home cleaning booking","ar":"حجز تنظيف منزل ليلى"},"body":{"en":"My client is a home cleaning company. Laila lives in Heliopolis. She's booking a 4-hour cleaning with ironing and windows, on a day the company has a free team. Her building's door code is 0427.\n\nYour job: choose the right control for each part of the booking form.\n\nThis is a skill check: no hints, and you'll see how you did at the end.","ar":"عميلي شركة تنظيف منزلي. تعيش ليلى في مصر الجديدة، وتحجز تنظيفًا لمدة 4 ساعات مع كيّ الملابس والنوافذ، في يوم فيه فريق متاح لدى الشركة. ورمز باب عمارتها 0427.\n\nمهمّتك: اختر عنصر التحكّم المناسب لكل جزء من نموذج الحجز.\n\nهذا اختبار مهارة: بدون تلميحات، وسترى نتيجتك في النهاية."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Book a home cleaning","ar":"احجز تنظيف منزل"}},{"kind":"select","label":{"en":"Add-ons","ar":"خدمات إضافية"},"text":{"en":"Select one…","ar":"اختر واحدًا…"},"gap":"m"},{"kind":"select","label":{"en":"Hours of cleaning","ar":"ساعات التنظيف"},"text":{"en":"Select…","ar":"اختر…"},"gap":"s"},{"kind":"select","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"s"},{"kind":"toggle","text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"},"gap":"m"},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U02-02","part":"check","rules":["R19"],"value":{"en":"Skill check, checkboxes (NN/g): a checkbox list lets people select one, several, all, or none. Add-ons are any number; a single-select dropdown loses Laila's second add-on.","ar":"اختبار مهارة، الـ Checkboxes (NN/g): قائمة الـ Checkboxes تتيح اختيار واحد أو عدة أو الكل أو لا شيء. والخدمات الإضافية أي عدد؛ والقائمة المنسدلة ذات الاختيار الواحد تُضيّع الخدمة الثانية لليلى."},"ref":{"url":"https://www.nngroup.com/articles/checkboxes-design-guidelines/","quote":"A checkbox list allows users the unique ability to select one, several, all, or no items from a list."},"scenario":{"en":"Laila wants both ironing and windows. On the current form, the add-ons are a dropdown that takes one choice.","ar":"تريد ليلى كيّ الملابس والنوافذ معًا. وفي النموذج الحالي، الخدمات الإضافية قائمة منسدلة تقبل اختيارًا واحدًا."},"prompt":{"en":"Try each control for the add-ons. Which one should ship?","ar":"جرّب كل عنصر للخدمات الإضافية. أيّها يجب أن يُطلق؟"},"start":"select","options":[{"id":"select","text":{"en":"A dropdown, one choice","ar":"قائمة منسدلة، اختيار واحد"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Add-ons","ar":"خدمات إضافية"},"filled":true,"text":{"en":"Ironing","ar":"كيّ الملابس"}}]}},{"id":"radio","text":{"en":"Radio buttons","ar":"Radio buttons"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Add-ons","ar":"خدمات إضافية"}},{"kind":"radio","selected":true,"text":{"en":"Ironing","ar":"كيّ الملابس"},"gap":"xs"},{"kind":"radio","text":{"en":"Windows","ar":"النوافذ"},"gap":"xs"}]}},{"id":"check","text":{"en":"Checkboxes","ar":"Checkboxes"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Add-ons (tick any)","ar":"خدمات إضافية (حدّد ما تريد)"}},{"kind":"check","selected":true,"text":{"en":"Ironing","ar":"كيّ الملابس"},"gap":"xs"},{"kind":"check","selected":true,"text":{"en":"Windows","ar":"النوافذ"},"gap":"xs"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-032","when":["select","radio"],"feedback":{"en":"This control takes one answer, so Laila can't book both. Add-ons are any number, including none: checkboxes.","ar":"هذا العنصر يقبل إجابة واحدة، فلا تستطيع ليلى حجز الاثنين. والخدمات الإضافية أي عدد، حتى لا شيء: Checkboxes."}}],"explain":{"en":"From Lesson 1: one answer, radio buttons; any number, checkboxes.","ar":"من الدرس 1: إجابة واحدة، Radio buttons؛ وأي عدد، Checkboxes."},"speaker":"sara"},{"id":"S03","type":"tune","skill":"SK-P01-U02-01","part":"check","rules":["R19"],"value":{"en":"Skill check, toggle switches (NN/g): separate controls with instant results from ones that wait for a button. The text-me option is only saved when Laila books.","ar":"اختبار مهارة، الـ Toggle switches (NN/g): افصل العناصر ذات النتيجة الفورية عن تلك التي تنتظر زرًا. وخيار الرسالة لا يُحفظ إلا حين تحجز ليلى."},"ref":{"url":"https://www.nngroup.com/articles/toggle-switch-guidelines/","quote":"Separate controls that produce instant results from those that require clicking a command button."},"scenario":{"en":"\"Text me when the team is on the way\" is a toggle above Book cleaning. Nothing is saved until she books.","ar":"«أرسل لي رسالة حين يكون الفريق في الطريق» Toggle فوق «احجز التنظيف». ولا يُحفظ شيء حتى تحجز."},"prompt":{"en":"Try each control. Which one should ship?","ar":"جرّب كل عنصر. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"toggle","text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"}},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]},"options":[{"id":"keep","text":{"en":"Keep the toggle","ar":"أبقِ الـ Toggle"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"toggle","text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"}},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]}},{"id":"check","text":{"en":"A checkbox, saved with the booking","ar":"Checkbox يُحفظ مع الحجز"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"check","selected":true,"text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"}},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]}},{"id":"segs","text":{"en":"A segmented control: On / Off","ar":"Segmented control: تشغيل / إيقاف"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","text":{"en":"Text me when the team is on the way","ar":"أرسل لي رسالة حين يكون الفريق في الطريق"}},{"kind":"segmented","options":[{"en":"On","ar":"تشغيل"},{"en":"Off","ar":"إيقاف"}],"value":1,"gap":"xs"},{"kind":"button","text":{"en":"Book cleaning","ar":"احجز التنظيف"},"gap":"m"}]}}],"answer":["check"],"misconceptions":[{"id":"MC-P01-018","when":["keep"],"feedback":{"en":"A toggle looks like it works the moment it's flipped. In a form that waits for Book cleaning, use a checkbox.","ar":"الـ Toggle يبدو كأنه يعمل لحظة تحريكه. وفي نموذج ينتظر «احجز التنظيف»، استخدم Checkbox."}},{"id":"MC-P01-018","when":["segs"],"feedback":{"en":"On / Off segments look like a live setting too, and take more space. A single checkbox says \"include this with my booking\".","ar":"أزرار تشغيل/إيقاف تبدو أيضًا كإعداد يعمل فورًا، وتأخذ مساحة أكبر. وCheckbox واحد يقول «أضِف هذا إلى حجزي»."}}],"explain":{"en":"From Lesson 1: toggles act now; in a form that waits for a button, use a checkbox.","ar":"من الدرس 1: الـ Toggle يعمل فورًا؛ وفي نموذج ينتظر زرًا، استخدم Checkbox."},"speaker":"sara"},{"id":"S04","type":"tune","skill":"SK-P01-U02-06","part":"check","rules":["R19"],"value":{"en":"Skill check, input steppers (NN/g): use a stepper for numeric fields with a clear most-frequent value, set as the default. Most cleanings are 4 hours, from 2 to 8.","ar":"اختبار مهارة، الـ Stepper (NN/g): استخدمه للحقول الرقمية التي لها قيمة شائعة واضحة، واجعلها الافتراضية. وأغلب حجوزات التنظيف 4 ساعات، من 2 إلى 8."},"ref":{"url":"https://www.nngroup.com/articles/input-steppers/","quote":"Use steppers for numerical fields with a clear most frequently selected value."},"scenario":{"en":"The company told me cleanings last 2 to 8 hours, and most customers book 4.","ar":"أخبرتني الشركة أن التنظيف يستمرّ من 2 إلى 8 ساعات، وأن أغلب العملاء يحجزون 4."},"prompt":{"en":"Try each control for the hours. Which one should ship?","ar":"جرّب كل عنصر لعدد الساعات. أيّها يجب أن يُطلق؟"},"start":"select","options":[{"id":"stepper","text":{"en":"A stepper starting at 4","ar":"Stepper يبدأ من 4"},"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Hours of cleaning","ar":"ساعات التنظيف"},"text":"4"}]}},{"id":"select","text":{"en":"A dropdown from 2 to 8","ar":"قائمة منسدلة من 2 إلى 8"},"mock":{"width":300,"blocks":[{"kind":"select","label":{"en":"Hours of cleaning","ar":"ساعات التنظيف"},"text":{"en":"Select…","ar":"اختر…"}}]}},{"id":"slider","text":{"en":"A slider from 2 to 8","ar":"Slider من 2 إلى 8"},"mock":{"width":300,"blocks":[{"kind":"slider","label":{"en":"Hours of cleaning","ar":"ساعات التنظيف"},"min":2,"max":8,"from":2,"to":5,"text":{"en":"Drag to choose","ar":"اسحب للاختيار"}}]}}],"answer":["stepper"],"misconceptions":[{"id":"MC-P01-023","when":["select"],"feedback":{"en":"Most people want 4, yet everyone opens a list to say so. Start at 4 and let the rest adjust with a tap.","ar":"أغلب الناس يريدون 4، ومع ذلك يفتح الجميع قائمة ليقولوا ذلك. ابدأ من 4 ودع الباقين يعدّلون بضغطة."}},{"id":"MC-P01-022","when":["slider"],"feedback":{"en":"Hours are exact whole numbers, and a slider makes her aim for one. A stepper lands on 4, 5 or 6 with no effort.","ar":"الساعات أرقام صحيحة دقيقة، والـ Slider يجعلها تصوّب نحو رقم. أما الـ Stepper فيصل إلى 4 أو 5 أو 6 بلا جهد."}}],"explain":{"en":"From Lesson 2: a small count with a usual value gets a stepper, starting at that value.","ar":"من الدرس 2: العدد الصغير ذو القيمة المعتادة يناسبه Stepper، يبدأ من تلك القيمة."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U02-05","part":"check","rules":["R19"],"value":{"en":"Skill check, date input (NN/g): disable and gray out options that aren't available. Only the company knows which days have a free team.","ar":"اختبار مهارة، إدخال التاريخ (NN/g): عطّل الخيارات غير المتاحة واجعلها رمادية. والشركة وحدها تعرف الأيام التي فيها فريق متاح."},"ref":{"url":"https://www.nngroup.com/articles/date-input/","quote":"Make the choices clear by disabling and graying out options that are not available or are illogical pairs."},"scenario":{"en":"Next week, the company has free teams only on Monday and Thursday.","ar":"في الأسبوع القادم، لدى الشركة فرق متاحة يومي الاثنين والخميس فقط."},"prompt":{"en":"Try each way of choosing the day. Which one should ship?","ar":"جرّب كل طريقة لاختيار اليوم. أيّها يجب أن تُطلق؟"},"start":"open","options":[{"id":"open","text":{"en":"Every day open; an error if no team is free","ar":"كل الأيام مفتوحة؛ ورسالة خطأ إذا لم يكن هناك فريق"},"mock":{"width":300,"blocks":[{"kind":"row","gap":"xs","blocks":[{"kind":"chip","text":{"en":"Sun 8","ar":"أحد 8"}},{"kind":"chip","text":{"en":"Mon 9","ar":"اثنين 9"}},{"kind":"chip","tone":"dark","text":{"en":"Tue 10","ar":"ثلاثاء 10"}},{"kind":"chip","text":{"en":"Wed 11","ar":"أربعاء 11"}},{"kind":"chip","text":{"en":"Thu 12","ar":"خميس 12"}}]},{"kind":"small","color":"red","text":{"en":"No team is free on this day. Try another.","ar":"لا يوجد فريق متاح في هذا اليوم. جرّب يومًا آخر."},"gap":"s"}]}},{"id":"field","text":{"en":"A date field she types into","ar":"حقل تاريخ تكتب فيه"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Cleaning date","ar":"تاريخ التنظيف"},"text":{"en":"e.g. 10 November","ar":"مثلًا: 10 نوفمبر"}}]}},{"id":"blocked","text":{"en":"Only days with a free team can be picked","ar":"لا يمكن اختيار إلا الأيام التي فيها فريق متاح"},"mock":{"width":300,"blocks":[{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":{"en":"Sun 8","ar":"أحد 8"}},{"kind":"chip","text":{"en":"Mon 9","ar":"اثنين 9"}},{"kind":"chip","tone":"off","text":{"en":"Tue 10","ar":"ثلاثاء 10"}},{"kind":"chip","tone":"off","text":{"en":"Wed 11","ar":"أربعاء 11"}},{"kind":"chip","text":{"en":"Thu 12","ar":"خميس 12"}}]},{"kind":"small","text":{"en":"Grayed-out days are fully booked.","ar":"الأيام الرمادية محجوزة بالكامل."},"gap":"s"}]}}],"answer":["blocked"],"misconceptions":[{"id":"MC-P01-013","when":["open","field"],"feedback":{"en":"Laila can't know which days have a team, so she guesses until she stops getting errors. Show her before she picks.","ar":"لا تستطيع ليلى معرفة الأيام التي فيها فريق، فتخمّن حتى تتوقّف رسائل الخطأ. أرِها قبل أن تختار."}}],"explain":{"en":"From Lesson 2: when only the system knows the options, let people pick, and block what isn't possible, with a reason.","ar":"من الدرس 2: حين لا يعرف الخيارات إلا النظام، دع الناس يختارون، واحجب غير الممكن، مع ذكر السبب."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U02-08","part":"check","rules":["R19"],"value":{"en":"Skill check, dropdown lists (NN/g): people may not explore beyond the default. The area field preselects the most common area, so Laila may book in the wrong one.","ar":"اختبار مهارة، القوائم المنسدلة (NN/g): قد لا يستكشف الناس ما بعد الخيار الافتراضي. وحقل المنطقة يحدّد المنطقة الأكثر شيوعًا مسبقًا، فقد تحجز ليلى في المنطقة الخطأ."},"ref":{"url":"https://www.nngroup.com/articles/dropdown-list/","quote":"Users may not interact with the control to explore additional options beyond the default."},"scenario":{"en":"The company covers about 50 areas. Most bookings come from Nasr City, so the area field starts on Nasr City. Laila lives in Heliopolis.","ar":"تغطّي الشركة نحو 50 منطقة. وأغلب الحجوزات من مدينة نصر، فيبدأ حقل المنطقة بمدينة نصر. وليلى تعيش في مصر الجديدة."},"prompt":{"en":"Try each version of the area field. Which one should ship?","ar":"جرّب كل نسخة من حقل المنطقة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"select","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"}}]},"options":[{"id":"pin","text":{"en":"Type to search, with Nasr City pinned on top; nothing selected","ar":"اكتب للبحث، مع تثبيت مدينة نصر في الأعلى؛ دون تحديد شيء"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"text":{"en":"Type your area","ar":"اكتب منطقتك"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"small","text":{"en":"Most booked","ar":"الأكثر حجزًا"}},{"kind":"text","text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"xs"}]}]}},{"id":"keep","text":{"en":"Keep Nasr City preselected; it saves most people a step","ar":"أبقِ مدينة نصر محدّدة مسبقًا؛ فهي توفّر خطوة لأغلب الناس"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"select","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"}}]}},{"id":"radios","text":{"en":"Show all 50 areas as radio buttons","ar":"اعرض الـ 50 منطقة كلها كـ Radio buttons"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Area","ar":"المنطقة"}},{"kind":"radio","text":{"en":"Abbassia","ar":"العباسية"},"gap":"xs"},{"kind":"radio","text":{"en":"Agouza","ar":"العجوزة"},"gap":"xs"},{"kind":"radio","text":{"en":"Ain Shams","ar":"عين شمس"},"gap":"xs"},{"kind":"small","text":{"en":"… 47 more","ar":"… 47 منطقة أخرى"},"gap":"xs"}]}}],"answer":["pin"],"misconceptions":[{"id":"MC-P01-015","when":["keep"],"feedback":{"en":"A filled field looks answered. If Laila doesn't notice, the team goes to Nasr City. Pin the common area; don't choose it for her.","ar":"الحقل الممتلئ يبدو مُجابًا. وإذا لم تنتبه ليلى، يذهب الفريق إلى مدينة نصر. ثبّت المنطقة الشائعة؛ ولا تختَرها عنها."}},{"id":"MC-P01-016","when":["radios"],"feedback":{"en":"Nothing is preselected now, but fifty radio buttons take several screens of scrolling. A long list needs typing.","ar":"لا شيء محدّد مسبقًا الآن، لكن خمسين Radio button تحتاج تمرير عدة شاشات. والقائمة الطويلة تحتاج كتابة."}}],"explain":{"en":"From Lesson 3: let people type to search a long list, and pin common choices without preselecting them.","ar":"من الدرس 3: دع الناس يكتبون للبحث في القائمة الطويلة، وثبّت الخيارات الشائعة دون تحديدها مسبقًا."},"speaker":"sara"},{"id":"S07","type":"tune","skill":"SK-P01-U02-08","part":"check","rules":["R19"],"value":{"en":"Skill check, site search (NN/g): users often don't formulate perfect queries. \"Heliopolice\" is one letter off; suggest the match.","ar":"اختبار مهارة، البحث في الموقع (NN/g): كثيرًا ما لا يصوغ المستخدمون استعلامات مثالية. وما كتبته ليلى قريب جدًا؛ فاقترح المطابقة."},"ref":{"url":"https://www.nngroup.com/articles/internal-website-search/","quote":"Users often don’t formulate perfect queries."},"scenario":{"en":"In testing, Laila typed her area quickly: \"Heliopolice\".","ar":"في الاختبار، كتبت ليلى منطقتها بسرعة: «مصر الجديده»، بالهاء بدل التاء المربوطة."},"prompt":{"en":"Try each response. Which one should ship?","ar":"جرّب كل استجابة. أيّها يجب أن تُطلق؟"},"start":"none","options":[{"id":"none","text":{"en":"\"No results\"","ar":"«لا توجد نتائج»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Heliopolice","ar":"مصر الجديده"}},{"kind":"small","text":{"en":"No results.","ar":"لا توجد نتائج."},"gap":"xs"}]}},{"id":"suggest","text":{"en":"Suggest the closest area","ar":"اقترح أقرب منطقة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Heliopolice","ar":"مصر الجديده"}},{"kind":"group","tone":"plain","gap":"xs","blocks":[{"kind":"text","weight":"bold","text":{"en":"Heliopolis","ar":"مصر الجديدة"}}]}]}},{"id":"rule","text":{"en":"Say \"Check your spelling\"","ar":"قل «تحقّق من الإملاء»"},"mock":{"width":300,"blocks":[{"kind":"field","tone":"bad","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Heliopolice","ar":"مصر الجديده"},"error":{"en":"Check your spelling.","ar":"تحقّق من الإملاء."}}]}}],"answer":["suggest"],"misconceptions":[{"id":"MC-P01-024","when":["none","rule"],"feedback":{"en":"The system can tell what she meant; it's one letter away. Make her fix nothing: suggest Heliopolis.","ar":"يستطيع النظام معرفة ما تقصده؛ فالفرق حرف واحد. لا تجعلها تصلح شيئًا: اقترح مصر الجديدة."}}],"explain":{"en":"From Lesson 3: forgiving search suggests the closest match instead of a dead end.","ar":"من الدرس 3: البحث المتسامح يقترح أقرب نتيجة بدل الطريق المسدود."},"speaker":"sara"},{"id":"S08","type":"tune","skill":"SK-P01-U02-07","part":"check","rules":["R19"],"value":{"en":"Skill check, mobile input checklist (NN/g): what is the right keyboard for this field? A door code is a code: a number field would drop the leading zero of 0427.","ar":"اختبار مهارة، قائمة تحقّق حقول الهاتف (NN/g): ما لوحة المفاتيح المناسبة لهذا الحقل؟ ورمز الباب رمز: حقل الرقم سيحذف الصفر في أول 0427."},"ref":{"url":"https://www.nngroup.com/articles/mobile-input-checklist/","quote":"What is the right keyboard for this field?"},"scenario":{"en":"The cleaning team needs the building's door code: 0427.","ar":"يحتاج فريق التنظيف رمز باب العمارة: 0427."},"prompt":{"en":"Try each field. Which one should ship?","ar":"جرّب كل حقل. أيّها يجب أن يُطلق؟"},"start":"number","options":[{"id":"number","text":{"en":"A number field","ar":"حقل رقم"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Door code","ar":"رمز الباب"},"filled":true,"text":"427"},{"kind":"small","color":"red","text":{"en":"Saved as 427: the leading 0 is gone","ar":"حُفظ هكذا: 427، واختفى الصفر في أوله"},"gap":"xs"}]}},{"id":"steps","text":{"en":"Four steppers, one per digit","ar":"أربعة Steppers، واحد لكل رقم"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Door code","ar":"رمز الباب"}},{"kind":"row","gap":"xs","blocks":[{"kind":"stepper","text":"0"},{"kind":"stepper","text":"0"}]}]}},{"id":"text","text":{"en":"A text field that opens the number pad","ar":"حقل نص يفتح لوحة الأرقام"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Door code","ar":"رمز الباب"},"filled":true,"text":"0427"},{"kind":"small","text":{"en":"Keyboard: 1 2 3 … 0","ar":"لوحة المفاتيح: 1 2 3 … 0"},"gap":"xs"}]}}],"answer":["text"],"misconceptions":[{"id":"MC-P01-021","when":["number"],"feedback":{"en":"A number field treats 0427 as the amount 427, and the team stands at the door with the wrong code. It's a code: text with the number pad.","ar":"حقل الرقم يعامل 0427 ككمية 427، فيقف الفريق أمام الباب برمز خاطئ. إنه رمز: نص مع لوحة الأرقام."}},{"id":"MC-P01-023","when":["steps"],"feedback":{"en":"Steppers are for small changes around a usual value. A code has no usual value; typing four digits is fastest.","ar":"الـ Stepper للتغييرات الصغيرة حول قيمة معتادة. والرمز ليس له قيمة معتادة؛ وكتابة أربعة أرقام هي الأسرع."}}],"explain":{"en":"From Lesson 2: IDs and codes are text made of digits. Use a text field that opens the number pad.","ar":"من الدرس 2: الأرقام التعريفية والرموز نص مكوّن من أرقام. استخدم حقل نص يفتح لوحة الأرقام."},"speaker":"sara"}]}$uxg$::jsonb),
  ($uxg$P01-U03-L01$uxg$, $uxg$c697a756eb6745ea4d4899594260a8830350574003b560d2d59f04e17b5146a0$uxg$, $uxg${"id":"P01-U03-L01","mode":"lesson","minutes":8,"title":{"en":"Labels that don't vanish","ar":"عناوين لا تختفي"},"speaker":"youssef","review_labels":{"MC-P01-034":{"en":"A placeholder is not a label","ar":"النص الداخلي ليس عنوانًا"},"MC-P01-035":{"en":"Hints inside the field vanish while typing","ar":"التلميح داخل الحقل يختفي أثناء الكتابة"},"MC-P01-036":{"en":"Grey text in a field can look already filled","ar":"النص الرمادي في الحقل قد يبدو مُعبّأ مسبقًا"},"MC-P01-037":{"en":"Needed info can't hide in a tooltip","ar":"المعلومة الضرورية لا تُخفى في Tooltip"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Yasser's delivery address","ar":"عنوان توصيل ياسر"},"body":{"en":"Yasser ordered a kettle from my online shop. Our address form has no labels: each box shows a grey example inside it, like \"Street and building\", and the example disappears when he starts typing.\n\nHe typed his street, then stopped at the next box. It already showed his browser's suggestion, and he couldn't tell what it had asked for.","ar":"طلب ياسر غلّاية من متجري الإلكتروني. ونموذج العنوان عندنا بلا عناوين: كل مربع يعرض مثالًا رماديًا بداخله، مثل «الشارع ورقم العمارة»، ويختفي المثال حين يبدأ الكتابة.\n\nكتب شارعه، ثم توقّف عند المربع التالي. كان يعرض اقتراحًا من المتصفّح، ولم يعرف ماذا كان يطلب."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery address","ar":"عنوان التوصيل"}},{"kind":"field","filled":true,"text":{"en":"14 Abbas El Akkad St","ar":"14 شارع عباس العقاد"},"gap":"m"},{"kind":"field","filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"s"},{"kind":"field","text":{"en":"Floor and flat number","ar":"رقم الدور والشقة"},"gap":"s"},{"kind":"button","text":{"en":"Continue to payment","ar":"تابع إلى الدفع"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U03-01","part":"try","rules":["R12"],"value":{"en":"Try first. Placeholders (NN/g): text inside a field disappears when people type, so they can't check what a filled field asked for. The fix is a visible label outside the field.","ar":"جرّب أولًا. النص الداخلي (NN/g): النص داخل الحقل يختفي حين يكتب الناس، فلا يستطيعون التأكّد مما طلبه الحقل المعبّأ. والحل عنوان ظاهر خارج الحقل."},"ref":{"url":"https://www.nngroup.com/articles/form-design-placeholders/","quote":"the best solution is to have clear, visible labels that are placed outside empty form fields."},"prompt":{"en":"Try each version of my form. Which one should ship?","ar":"جرّب كل نسخة من نموذجي. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery address","ar":"عنوان التوصيل"}},{"kind":"field","filled":true,"text":{"en":"14 Abbas El Akkad St","ar":"14 شارع عباس العقاد"},"gap":"m"},{"kind":"field","filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"s"},{"kind":"field","text":{"en":"Floor and flat number","ar":"رقم الدور والشقة"},"gap":"s"},{"kind":"button","text":{"en":"Continue to payment","ar":"تابع إلى الدفع"},"gap":"m"}]},"options":[{"id":"darker","text":{"en":"Keep the examples inside, but make them darker","ar":"أبقِ الأمثلة بالداخل، لكن اجعلها أغمق"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery address","ar":"عنوان التوصيل"}},{"kind":"field","filled":true,"text":{"en":"14 Abbas El Akkad St","ar":"14 شارع عباس العقاد"},"gap":"m"},{"kind":"field","filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"s"},{"kind":"field","filled":true,"text":{"en":"Floor and flat number","ar":"رقم الدور والشقة"},"gap":"s"},{"kind":"button","text":{"en":"Continue to payment","ar":"تابع إلى الدفع"},"gap":"m"}]}},{"id":"labels","text":{"en":"Put a label above each box, and leave the boxes empty","ar":"ضع عنوانًا فوق كل مربع، واترك المربعات فارغة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery address","ar":"عنوان التوصيل"}},{"kind":"field","label":{"en":"Street and building","ar":"الشارع ورقم العمارة"},"filled":true,"text":{"en":"14 Abbas El Akkad St","ar":"14 شارع عباس العقاد"},"gap":"m"},{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"s"},{"kind":"field","label":{"en":"Floor and flat number","ar":"رقم الدور والشقة"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Continue to payment","ar":"تابع إلى الدفع"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep it; the examples save space on a phone","ar":"أبقِه؛ فالأمثلة توفّر مساحة على الهاتف"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Delivery address","ar":"عنوان التوصيل"}},{"kind":"field","filled":true,"text":{"en":"14 Abbas El Akkad St","ar":"14 شارع عباس العقاد"},"gap":"m"},{"kind":"field","filled":true,"text":{"en":"Nasr City","ar":"مدينة نصر"},"gap":"s"},{"kind":"field","text":{"en":"Floor and flat number","ar":"رقم الدور والشقة"},"gap":"s"},{"kind":"button","text":{"en":"Continue to payment","ar":"تابع إلى الدفع"},"gap":"m"}]}}],"answer":["labels"],"misconceptions":[{"id":"MC-P01-034","when":["keep"],"feedback":{"en":"Once Yasser types, the example is gone, so a filled box no longer says what it asked for. A label outside stays there the whole time.","ar":"بمجرّد أن يكتب ياسر، يختفي المثال، فلا يعود المربع المعبّأ يقول ماذا طلب. أما العنوان الخارجي فيبقى طوال الوقت."}},{"id":"MC-P01-036","when":["darker"],"feedback":{"en":"Darker examples look like real answers, so the empty box now seems filled. And they still vanish when he types. Move the words out of the box.","ar":"الأمثلة الأغمق تبدو كإجابات حقيقية، فيبدو المربع الفارغ مُعبّأ. وما زالت تختفي حين يكتب. انقل الكلمات خارج المربع."}}],"hints":[{"en":"After Yasser types in a box, what tells him what that box asked for?","ar":"بعد أن يكتب ياسر في مربع، ما الذي يخبره بما طلبه هذا المربع؟"},{"en":"Which version keeps the meaning of every box on screen?","ar":"أي نسخة تُبقي معنى كل مربع ظاهرًا على الشاشة؟"}],"correct":{"en":"A label outside the field never disappears.","ar":"العنوان خارج الحقل لا يختفي أبدًا."},"explain":{"en":"Text inside a field is gone the moment someone types. A label above the box keeps telling them what belongs there, before, during and after typing.","ar":"النص داخل الحقل يختفي لحظة الكتابة. أما العنوان فوق المربع فيظل يخبر الشخص بما يُكتب فيه، قبل الكتابة وأثناءها وبعدها."}},{"id":"S03","type":"card","part":"concept","icons":["text","eye","warn","idea"],"title":{"en":"A label has to survive typing","ar":"العنوان يجب أن يبقى بعد الكتابة"},"body":{"en":"Grey text inside a field is called a placeholder. It looks tidy, but it causes real problems.\n\n- **Labels outside:** put what the field is above it, where it stays visible.\n- **Hints outside too:** a format or example belongs under or above the field, not inside, so it's there while people type.\n- **Grey text misleads:** people may think it's already filled in and skip the field.\n- **Tooltips aren't for must-know info:** an info icon needs a hover, and phones don't have one. Show what people need on the screen.","ar":"النص الرمادي داخل الحقل يسمّى Placeholder (نص داخلي). يبدو مرتّبًا، لكنه يسبّب مشكلات حقيقية.\n\n- **العناوين بالخارج:** ضع اسم الحقل فوقه، حيث يبقى ظاهرًا.\n- **التلميحات بالخارج أيضًا:** الصيغة أو المثال مكانه تحت الحقل أو فوقه، لا بداخله، حتى يبقى أثناء الكتابة.\n- **النص الرمادي يضلّل:** قد يظن الناس أن الحقل مُعبّأ فيتخطّونه.\n- **الـ Tooltip ليس للمعلومة الضرورية:** أيقونة المعلومات تحتاج تمرير الماوس، والهواتف ليس فيها ذلك. اعرض ما يحتاجه الناس على الشاشة."}},{"id":"S04","type":"tune","skill":"SK-P01-U03-02","part":"guided","rules":["R06","R15"],"value":{"en":"Placeholders (NN/g): hints and instructions should be persistent and placed outside the field. An example inside the phone field is gone before Yasser reaches the digit he's unsure about.","ar":"النص الداخلي (NN/g): التلميحات والتعليمات يجب أن تبقى ظاهرة وتوضع خارج الحقل. والمثال داخل حقل الهاتف يختفي قبل أن يصل ياسر إلى الرقم الذي لا يعرفه."},"ref":{"url":"https://www.nngroup.com/articles/form-design-placeholders/","quote":"Hints and instructions should also be persistent and placed outside of the field."},"scenario":{"en":"Our driver calls the number in the \"Phone for the driver\" field. It must be an Egyptian mobile: 11 digits starting with 01. Yasser is halfway through typing his.","ar":"يتّصل سائقنا بالرقم المكتوب في حقل «رقم هاتف للسائق». ويجب أن يكون رقم موبايل مصريًا: 11 رقمًا يبدأ بـ 01. وياسر في منتصف كتابة رقمه."},"prompt":{"en":"Try each place for the hint. Which one should ship?","ar":"جرّب كل مكان للتلميح. أيّها يجب أن يُطلق؟"},"start":"inside","options":[{"id":"inside","text":{"en":"Inside the field: \"e.g. 010 1234 5678\"","ar":"داخل الحقل: «مثال: 010 1234 5678»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"filled":true,"focus":true,"text":"⁦010 98⁩"}]}},{"id":"none","text":{"en":"No hint; the label is enough","ar":"بلا تلميح؛ العنوان يكفي"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"filled":true,"focus":true,"text":"⁦010 98⁩"}]}},{"id":"below","text":{"en":"Under the field: \"11 digits, starting with 01\"","ar":"تحت الحقل: «11 رقمًا، يبدأ بـ 01»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Phone for the driver","ar":"رقم هاتف للسائق"},"filled":true,"focus":true,"text":"⁦010 98⁩","hint":{"en":"11 digits, starting with 01","ar":"11 رقمًا، يبدأ بـ 01"}}]}}],"answer":["below"],"misconceptions":[{"id":"MC-P01-035","when":["inside"],"feedback":{"en":"Look at the preview: Yasser has started typing, and the example is already gone. A hint has to be there while he types.","ar":"انظر إلى المعاينة: بدأ ياسر الكتابة، واختفى المثال بالفعل. والتلميح يجب أن يكون موجودًا أثناء الكتابة."}},{"id":"MC-P01-035","when":["none"],"feedback":{"en":"The label says what the number is for, not what it should look like. The driver only gets through if the format is right, so say it.","ar":"العنوان يقول لماذا نطلب الرقم، لا كيف يجب أن يبدو. والسائق لن يصل إلا إذا كانت الصيغة صحيحة، فاذكرها."}}],"hints":[{"en":"In the preview, Yasser is typing. Can he still see the hint?","ar":"في المعاينة، ياسر يكتب. هل ما زال يرى التلميح؟"},{"en":"Where can a hint sit so that typing doesn't erase it?","ar":"أين يمكن أن يوضع التلميح حتى لا تمسحه الكتابة؟"}],"correct":{"en":"The hint sits outside, so it's still there mid-typing.","ar":"التلميح بالخارج، فيبقى ظاهرًا في منتصف الكتابة."},"explain":{"en":"People need a format most while they type and when they check their answer. A hint under the field is there at both moments; one inside is gone at both.","ar":"يحتاج الناس الصيغة أكثر ما يحتاجونها أثناء الكتابة وعند مراجعة إجابتهم. والتلميح تحت الحقل موجود في اللحظتين؛ أما الذي بالداخل فيختفي في الاثنتين."},"speaker":"youssef"},{"id":"S05","type":"tune","skill":"SK-P01-U03-01","part":"guided","rules":["R06","R15"],"value":{"en":"Placeholders (NN/g): some people assume placeholder text is a default value and skip the field. A gift message that seems written already gets skipped, and the gift arrives blank.","ar":"النص الداخلي (NN/g): بعض الناس يظنون أن النص الداخلي قيمة افتراضية فيتخطّون الحقل. ورسالة الهدية التي تبدو مكتوبة بالفعل تُتخطّى، فتصل الهدية بلا رسالة."},"ref":{"url":"https://www.nngroup.com/articles/form-design-placeholders/","quote":"Some users assume the placeholder text is a default value and skip the field completely."},"scenario":{"en":"Many orders sent as gifts reach us with an empty gift message. The message box shows \"Happy birthday! With love…\" in grey until someone types.","ar":"كثير من الطلبات المرسلة كهدايا تصلنا برسالة إهداء فارغة. ومربع الرسالة يعرض «عيد ميلاد سعيد! مع حبّي…» باللون الرمادي حتى يكتب أحد."},"prompt":{"en":"Try each version of the gift box. Which one should ship?","ar":"جرّب كل نسخة من مربع الهدية. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"check","selected":true,"text":{"en":"This is a gift","ar":"هذا الطلب هدية"}},{"kind":"field","text":{"en":"Happy birthday! With love…","ar":"عيد ميلاد سعيد! مع حبّي…"},"gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]},"options":[{"id":"label","text":{"en":"Add the label \"Gift message (optional)\" above an empty box","ar":"أضف العنوان «رسالة الهدية (اختيارية)» فوق مربع فارغ"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"check","selected":true,"text":{"en":"This is a gift","ar":"هذا الطلب هدية"}},{"kind":"field","label":{"en":"Gift message (optional)","ar":"رسالة الهدية (اختيارية)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"example","text":{"en":"Keep it, and make the example longer and friendlier","ar":"أبقِه، واجعل المثال أطول وألطف"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"check","selected":true,"text":{"en":"This is a gift","ar":"هذا الطلب هدية"}},{"kind":"field","text":{"en":"Happy birthday, dear! Wishing you a wonderful year…","ar":"عيد ميلاد سعيد يا عزيزي! أتمنّى لك سنة رائعة…"},"gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep it as it is","ar":"أبقِه كما هو"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"check","selected":true,"text":{"en":"This is a gift","ar":"هذا الطلب هدية"}},{"kind":"field","text":{"en":"Happy birthday! With love…","ar":"عيد ميلاد سعيد! مع حبّي…"},"gap":"s"},{"kind":"button","text":{"en":"Place order","ar":"أكّد الطلب"},"gap":"m"}]}}],"answer":["label"],"misconceptions":[{"id":"MC-P01-036","when":["keep","example"],"feedback":{"en":"The grey sentence reads like a message someone already wrote, so people move on. A longer one looks even more finished. Name the box, and leave it empty.","ar":"الجملة الرمادية تُقرأ كرسالة كتبها أحد بالفعل، فيتابع الناس. والأطول تبدو أكثر اكتمالًا. سمِّ المربع، واتركه فارغًا."}}],"hints":[{"en":"Does the box look empty or already written?","ar":"هل يبدو المربع فارغًا أم مكتوبًا بالفعل؟"},{"en":"What makes it clear that the box is waiting for the buyer's own words?","ar":"ما الذي يوضّح أن المربع ينتظر كلمات المشتري نفسه؟"}],"correct":{"en":"An empty box under a label clearly waits for an answer.","ar":"المربع الفارغ تحت عنوان ينتظر إجابة بوضوح."},"explain":{"en":"Grey text can pass for a real answer. A label outside plus an empty box removes the doubt: the box is empty, so it's the buyer's to fill.","ar":"النص الرمادي قد يبدو إجابة حقيقية. والعنوان بالخارج مع مربع فارغ يزيل الشك: المربع فارغ، إذن على المشتري أن يملأه."},"speaker":"youssef"},{"id":"S06","type":"tune","skill":"SK-P01-U03-03","part":"guided","rules":["R06","R15"],"value":{"en":"Tooltips (NN/g): tooltips need a hover, so they're not normally available on touchscreens, and people shouldn't need one to finish a task. Where to find the card code is needed to pay.","ar":"الـ Tooltip (NN/g): يحتاج الـ Tooltip تمرير الماوس، لذلك لا يتوفّر عادةً على شاشات اللمس، ويجب ألا يحتاج الناس إليه لإكمال مهمتهم. ومكان رمز البطاقة ضروري للدفع."},"ref":{"url":"https://www.nngroup.com/articles/tooltip-guidelines/","quote":"They are not normally available on touchscreens."},"scenario":{"en":"Most of my customers pay on their phones. Our card form asks for the security code, and many people don't know where it is. Right now, \"3 digits on the back of your card\" appears only when you hover over the ⓘ.","ar":"أغلب عملائي يدفعون من هواتفهم. ونموذج البطاقة عندنا يطلب رمز الأمان، وكثيرون لا يعرفون مكانه. والآن، تظهر عبارة «3 أرقام على ظهر بطاقتك» فقط عند تمرير الماوس فوق ⓘ."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Security code ⓘ","ar":"رمز الأمان ⓘ"},"text":""},{"kind":"button","text":{"en":"Pay 450 EGP","ar":"ادفع 450 جنيهًا"},"gap":"m"}]},"options":[{"id":"placeholder","text":{"en":"Put \"3 digits on the back\" inside the field","ar":"ضع «3 أرقام على الظهر» داخل الحقل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Security code","ar":"رمز الأمان"},"text":{"en":"3 digits on the back","ar":"3 أرقام على الظهر"}},{"kind":"button","text":{"en":"Pay 450 EGP","ar":"ادفع 450 جنيهًا"},"gap":"m"}]}},{"id":"hint","text":{"en":"Show \"The 3 digits on the back of your card\" under the label","ar":"اعرض «الأرقام الثلاثة على ظهر بطاقتك» تحت العنوان"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Security code","ar":"رمز الأمان"},"hintFirst":true,"hint":{"en":"The 3 digits on the back of your card","ar":"الأرقام الثلاثة على ظهر بطاقتك"},"text":""},{"kind":"button","text":{"en":"Pay 450 EGP","ar":"ادفع 450 جنيهًا"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep the ⓘ; it keeps the form clean","ar":"أبقِ ⓘ؛ فهي تُبقي النموذج نظيفًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Security code ⓘ","ar":"رمز الأمان ⓘ"},"text":""},{"kind":"button","text":{"en":"Pay 450 EGP","ar":"ادفع 450 جنيهًا"},"gap":"m"}]}}],"answer":["hint"],"misconceptions":[{"id":"MC-P01-037","when":["keep"],"feedback":{"en":"On a phone there's no hover, so most of my customers never see the help. Something they need in order to pay must be on the screen.","ar":"على الهاتف لا يوجد تمرير للماوس، فلا يرى أغلب عملائي المساعدة أبدًا. وما يحتاجونه للدفع يجب أن يكون على الشاشة."}},{"id":"MC-P01-035","when":["placeholder"],"feedback":{"en":"Now it's visible, but it vanishes as soon as they type the first digit, while they're still turning the card over. Put it outside the field.","ar":"صار ظاهرًا، لكنه يختفي مع أول رقم يكتبونه، وهم ما زالوا يقلبون البطاقة. ضعه خارج الحقل."}}],"hints":[{"en":"How does someone on a phone open a hover tooltip?","ar":"كيف يفتح شخص على الهاتف Tooltip يعمل بتمرير الماوس؟"},{"en":"Which version shows the help without a hover and keeps it while typing?","ar":"أي نسخة تعرض المساعدة دون تمرير الماوس، وتُبقيها أثناء الكتابة؟"}],"correct":{"en":"Help people need to pay sits on the screen, outside the field.","ar":"المساعدة التي يحتاجها الناس للدفع موجودة على الشاشة، خارج الحقل."},"explain":{"en":"A tooltip hides help behind a gesture phones don't have. A short line under the label is seen by everyone, on every device, and stays while they type.","ar":"الـ Tooltip يُخفي المساعدة خلف حركة لا توجد في الهواتف. أما السطر القصير تحت العنوان فيراه الجميع، على كل جهاز، ويبقى أثناء الكتابة."},"speaker":"youssef"},{"id":"S07","type":"compare","skill":"SK-P01-U03-02","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast: both versions have a label, which is a step in the right direction. Placeholders (NN/g): hints should still be persistent and outside the field, so B's example survives typing.","ar":"مقارنة: في النسختين عنوان، وهذه خطوة في الاتجاه الصحيح. النص الداخلي (NN/g): ومع ذلك يجب أن تبقى التلميحات ظاهرة وخارج الحقل، لذلك يبقى مثال النسخة B بعد الكتابة."},"ref":{"url":"https://www.nngroup.com/articles/form-design-placeholders/","quote":"Using placeholder text in combination with form labels is a step in the right direction."},"scenario":{"en":"Our returns form asks for the order number. It looks like ORD-48291, and Yasser has typed the first part.","ar":"نموذج الإرجاع عندنا يطلب رقم الطلب. وهو يشبه ORD-48291، وقد كتب ياسر الجزء الأول."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Order number","ar":"رقم الطلب"},"filled":true,"focus":true,"text":"ORD-"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Order number","ar":"رقم الطلب"},"filled":true,"focus":true,"text":"ORD-","hint":{"en":"Like ORD-48291, on your receipt","ar":"مثل ORD-48291، على إيصالك"}}]}},"answer":"b","reason":{"prompt":{"en":"What makes B better, when both have a label?","ar":"ما الذي يجعل B أفضل، مع أن في الاثنتين عنوانًا؟"},"options":[{"id":"short","text":{"en":"Its label is shorter","ar":"عنوانها أقصر"}},{"id":"stays","text":{"en":"Its example is still there while he types","ar":"مثالها ما زال ظاهرًا أثناء كتابته"}},{"id":"pretty","text":{"en":"It looks more modern","ar":"تبدو أكثر حداثة"}}],"answer":["stays"],"misconceptions":[{"id":"MC-P01-035","when":["short","pretty"],"feedback":{"en":"Both labels are the same. The difference is the example: A had it inside the field, and typing erased it.","ar":"العنوانان متطابقان. الفرق في المثال: في A كان داخل الحقل، ومسحته الكتابة."}}]},"misconceptions":[{"id":"MC-P01-035","when":["a"],"feedback":{"en":"A's example was inside the field, and it disappeared with the first letter. Yasser now has to guess how many digits come next.","ar":"مثال A كان داخل الحقل، واختفى مع أول حرف. والآن على ياسر أن يخمّن كم رقمًا يأتي بعد ذلك."}}],"hints":[{"en":"Yasser has started typing. In which version can he still see what the number looks like?","ar":"بدأ ياسر الكتابة. في أي نسخة ما زال يرى شكل الرقم؟"},{"en":"Where did the example go in A?","ar":"أين ذهب المثال في A؟"}],"correct":{"en":"A label is good; a hint outside the field is what survives typing.","ar":"العنوان جيد؛ لكن التلميح خارج الحقل هو ما يبقى بعد الكتابة."},"explain":{"en":"A label alone fixes \"what is this field\". The format still has to be outside the box, so it's there exactly when people are typing and checking.","ar":"العنوان وحده يحلّ سؤال «ما هذا الحقل». لكن الصيغة يجب أن تكون خارج المربع أيضًا، لتكون موجودة تمامًا حين يكتب الناس ويراجعون."},"speaker":"youssef"},{"id":"S08","type":"tune","skill":"SK-P01-U03-01","part":"independent","speaker":"nour","rules":["R14","R19"],"value":{"en":"New case. Placeholders (NN/g): labels outside the fields keep the essential information visible at all times, so a patient can check each answer before submitting.","ar":"حالة جديدة. النص الداخلي (NN/g): العناوين خارج الحقول تُبقي المعلومة الأساسية ظاهرة طوال الوقت، فيستطيع المريض مراجعة كل إجابة قبل الإرسال."},"ref":{"url":"https://www.nngroup.com/articles/form-design-placeholders/","quote":"Labels outside the form fields make the essential information visible at all times"},"scenario":{"en":"In my clinic's app, patients sign in to see test results with two fields. Both only have grey words inside. Ahmed filled them in and now wants to check them before tapping Sign in, but both boxes just show numbers.","ar":"في تطبيق عيادتي، يدخل المرضى لرؤية نتائج التحاليل عبر حقلين. وكلاهما فيه كلمات رمادية بالداخل فقط. ملأهما أحمد ويريد الآن مراجعتهما قبل أن يضغط «دخول»، لكن المربعين يعرضان أرقامًا فقط."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"See your results","ar":"اطّلع على نتائجك"}},{"kind":"field","filled":true,"text":"48213","gap":"m"},{"kind":"field","filled":true,"text":"⁦0101 1985⁩","gap":"s"},{"kind":"button","text":{"en":"Sign in","ar":"دخول"},"gap":"m"}]},"options":[{"id":"icons","text":{"en":"Add a small icon inside each field","ar":"أضف أيقونة صغيرة داخل كل حقل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"See your results","ar":"اطّلع على نتائجك"}},{"kind":"field","filled":true,"text":"# 48213","gap":"m"},{"kind":"field","filled":true,"text":"▦ ⁦0101 1985⁩","gap":"s"},{"kind":"button","text":{"en":"Sign in","ar":"دخول"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep it; patients know what they typed","ar":"أبقِه؛ فالمرضى يعرفون ما كتبوه"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"See your results","ar":"اطّلع على نتائجك"}},{"kind":"field","filled":true,"text":"48213","gap":"m"},{"kind":"field","filled":true,"text":"⁦0101 1985⁩","gap":"s"},{"kind":"button","text":{"en":"Sign in","ar":"دخول"},"gap":"m"}]}},{"id":"labels","text":{"en":"Put \"File number\" and \"Date of birth\" above the fields","ar":"ضع «رقم الملف» و«تاريخ الميلاد» فوق الحقلين"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"See your results","ar":"اطّلع على نتائجك"}},{"kind":"field","label":{"en":"File number","ar":"رقم الملف"},"filled":true,"text":"48213","gap":"m"},{"kind":"field","label":{"en":"Date of birth (DDMM YYYY)","ar":"تاريخ الميلاد (يوم شهر سنة)"},"filled":true,"text":"⁦0101 1985⁩","gap":"s"},{"kind":"button","text":{"en":"Sign in","ar":"دخول"},"gap":"m"}]}}],"answer":["labels"],"misconceptions":[{"id":"MC-P01-034","when":["keep"],"feedback":{"en":"Two filled boxes of numbers look alike. Without labels, Ahmed can't tell if he put his file number in the date box. Labels let him check.","ar":"مربّعان مليئان بالأرقام يتشابهان. ومن دون عناوين، لا يعرف أحمد هل كتب رقم ملفه في مربع التاريخ. والعناوين تتيح له المراجعة."}},{"id":"MC-P01-034","when":["icons"],"feedback":{"en":"An icon still has to be guessed, and these two could mean many things. Words outside the field say exactly what each box holds.","ar":"الأيقونة ما زالت تحتاج تخمينًا، وهاتان قد تعنيان أشياء كثيرة. والكلمات خارج الحقل تقول بالضبط ماذا يحمل كل مربع."}}],"hints":[{"en":"After filling in both boxes, how can Ahmed tell which is which?","ar":"بعد ملء المربعين، كيف يعرف أحمد أيّهما أيّ؟"},{"en":"Which version still names each box once it's filled?","ar":"أي نسخة ما زالت تسمّي كل مربع بعد ملئه؟"}],"correct":{"en":"Labels outside let people check filled fields.","ar":"العناوين بالخارج تتيح مراجعة الحقول المعبّأة."},"explain":{"en":"The moment of checking comes after typing, exactly when placeholder words are gone. Labels outside are still there to confirm each answer.","ar":"لحظة المراجعة تأتي بعد الكتابة، أي تمامًا حين تختفي كلمات النص الداخلي. أما العناوين بالخارج فتبقى لتأكيد كل إجابة."}},{"id":"S09","type":"card","part":"recap","icons":["text","eye","warn","idea"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Labels outside:** replaced vanishing grey words with labels above each field.\n- **Hints outside:** put the phone format under the field, so it stayed while typing.\n- **No fake answers:** left the gift box empty under a label, so it didn't look already written.\n- **No hidden help:** showed where the card code is, instead of hiding it in a tooltip.\n\nNext lesson: where labels sit and how fields line up.","ar":"- **العناوين بالخارج:** استبدلت الكلمات الرمادية التي تختفي بعناوين فوق كل حقل.\n- **التلميحات بالخارج:** وضعت صيغة الهاتف تحت الحقل، فبقيت أثناء الكتابة.\n- **لا إجابات مزيّفة:** تركت مربع الهدية فارغًا تحت عنوان، حتى لا يبدو مكتوبًا.\n- **لا مساعدة مخفية:** عرضت مكان رمز البطاقة، بدل إخفائه في Tooltip.\n\nالدرس التالي: أين توضع العناوين وكيف تُرتّب الحقول."}}]}$uxg$::jsonb),
  ($uxg$P01-U03-L02$uxg$, $uxg$759b265fb767c1600681803adb34f6db58680cccec0db92d6414a8a489085aff$uxg$, $uxg${"id":"P01-U03-L02","mode":"lesson","minutes":8,"title":{"en":"Where labels sit, how fields line up","ar":"أين توضع العناوين، وكيف تُرتّب الحقول"},"speaker":"youssef","review_labels":{"MC-P01-038":{"en":"A label belongs nearest its own field","ar":"العنوان مكانه الأقرب إلى حقله"},"MC-P01-039":{"en":"On phones, labels go above fields","ar":"على الهاتف، العناوين فوق الحقول"},"MC-P01-040":{"en":"Two columns break the path down the form","ar":"العمودان يقطعان المسار إلى أسفل النموذج"},"MC-P01-041":{"en":"Group related fields under a heading","ar":"اجمع الحقول المترابطة تحت عنوان"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Nada's phone number","ar":"رقم هاتف ندى"},"body":{"en":"Nada created an account in my shop's app. Our sign-up form has labels, but each one sits halfway between two boxes.\n\nShe typed her email into the phone box, got an error, and gave up.","ar":"أنشأت ندى حسابًا في تطبيق متجري. ونموذج التسجيل عندنا فيه عناوين، لكن كل عنوان يقع في منتصف المسافة بين مربعين.\n\nكتبت بريدها في مربع الهاتف، فظهر خطأ، فتوقّفت."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Create your account","ar":"أنشئ حسابك"}},{"kind":"small","weight":"bold","text":{"en":"Full name","ar":"الاسم الكامل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"small","weight":"bold","text":{"en":"Mobile number","ar":"رقم الموبايل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"small","weight":"bold","text":{"en":"Email","ar":"البريد الإلكتروني"},"gap":"m"},{"kind":"field","text":"","gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U03-04","part":"try","rules":["R12"],"value":{"en":"Try first. White space in forms (NN/g): items near each other appear related, so place each label closer to its own field than to other fields. Equal gaps leave people guessing.","ar":"جرّب أولًا. المسافات في النماذج (NN/g): العناصر المتقاربة تبدو مترابطة، لذلك ضع كل عنوان أقرب إلى حقله منه إلى الحقول الأخرى. والمسافات المتساوية تترك الناس يخمّنون."},"ref":{"url":"https://www.nngroup.com/articles/form-design-white-space/","quote":"Place the label closer to the associated text field than to other text fields."},"prompt":{"en":"Try each spacing. Which one should ship?","ar":"جرّب كل توزيع للمسافات. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"title","text":{"en":"Create your account","ar":"أنشئ حسابك"}},{"kind":"small","weight":"bold","text":{"en":"Full name","ar":"الاسم الكامل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"small","weight":"bold","text":{"en":"Mobile number","ar":"رقم الموبايل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"small","weight":"bold","text":{"en":"Email","ar":"البريد الإلكتروني"},"gap":"m"},{"kind":"field","text":"","gap":"m"}]},"options":[{"id":"lines","text":{"en":"Keep the gaps, and add a line between fields","ar":"أبقِ المسافات، وأضف خطًّا بين الحقول"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Create your account","ar":"أنشئ حسابك"}},{"kind":"small","weight":"bold","text":{"en":"Full name","ar":"الاسم الكامل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"divider","gap":"s"},{"kind":"small","weight":"bold","text":{"en":"Mobile number","ar":"رقم الموبايل"},"gap":"s"},{"kind":"field","text":"","gap":"m"},{"kind":"divider","gap":"s"},{"kind":"small","weight":"bold","text":{"en":"Email","ar":"البريد الإلكتروني"},"gap":"s"},{"kind":"field","text":"","gap":"m"}]}},{"id":"tight","text":{"en":"Each label right on top of its field, more space before the next","ar":"كل عنوان فوق حقله مباشرة، ومسافة أكبر قبل الحقل التالي"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Create your account","ar":"أنشئ حسابك"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"l"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"l"}]}},{"id":"bold","text":{"en":"Keep the gaps, and make the labels bigger","ar":"أبقِ المسافات، واجعل العناوين أكبر"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"title","text":{"en":"Create your account","ar":"أنشئ حسابك"}},{"kind":"text","weight":"bold","text":{"en":"Full name","ar":"الاسم الكامل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"text","weight":"bold","text":{"en":"Mobile number","ar":"رقم الموبايل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"text","weight":"bold","text":{"en":"Email","ar":"البريد الإلكتروني"},"gap":"m"},{"kind":"field","text":"","gap":"m"}]}}],"answer":["tight"],"misconceptions":[{"id":"MC-P01-038","when":["lines","bold"],"feedback":{"en":"Each label is still as close to the box below it as to the box above it, so \"Mobile number\" could belong to either. Move it next to its own field.","ar":"ما زال كل عنوان قريبًا من المربع تحته بقدر قربه من المربع فوقه، فقد يخصّ «رقم الموبايل» أيًّا منهما. ضعه بجوار حقله."}}],"hints":[{"en":"In the Now screen, is \"Mobile number\" nearer the box above it or the one below?","ar":"في شاشة «الآن»، هل «رقم الموبايل» أقرب إلى المربع فوقه أم تحته؟"},{"en":"Which version makes the gap itself say which box a label belongs to?","ar":"أي نسخة تجعل المسافة نفسها تقول لأي مربع ينتمي العنوان؟"}],"correct":{"en":"A label hugs its own field; the bigger gap separates fields.","ar":"العنوان ملاصق لحقله؛ والمسافة الأكبر تفصل بين الحقول."},"explain":{"en":"People pair things that are close together. Keep each label tight to its field and leave a clearly bigger gap before the next one, and nobody has to guess.","ar":"يربط الناس بين الأشياء المتقاربة. اجعل كل عنوان ملاصقًا لحقله، واترك مسافة أكبر بوضوح قبل الحقل التالي، فلن يضطر أحد إلى التخمين."}},{"id":"S03","type":"card","part":"concept","icons":["space","phone","list","group"],"title":{"en":"Layout tells people what goes where","ar":"التخطيط يخبر الناس بما يُكتب وأين"},"body":{"en":"Before reading a word, people use position and spacing to understand a form.\n\n- **Close means related:** a label sits nearer its own field than any other field.\n- **Above, on phones:** put labels right above their fields on phones and short forms.\n- **One column:** fields in a single column give one clear path down the form.\n- **Groups with a heading:** related fields sit together under a short heading, like \"Delivery\" or \"Payment\".","ar":"قبل قراءة أي كلمة، يستخدم الناس المكان والمسافات لفهم النموذج.\n\n- **القريب مترابط:** العنوان أقرب إلى حقله من أي حقل آخر.\n- **فوق، على الهاتف:** ضع العناوين فوق حقولها مباشرة على الهواتف وفي النماذج القصيرة.\n- **عمود واحد:** الحقول في عمود واحد تعطي مسارًا واحدًا واضحًا إلى أسفل النموذج.\n- **مجموعات بعنوان:** الحقول المترابطة معًا تحت عنوان قصير، مثل «التوصيل» أو «الدفع»."}},{"id":"S04","type":"tune","skill":"SK-P01-U03-04","part":"guided","rules":["R06","R15"],"value":{"en":"Form usability (NN/g): put labels immediately above the field for mobile and shorter forms. Beside the field on a narrow phone, long labels squeeze the box or wrap awkwardly.","ar":"سهولة استخدام النماذج (NN/g): ضع العناوين فوق الحقل مباشرة على الهاتف وفي النماذج القصيرة. وبجانب الحقل على هاتف ضيّق، تضغط العناوين الطويلة المربع أو تنكسر بشكل غريب."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"immediately above the field for mobile and shorter desktop forms"},"scenario":{"en":"Our checkout was copied from the laptop design: each label sits to the left of its box. On a 320 px phone, the labels and boxes share one narrow line.","ar":"صفحة الدفع عندنا منسوخة من تصميم الـ Laptop: كل عنوان بجانب مربعه. وعلى هاتف بعرض 320 px، يتقاسم العنوان والمربع سطرًا واحدًا ضيقًا."},"prompt":{"en":"Try each layout on the small phone. Which one should ship?","ar":"جرّب كل تخطيط على الهاتف الصغير. أيّها يجب أن يُطلق؟"},"start":"beside","options":[{"id":"beside","text":{"en":"Labels beside the boxes, as on the laptop","ar":"العناوين بجانب المربعات، كما على الـ Laptop"},"mock":{"width":280,"caption":"320 px","blocks":[{"kind":"row","blocks":[{"kind":"small","weight":"bold","text":{"en":"Building and street","ar":"العمارة والشارع"}},{"kind":"field","text":""}]},{"kind":"row","gap":"s","blocks":[{"kind":"small","weight":"bold","text":{"en":"Nearest landmark","ar":"أقرب علامة مميّزة"}},{"kind":"field","text":""}]}]}},{"id":"above","text":{"en":"Each label right above its box","ar":"كل عنوان فوق مربعه مباشرة"},"mock":{"width":280,"caption":"320 px","blocks":[{"kind":"field","label":{"en":"Building and street","ar":"العمارة والشارع"},"text":""},{"kind":"field","label":{"en":"Nearest landmark","ar":"أقرب علامة مميّزة"},"text":"","gap":"m"}]}},{"id":"inside","text":{"en":"Labels inside the boxes, to save room","ar":"العناوين داخل المربعات، لتوفير المساحة"},"mock":{"width":280,"caption":"320 px","blocks":[{"kind":"field","text":{"en":"Building and street","ar":"العمارة والشارع"}},{"kind":"field","text":{"en":"Nearest landmark","ar":"أقرب علامة مميّزة"},"gap":"s"}]}}],"answer":["above"],"misconceptions":[{"id":"MC-P01-039","when":["beside"],"feedback":{"en":"Half the width goes to the label, so the box is too narrow to show what people type, and long labels wrap into the next row. On phones, stack them.","ar":"نصف العرض يذهب للعنوان، فيصبح المربع أضيق من أن يعرض ما يُكتب، وتنكسر العناوين الطويلة إلى السطر التالي. على الهاتف، ضعهما فوق بعض."}},{"id":"MC-P01-034","when":["inside"],"feedback":{"en":"It saves room, but the label disappears the moment someone types. You saw this in the last lesson: labels belong outside.","ar":"يوفّر مساحة، لكن العنوان يختفي لحظة الكتابة. رأيت هذا في الدرس الماضي: العناوين مكانها بالخارج."}}],"hints":[{"en":"How wide is the box people type into in each version?","ar":"ما عرض المربع الذي يكتب فيه الناس في كل نسخة؟"},{"en":"Which version gives the box the full width and keeps the label visible?","ar":"أي نسخة تعطي المربع العرض الكامل وتُبقي العنوان ظاهرًا؟"}],"correct":{"en":"On a phone, the label goes right above its field.","ar":"على الهاتف، يوضع العنوان فوق حقله مباشرة."},"explain":{"en":"Above the field, a label can be as long as it needs and the box gets the full width. People read straight down: label, box, label, box.","ar":"فوق الحقل، يمكن أن يكون العنوان بالطول الذي يحتاجه، ويأخذ المربع العرض الكامل. ويقرأ الناس إلى الأسفل مباشرة: عنوان، مربع، عنوان، مربع."},"speaker":"youssef"},{"id":"S05","type":"tune","skill":"SK-P01-U03-05","part":"guided","rules":["R06","R15"],"value":{"en":"Form usability (NN/g): present fields in a single column; multiple columns interrupt the vertical momentum of moving down the form, and people skip or misorder fields.","ar":"سهولة استخدام النماذج (NN/g): اعرض الحقول في عمود واحد؛ فالأعمدة المتعدّدة تقطع الحركة المستمرة إلى أسفل النموذج، فيتخطّى الناس حقولًا أو يملؤونها بترتيب خاطئ."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Multiple columns interrupt the vertical momentum of moving down the form."},"scenario":{"en":"On tablets, my team put the sign-up fields in two columns to make the form look shorter. Several customers left the right-hand fields empty.","ar":"على الأجهزة اللوحية، وضع فريقي حقول التسجيل في عمودين ليبدو النموذج أقصر. وترك عدد من العملاء حقول العمود الثاني فارغة."},"prompt":{"en":"Try each layout. Which one should ship?","ar":"جرّب كل تخطيط. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":340,"blocks":[{"kind":"row","blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":""}]},{"kind":"row","gap":"m","blocks":[{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":""},{"kind":"field","label":{"en":"City","ar":"المدينة"},"text":""}]},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]},"options":[{"id":"keep","text":{"en":"Keep two columns; it looks shorter","ar":"أبقِ العمودين؛ فالنموذج يبدو أقصر"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":340,"blocks":[{"kind":"row","blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":""}]},{"kind":"row","gap":"m","blocks":[{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":""},{"kind":"field","label":{"en":"City","ar":"المدينة"},"text":""}]},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]}},{"id":"number","text":{"en":"Keep two columns, and number the fields 1 to 4","ar":"أبقِ العمودين، ورقّم الحقول من 1 إلى 4"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":340,"blocks":[{"kind":"row","blocks":[{"kind":"field","label":{"en":"1. Full name","ar":"1. الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"2. Mobile number","ar":"2. رقم الموبايل"},"text":""}]},{"kind":"row","gap":"m","blocks":[{"kind":"field","label":{"en":"3. Email","ar":"3. البريد الإلكتروني"},"text":""},{"kind":"field","label":{"en":"4. City","ar":"4. المدينة"},"text":""}]},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]}},{"id":"one","text":{"en":"One column, one field under the other","ar":"عمود واحد، حقل تحت الآخر"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":340,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"m"},{"kind":"field","label":{"en":"City","ar":"المدينة"},"text":"","gap":"m"},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]}}],"answer":["one"],"misconceptions":[{"id":"MC-P01-040","when":["keep"],"feedback":{"en":"Looking shorter isn't the goal. With two columns, people go down the first one and miss the second, which is what happened. One column has one path.","ar":"أن يبدو أقصر ليس الهدف. مع عمودين، ينزل الناس في العمود الأول ويفوتهم الثاني، وهذا ما حدث. والعمود الواحد له مسار واحد."}},{"id":"MC-P01-040","when":["number"],"feedback":{"en":"Numbers make people zigzag on purpose: across, back, across. One column needs no numbers because the order is simply top to bottom.","ar":"الأرقام تجعل الناس يتنقّلون متعرّجين عمدًا: عبر السطر، ثم رجوعًا، ثم عبره مرة أخرى. والعمود الواحد لا يحتاج أرقامًا لأن الترتيب ببساطة من الأعلى إلى الأسفل."}}],"hints":[{"en":"In two columns, after Full name, which field comes next: the one beside it or the one below?","ar":"في العمودين، بعد «الاسم الكامل»، أي حقل يأتي: الذي بجانبه أم الذي تحته؟"},{"en":"Which layout has only one possible order?","ar":"أي تخطيط له ترتيب واحد ممكن فقط؟"}],"correct":{"en":"One column: one clear path, nothing skipped.","ar":"عمود واحد: مسار واحد واضح، ولا شيء يُتخطّى."},"explain":{"en":"A form is filled in order, so give it one order. In a single column, every field sits on the path down to the button.","ar":"النموذج يُملأ بالترتيب، فأعطه ترتيبًا واحدًا. في العمود الواحد، كل حقل يقع على المسار المؤدّي إلى الزر."},"speaker":"youssef"},{"id":"S06","type":"tune","skill":"SK-P01-U03-05","part":"guided","rules":["R06","R15"],"value":{"en":"White space in forms (NN/g): grouping related fields together helps people make sense of what they must fill in, and a group heading can add context.","ar":"المسافات في النماذج (NN/g): جمع الحقول المترابطة معًا يساعد الناس على فهم ما عليهم ملؤه، وعنوان المجموعة يضيف سياقًا."},"ref":{"url":"https://www.nngroup.com/articles/form-design-white-space/","quote":"Grouping related fields together helps users make sense of the information that they must fill in."},"scenario":{"en":"Our checkout now has eight fields in one even list: three about the person receiving the order, three about the address, and two about payment.","ar":"صفحة الدفع عندنا فيها الآن ثمانية حقول في قائمة واحدة متساوية: ثلاثة عن مستلم الطلب، وثلاثة عن العنوان، واثنان عن الدفع."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"list","options":[{"id":"list","text":{"en":"One even list of eight fields","ar":"قائمة واحدة متساوية من ثمانية حقول"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Receiver's name","ar":"اسم المستلم"},"text":""},{"kind":"field","label":{"en":"Receiver's mobile","ar":"موبايل المستلم"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Street and building","ar":"الشارع والعمارة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"text":"","gap":"s"},{"kind":"small","text":{"en":"+ 3 more fields","ar":"+ 3 حقول أخرى"},"gap":"s"}]}},{"id":"groups","text":{"en":"Three groups, each under a short heading","ar":"ثلاث مجموعات، كل منها تحت عنوان قصير"},"mock":{"width":300,"blocks":[{"kind":"heading","text":{"en":"Who receives it","ar":"من يستلم الطلب"}},{"kind":"field","label":{"en":"Receiver's name","ar":"اسم المستلم"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Receiver's mobile","ar":"موبايل المستلم"},"text":"","gap":"s"},{"kind":"heading","text":{"en":"Where to deliver","ar":"عنوان التوصيل"},"gap":"l"},{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Street and building","ar":"الشارع والعمارة"},"text":"","gap":"s"},{"kind":"heading","text":{"en":"Payment","ar":"الدفع"},"gap":"l"},{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"text":"","gap":"s"}]}},{"id":"cards","text":{"en":"Each field in its own card with a shadow","ar":"كل حقل في بطاقة مستقلة بظل"},"mock":{"width":300,"blocks":[{"kind":"group","tone":"tint","blocks":[{"kind":"field","label":{"en":"Receiver's name","ar":"اسم المستلم"},"text":""}]},{"kind":"group","tone":"tint","gap":"s","blocks":[{"kind":"field","label":{"en":"Receiver's mobile","ar":"موبايل المستلم"},"text":""}]},{"kind":"group","tone":"tint","gap":"s","blocks":[{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"text":""}]},{"kind":"group","tone":"tint","gap":"s","blocks":[{"kind":"field","label":{"en":"Street and building","ar":"الشارع والعمارة"},"text":""}]},{"kind":"small","text":{"en":"+ 4 more cards","ar":"+ 4 بطاقات أخرى"},"gap":"s"}]}}],"answer":["groups"],"misconceptions":[{"id":"MC-P01-041","when":["list"],"feedback":{"en":"Eight equal fields make one long wall. People can't see that the order has three parts, or how far along they are.","ar":"ثمانية حقول متساوية تصنع جدارًا طويلًا واحدًا. ولا يرى الناس أن الطلب من ثلاثة أجزاء، ولا إلى أين وصلوا."}},{"id":"MC-P01-041","when":["cards"],"feedback":{"en":"A card around every field separates everything equally, so nothing looks related. Group the fields that belong together.","ar":"بطاقة حول كل حقل تفصل كل شيء بالتساوي، فلا يبدو أي شيء مترابطًا. اجمع الحقول التي تنتمي لبعضها."}}],"hints":[{"en":"The eight fields are really about three things. Which version shows that?","ar":"الحقول الثمانية في الحقيقة عن ثلاثة أشياء. أي نسخة تُظهر ذلك؟"},{"en":"Which version puts related fields close together and unrelated ones apart?","ar":"أي نسخة تقرّب الحقول المترابطة وتُبعد غير المترابطة؟"}],"correct":{"en":"Related fields together, under a short heading.","ar":"الحقول المترابطة معًا، تحت عنوان قصير."},"explain":{"en":"Groups turn one long form into three short tasks. The headings tell people what each part is about, and the spacing shows where it ends.","ar":"المجموعات تحوّل نموذجًا طويلًا واحدًا إلى ثلاث مهام قصيرة. والعناوين تخبر الناس عمّا يخصّه كل جزء، والمسافات تُظهر أين ينتهي."},"speaker":"youssef"},{"id":"S07","type":"compare","skill":"SK-P01-U03-04","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S02: here both versions use tight spacing, but B puts each label under its field, so it sits right on top of the next field. White space in forms (NN/g): items near each other appear related.","ar":"مقارنة مع الخطوة 2: هنا تستخدم النسختان مسافات ضيقة، لكن B تضع كل عنوان تحت حقله، فيقع مباشرة فوق الحقل التالي. المسافات في النماذج (NN/g): العناصر المتقاربة تبدو مترابطة."},"ref":{"url":"https://www.nngroup.com/articles/form-design-white-space/","quote":"items near each other appear related"},"scenario":{"en":"A designer suggested putting the label under each box, \"like a caption\". Both versions below use the same tight spacing.","ar":"اقترح أحد المصمّمين وضع العنوان تحت كل مربع، «مثل التعليق على صورة». والنسختان أدناه بالمسافات الضيقة نفسها."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Area","ar":"المنطقة"},"text":""},{"kind":"field","label":{"en":"Street and building","ar":"الشارع والعمارة"},"text":"","gap":"l"},{"kind":"field","label":{"en":"Floor and flat","ar":"الدور والشقة"},"text":"","gap":"l"}]}},"b":{"mock":{"width":300,"blocks":[{"kind":"field","text":""},{"kind":"small","weight":"bold","text":{"en":"Area","ar":"المنطقة"},"gap":"xs"},{"kind":"field","text":"","gap":"l"},{"kind":"small","weight":"bold","text":{"en":"Street and building","ar":"الشارع والعمارة"},"gap":"xs"},{"kind":"field","text":"","gap":"l"},{"kind":"small","weight":"bold","text":{"en":"Floor and flat","ar":"الدور والشقة"},"gap":"xs"}]}},"answer":"a","reason":{"prompt":{"en":"Why does B confuse people?","ar":"لماذا تُربك B الناس؟"},"options":[{"id":"next","text":{"en":"Each label also sits right above the next box","ar":"كل عنوان يقع أيضًا فوق المربع التالي مباشرة"}},{"id":"font","text":{"en":"Its labels are in a smaller font","ar":"عناوينها بخط أصغر"}},{"id":"count","text":{"en":"It has more lines on the screen","ar":"فيها أسطر أكثر على الشاشة"}}],"answer":["next"],"misconceptions":[{"id":"MC-P01-038","when":["font","count"],"feedback":{"en":"Size and line count aren't the problem. People read a label, then look for the box under it, and in B that's the wrong box.","ar":"الحجم وعدد الأسطر ليسا المشكلة. يقرأ الناس العنوان، ثم يبحثون عن المربع تحته، وفي B هذا هو المربع الخطأ."}}]},"misconceptions":[{"id":"MC-P01-038","when":["b"],"feedback":{"en":"In B, \"Area\" sits under the first box and right on top of the second. People read down, so many will type the area into the second box.","ar":"في B، تقع «المنطقة» تحت المربع الأول ومباشرة فوق الثاني. والناس يقرؤون إلى الأسفل، فسيكتب كثيرون المنطقة في المربع الثاني."}}],"hints":[{"en":"In B, which box is right under the word \"Area\"?","ar":"في B، أي مربع يقع مباشرة تحت كلمة «المنطقة»؟"},{"en":"When people read a label, where do they expect its box?","ar":"حين يقرأ الناس عنوانًا، أين يتوقّعون مربعه؟"}],"correct":{"en":"Label above its box, so nothing sits between them.","ar":"العنوان فوق مربعه، فلا يفصل بينهما شيء."},"explain":{"en":"Tight spacing isn't enough on its own. The label has to be on the side people read first, above, so the box they meet next is the right one.","ar":"المسافة الضيقة وحدها لا تكفي. يجب أن يكون العنوان في الجهة التي يقرؤها الناس أولًا، أي فوق، ليكون المربع الذي يصلون إليه بعده هو الصحيح."},"speaker":"youssef"},{"id":"S08","type":"tune","skill":"SK-P01-U03-05","part":"independent","speaker":"hana","rules":["R14","R19"],"value":{"en":"New case. Form usability (NN/g): visually group related labels and fields, in a single column. The gym form mixes the member's details with the emergency contact's, side by side.","ar":"حالة جديدة. سهولة استخدام النماذج (NN/g): اجمع العناوين والحقول المترابطة بصريًا، في عمود واحد. ونموذج النادي يخلط بيانات العضو ببيانات جهة الطوارئ، جنبًا إلى جنب."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Visually group related labels and fields."},"scenario":{"en":"My gym's membership form shows the member's details in one column and an emergency contact in the column beside it. Several new members wrote their own mobile number as the emergency number.","ar":"نموذج الاشتراك في ناديّ يعرض بيانات العضو في عمود، وجهة اتصال للطوارئ في العمود المجاور. وكتب عدد من الأعضاء الجدد رقمهم هم كرقم للطوارئ."},"prompt":{"en":"Try each layout. Which one should ship?","ar":"جرّب كل تخطيط. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":340,"blocks":[{"kind":"row","blocks":[{"kind":"field","label":{"en":"Your name","ar":"اسمك"},"text":""},{"kind":"field","label":{"en":"Contact name","ar":"اسم جهة الاتصال"},"text":""}]},{"kind":"row","gap":"m","blocks":[{"kind":"field","label":{"en":"Your mobile","ar":"رقم موبايلك"},"text":""},{"kind":"field","label":{"en":"Contact mobile","ar":"رقم جهة الاتصال"},"text":""}]}]},"options":[{"id":"stack","text":{"en":"One column: your details, then \"In an emergency, call\"","ar":"عمود واحد: بياناتك، ثم «في حالة الطوارئ، اتصل بـ»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":340,"blocks":[{"kind":"heading","text":{"en":"Your details","ar":"بياناتك"}},{"kind":"field","label":{"en":"Your name","ar":"اسمك"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Your mobile","ar":"رقم موبايلك"},"text":"","gap":"s"},{"kind":"heading","text":{"en":"In an emergency, call","ar":"في حالة الطوارئ، اتصل بـ"},"gap":"l"},{"kind":"field","label":{"en":"Their name","ar":"اسمه"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Their mobile","ar":"رقم موبايله"},"text":"","gap":"s"}]}},{"id":"color","text":{"en":"Keep both columns; tint the emergency column","ar":"أبقِ العمودين؛ ولوّن عمود الطوارئ"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":340,"blocks":[{"kind":"row","blocks":[{"kind":"field","label":{"en":"Your name","ar":"اسمك"},"text":""},{"kind":"group","tone":"tint","blocks":[{"kind":"field","label":{"en":"Contact name","ar":"اسم جهة الاتصال"},"text":""}]}]},{"kind":"row","gap":"m","blocks":[{"kind":"field","label":{"en":"Your mobile","ar":"رقم موبايلك"},"text":""},{"kind":"group","tone":"tint","blocks":[{"kind":"field","label":{"en":"Contact mobile","ar":"رقم جهة الاتصال"},"text":""}]}]}]}},{"id":"keep","text":{"en":"Keep it; the labels say whose details they are","ar":"أبقِه؛ فالعناوين تقول بيانات من هذه"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":340,"blocks":[{"kind":"row","blocks":[{"kind":"field","label":{"en":"Your name","ar":"اسمك"},"text":""},{"kind":"field","label":{"en":"Contact name","ar":"اسم جهة الاتصال"},"text":""}]},{"kind":"row","gap":"m","blocks":[{"kind":"field","label":{"en":"Your mobile","ar":"رقم موبايلك"},"text":""},{"kind":"field","label":{"en":"Contact mobile","ar":"رقم جهة الاتصال"},"text":""}]}]}}],"answer":["stack"],"misconceptions":[{"id":"MC-P01-040","when":["keep","color"],"feedback":{"en":"Side by side, \"Your mobile\" and \"Contact mobile\" look like a pair, and people fill the row from left to right. One column with a heading per person keeps the two sets apart.","ar":"جنبًا إلى جنب، يبدو «رقم موبايلك» و«رقم جهة الاتصال» كزوج، ويملأ الناس السطر من جهة إلى أخرى. وعمود واحد بعنوان لكل شخص يفصل المجموعتين."}}],"hints":[{"en":"Which fields belong to the member, and which to someone else?","ar":"أي الحقول تخصّ العضو، وأيها تخصّ شخصًا آخر؟"},{"en":"Which layout puts each person's fields together, one after the other?","ar":"أي تخطيط يجمع حقول كل شخص معًا، واحدًا بعد الآخر؟"}],"correct":{"en":"One column, one group per person.","ar":"عمود واحد، ومجموعة لكل شخص."},"explain":{"en":"Two people's details are two groups. Stacking them, each under its own heading, makes the switch from \"you\" to \"them\" impossible to miss.","ar":"بيانات شخصين هي مجموعتان. ووضعهما فوق بعض، كل منهما تحت عنوانها، يجعل الانتقال من «أنت» إلى «هو» واضحًا لا يُفوَّت."}},{"id":"S09","type":"card","part":"recap","icons":["space","phone","list","group"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Close means related:** moved each label next to its own field, with a bigger gap before the next.\n- **Above on phones:** stacked labels over fields on a small screen.\n- **Label first:** kept labels above, never below, their boxes.\n- **One column:** replaced two columns that made people skip fields.\n- **Groups:** split a long checkout, and a gym form, into groups with headings.\n\nNext lesson: say the rules before people type.","ar":"- **القريب مترابط:** نقلت كل عنوان بجوار حقله، مع مسافة أكبر قبل الحقل التالي.\n- **فوق على الهاتف:** وضعت العناوين فوق الحقول على الشاشة الصغيرة.\n- **العنوان أولًا:** أبقيت العناوين فوق مربعاتها، لا تحتها أبدًا.\n- **عمود واحد:** استبدلت عمودين جعلا الناس يتخطّون حقولًا.\n- **المجموعات:** قسّمت صفحة دفع طويلة، ونموذج نادٍ، إلى مجموعات بعناوين.\n\nالدرس التالي: قل القواعد قبل أن يكتب الناس."}}]}$uxg$::jsonb),
  ($uxg$P01-U03-L03$uxg$, $uxg$150675e720e87d779f74a7f03262e73a3b0cde122b3167f3a9de4bcb7a0592ee$uxg$, $uxg${"id":"P01-U03-L03","mode":"lesson","minutes":8,"title":{"en":"Say the rules before people type","ar":"قل القواعد قبل أن يكتب الناس"},"speaker":"youssef","review_labels":{"MC-P01-042":{"en":"Rules go before typing, not in the error","ar":"القواعد تأتي قبل الكتابة، لا في رسالة الخطأ"},"MC-P01-043":{"en":"A rule must be exact, not general","ar":"القاعدة يجب أن تكون دقيقة، لا عامة"},"MC-P01-037":{"en":"Needed info can't hide in a tooltip","ar":"المعلومة الضرورية لا تُخفى في Tooltip"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Nada's password","ar":"كلمة مرور ندى"},"body":{"en":"Nada is setting a password in my shop's app. The form gives no rules. Each time she taps Create account, she gets \"Password doesn't meet the requirements\".\n\nShe tried three passwords, then left.","ar":"تضع ندى كلمة مرور في تطبيق متجري. والنموذج لا يذكر أي قواعد. وكل مرة تضغط «أنشئ الحساب»، تظهر لها «كلمة المرور لا تستوفي الشروط».\n\nجرّبت ثلاث كلمات مرور، ثم غادرت."},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"text":"••••••","tone":"bad","error":{"en":"Password doesn't meet the requirements.","ar":"كلمة المرور لا تستوفي الشروط."}},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U03-06","part":"try","rules":["R12"],"value":{"en":"Try first. Form usability (NN/g): don't make people guess password requirements. Rules that appear only after a failed try turn the form into a guessing game.","ar":"جرّب أولًا. سهولة استخدام النماذج (NN/g): لا تجعل الناس يخمّنون شروط كلمة المرور. والقواعد التي تظهر فقط بعد محاولة فاشلة تحوّل النموذج إلى لعبة تخمين."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Don’t make users guess your obscure password requirements."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"text":"••••••","tone":"bad","error":{"en":"Password doesn't meet the requirements.","ar":"كلمة المرور لا تستوفي الشروط."}},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]},"options":[{"id":"loud","text":{"en":"Keep it, but make the error bigger and bolder","ar":"أبقِه، لكن اجعل رسالة الخطأ أكبر وأوضح"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"text":"••••••","tone":"bad"},{"kind":"banner","tone":"bad","text":{"en":"PASSWORD DOESN'T MEET THE REQUIREMENTS!","ar":"كلمة المرور لا تستوفي الشروط!"},"gap":"s"},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]}},{"id":"tip","text":{"en":"Add an ⓘ next to the label that shows the rules","ar":"أضف ⓘ بجانب العنوان تعرض القواعد"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Password ⓘ","ar":"كلمة المرور ⓘ"},"text":""},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]}},{"id":"rules","text":{"en":"Show the rules under the label, before she types","ar":"اعرض القواعد تحت العنوان، قبل أن تكتب"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"hintFirst":true,"hint":{"en":"At least 8 characters, including one number","ar":"8 أحرف على الأقل، منها رقم واحد"},"text":""},{"kind":"button","text":{"en":"Create account","ar":"أنشئ الحساب"},"gap":"m"}]}}],"answer":["rules"],"misconceptions":[{"id":"MC-P01-042","when":["loud"],"feedback":{"en":"A louder error still comes after the mistake, and it still doesn't say what the rules are. Nada needs them before she types.","ar":"رسالة الخطأ الأعلى صوتًا ما زالت تأتي بعد الخطأ، وما زالت لا تقول ما هي القواعد. وندى تحتاجها قبل أن تكتب."}},{"id":"MC-P01-037","when":["tip"],"feedback":{"en":"The rules exist now, but only for people who find and open the ⓘ, and on a phone there's no hover. Anyone who must follow a rule needs to see it.","ar":"صارت القواعد موجودة، لكن فقط لمن يجد ⓘ ويفتحها، والهاتف ليس فيه تمرير للماوس. ومن يجب أن يتبع قاعدة يحتاج أن يراها."}}],"hints":[{"en":"When does Nada find out what the rules are in each version?","ar":"متى تعرف ندى القواعد في كل نسخة؟"},{"en":"Which version lets her get it right on the first try?","ar":"أي نسخة تتيح لها أن تنجح من المحاولة الأولى؟"}],"correct":{"en":"Visible rules, before typing.","ar":"قواعد ظاهرة، قبل الكتابة."},"explain":{"en":"If a field has rules, they're part of the question. Showing them up front turns three failed tries into one right one.","ar":"إذا كان للحقل قواعد، فهي جزء من السؤال. وعرضها من البداية يحوّل ثلاث محاولات فاشلة إلى محاولة واحدة صحيحة."}},{"id":"S03","type":"card","part":"concept","icons":["list","eye","target","warn"],"title":{"en":"Rules are part of the question","ar":"القواعد جزء من السؤال"},"body":{"en":"When a field only accepts some answers, tell people which ones before they start.\n\n- **Before typing:** show the rule with the field, not only in an error afterwards.\n- **Exact:** \"At least 8 characters, including one number\", not \"Use a strong password\".\n- **Still visible while typing:** outside the field, so it stays there.\n- **Not behind an icon:** a rule people must follow belongs on the screen. A tooltip can hold nice-to-know extras.","ar":"حين يقبل الحقل إجابات معيّنة فقط، أخبر الناس بها قبل أن يبدؤوا.\n\n- **قبل الكتابة:** اعرض القاعدة مع الحقل، لا في رسالة خطأ بعدها فقط.\n- **دقيقة:** «8 أحرف على الأقل، منها رقم واحد»، لا «استخدم كلمة مرور قوية».\n- **ظاهرة أثناء الكتابة:** خارج الحقل، حتى تبقى.\n- **ليست خلف أيقونة:** القاعدة التي يجب أن يتبعها الناس مكانها على الشاشة. والـ Tooltip يمكن أن يحمل معلومات إضافية من باب «من الجيد أن تعرف»."}},{"id":"S04","type":"tune","skill":"SK-P01-U03-06","part":"guided","rules":["R06","R15"],"value":{"en":"Form usability (NN/g): if a field requires a specific format or type of input, state the exact instructions. A photo upload that rejects large files must say the limit first.","ar":"سهولة استخدام النماذج (NN/g): إذا كان الحقل يتطلّب صيغة أو نوعًا محدّدًا من الإدخال، فاذكر التعليمات بدقة. ورفع الصور الذي يرفض الملفات الكبيرة يجب أن يذكر الحدّ أولًا."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"If a field requires a specific format or type of input, state the exact instructions."},"scenario":{"en":"To return a broken item, customers upload a photo. Our system takes JPG or PNG up to 5 MB. Phone photos are often bigger, and people only learn this after waiting for the upload to fail.","ar":"لإرجاع منتج مكسور، يرفع العملاء صورة. ونظامنا يقبل JPG أو PNG حتى 5 MB. وصور الهواتف غالبًا أكبر، ولا يعرف الناس ذلك إلا بعد انتظار فشل الرفع."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"before","options":[{"id":"before","text":{"en":"Under the label: \"JPG or PNG, up to 5 MB\"","ar":"تحت العنوان: «JPG أو PNG، حتى 5 MB»"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Photo of the damage","ar":"صورة للتلف"}},{"kind":"small","text":{"en":"JPG or PNG, up to 5 MB","ar":"JPG أو PNG، حتى 5 MB"},"gap":"xs"},{"kind":"button","emphasis":"low","text":{"en":"Choose a photo","ar":"اختر صورة"},"gap":"s"}]}},{"id":"after","text":{"en":"Keep it; the error explains the limit","ar":"أبقِه؛ فرسالة الخطأ تشرح الحدّ"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Photo of the damage","ar":"صورة للتلف"}},{"kind":"button","emphasis":"low","text":{"en":"Choose a photo","ar":"اختر صورة"},"gap":"s"},{"kind":"banner","tone":"bad","text":{"en":"Upload failed: file too large (max 5 MB).","ar":"فشل الرفع: الملف كبير جدًا (الحدّ 5 MB)."},"gap":"s"}]}},{"id":"vague","text":{"en":"Under the label: \"Please upload a suitable photo\"","ar":"تحت العنوان: «يُرجى رفع صورة مناسبة»"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Photo of the damage","ar":"صورة للتلف"}},{"kind":"small","text":{"en":"Please upload a suitable photo","ar":"يُرجى رفع صورة مناسبة"},"gap":"xs"},{"kind":"button","emphasis":"low","text":{"en":"Choose a photo","ar":"اختر صورة"},"gap":"s"}]}}],"answer":["before"],"misconceptions":[{"id":"MC-P01-042","when":["after"],"feedback":{"en":"The error is clear, but it arrives after a long wait for an upload that was never going to work. Say the limit before they pick a photo.","ar":"رسالة الخطأ واضحة، لكنها تصل بعد انتظار طويل لرفع لم يكن لينجح أبدًا. اذكر الحدّ قبل أن يختاروا صورة."}},{"id":"MC-P01-043","when":["vague"],"feedback":{"en":"\"Suitable\" doesn't tell anyone the type or the size. Only the exact rule lets them choose the right file.","ar":"«مناسبة» لا تخبر أحدًا بالنوع أو الحجم. والقاعدة الدقيقة وحدها تتيح لهم اختيار الملف الصحيح."}}],"hints":[{"en":"What two facts decide whether a photo will upload?","ar":"ما المعلومتان اللتان تحدّدان هل ستُرفع الصورة؟"},{"en":"Which version gives both facts before the person picks a photo?","ar":"أي نسخة تعطي المعلومتين قبل أن يختار الشخص صورة؟"}],"correct":{"en":"The exact type and size, before choosing.","ar":"النوع والحجم بدقة، قبل الاختيار."},"explain":{"en":"A rule is useful only if it comes in time and says exactly what's accepted. Then people can pick, or shrink, the right photo at once.","ar":"القاعدة مفيدة فقط إذا جاءت في وقتها وقالت بالضبط ما المقبول. حينها يستطيع الناس اختيار الصورة المناسبة، أو تصغيرها، من البداية."},"speaker":"youssef"},{"id":"S05","type":"tune","skill":"SK-P01-U03-03","part":"guided","rules":["R06","R15"],"value":{"en":"Tooltips (NN/g): people shouldn't need to find a tooltip to complete their task. Customers can't receive a refund without finding their IBAN, so that help must be on the screen.","ar":"الـ Tooltip (NN/g): يجب ألا يحتاج الناس إلى إيجاد Tooltip لإكمال مهمتهم. ولا يستطيع العملاء استلام المبلغ المسترد دون إيجاد رقم الـ IBAN، فالمساعدة يجب أن تكون على الشاشة."},"ref":{"url":"https://www.nngroup.com/articles/tooltip-guidelines/","quote":"Users shouldn’t need to find a tooltip in order to complete their task."},"scenario":{"en":"Refunds go to the customer's bank account. The field asks for an IBAN, which starts with EG and has 29 characters; most people find it in their bank app. That help only appears when you hover over the ⓘ.","ar":"يُحوَّل المبلغ المسترد إلى حساب العميل في البنك. والحقل يطلب رقم الـ IBAN، الذي يبدأ بـ EG ويتكوّن من 29 حرفًا ورقمًا؛ ويجده أغلب الناس في تطبيق البنك. وهذه المساعدة تظهر فقط عند تمرير الماوس فوق ⓘ."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"IBAN ⓘ","ar":"رقم الـ IBAN ⓘ"},"text":""},{"kind":"button","text":{"en":"Send my refund","ar":"أرسل المبلغ المسترد"},"gap":"m"}]},"options":[{"id":"keep","text":{"en":"Keep the ⓘ; most people know what an IBAN is","ar":"أبقِ ⓘ؛ فأغلب الناس يعرفون ما الـ IBAN"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"IBAN ⓘ","ar":"رقم الـ IBAN ⓘ"},"text":""},{"kind":"button","text":{"en":"Send my refund","ar":"أرسل المبلغ المسترد"},"gap":"m"}]}},{"id":"hint","text":{"en":"Show the help under the label","ar":"اعرض المساعدة تحت العنوان"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"IBAN","ar":"رقم الـ IBAN"},"hintFirst":true,"hint":{"en":"Starts with EG, 29 characters. You'll find it in your bank app.","ar":"يبدأ بـ EG، و29 حرفًا ورقمًا. ستجده في تطبيق البنك."},"text":""},{"kind":"button","text":{"en":"Send my refund","ar":"أرسل المبلغ المسترد"},"gap":"m"}]}},{"id":"link","text":{"en":"Add a link: \"What's an IBAN?\" to our help page","ar":"أضف رابطًا: «ما هو الـ IBAN؟» إلى صفحة المساعدة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"IBAN","ar":"رقم الـ IBAN"},"text":""},{"kind":"link","text":{"en":"What's an IBAN?","ar":"ما هو الـ IBAN؟"},"gap":"xs"},{"kind":"button","text":{"en":"Send my refund","ar":"أرسل المبلغ المسترد"},"gap":"m"}]}}],"answer":["hint"],"misconceptions":[{"id":"MC-P01-037","when":["keep"],"feedback":{"en":"If people can't find their IBAN, they can't get their money. Help that the task depends on can't wait behind a hover that phones don't have.","ar":"إذا لم يجد الناس رقم الـ IBAN، فلن يستلموا أموالهم. والمساعدة التي تعتمد عليها المهمة لا يمكن أن تنتظر خلف تمرير ماوس لا يوجد في الهواتف."}},{"id":"MC-P01-037","when":["link"],"feedback":{"en":"A link sends them away from the form to read a page. The two facts they need fit in one line right here.","ar":"الرابط يُخرجهم من النموذج لقراءة صفحة. والمعلومتان اللتان يحتاجونهما تتّسعان في سطر واحد هنا."}}],"hints":[{"en":"Can someone get a refund without knowing where to find their IBAN?","ar":"هل يستطيع أحد استلام المبلغ دون أن يعرف أين يجد رقم الـ IBAN؟"},{"en":"Which version gives that help without a hover or leaving the form?","ar":"أي نسخة تعطي هذه المساعدة دون تمرير ماوس أو مغادرة النموذج؟"}],"correct":{"en":"Help the task needs is on the screen.","ar":"المساعدة التي تحتاجها المهمة على الشاشة."},"explain":{"en":"Ask: could someone finish without this? If not, show it next to the field, in a line short enough to read while typing.","ar":"اسأل: هل يستطيع أحد الإنهاء بدون هذه المعلومة؟ إذا كان الجواب لا، فاعرضها بجانب الحقل، في سطر قصير يُقرأ أثناء الكتابة."},"speaker":"youssef"},{"id":"S06","type":"words","skill":"SK-P01-U03-06","part":"guided","confidence":true,"rules":["R06","R15"],"value":{"en":"Form usability (NN/g): state the exact instructions. Only a rule with real numbers and limits lets people choose a username that works the first time.","ar":"سهولة استخدام النماذج (NN/g): اذكر التعليمات بدقة. والقاعدة التي فيها أرقام وحدود حقيقية هي وحدها التي تتيح للناس اختيار اسم مستخدم يعمل من المرة الأولى."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"If a field requires a specific format or type of input, state the exact instructions."},"scenario":{"en":"Customers also pick a username for reviews. Our system accepts 4 to 15 letters or numbers, with no spaces.","ar":"يختار العملاء أيضًا اسم مستخدم للتقييمات. ونظامنا يقبل من 4 إلى 15 حرفًا أو رقمًا، بلا مسافات."},"prompt":{"en":"Which line should sit under the \"Username\" label?","ar":"أي سطر يجب أن يوضع تحت عنوان «اسم المستخدم»؟"},"options":[{"id":"valid","text":{"en":"\"Choose a valid username.\"","ar":"«اختر اسم مستخدم صالحًا.»"}},{"id":"rules","text":{"en":"\"Username must follow our rules.\"","ar":"«يجب أن يتبع اسم المستخدم قواعدنا.»"}},{"id":"exact","text":{"en":"\"4 to 15 letters or numbers, no spaces.\"","ar":"«من 4 إلى 15 حرفًا أو رقمًا، بلا مسافات.»"}}],"answer":["exact"],"misconceptions":[{"id":"MC-P01-043","when":["valid","rules"],"feedback":{"en":"This tells people a rule exists without saying what it is. They'd still have to guess, and fail, to find out.","ar":"هذا يخبر الناس أن هناك قاعدة دون أن يقول ما هي. وسيظلّون يخمّنون، ويفشلون، ليعرفوها."}}],"hints":[{"en":"After reading the line, could someone type a username that's sure to work?","ar":"بعد قراءة السطر، هل يستطيع أحد كتابة اسم مستخدم يعمل بالتأكيد؟"},{"en":"Which line names the length and the allowed characters?","ar":"أي سطر يذكر الطول والحروف المسموح بها؟"}],"correct":{"en":"Exact: length, characters and the one thing not allowed.","ar":"دقيقة: الطول، والحروف، والشيء الوحيد غير المسموح."},"explain":{"en":"A useful rule can be checked against what you type. \"Valid\" and \"our rules\" can't; numbers and a clear limit can.","ar":"القاعدة المفيدة يمكن مقارنتها بما تكتبه. «صالح» و«قواعدنا» لا يمكن مقارنتهما؛ أما الأرقام والحدّ الواضح فيمكن."},"speaker":"youssef"},{"id":"S07","type":"compare","skill":"SK-P01-U03-03","part":"contrast","rules":["R11","R15"],"value":{"en":"Contrast with S05: tooltips aren't banned. Tooltips (NN/g): they shouldn't be essential for the task. A nice-to-know reason can sit in a tooltip; a rule people must follow can't.","ar":"مقارنة مع الخطوة 5: الـ Tooltip ليس ممنوعًا. الـ Tooltip (NN/g): يجب ألا يكون ضروريًا لإنجاز المهمة. والسبب الذي «من الجيد معرفته» يمكن أن يوضع في Tooltip؛ أما القاعدة التي يجب اتّباعها فلا."},"ref":{"url":"https://www.nngroup.com/articles/tooltip-guidelines/","quote":"tooltips shouldn’t be essential for the tasks users need to accomplish on your site."},"scenario":{"en":"Two screens in my app each use an ⓘ. Screen A explains why we ask for a birthday (an optional field): \"We send you a small gift.\" Screen B hides the delivery phone format: \"11 digits, starting with 01.\"","ar":"شاشتان في تطبيقي تستخدم كل منهما ⓘ. الشاشة A تشرح لماذا نسأل عن تاريخ الميلاد (حقل اختياري): «نرسل لك هدية صغيرة». والشاشة B تُخفي صيغة هاتف التوصيل: «11 رقمًا، يبدأ بـ 01»."},"prompt":{"en":"Which screen uses its ⓘ in an acceptable way?","ar":"أي شاشة تستخدم ⓘ بطريقة مقبولة؟"},"a":{"label":{"en":"Birthday, optional","ar":"تاريخ الميلاد، اختياري"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Birthday (optional) ⓘ","ar":"تاريخ الميلاد (اختياري) ⓘ"},"text":""}]}},"b":{"label":{"en":"Delivery phone","ar":"هاتف التوصيل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Phone for the driver ⓘ","ar":"رقم هاتف للسائق ⓘ"},"text":""}]}},"answer":"a","reason":{"prompt":{"en":"What makes A's tooltip acceptable?","ar":"ما الذي يجعل Tooltip الشاشة A مقبولًا؟"},"options":[{"id":"short","text":{"en":"Its text is shorter","ar":"نصه أقصر"}},{"id":"extra","text":{"en":"Nobody needs it to fill in the form correctly","ar":"لا أحد يحتاجه لملء النموذج بشكل صحيح"}},{"id":"optional","text":{"en":"Optional fields can never have rules","ar":"الحقول الاختيارية لا يمكن أن تكون لها قواعد"}}],"answer":["extra"],"misconceptions":[{"id":"MC-P01-037","when":["short","optional"],"feedback":{"en":"Length isn't the test. Ask whether anyone could fail the task without reading it. The gift reason: no. The phone format: yes.","ar":"الطول ليس المعيار. اسأل هل يمكن أن يفشل أحد في المهمة دون قراءته. سبب الهدية: لا. وصيغة الهاتف: نعم."}}]},"misconceptions":[{"id":"MC-P01-037","when":["b"],"feedback":{"en":"B hides a rule people must follow for the driver to reach them, and on phones they can't hover to see it. That one has to be on the screen.","ar":"B تُخفي قاعدة يجب أن يتبعها الناس ليصل إليهم السائق، وعلى الهواتف لا يمكنهم تمرير الماوس لرؤيتها. وهذه يجب أن تكون على الشاشة."}}],"hints":[{"en":"If someone never opens the ⓘ, which screen can they still fill in correctly?","ar":"إذا لم يفتح أحد ⓘ أبدًا، فأي شاشة ما زال يستطيع ملأها بشكل صحيح؟"},{"en":"Which tooltip holds a rule, and which holds a nice-to-know reason?","ar":"أي Tooltip يحمل قاعدة، وأيّهما يحمل سببًا من باب «من الجيد أن تعرف»؟"}],"correct":{"en":"A tooltip can hold extras, never what the task needs.","ar":"الـ Tooltip يمكن أن يحمل إضافات، لا ما تحتاجه المهمة أبدًا."},"explain":{"en":"The test is simple: could someone fail without reading it? If yes, it belongs on the screen. If no, a tooltip is fine, for people with a mouse.","ar":"المعيار بسيط: هل يمكن أن يفشل أحد دون قراءته؟ إذا كان نعم، فمكانه على الشاشة. وإذا كان لا، فالـ Tooltip مناسب، لمن لديه ماوس."},"speaker":"youssef"},{"id":"S08","type":"tune","skill":"SK-P01-U03-06","part":"independent","speaker":"karim","rules":["R14","R19"],"value":{"en":"New case. Form usability (NN/g): state the exact instructions for input a field accepts. A daily transfer limit is a rule on the amount field, so it belongs there before people type.","ar":"حالة جديدة. سهولة استخدام النماذج (NN/g): اذكر بدقة ما يقبله الحقل. وحدّ التحويل اليومي قاعدة لحقل المبلغ، فمكانها هناك قبل أن يكتب الناس."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"If a field requires a specific format or type of input, state the exact instructions."},"scenario":{"en":"I'm building a bank app. People can send up to 10,000 EGP a day. Mostafa typed 15,000 to pay his rent, filled in the rest, and only then got \"Amount exceeds limit\".","ar":"أبني تطبيقًا لبنك. يستطيع الناس تحويل 10,000 جنيه يوميًا كحدّ أقصى. كتب مصطفى 15,000 ليدفع الإيجار، وملأ باقي الحقول، ثم ظهرت له فقط «المبلغ يتجاوز الحدّ»."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Amount (EGP)","ar":"المبلغ (جنيه)"},"filled":true,"text":"15,000"},{"kind":"field","label":{"en":"To","ar":"إلى"},"filled":true,"text":{"en":"Landlord","ar":"صاحب الشقة"},"gap":"m"},{"kind":"banner","tone":"bad","text":{"en":"Amount exceeds limit.","ar":"المبلغ يتجاوز الحدّ."},"gap":"m"}]},"options":[{"id":"limit","text":{"en":"Show \"Up to 10,000 EGP a day\" under the amount label","ar":"اعرض «حتى 10,000 جنيه يوميًا» تحت عنوان المبلغ"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Amount (EGP)","ar":"المبلغ (جنيه)"},"hintFirst":true,"hint":{"en":"Up to 10,000 EGP a day","ar":"حتى 10,000 جنيه يوميًا"},"text":""},{"kind":"field","label":{"en":"To","ar":"إلى"},"text":"","gap":"m"}]}},{"id":"cap","text":{"en":"Quietly stop the field at 10,000","ar":"أوقف الحقل عند 10,000 دون أي رسالة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Amount (EGP)","ar":"المبلغ (جنيه)"},"filled":true,"text":"10,000"},{"kind":"field","label":{"en":"To","ar":"إلى"},"filled":true,"text":{"en":"Landlord","ar":"صاحب الشقة"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep the message at the end","ar":"أبقِ الرسالة في النهاية"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Amount (EGP)","ar":"المبلغ (جنيه)"},"filled":true,"text":"15,000"},{"kind":"field","label":{"en":"To","ar":"إلى"},"filled":true,"text":{"en":"Landlord","ar":"صاحب الشقة"},"gap":"m"},{"kind":"banner","tone":"bad","text":{"en":"Amount exceeds limit.","ar":"المبلغ يتجاوز الحدّ."},"gap":"m"}]}}],"answer":["limit"],"misconceptions":[{"id":"MC-P01-042","when":["keep"],"feedback":{"en":"Mostafa only learns the rule after doing all the work, and \"exceeds limit\" doesn't even say what the limit is. Say it with the field.","ar":"لا يعرف مصطفى القاعدة إلا بعد إنجاز كل العمل، و«يتجاوز الحدّ» لا تقول حتى ما هو الحدّ. اذكره مع الحقل."}},{"id":"MC-P01-042","when":["cap"],"feedback":{"en":"He typed 15,000 and the app silently sent 10,000. He may not notice, and his rent is short. A hidden rule is still a surprise; show it.","ar":"كتب 15,000 فحوّل التطبيق 10,000 دون أن يقول شيئًا. وقد لا يلاحظ، فيصبح الإيجار ناقصًا. والقاعدة المخفية تظل مفاجأة؛ فاعرضها."}}],"hints":[{"en":"When does Mostafa learn the limit in each version, if at all?","ar":"متى يعرف مصطفى الحدّ في كل نسخة، إن عرفه أصلًا؟"},{"en":"Which version lets him plan, say, two transfers, before he starts?","ar":"أي نسخة تتيح له أن يخطّط، مثلًا لتحويلين، قبل أن يبدأ؟"}],"correct":{"en":"The limit sits with the field, before he types.","ar":"الحدّ مكتوب مع الحقل، قبل أن يكتب."},"explain":{"en":"A limit is a rule about what the field accepts, so say it there, with the real number. Then people can plan around it instead of hitting it.","ar":"الحدّ قاعدة عمّا يقبله الحقل، فاذكره هناك، بالرقم الحقيقي. حينها يستطيع الناس التخطيط حوله بدل الاصطدام به."}},{"id":"S09","type":"card","part":"recap","icons":["list","eye","target","warn"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Rules first:** showed password rules before typing, not only in an error.\n- **Exact rules:** named the file type and size, and a username's length and characters.\n- **Help on the screen:** showed where to find an IBAN instead of hiding it.\n- **Tooltips for extras:** kept an ⓘ only for a nice-to-know reason.\n- **Limits up front:** put a bank's daily limit with the amount field.\n\nNext: the skill check for this unit.","ar":"- **القواعد أولًا:** عرضت قواعد كلمة المرور قبل الكتابة، لا في رسالة خطأ فقط.\n- **قواعد دقيقة:** ذكرت نوع الملف وحجمه، وطول اسم المستخدم وحروفه.\n- **المساعدة على الشاشة:** عرضت أين يوجد رقم الـ IBAN بدل إخفائه.\n- **الـ Tooltip للإضافات:** أبقيت ⓘ فقط لسبب من باب «من الجيد أن تعرف».\n- **الحدود من البداية:** وضعت الحدّ اليومي للبنك مع حقل المبلغ.\n\nالتالي: اختبار المهارة لهذه الوحدة."}}]}$uxg$::jsonb),
  ($uxg$P01-U03-L04$uxg$, $uxg$c421f8701176c5ff72ce4b2508b29f20f8b0bd769e3cfe1aee17ce7c81343e5d$uxg$, $uxg${"id":"P01-U03-L04","mode":"check","minutes":7,"title":{"en":"Skill check: keep labels and hints in sight","ar":"اختبار المهارة: أبقِ العناوين والتلميحات ظاهرة"},"speaker":"nour","steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Samira's first visit","ar":"الزيارة الأولى لسميرة"},"body":{"en":"Samira is booking her first visit at my clinic on her phone. Our booking form came from an old template: grey words inside the boxes, a few ⓘ icons, and rules that only show up in errors.\n\nYour job: fix the form so she can fill it in right the first time.\n\nThis is a skill check: no hints, and you'll see how you did at the end.","ar":"تحجز سميرة زيارتها الأولى في عيادتي من هاتفها. ونموذج الحجز عندنا مأخوذ من قالب قديم: كلمات رمادية داخل المربعات، وبعض أيقونات ⓘ، وقواعد لا تظهر إلا في رسائل الخطأ.\n\nمهمّتك: أصلح النموذج لتملأه بشكل صحيح من المرة الأولى.\n\nهذا اختبار مهارة: بدون تلميحات، وسترى نتيجتك في النهاية."},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Book your first visit","ar":"احجز زيارتك الأولى"}},{"kind":"field","text":{"en":"Full name","ar":"الاسم الكامل"},"gap":"m"},{"kind":"field","text":{"en":"Date of birth","ar":"تاريخ الميلاد"},"gap":"s"},{"kind":"field","label":{"en":"Insurance number ⓘ","ar":"رقم التأمين ⓘ"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Book visit ⓘ","ar":"احجز الزيارة ⓘ"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U03-01","part":"check","rules":["R19"],"value":{"en":"Skill check, placeholders (NN/g): people may mistake a placeholder for data that was filled in, and it vanishes once they type. Clear labels outside empty fields fix both.","ar":"اختبار مهارة، النص الداخلي (NN/g): قد يظن الناس أن النص الداخلي بيانات معبّأة، ثم يختفي حين يكتبون. والعناوين الواضحة خارج حقول فارغة تحلّ المشكلتين."},"ref":{"url":"https://www.nngroup.com/articles/form-design-placeholders/","quote":"Users may mistake a placeholder for data that was automatically filled in."},"scenario":{"en":"The first two boxes only have grey words inside: \"Full name\" and \"Date of birth\". Samira has typed her name in the first one.","ar":"أول مربعين فيهما كلمات رمادية بالداخل فقط: «الاسم الكامل» و«تاريخ الميلاد». وقد كتبت سميرة اسمها في الأول."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","filled":true,"text":{"en":"Samira Adel","ar":"سميرة عادل"}},{"kind":"field","text":{"en":"Date of birth","ar":"تاريخ الميلاد"},"gap":"s"}]},"options":[{"id":"bold","text":{"en":"Make the grey words bold so they stand out","ar":"اجعل الكلمات الرمادية عريضة لتبرز"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","filled":true,"text":{"en":"Samira Adel","ar":"سميرة عادل"}},{"kind":"field","filled":true,"text":{"en":"Date of birth","ar":"تاريخ الميلاد"},"gap":"s"}]}},{"id":"keep","text":{"en":"Keep it; the form is short","ar":"أبقِه؛ فالنموذج قصير"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","filled":true,"text":{"en":"Samira Adel","ar":"سميرة عادل"}},{"kind":"field","text":{"en":"Date of birth","ar":"تاريخ الميلاد"},"gap":"s"}]}},{"id":"labels","text":{"en":"Labels above the boxes; boxes start empty","ar":"عناوين فوق المربعات؛ والمربعات تبدأ فارغة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Samira Adel","ar":"سميرة عادل"}},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"}]}}],"answer":["labels"],"misconceptions":[{"id":"MC-P01-034","when":["keep"],"feedback":{"en":"Her name already replaced \"Full name\", so the first box no longer says what it is. Short forms need labels too.","ar":"اسمها حلّ مكان «الاسم الكامل»، فلم يعد المربع الأول يقول ما هو. والنماذج القصيرة تحتاج عناوين أيضًا."}},{"id":"MC-P01-036","when":["bold"],"feedback":{"en":"Bold dark words look like an answer that's already there, so the date box now seems filled. Labels go outside, boxes stay empty.","ar":"الكلمات الداكنة العريضة تبدو كإجابة موجودة بالفعل، فيبدو مربع التاريخ مُعبّأ. العناوين بالخارج، والمربعات تبقى فارغة."}}],"explain":{"en":"From Lesson 1: a label outside the box is there before, during and after typing, and an empty box clearly waits for an answer.","ar":"من الدرس 1: العنوان خارج المربع موجود قبل الكتابة وأثناءها وبعدها، والمربع الفارغ ينتظر إجابة بوضوح."},"speaker":"nour"},{"id":"S03","type":"tune","skill":"SK-P01-U03-04","part":"check","rules":["R19"],"value":{"en":"Skill check, white space in forms (NN/g): place the label closer to its own field than to other fields. On a phone, that means right above it.","ar":"اختبار مهارة، المسافات في النماذج (NN/g): ضع العنوان أقرب إلى حقله منه إلى الحقول الأخرى. وعلى الهاتف، هذا يعني فوقه مباشرة."},"ref":{"url":"https://www.nngroup.com/articles/form-design-white-space/","quote":"Place the label closer to the associated text field than to other text fields."},"scenario":{"en":"Further down, the contact fields have labels, but each one floats in the middle of the gap between two boxes.","ar":"في الأسفل، لحقول التواصل عناوين، لكن كل عنوان يطفو في منتصف المسافة بين مربعين."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","text":""},{"kind":"small","weight":"bold","text":{"en":"Mobile number","ar":"رقم الموبايل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"small","weight":"bold","text":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"gap":"m"},{"kind":"field","text":"","gap":"m"}]},"options":[{"id":"tight","text":{"en":"Each label right above its box, more space between fields","ar":"كل عنوان فوق مربعه مباشرة، ومسافة أكبر بين الحقول"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":""},{"kind":"field","label":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"text":"","gap":"l"}]}},{"id":"color","text":{"en":"Keep the gaps; color each label like its box border","ar":"أبقِ المسافات؛ ولوّن كل عنوان بلون حدود مربعه"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","text":""},{"kind":"small","weight":"bold","color":"brand","text":{"en":"Mobile number","ar":"رقم الموبايل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"small","weight":"bold","color":"brand","text":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"gap":"m"},{"kind":"field","text":"","gap":"m"}]}},{"id":"keep","text":{"en":"Keep it; even spacing looks neat","ar":"أبقِه؛ فالمسافات المتساوية تبدو مرتّبة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","text":""},{"kind":"small","weight":"bold","text":{"en":"Mobile number","ar":"رقم الموبايل"},"gap":"m"},{"kind":"field","text":"","gap":"m"},{"kind":"small","weight":"bold","text":{"en":"Email (optional)","ar":"البريد الإلكتروني (اختياري)"},"gap":"m"},{"kind":"field","text":"","gap":"m"}]}}],"answer":["tight"],"misconceptions":[{"id":"MC-P01-038","when":["keep","color"],"feedback":{"en":"Each label is still exactly between two boxes, so it could belong to either. Distance has to point to the right box.","ar":"ما زال كل عنوان في منتصف المسافة بين مربعين تمامًا، فقد يخصّ أيًّا منهما. والمسافة يجب أن تشير إلى المربع الصحيح."}}],"explain":{"en":"From Lesson 2: people pair what's close. A label tight above its own box, with a bigger gap before the next, can't be misread.","ar":"من الدرس 2: يربط الناس بين المتقارب. والعنوان الملاصق فوق مربعه، مع مسافة أكبر قبل المربع التالي، لا يمكن أن يُساء فهمه."},"speaker":"nour"},{"id":"S04","type":"tune","skill":"SK-P01-U03-05","part":"check","rules":["R19"],"value":{"en":"Skill check, white space in forms (NN/g): grouping related fields together helps people make sense of what they must fill in. Patient and insurance details are two different groups.","ar":"اختبار مهارة، المسافات في النماذج (NN/g): جمع الحقول المترابطة معًا يساعد الناس على فهم ما عليهم ملؤه. وبيانات المريض وبيانات التأمين مجموعتان مختلفتان."},"ref":{"url":"https://www.nngroup.com/articles/form-design-white-space/","quote":"Grouping related fields together helps users make sense of the information that they must fill in."},"scenario":{"en":"The form mixes Samira's details and her insurance details in one even list: name, insurance company, mobile, policy holder's name, date of birth.","ar":"النموذج يخلط بيانات سميرة وبيانات تأمينها في قائمة واحدة متساوية: الاسم، وشركة التأمين، والموبايل، واسم صاحب الوثيقة، وتاريخ الميلاد."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"mixed","options":[{"id":"mixed","text":{"en":"Keep one mixed list","ar":"أبقِ قائمة واحدة مختلطة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Insurance company","ar":"شركة التأمين"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Policy holder's name","ar":"اسم صاحب الوثيقة"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"}]}},{"id":"groups","text":{"en":"Two groups: \"About you\" and \"Your insurance\"","ar":"مجموعتان: «عنك» و«تأمينك»"},"mock":{"width":300,"blocks":[{"kind":"heading","text":{"en":"About you","ar":"عنك"}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"heading","text":{"en":"Your insurance","ar":"تأمينك"},"gap":"l"},{"kind":"field","label":{"en":"Insurance company","ar":"شركة التأمين"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Policy holder's name","ar":"اسم صاحب الوثيقة"},"text":"","gap":"s"}]}},{"id":"cols","text":{"en":"Two columns: you on one side, insurance on the other","ar":"عمودان: أنت في جانب، والتأمين في الجانب الآخر"},"mock":{"width":300,"blocks":[{"kind":"row","blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":""},{"kind":"field","label":{"en":"Insurance company","ar":"شركة التأمين"},"text":""}]},{"kind":"row","gap":"s","blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"text":""},{"kind":"field","label":{"en":"Policy holder","ar":"صاحب الوثيقة"},"text":""}]}]}}],"answer":["groups"],"misconceptions":[{"id":"MC-P01-041","when":["mixed"],"feedback":{"en":"Jumping between Samira and her insurance makes \"name\" fields easy to mix up. Put each set together under its own heading.","ar":"التنقّل بين سميرة وتأمينها يجعل حقول «الاسم» سهلة الخلط. اجمع كل مجموعة معًا تحت عنوانها."}},{"id":"MC-P01-040","when":["cols"],"feedback":{"en":"The groups are right, but side by side people fill across the row and mix them again. Stack the groups in one column.","ar":"المجموعات صحيحة، لكن جنبًا إلى جنب يملأ الناس السطر من جهة لأخرى فيخلطونها من جديد. ضع المجموعات فوق بعضها في عمود واحد."}}],"explain":{"en":"From Lesson 2: related fields together, under a heading, in one column. Each group becomes one small task.","ar":"من الدرس 2: الحقول المترابطة معًا، تحت عنوان، في عمود واحد. فتصبح كل مجموعة مهمة صغيرة واحدة."},"speaker":"nour"},{"id":"S05","type":"tune","skill":"SK-P01-U03-02","part":"check","rules":["R19"],"value":{"en":"Skill check, placeholders (NN/g): hints and instructions should be persistent and placed outside the field. A date format inside the box is gone before Samira types the year.","ar":"اختبار مهارة، النص الداخلي (NN/g): التلميحات والتعليمات يجب أن تبقى ظاهرة وخارج الحقل. وصيغة التاريخ داخل المربع تختفي قبل أن تكتب سميرة السنة."},"ref":{"url":"https://www.nngroup.com/articles/form-design-placeholders/","quote":"Hints and instructions should also be persistent and placed outside of the field."},"scenario":{"en":"Our system needs the date of birth as day, month, year, like 07 03 1990. Samira has typed \"07 03\".","ar":"يحتاج نظامنا تاريخ الميلاد بترتيب اليوم ثم الشهر ثم السنة، مثل 07 03 1990. وقد كتبت سميرة «07 03»."},"prompt":{"en":"Try each place for the format. Which one should ship?","ar":"جرّب كل مكان للصيغة. أيّها يجب أن يُطلق؟"},"start":"inside","options":[{"id":"inside","text":{"en":"Inside the box: \"DD MM YYYY\"","ar":"داخل المربع: «يوم شهر سنة»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"focus":true,"text":"⁦07 03⁩"}]}},{"id":"error","text":{"en":"Only in the error, if she gets it wrong","ar":"في رسالة الخطأ فقط، إذا أخطأت"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"focus":true,"text":"⁦07 03⁩"}]}},{"id":"under","text":{"en":"Under the label: \"Day, month, year. Example: 07 03 1990\"","ar":"تحت العنوان: «اليوم ثم الشهر ثم السنة. مثال: 07 03 1990»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"hintFirst":true,"hint":{"en":"Day, month, year. Example: 07 03 1990","ar":"اليوم ثم الشهر ثم السنة. مثال: 07 03 1990"},"filled":true,"focus":true,"text":"⁦07 03⁩"}]}}],"answer":["under"],"misconceptions":[{"id":"MC-P01-035","when":["inside"],"feedback":{"en":"Look at the preview: she has typed, and the format is gone. Day-or-month-first is exactly what she needs to check now.","ar":"انظر إلى المعاينة: كتبت، فاختفت الصيغة. وترتيب اليوم والشهر هو بالضبط ما تحتاج أن تتأكّد منه الآن."}},{"id":"MC-P01-042","when":["error"],"feedback":{"en":"An error can't catch 07 03 typed in the wrong order: both are valid dates. The format has to be visible before and while she types.","ar":"رسالة الخطأ لا تستطيع اكتشاف 07 03 إذا كُتب بترتيب خاطئ: فكلاهما تاريخ صحيح. والصيغة يجب أن تكون ظاهرة قبل الكتابة وأثناءها."}}],"explain":{"en":"From Lesson 1: hints go outside the field, where typing can't erase them. For dates, the order is the hint that matters most.","ar":"من الدرس 1: التلميحات مكانها خارج الحقل، حيث لا تمسحها الكتابة. وفي التواريخ، الترتيب هو أهم تلميح."},"speaker":"nour"},{"id":"S06","type":"tune","skill":"SK-P01-U03-03","part":"check","rules":["R19"],"value":{"en":"Skill check, tooltips (NN/g): tooltips shouldn't be essential for the task. What to bring to a first visit decides whether the visit can happen, so it belongs on the screen.","ar":"اختبار مهارة، الـ Tooltip (NN/g): يجب ألا يكون الـ Tooltip ضروريًا لإنجاز المهمة. وما يجب إحضاره للزيارة الأولى يحدّد هل يمكن أن تتم الزيارة، فمكانه على الشاشة."},"ref":{"url":"https://www.nngroup.com/articles/tooltip-guidelines/","quote":"tooltips shouldn’t be essential for the tasks users need to accomplish on your site."},"scenario":{"en":"First-time patients must bring their national ID and insurance card, or we can't see them. Right now, that note hides in the ⓘ on the Book visit button.","ar":"يجب أن يُحضر المرضى الجدد بطاقة الرقم القومي وبطاقة التأمين، وإلا لا نستطيع الكشف عليهم. والآن، هذه الملاحظة مخفية في ⓘ على زر «احجز الزيارة»."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"button","text":{"en":"Book visit ⓘ","ar":"احجز الزيارة ⓘ"}}]},"options":[{"id":"sms","text":{"en":"Keep the ⓘ, and also mention it in the confirmation SMS","ar":"أبقِ ⓘ، واذكرها أيضًا في رسالة التأكيد النصية"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"button","text":{"en":"Book visit ⓘ","ar":"احجز الزيارة ⓘ"}}]}},{"id":"show","text":{"en":"Show \"Bring your national ID and insurance card\" above the button","ar":"اعرض «أحضر بطاقة الرقم القومي وبطاقة التأمين» فوق الزر"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"banner","text":{"en":"Bring your national ID and insurance card to your visit.","ar":"أحضر بطاقة الرقم القومي وبطاقة التأمين معك في الزيارة."}},{"kind":"button","text":{"en":"Book visit","ar":"احجز الزيارة"},"gap":"s"}]}},{"id":"keep","text":{"en":"Keep the ⓘ; it's always there for anyone who looks","ar":"أبقِ ⓘ؛ فهي موجودة دائمًا لمن يبحث"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"button","text":{"en":"Book visit ⓘ","ar":"احجز الزيارة ⓘ"}}]}}],"answer":["show"],"misconceptions":[{"id":"MC-P01-037","when":["keep","sms"],"feedback":{"en":"Samira books on a phone, where there's no hover, so she won't see it here. A rule that can cancel her visit belongs on the screen, not only in an icon or a later SMS.","ar":"تحجز سميرة من الهاتف، حيث لا يوجد تمرير للماوس، فلن تراها هنا. والقاعدة التي قد تُلغي زيارتها مكانها على الشاشة، لا في أيقونة أو رسالة لاحقة فقط."}}],"explain":{"en":"From Lesson 3: could someone fail without reading it? Without the documents, the visit fails, so the note goes on the screen.","ar":"من الدرس 3: هل يمكن أن يفشل أحد دون قراءتها؟ بدون الأوراق، تفشل الزيارة، فمكان الملاحظة على الشاشة."},"speaker":"nour"},{"id":"S07","type":"tune","skill":"SK-P01-U03-06","part":"check","rules":["R19"],"value":{"en":"Skill check, form usability (NN/g): if a field requires a specific format, state the exact instructions. The insurance number has a fixed length and a known place on the card.","ar":"اختبار مهارة، سهولة استخدام النماذج (NN/g): إذا كان الحقل يتطلّب صيغة محدّدة، فاذكر التعليمات بدقة. ورقم التأمين له طول ثابت ومكان معروف على البطاقة."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"If a field requires a specific format or type of input, state the exact instructions."},"scenario":{"en":"The insurance number is always 10 digits, printed on the front of the card. Right now, the rule only appears in an error: \"Invalid insurance number\".","ar":"رقم التأمين دائمًا 10 أرقام، مطبوع على وجه البطاقة. والآن، تظهر القاعدة فقط في رسالة خطأ: «رقم تأمين غير صالح»."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"exact","options":[{"id":"exact","text":{"en":"Under the label: \"10 digits, on the front of your card\"","ar":"تحت العنوان: «10 أرقام، على وجه بطاقتك»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Insurance number","ar":"رقم التأمين"},"hintFirst":true,"hint":{"en":"10 digits, on the front of your card","ar":"10 أرقام، على وجه بطاقتك"},"text":""}]}},{"id":"vague","text":{"en":"Under the label: \"Enter a valid insurance number\"","ar":"تحت العنوان: «أدخل رقم تأمين صالحًا»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Insurance number","ar":"رقم التأمين"},"hintFirst":true,"hint":{"en":"Enter a valid insurance number","ar":"أدخل رقم تأمين صالحًا"},"text":""}]}},{"id":"error","text":{"en":"Keep the rule in the error message","ar":"أبقِ القاعدة في رسالة الخطأ"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Insurance number","ar":"رقم التأمين"},"filled":true,"tone":"bad","text":"48210","error":{"en":"Invalid insurance number.","ar":"رقم تأمين غير صالح."}}]}}],"answer":["exact"],"misconceptions":[{"id":"MC-P01-043","when":["vague"],"feedback":{"en":"\"Valid\" doesn't say how many digits or where to find them. Samira still has to guess.","ar":"«صالح» لا تقول كم رقمًا ولا أين تجدها. وما زالت سميرة مضطرة للتخمين."}},{"id":"MC-P01-042","when":["error"],"feedback":{"en":"The error comes after her mistake and still doesn't say the rule. Give the exact rule before she types.","ar":"رسالة الخطأ تأتي بعد خطئها وما زالت لا تذكر القاعدة. أعطِ القاعدة الدقيقة قبل أن تكتب."}}],"explain":{"en":"From Lesson 3: an exact rule, shown before typing, lets people get it right the first time: the length, and where to look.","ar":"من الدرس 3: القاعدة الدقيقة، المعروضة قبل الكتابة، تتيح للناس النجاح من المرة الأولى: الطول، وأين يبحثون."},"speaker":"nour"}]}$uxg$::jsonb),
  ($uxg$P01-U04-L01$uxg$, $uxg$abc76546477b7592cd964f347c04e33b69ff07736b109bb942402c4b0aae144b$uxg$, $uxg${"id":"P01-U04-L01","mode":"lesson","minutes":8,"title":{"en":"Put the error where the problem is","ar":"ضع الخطأ حيث توجد المشكلة"},"speaker":"hana","review_labels":{"MC-P01-044":{"en":"An error belongs next to its field","ar":"مكان الخطأ بجوار حقله"},"MC-P01-045":{"en":"Color alone doesn't signal an error","ar":"اللون وحده لا يكفي لإظهار الخطأ"},"MC-P01-046":{"en":"Long forms need a listed summary plus inline errors","ar":"النموذج الطويل يحتاج ملخّصًا يعدّد الأخطاء مع أخطاء بجوار الحقول"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Salma's membership form","ar":"نموذج اشتراك سلمى"},"body":{"en":"Salma tried to join my gym on our website. She filled in everything and tapped Join. A red line appeared at the very top: \"There's a problem with your form.\"\n\nShe looked at each field and couldn't see anything wrong. In the end, she walked to the front desk and signed up on paper.","ar":"حاولت سلمى الاشتراك في نادي الرياضي من موقعنا. ملأت كل شيء وضغطت «اشترك». فظهر سطر أحمر في أعلى الصفحة: «هناك مشكلة في النموذج».\n\nنظرت إلى كل حقل ولم ترَ أي خطأ. وفي النهاية، ذهبت إلى مكتب الاستقبال واشتركت على الورق."},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"There's a problem with your form.","ar":"هناك مشكلة في النموذج."}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Salma Fathy","ar":"سلمى فتحي"},"gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0101 234 567⁩","gap":"s"},{"kind":"field","label":{"en":"Start date","ar":"تاريخ البدء"},"filled":true,"text":"01/12/2026","gap":"s"},{"kind":"button","text":{"en":"Join","ar":"اشترك"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U04-01","part":"try","rules":["R12"],"value":{"en":"Try first. Error messages (NN/g): show the message close to the source of the error. Salma's mobile number has 10 digits; a message far from that field makes her search.","ar":"جرّب أولًا. رسائل الخطأ (NN/g): اعرض الرسالة قريبًا من مصدر الخطأ. ورقم موبايل سلمى 10 أرقام؛ والرسالة البعيدة عن هذا الحقل تجعلها تبحث."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Display the error message close to the error's source."},"scenario":{"en":"The problem was her mobile number: she typed 10 digits, and Egyptian mobiles have 11.","ar":"كانت المشكلة في رقم الموبايل: كتبت 10 أرقام، وأرقام الموبايل المصرية 11 رقمًا."},"prompt":{"en":"Try each version of my form. Which one should ship?","ar":"جرّب كل نسخة من نموذجي. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"There's a problem with your form.","ar":"هناك مشكلة في النموذج."}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Salma Fathy","ar":"سلمى فتحي"},"gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0101 234 567⁩","gap":"s"},{"kind":"field","label":{"en":"Start date","ar":"تاريخ البدء"},"filled":true,"text":"01/12/2026","gap":"s"},{"kind":"button","text":{"en":"Join","ar":"اشترك"},"gap":"m"}]},"options":[{"id":"top","text":{"en":"Keep the message at the top, but name the problem","ar":"أبقِ الرسالة في الأعلى، لكن اذكر المشكلة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"Mobile number needs 11 digits.","ar":"رقم الموبايل يحتاج 11 رقمًا."}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Salma Fathy","ar":"سلمى فتحي"},"gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0101 234 567⁩","gap":"s"},{"kind":"field","label":{"en":"Start date","ar":"تاريخ البدء"},"filled":true,"text":"01/12/2026","gap":"s"},{"kind":"button","text":{"en":"Join","ar":"اشترك"},"gap":"m"}]}},{"id":"inline","text":{"en":"Mark the mobile field and put the message under it","ar":"علّم حقل الموبايل وضع الرسالة تحته"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Salma Fathy","ar":"سلمى فتحي"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0101 234 567⁩","tone":"bad","error":{"en":"⚠ Mobile number needs 11 digits. This one has 10.","ar":"⚠ رقم الموبايل يحتاج 11 رقمًا. هذا الرقم فيه 10."},"gap":"s"},{"kind":"field","label":{"en":"Start date","ar":"تاريخ البدء"},"filled":true,"text":"01/12/2026","gap":"s"},{"kind":"button","text":{"en":"Join","ar":"اشترك"},"gap":"m"}]}},{"id":"keep","text":{"en":"Keep it; people can check their own answers","ar":"أبقِه؛ يستطيع الناس مراجعة إجاباتهم بأنفسهم"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"There's a problem with your form.","ar":"هناك مشكلة في النموذج."}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Salma Fathy","ar":"سلمى فتحي"},"gap":"m"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0101 234 567⁩","gap":"s"},{"kind":"field","label":{"en":"Start date","ar":"تاريخ البدء"},"filled":true,"text":"01/12/2026","gap":"s"},{"kind":"button","text":{"en":"Join","ar":"اشترك"},"gap":"m"}]}}],"answer":["inline"],"misconceptions":[{"id":"MC-P01-044","when":["top"],"feedback":{"en":"Better, because it names the problem. But Salma reads it at the top, scrolls to the field, and has to remember it while she fixes it. Put it on the field.","ar":"أفضل، لأنها تذكر المشكلة. لكن سلمى تقرؤها في الأعلى، ثم تنزل إلى الحقل، وعليها أن تتذكّرها أثناء الإصلاح. ضعها على الحقل."}},{"id":"MC-P01-044","when":["keep"],"feedback":{"en":"Salma did check, and found nothing. Ten digits look normal at a glance. The form knows which field failed, so it should say so there.","ar":"راجعت سلمى بالفعل، ولم تجد شيئًا. فعشرة أرقام تبدو طبيعية للوهلة الأولى. والنموذج يعرف أي حقل فشل، فليقل ذلك عنده."}}],"hints":[{"en":"When Salma starts fixing her number, where are her eyes?","ar":"حين تبدأ سلمى في إصلاح رقمها، أين تنظر؟"},{"en":"Which version puts the message in that same spot?","ar":"أي نسخة تضع الرسالة في المكان نفسه؟"}],"correct":{"en":"The message sits on the field she has to fix.","ar":"الرسالة موجودة على الحقل الذي يجب أن تُصلحه."},"explain":{"en":"People fix errors where the field is. A message there tells them which field and what to do, without searching or remembering.","ar":"يُصلح الناس الأخطاء حيث يوجد الحقل. والرسالة هناك تخبرهم أي حقل وماذا يفعلون، دون بحث أو تذكّر."},"speaker":"hana"},{"id":"S03","type":"card","part":"concept","icons":["pin","color","list","ok"],"title":{"en":"An error has to lead to the fix","ar":"الخطأ يجب أن يقود إلى الإصلاح"},"body":{"en":"An error message only helps if people can find it and act on it.\n\n- **Next to the field:** put the message right under the field with the problem, where people look while fixing it.\n- **More than color:** a red border alone is easy to miss, and some people can't see red well. Add words and an icon.\n- **A list at the top of long forms:** when errors may be out of sight, list them at the top, and still mark each field.\n- **Keep it on screen:** a message that disappears after a few seconds is gone before people finish fixing.","ar":"رسالة الخطأ لا تفيد إلا إذا وجدها الناس واستطاعوا التصرّف بناءً عليها.\n\n- **بجوار الحقل:** ضع الرسالة تحت الحقل الذي فيه المشكلة مباشرة، حيث ينظر الناس أثناء الإصلاح.\n- **أكثر من اللون:** الإطار الأحمر وحده يسهل أن يفوت، وبعض الناس لا يرون الأحمر جيدًا. أضف كلمات وأيقونة.\n- **قائمة أعلى النماذج الطويلة:** حين قد تكون الأخطاء خارج الشاشة، اعرضها في قائمة بالأعلى، مع تعليم كل حقل أيضًا.\n- **أبقِها على الشاشة:** الرسالة التي تختفي بعد ثوانٍ تذهب قبل أن ينتهي الناس من الإصلاح."}},{"id":"S04","type":"tune","skill":"SK-P01-U04-06","part":"guided","rules":["R06","R15"],"value":{"en":"Form usability (NN/g): errors should be signaled through several cues, not only color. A red border alone can look like a normal border, especially for people who don't see red well.","ar":"سهولة استخدام النماذج (NN/g): يجب إظهار الأخطاء بعدّة إشارات، لا باللون وحده. والإطار الأحمر وحده قد يبدو إطارًا عاديًا، خاصة لمن لا يرى الأحمر جيدًا."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Errors should be signaled through a variety of cues, not solely through color:"},"scenario":{"en":"Members book a personal trainer in our app. When the email is wrong, we only turn its border red. Khaled, who can't tell red from green, tapped Book five times.","ar":"يحجز الأعضاء مدرّبًا خاصًا من تطبيقنا. وحين يكون البريد خاطئًا، نكتفي بتحويل إطاره إلى الأحمر. وخالد، الذي لا يميّز الأحمر من الأخضر، ضغط «احجز» خمس مرات."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"red","options":[{"id":"red","text":{"en":"Keep the red border only","ar":"أبقِ الإطار الأحمر فقط"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"text":"khaled.mail.com","tone":"bad"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}},{"id":"grey","text":{"en":"Keep the red border, and grey out Book until it's fixed","ar":"أبقِ الإطار الأحمر، واجعل «احجز» رماديًا حتى يُصلَح"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"text":"khaled.mail.com","tone":"bad"},{"kind":"button","tone":"off","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}},{"id":"words","text":{"en":"Keep the red border, and add an icon and a message","ar":"أبقِ الإطار الأحمر، وأضف أيقونة ورسالة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"text":"khaled.mail.com","tone":"bad","error":{"en":"⚠ This email is missing @. For example: name@mail.com","ar":"⚠ هذا البريد ينقصه @. مثال: name@mail.com"}},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}}],"answer":["words"],"misconceptions":[{"id":"MC-P01-045","when":["red"],"feedback":{"en":"To Khaled, a red border looks like any other border. Only words and an icon reach him, and they also say what to fix.","ar":"بالنسبة إلى خالد، الإطار الأحمر يبدو مثل أي إطار. والكلمات والأيقونة وحدها تصل إليه، وتقول أيضًا ما يجب إصلاحه."}},{"id":"MC-P01-045","when":["grey"],"feedback":{"en":"Now Khaled knows something is wrong, but not what or where. A grey button is one more signal without words. Say what to fix next to the email.","ar":"الآن يعرف خالد أن هناك خطأ، لكن لا يعرف ما هو ولا أين. والزر الرمادي إشارة أخرى بلا كلمات. قل ما يجب إصلاحه بجوار البريد."}}],"hints":[{"en":"Imagine the preview in black and white. Which version still shows an error?","ar":"تخيّل المعاينة بالأبيض والأسود. أي نسخة ما زالت تُظهر الخطأ؟"},{"en":"Which version also tells Khaled what's wrong with his email?","ar":"أي نسخة تخبر خالد أيضًا بما في بريده من خطأ؟"}],"correct":{"en":"Color, icon and words: anyone can see the error.","ar":"لون وأيقونة وكلمات: أي شخص يرى الخطأ."},"explain":{"en":"Color helps, but it can't be the only signal. An icon and a short message work for everyone, and the message also explains the fix.","ar":"اللون يساعد، لكن لا يصح أن يكون الإشارة الوحيدة. والأيقونة والرسالة القصيرة تعملان مع الجميع، والرسالة تشرح الإصلاح أيضًا."},"speaker":"hana"},{"id":"S05","type":"tune","skill":"SK-P01-U04-07","part":"guided","rules":["R06","R15"],"value":{"en":"Form errors (NN/g): a summary at the top gives a global view of all the errors. On a long form, it tells people how many problems there are and where, even ones off screen.","ar":"أخطاء النماذج (NN/g): الملخّص في الأعلى يعطي صورة شاملة عن كل الأخطاء. وفي النموذج الطويل، يخبر الناس كم مشكلة هناك وأين، حتى التي خارج الشاشة."},"ref":{"url":"https://www.nngroup.com/articles/errors-forms-design-guidelines/","quote":"A validation summary can give the user a global understanding of all the errors in a form"},"scenario":{"en":"New members fill in a health form with 14 questions before their first session. When they tap Send with problems, the page jumps back to the top. Last week, Heba fixed one error, tapped Send, and got bounced back again twice.","ar":"يملأ الأعضاء الجدد استمارة صحية فيها 14 سؤالًا قبل أول حصة. وحين يضغطون «أرسل» وفيها مشكلات، تقفز الصفحة إلى الأعلى. والأسبوع الماضي، أصلحت هبة خطأ واحدًا، وضغطت «أرسل»، فأعادتها الصفحة مرتين أخريين."},"prompt":{"en":"Try each version of the top of the form after Send. Which one should ship?","ar":"جرّب كل نسخة من أعلى النموذج بعد «أرسل». أيّها يجب أن تُطلق؟"},"start":"inline","options":[{"id":"inline","text":{"en":"Only mark each field with its error","ar":"علّم كل حقل بخطئه فقط"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Health form","ar":"الاستمارة الصحية"}},{"kind":"field","label":{"en":"Weight (kg)","ar":"الوزن (كجم)"},"filled":true,"text":"68","gap":"m"},{"kind":"field","label":{"en":"Height (cm)","ar":"الطول (سم)"},"text":"","tone":"bad","error":{"en":"⚠ Enter your height in cm, like 165.","ar":"⚠ اكتب طولك بالسنتيمتر، مثل 165."},"gap":"s"},{"kind":"small","color":"muted","text":{"en":"12 more questions below","ar":"12 سؤالًا آخر بالأسفل"},"gap":"s"}]}},{"id":"both","text":{"en":"List all 3 errors at the top, and mark each field","ar":"اعرض الأخطاء الثلاثة في قائمة بالأعلى، وعلّم كل حقل"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Health form","ar":"الاستمارة الصحية"}},{"kind":"banner","tone":"bad","text":{"en":"3 answers need a fix: Height, Injuries, Emergency phone.","ar":"3 إجابات تحتاج إصلاحًا: الطول، الإصابات، هاتف الطوارئ."},"gap":"s"},{"kind":"field","label":{"en":"Weight (kg)","ar":"الوزن (كجم)"},"filled":true,"text":"68","gap":"m"},{"kind":"field","label":{"en":"Height (cm)","ar":"الطول (سم)"},"text":"","tone":"bad","error":{"en":"⚠ Enter your height in cm, like 165.","ar":"⚠ اكتب طولك بالسنتيمتر، مثل 165."},"gap":"s"},{"kind":"small","color":"muted","text":{"en":"12 more questions below","ar":"12 سؤالًا آخر بالأسفل"},"gap":"s"}]}},{"id":"list","text":{"en":"List all 3 errors at the top, and leave the fields unmarked","ar":"اعرض الأخطاء الثلاثة في قائمة بالأعلى، واترك الحقول بلا علامات"},"mock":{"width":300,"blocks":[{"kind":"title","text":{"en":"Health form","ar":"الاستمارة الصحية"}},{"kind":"banner","tone":"bad","text":{"en":"3 answers need a fix: Height, Injuries, Emergency phone.","ar":"3 إجابات تحتاج إصلاحًا: الطول، الإصابات، هاتف الطوارئ."},"gap":"s"},{"kind":"field","label":{"en":"Weight (kg)","ar":"الوزن (كجم)"},"filled":true,"text":"68","gap":"m"},{"kind":"field","label":{"en":"Height (cm)","ar":"الطول (سم)"},"text":"","gap":"s"},{"kind":"small","color":"muted","text":{"en":"12 more questions below","ar":"12 سؤالًا آخر بالأسفل"},"gap":"s"}]}}],"answer":["both"],"misconceptions":[{"id":"MC-P01-046","when":["inline"],"feedback":{"en":"Heba sees one marked field at the top and thinks that's the only one. The other two are 12 questions down. A list at the top tells her there are three.","ar":"ترى هبة حقلًا واحدًا عليه علامة في الأعلى فتظن أنه الوحيد. أما الاثنان الآخران فبعد 12 سؤالًا. والقائمة في الأعلى تخبرها أنها ثلاثة."}},{"id":"MC-P01-046","when":["list"],"feedback":{"en":"Now she knows there are three, but when she scrolls to \"Injuries\", nothing marks it or says what to fix. Keep the message on each field too.","ar":"الآن تعرف أنها ثلاثة، لكن حين تنزل إلى «الإصابات» لا شيء يعلّمه أو يقول ما يجب إصلاحه. أبقِ الرسالة على كل حقل أيضًا."}}],"hints":[{"en":"After Send, what does Heba need to know first: how many problems, or how to fix one?","ar":"بعد «أرسل»، ماذا تحتاج هبة أن تعرف أولًا: كم مشكلة، أم كيف تُصلح واحدة؟"},{"en":"And when she reaches each field, what should be waiting there?","ar":"وحين تصل إلى كل حقل، ماذا يجب أن يكون في انتظارها؟"}],"correct":{"en":"The list shows how many; each field shows how to fix it.","ar":"القائمة تُظهر كم خطأ؛ وكل حقل يُظهر كيف يُصلح."},"explain":{"en":"On a long form, some errors are always off screen. A list at the top gives the full picture, and the message on each field helps with the fix.","ar":"في النموذج الطويل، بعض الأخطاء تكون دائمًا خارج الشاشة. والقائمة في الأعلى تعطي الصورة كاملة، والرسالة على كل حقل تساعد في الإصلاح."},"speaker":"hana"},{"id":"S06","type":"tune","skill":"SK-P01-U04-01","part":"guided","rules":["R06","R15"],"value":{"en":"Form errors (NN/g): when the message stays by the field, people can see it while fixing the error instead of remembering it. A message that disappears after 3 seconds forces them to remember.","ar":"أخطاء النماذج (NN/g): حين تبقى الرسالة بجوار الحقل، يراها الناس أثناء إصلاح الخطأ بدل أن يتذكّروها. والرسالة التي تختفي بعد 3 ثوانٍ تجبرهم على التذكّر."},"ref":{"url":"https://www.nngroup.com/articles/errors-forms-design-guidelines/","quote":"users can see the error message while fixing the error instead of having to remember it."},"scenario":{"en":"Members pay for their plan in our app. When the card number is short, a message pops up at the bottom for 3 seconds and then disappears. Bassem looked down at his card, and when he looked up, the message was gone.","ar":"يدفع الأعضاء ثمن باقتهم من تطبيقنا. وحين يكون رقم البطاقة ناقصًا، تظهر رسالة أسفل الشاشة لمدة 3 ثوانٍ ثم تختفي. ونظر باسم إلى بطاقته، وحين رفع عينيه كانت الرسالة قد اختفت."},"prompt":{"en":"Try each version, 5 seconds after Pay. Which one should ship?","ar":"جرّب كل نسخة، بعد 5 ثوانٍ من «ادفع». أيّها يجب أن تُطلق؟"},"start":"toast","options":[{"id":"toast","text":{"en":"Keep the 3-second message at the bottom","ar":"أبقِ رسالة الثواني الثلاث في الأسفل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"filled":true,"text":"⁦4512 7731 0098 21⁩"},{"kind":"field","label":{"en":"Expiry date","ar":"تاريخ الانتهاء"},"filled":true,"text":"08/28","gap":"s"},{"kind":"button","text":{"en":"Pay 900 EGP","ar":"ادفع 900 جنيه"},"gap":"m"}]}},{"id":"long","text":{"en":"Keep it at the bottom, but for 10 seconds","ar":"أبقِها في الأسفل، لكن لمدة 10 ثوانٍ"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"filled":true,"text":"⁦4512 7731 0098 21⁩"},{"kind":"field","label":{"en":"Expiry date","ar":"تاريخ الانتهاء"},"filled":true,"text":"08/28","gap":"s"},{"kind":"button","text":{"en":"Pay 900 EGP","ar":"ادفع 900 جنيه"},"gap":"m"},{"kind":"banner","tone":"bad","text":{"en":"Card number is incomplete.","ar":"رقم البطاقة غير مكتمل."},"gap":"l"}]}},{"id":"field","text":{"en":"Show it under the card number until it's fixed","ar":"اعرضها تحت رقم البطاقة حتى يُصلَح"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"filled":true,"text":"⁦4512 7731 0098 21⁩","tone":"bad","error":{"en":"⚠ Card number needs 16 digits. This one has 14.","ar":"⚠ رقم البطاقة يحتاج 16 رقمًا. هذا الرقم فيه 14."}},{"kind":"field","label":{"en":"Expiry date","ar":"تاريخ الانتهاء"},"filled":true,"text":"08/28","gap":"s"},{"kind":"button","text":{"en":"Pay 900 EGP","ar":"ادفع 900 جنيه"},"gap":"m"}]}}],"answer":["field"],"misconceptions":[{"id":"MC-P01-044","when":["toast"],"feedback":{"en":"The preview shows Bassem's screen 5 seconds later: nothing tells him what went wrong. He has to remember the message while he checks his card.","ar":"المعاينة تُظهر شاشة باسم بعد 5 ثوانٍ: لا شيء يخبره بما حدث. وعليه أن يتذكّر الرسالة وهو يراجع بطاقته."}},{"id":"MC-P01-044","when":["long"],"feedback":{"en":"It lasts longer, but it's still far from the field and will still vanish. A message that stays on the field is there for as long as he needs it.","ar":"تبقى مدة أطول، لكنها ما زالت بعيدة عن الحقل وستختفي أيضًا. والرسالة التي تبقى على الحقل موجودة طالما احتاجها."}}],"hints":[{"en":"How long does it take Bassem to read 16 digits off his card and fix them?","ar":"كم يستغرق باسم ليقرأ 16 رقمًا من بطاقته ويُصلحها؟"},{"en":"Which version is still there, in the right place, when he's done?","ar":"أي نسخة ما زالت موجودة، في المكان الصحيح، حين ينتهي؟"}],"correct":{"en":"The message stays on the field for as long as the problem does.","ar":"الرسالة تبقى على الحقل طالما بقيت المشكلة."},"explain":{"en":"Fixing takes time: people look away, check a card, type. An error that stays by its field is there whenever they look back.","ar":"الإصلاح يحتاج وقتًا: ينظر الناس بعيدًا، ويراجعون بطاقة، ويكتبون. والخطأ الذي يبقى بجوار حقله موجود كلما نظروا إليه."},"speaker":"hana"},{"id":"S07","type":"compare","skill":"SK-P01-U04-07","part":"contrast","rules":["R11","R15"],"value":{"en":"Contrast with S05: both versions have a summary at the top. Form errors (NN/g): the summary should give a global understanding of all the errors. \"There are errors\" doesn't; a list by field name does.","ar":"مقارنة مع الخطوة 5: النسختان فيهما ملخّص في الأعلى. أخطاء النماذج (NN/g): الملخّص يجب أن يعطي صورة شاملة عن كل الأخطاء. وعبارة «يوجد أخطاء» لا تفعل ذلك؛ أما القائمة بأسماء الحقول فتفعل."},"ref":{"url":"https://www.nngroup.com/articles/errors-forms-design-guidelines/","quote":"A validation summary can give the user a global understanding of all the errors in a form"},"scenario":{"en":"Our corporate membership form is long: company details, 5 employees, and billing. Two designers sent me different summaries for the top of the page. Both also mark each field.","ar":"نموذج اشتراك الشركات عندنا طويل: بيانات الشركة، و5 موظفين، والفاتورة. وأرسل لي مصمّمان ملخّصين مختلفين لأعلى الصفحة. وكلاهما يعلّم كل حقل أيضًا."},"prompt":{"en":"Which summary should ship?","ar":"أي ملخّص يجب أن يُطلق؟"},"a":{"label":{"en":"General","ar":"عام"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"Some fields have errors. Please check the form.","ar":"بعض الحقول فيها أخطاء. يُرجى مراجعة النموذج."}}]}},"b":{"label":{"en":"Listed","ar":"مُعدَّد"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"2 answers need a fix: Employee 3 phone, Billing email.","ar":"إجابتان تحتاجان إصلاحًا: هاتف الموظف 3، بريد الفاتورة."}}]}},"answer":"b","reason":{"prompt":{"en":"What makes the better summary work?","ar":"ما الذي يجعل الملخّص الأفضل ناجحًا؟"},"options":[{"id":"count","text":{"en":"It says how many and which fields, so people know where to go","ar":"يقول كم خطأ وأي حقول، فيعرف الناس إلى أين يذهبون"}},{"id":"polite","text":{"en":"It sounds more polite","ar":"يبدو أكثر أدبًا"}},{"id":"short","text":{"en":"It is shorter","ar":"أقصر"}}],"answer":["count"],"misconceptions":[{"id":"MC-P01-046","when":["polite","short"],"feedback":{"en":"Both are polite, and B is not shorter. The difference is that B names the fields, so people know how many to find and where.","ar":"كلاهما مؤدّب، وB ليس أقصر. الفرق أن B يذكر الحقول، فيعرف الناس كم حقلًا يبحثون عنه وأين."}}]},"misconceptions":[{"id":"MC-P01-046","when":["a"],"feedback":{"en":"A sends people hunting through 20 fields, with no idea how many problems there are. A summary has to name them.","ar":"A يجعل الناس يبحثون بين 20 حقلًا، دون أن يعرفوا كم مشكلة هناك. والملخّص يجب أن يذكرها."}}],"hints":[{"en":"After reading each one, does the person know when they're done fixing?","ar":"بعد قراءة كل ملخّص، هل يعرف الشخص متى ينتهي من الإصلاح؟"},{"en":"Which one names the fields?","ar":"أيّهما يذكر الحقول؟"}],"correct":{"en":"A summary that names the fields is a to-do list.","ar":"الملخّص الذي يذكر الحقول قائمة مهام."},"explain":{"en":"\"There are errors\" only repeats what the red marks say. A summary helps when it lists how many and which fields, so people know where to go and when they're done.","ar":"عبارة «يوجد أخطاء» تكرّر فقط ما تقوله العلامات الحمراء. والملخّص يفيد حين يذكر كم خطأ وأي حقول، فيعرف الناس إلى أين يذهبون ومتى ينتهون."},"speaker":"hana"},{"id":"S08","type":"tune","skill":"SK-P01-U04-06","part":"independent","speaker":"nour","rules":["R14","R19"],"value":{"en":"New case. Form errors (NN/g): color shouldn't be the only sign of an error. A label that turns red is easy to miss; words and an icon say it clearly.","ar":"حالة جديدة. أخطاء النماذج (NN/g): يجب ألّا يكون اللون العلامة الوحيدة للخطأ. والعنوان الذي يتحوّل إلى الأحمر يسهل أن يفوت؛ أما الكلمات والأيقونة فتقولانه بوضوح."},"ref":{"url":"https://www.nngroup.com/articles/errors-forms-design-guidelines/","quote":"shouldn't be used as the only form of error indication"},"scenario":{"en":"Patients book appointments on my clinic's website. If they skip the insurance number, we only turn its label red. Magdy is over 60, and he kept tapping Book without noticing anything had changed.","ar":"يحجز المرضى مواعيدهم من موقع عيادتي. وإن تركوا رقم التأمين فارغًا، نكتفي بتحويل عنوانه إلى الأحمر. ومجدي تجاوز الستين، وظلّ يضغط «احجز» دون أن يلاحظ أن شيئًا تغيّر."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"label","options":[{"id":"label","text":{"en":"Keep the red label only","ar":"أبقِ العنوان الأحمر فقط"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Appointment day","ar":"يوم الموعد"},"filled":true,"text":{"en":"Sunday 6 Dec","ar":"الأحد 6 ديسمبر"}},{"kind":"small","weight":"bold","color":"red","text":{"en":"Insurance number","ar":"رقم التأمين"},"gap":"s"},{"kind":"field","text":"","gap":"xs"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}},{"id":"both","text":{"en":"Red label and red border","ar":"عنوان أحمر وإطار أحمر"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Appointment day","ar":"يوم الموعد"},"filled":true,"text":{"en":"Sunday 6 Dec","ar":"الأحد 6 ديسمبر"}},{"kind":"small","weight":"bold","color":"red","text":{"en":"Insurance number","ar":"رقم التأمين"},"gap":"s"},{"kind":"field","text":"","tone":"bad","gap":"xs"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}},{"id":"message","text":{"en":"Red border, an icon, and a message under the field","ar":"إطار أحمر، وأيقونة، ورسالة تحت الحقل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Appointment day","ar":"يوم الموعد"},"filled":true,"text":{"en":"Sunday 6 Dec","ar":"الأحد 6 ديسمبر"}},{"kind":"field","label":{"en":"Insurance number","ar":"رقم التأمين"},"text":"","tone":"bad","error":{"en":"⚠ Enter your insurance number, or choose \"I'll pay myself\" below.","ar":"⚠ اكتب رقم التأمين، أو اختر «سأدفع بنفسي» بالأسفل."},"gap":"s"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}}],"answer":["message"],"misconceptions":[{"id":"MC-P01-045","when":["label","both"],"feedback":{"en":"More red is still only red. Magdy didn't notice a color change; a message in words, with an icon, is hard to miss and tells him what to do.","ar":"زيادة الأحمر تظل أحمر فقط. لم يلاحظ مجدي تغيّر اللون؛ أما رسالة بالكلمات مع أيقونة فيصعب أن تفوته، وتخبره بما يفعل."}}],"correct":{"en":"Words and an icon reach Magdy, whatever he sees in red.","ar":"الكلمات والأيقونة تصل إلى مجدي، أيًّا كان ما يراه من الأحمر."},"explain":{"en":"Color is a hint, not a message. Add words that say what's missing and an icon that catches the eye.","ar":"اللون إشارة، لا رسالة. أضف كلمات تقول ما الناقص وأيقونة تلفت النظر."}},{"id":"S09","type":"card","part":"recap","icons":["pin","color","list","clock"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Next to the field:** moved Salma's mobile error from the top of the form to the field itself.\n- **More than color:** added an icon and words to a red border and a red label.\n- **A list on long forms:** listed every error at the top of a 14-question form, and kept each field marked.\n- **A summary that names fields:** chose a list of fields over \"Some fields have errors\".\n- **Messages that stay:** replaced a 3-second pop-up with a message on the card field.\n\nNext: the words inside the message.","ar":"- **بجوار الحقل:** نقلت خطأ موبايل سلمى من أعلى النموذج إلى الحقل نفسه.\n- **أكثر من اللون:** أضفت أيقونة وكلمات إلى إطار أحمر وعنوان أحمر.\n- **قائمة في النماذج الطويلة:** عرضت كل الأخطاء في قائمة أعلى استمارة من 14 سؤالًا، مع إبقاء العلامة على كل حقل.\n- **ملخّص يذكر الحقول:** اخترت قائمة بالحقول بدل «بعض الحقول فيها أخطاء».\n- **رسائل تبقى:** استبدلت رسالة الثواني الثلاث برسالة على حقل البطاقة.\n\nالتالي: الكلمات داخل الرسالة."}}]}$uxg$::jsonb),
  ($uxg$P01-U04-L02$uxg$, $uxg$aeaa4762c4beb0b9a4ad29973bef3938991454bd59d7599e734328871ca0d6cc$uxg$, $uxg${"id":"P01-U04-L02","mode":"lesson","minutes":8,"title":{"en":"Words that help people fix it","ar":"كلمات تساعد الناس على الإصلاح"},"speaker":"hana","review_labels":{"MC-P01-047":{"en":"Say what's wrong and how to fix it","ar":"قل ما الخطأ وكيف يُصلح"},"MC-P01-048":{"en":"No codes or jargon in error messages","ar":"لا أكواد ولا مصطلحات تقنية في رسائل الخطأ"},"MC-P01-049":{"en":"Don't blame the person","ar":"لا تلُم الشخص"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Mahmoud's guest pass","ar":"دعوة محمود"},"body":{"en":"Members can invite a friend with a guest pass code. Mahmoud typed the code his friend sent him into our app and got \"Error 403: Invalid request.\"\n\nHe thought the app was broken and called the front desk. The code had simply ended a week earlier.","ar":"يستطيع الأعضاء دعوة صديق بكود دعوة. كتب محمود الكود الذي أرسله له صديقه في تطبيقنا، فظهرت له «Error 403: Invalid request».\n\nظنّ أن التطبيق معطّل واتصل بالاستقبال. والكود كان قد انتهى ببساطة قبل أسبوع."},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Guest pass code","ar":"كود الدعوة"},"filled":true,"text":"GP-7731","tone":"bad","error":{"en":"⚠ Error 403: Invalid request.","ar":"⚠ Error 403: Invalid request."}},{"kind":"button","text":{"en":"Use pass","ar":"استخدم الدعوة"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U04-02","part":"try","rules":["R12"],"value":{"en":"Try first. Error messages (NN/g): hide obscure error codes, or show them only for technical diagnosis. Mahmoud needs to know the pass ended and what he can do instead.","ar":"جرّب أولًا. رسائل الخطأ (NN/g): أخفِ أكواد الخطأ الغامضة، أو اعرضها فقط للتشخيص التقني. ومحمود يحتاج أن يعرف أن الدعوة انتهت وماذا يستطيع أن يفعل بدلًا منها."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Hide or minimize the use of obscure error codes or abbreviations; show them for technical diagnostic purposes only."},"prompt":{"en":"Try each message. Which one should ship?","ar":"جرّب كل رسالة. أيّها يجب أن تُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"width":300,"blocks":[{"kind":"field","label":{"en":"Guest pass code","ar":"كود الدعوة"},"filled":true,"text":"GP-7731","tone":"bad","error":{"en":"⚠ Error 403: Invalid request.","ar":"⚠ Error 403: Invalid request."}},{"kind":"button","text":{"en":"Use pass","ar":"استخدم الدعوة"},"gap":"m"}]},"options":[{"id":"keep","text":{"en":"Keep it; the code helps our developers","ar":"أبقِها؛ فالكود يساعد المطوّرين عندنا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Guest pass code","ar":"كود الدعوة"},"filled":true,"text":"GP-7731","tone":"bad","error":{"en":"⚠ Error 403: Invalid request.","ar":"⚠ Error 403: Invalid request."}},{"kind":"button","text":{"en":"Use pass","ar":"استخدم الدعوة"},"gap":"m"}]}},{"id":"vague","text":{"en":"\"Something went wrong. Try again.\"","ar":"«حدث خطأ ما. حاول مرة أخرى.»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Guest pass code","ar":"كود الدعوة"},"filled":true,"text":"GP-7731","tone":"bad","error":{"en":"⚠ Something went wrong. Try again.","ar":"⚠ حدث خطأ ما. حاول مرة أخرى."}},{"kind":"button","text":{"en":"Use pass","ar":"استخدم الدعوة"},"gap":"m"}]}},{"id":"clear","text":{"en":"Say the pass ended, and what to do instead","ar":"قل إن الدعوة انتهت، وماذا يفعل بدلًا منها"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"width":300,"blocks":[{"kind":"field","label":{"en":"Guest pass code","ar":"كود الدعوة"},"filled":true,"text":"GP-7731","tone":"bad","error":{"en":"⚠ This pass ended on 26 October. Ask your friend for a new one, or buy a day pass.","ar":"⚠ انتهت هذه الدعوة يوم 26 أكتوبر. اطلب دعوة جديدة من صديقك، أو اشترِ تذكرة يوم واحد."}},{"kind":"button","text":{"en":"Use pass","ar":"استخدم الدعوة"},"gap":"m"}]}}],"answer":["clear"],"misconceptions":[{"id":"MC-P01-048","when":["keep"],"feedback":{"en":"\"403\" means something to our developers, not to Mahmoud. They can log the code; the screen should speak his language.","ar":"«403» تعني شيئًا للمطوّرين، لا لمحمود. يمكنهم تسجيل الكود في النظام؛ أما الشاشة فيجب أن تتكلّم بلغته."}},{"id":"MC-P01-047","when":["vague"],"feedback":{"en":"Plain words, but no help. \"Try again\" sends Mahmoud to type the same ended code again. Say what's wrong and what will work.","ar":"كلمات بسيطة، لكن بلا مساعدة. «حاول مرة أخرى» تجعل محمود يكتب الكود المنتهي نفسه مرة أخرى. قل ما الخطأ وما الذي سينجح."}}],"hints":[{"en":"After reading each message, does Mahmoud know why the code failed?","ar":"بعد قراءة كل رسالة، هل يعرف محمود لماذا فشل الكود؟"},{"en":"Which message also tells him what to do next?","ar":"أي رسالة تخبره أيضًا بما يفعل بعد ذلك؟"}],"correct":{"en":"He knows why it failed and has two ways forward.","ar":"يعرف لماذا فشل الكود، وأمامه طريقان للمتابعة."},"explain":{"en":"A useful error answers two questions in plain words: what went wrong, and what can I do now? Codes answer neither for the person on the screen.","ar":"رسالة الخطأ المفيدة تجيب عن سؤالين بكلمات بسيطة: ما الذي حدث، وماذا أستطيع أن أفعل الآن؟ والأكواد لا تجيب عن أيٍّ منهما لمن أمام الشاشة."}},{"id":"S03","type":"card","part":"concept","icons":["text","idea","person","ok"],"title":{"en":"What a good error says","ar":"ماذا تقول رسالة الخطأ الجيدة"},"body":{"en":"A good error message is short, but it does three jobs.\n\n- **What's wrong:** name the exact problem, like \"This pass ended on 26 October\", not \"Invalid input\".\n- **How to fix it:** give the next step, like \"Choose 3 November or later\".\n- **Plain words:** no error codes or technical terms. Developers can keep the code in their logs.\n- **No blame:** talk about the input (\"This date is in the past\"), not about the person (\"You entered a wrong date\").","ar":"رسالة الخطأ الجيدة قصيرة، لكنها تؤدّي ثلاث مهام.\n\n- **ما الخطأ:** اذكر المشكلة بدقة، مثل «انتهت هذه الدعوة يوم 26 أكتوبر»، لا «مُدخل غير صالح».\n- **كيف يُصلح:** أعطِ الخطوة التالية، مثل «اختر 3 نوفمبر أو بعده».\n- **كلمات بسيطة:** بلا أكواد خطأ أو مصطلحات تقنية. ويمكن للمطوّرين الاحتفاظ بالكود في سجلّاتهم.\n- **بلا لوم:** تحدّث عن المُدخل («هذا التاريخ مضى»)، لا عن الشخص («أدخلت تاريخًا خاطئًا»)."}},{"id":"S04","type":"tune","skill":"SK-P01-U04-03","part":"guided","rules":["R06","R15"],"value":{"en":"Error messages (NN/g): don't use phrasing that blames users or implies they did something wrong. Inas didn't do anything wrong; the class filled up.","ar":"رسائل الخطأ (NN/g): لا تستخدم صياغة تلوم المستخدم أو توحي بأنه أخطأ. وإيناس لم تخطئ في شيء؛ الحصة امتلأت فقط."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Don't use phrasing that blames users or implies they are doing something wrong"},"scenario":{"en":"Inas tried to book the 7 pm yoga class, which filled up while she was choosing. Our app said: \"You selected a full class. You must choose another class.\" She wrote a one-star review saying the app talks down to her.","ar":"حاولت إيناس حجز حصة اليوجا في السابعة مساءً، وقد امتلأت وهي تختار. فقال تطبيقنا: «لقد اخترت حصة ممتلئة. يجب أن تختاري حصة أخرى.» فكتبت تقييمًا بنجمة واحدة تقول إن التطبيق يكلّمها بتعالٍ."},"prompt":{"en":"Try each message. Which one should ship?","ar":"جرّب كل رسالة. أيّها يجب أن تُطلق؟"},"start":"you","options":[{"id":"neutral","text":{"en":"\"Yoga at 7 pm just filled up. Join the waiting list, or book 8 pm.\"","ar":"«امتلأت حصة اليوجا في السابعة للتوّ. انضمّي لقائمة الانتظار، أو احجزي الثامنة.»"},"mock":{"width":300,"blocks":[{"kind":"radio","selected":true,"text":{"en":"Yoga, 7 pm","ar":"يوجا، 7 مساءً"}},{"kind":"radio","text":{"en":"Yoga, 8 pm","ar":"يوجا، 8 مساءً"},"gap":"xs"},{"kind":"small","color":"red","text":{"en":"⚠ Yoga at 7 pm just filled up. Join the waiting list, or book 8 pm.","ar":"⚠ امتلأت حصة اليوجا في السابعة للتوّ. انضمّي لقائمة الانتظار، أو احجزي الثامنة."},"gap":"s"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}},{"id":"you","text":{"en":"Keep \"You selected a full class. You must choose another class.\"","ar":"أبقِ «لقد اخترت حصة ممتلئة. يجب أن تختاري حصة أخرى.»"},"mock":{"width":300,"blocks":[{"kind":"radio","selected":true,"text":{"en":"Yoga, 7 pm","ar":"يوجا، 7 مساءً"}},{"kind":"radio","text":{"en":"Yoga, 8 pm","ar":"يوجا، 8 مساءً"},"gap":"xs"},{"kind":"small","color":"red","text":{"en":"⚠ You selected a full class. You must choose another class.","ar":"⚠ لقد اخترت حصة ممتلئة. يجب أن تختاري حصة أخرى."},"gap":"s"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}},{"id":"oops","text":{"en":"\"Oops! Wrong choice, this class is full.\"","ar":"«عفوًا! اختيار خاطئ، هذه الحصة ممتلئة.»"},"mock":{"width":300,"blocks":[{"kind":"radio","selected":true,"text":{"en":"Yoga, 7 pm","ar":"يوجا، 7 مساءً"}},{"kind":"radio","text":{"en":"Yoga, 8 pm","ar":"يوجا، 8 مساءً"},"gap":"xs"},{"kind":"small","color":"red","text":{"en":"⚠ Oops! Wrong choice, this class is full.","ar":"⚠ عفوًا! اختيار خاطئ، هذه الحصة ممتلئة."},"gap":"s"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"}]}}],"answer":["neutral"],"misconceptions":[{"id":"MC-P01-049","when":["you","oops"],"feedback":{"en":"\"You selected\" and \"Wrong choice\" make it sound like Inas made a mistake. She didn't: the class filled while she was choosing. Talk about the class, and offer what's still open.","ar":"«لقد اخترتِ» و«اختيار خاطئ» تجعلان الأمر يبدو كأن إيناس أخطأت. وهي لم تخطئ: الحصة امتلأت وهي تختار. تحدّث عن الحصة، واعرض ما زال متاحًا."}}],"hints":[{"en":"In each message, who is the subject of the sentence: Inas or the class?","ar":"في كل رسالة، من فاعل الجملة: إيناس أم الحصة؟"},{"en":"Which one also gives her a way to still work out tonight?","ar":"أي رسالة تعطيها أيضًا طريقة لتتمرّن الليلة رغم ذلك؟"}],"correct":{"en":"The message is about the class, and it offers two ways forward.","ar":"الرسالة عن الحصة، وتعرض طريقين للمتابعة."},"explain":{"en":"Errors feel like criticism when \"you\" is the subject. Make the input or the situation the subject, and end with what the person can do.","ar":"تبدو الأخطاء كأنها انتقاد حين يكون «أنت» فاعل الجملة. اجعل المُدخل أو الموقف هو الفاعل، واختم بما يستطيع الشخص فعله."},"speaker":"hana"},{"id":"S05","type":"tune","skill":"SK-P01-U04-02","part":"guided","rules":["R06","R15"],"value":{"en":"Error messages (NN/g): just stating the problem is not enough; offer a possible remedy. \"Invalid date\" names a problem; \"Choose 3 November or later\" fixes it.","ar":"رسائل الخطأ (NN/g): ذكر المشكلة وحده لا يكفي؛ اعرض حلًا ممكنًا. و«تاريخ غير صالح» تذكر مشكلة؛ أما «اختر 3 نوفمبر أو بعده» فتحلّها."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Merely stating the problem is also not enough; offer some potential remedies."},"scenario":{"en":"Members can freeze their membership while they travel. A freeze can start tomorrow at the earliest. Marwa typed today's date and got \"Invalid date\", then tried two other formats of the same date.","ar":"يستطيع الأعضاء تجميد اشتراكهم أثناء السفر. ويمكن أن يبدأ التجميد من الغد على الأقرب. كتبت مروة تاريخ اليوم فظهرت «تاريخ غير صالح»، فجرّبت صيغتين أخريين للتاريخ نفسه."},"prompt":{"en":"Try each message. Which one should ship?","ar":"جرّب كل رسالة. أيّها يجب أن تُطلق؟"},"start":"invalid","options":[{"id":"invalid","text":{"en":"Keep \"Invalid date.\"","ar":"أبقِ «تاريخ غير صالح.»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Freeze starts on","ar":"يبدأ التجميد يوم"},"filled":true,"text":"02/11/2026","tone":"bad","error":{"en":"⚠ Invalid date.","ar":"⚠ تاريخ غير صالح."}}]}},{"id":"fix","text":{"en":"\"A freeze can start from tomorrow. Choose 3 November or later.\"","ar":"«يمكن أن يبدأ التجميد من الغد. اختاري 3 نوفمبر أو بعده.»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Freeze starts on","ar":"يبدأ التجميد يوم"},"filled":true,"text":"02/11/2026","tone":"bad","error":{"en":"⚠ A freeze can start from tomorrow. Choose 3 November or later.","ar":"⚠ يمكن أن يبدأ التجميد من الغد. اختاري 3 نوفمبر أو بعده."}}]}},{"id":"problem","text":{"en":"\"This date is not accepted for a freeze.\"","ar":"«هذا التاريخ غير مقبول للتجميد.»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Freeze starts on","ar":"يبدأ التجميد يوم"},"filled":true,"text":"02/11/2026","tone":"bad","error":{"en":"⚠ This date is not accepted for a freeze.","ar":"⚠ هذا التاريخ غير مقبول للتجميد."}}]}}],"answer":["fix"],"misconceptions":[{"id":"MC-P01-047","when":["invalid","problem"],"feedback":{"en":"Marwa already knows the date was refused; she doesn't know why, so she changed the format. Tell her the rule and a date that works.","ar":"تعرف مروة بالفعل أن التاريخ رُفض؛ لكنها لا تعرف لماذا، فغيّرت الصيغة. أخبرها بالقاعدة وبتاريخ ينجح."}}],"hints":[{"en":"Why did Marwa try other formats of the same date?","ar":"لماذا جرّبت مروة صيغًا أخرى للتاريخ نفسه؟"},{"en":"Which message tells her which dates will work?","ar":"أي رسالة تخبرها بالتواريخ التي ستنجح؟"}],"correct":{"en":"She learns the rule and the first date that works.","ar":"تعرف القاعدة وأول تاريخ ينجح."},"explain":{"en":"\"Invalid\" leaves people guessing what part is wrong. Name the rule, then give an answer that fits it.","ar":"كلمة «غير صالح» تترك الناس يخمّنون أي جزء خطأ. اذكر القاعدة، ثم أعطِ إجابة تناسبها."},"speaker":"hana"},{"id":"S06","type":"words","skill":"SK-P01-U04-02","part":"guided","confidence":true,"rules":["R06","R15"],"value":{"en":"Form errors (NN/g): an error message should be explicit, human-readable, polite, precise, and give constructive advice. Bank codes and \"issuer\" fail the human-readable test.","ar":"أخطاء النماذج (NN/g): رسالة الخطأ يجب أن تكون صريحة، ومفهومة للبشر، ومهذّبة، ودقيقة، وتقدّم نصيحة مفيدة. وأكواد البنك وكلمة «الجهة المُصدِرة» لا تجتاز اختبار «مفهومة للبشر»."},"ref":{"url":"https://www.nngroup.com/articles/errors-forms-design-guidelines/","quote":"it should be explicit, human-readable, polite, precise, and give constructive advice."},"scenario":{"en":"Gamal renewed his membership online. His bank refused the card for low balance, and our payment page sends back the code \"51\".","ar":"جدّد جمال اشتراكه من الموقع. ورفض بنكه البطاقة لعدم كفاية الرصيد، وصفحة الدفع عندنا تُرجع الكود «51»."},"prompt":{"en":"Which message should Gamal see?","ar":"أي رسالة يجب أن يراها جمال؟"},"options":[{"id":"code","text":{"en":"\"Payment failed (ERR_CARD_51).\"","ar":"«فشل الدفع (ERR_CARD_51).»"}},{"id":"plain","text":{"en":"\"Your bank declined this card because of low balance. Try another card, or pay at the front desk.\"","ar":"«رفض بنكك هذه البطاقة بسبب عدم كفاية الرصيد. جرّب بطاقة أخرى، أو ادفع في الاستقبال.»"}},{"id":"jargon","text":{"en":"\"Transaction declined by issuer.\"","ar":"«رُفضت المعاملة من الجهة المُصدِرة.»"}}],"answer":["plain"],"misconceptions":[{"id":"MC-P01-048","when":["code","jargon"],"feedback":{"en":"A code and the word \"issuer\" are bank language. Gamal can't tell whether the problem is his card, our site, or his internet.","ar":"الكود وكلمة «الجهة المُصدِرة» لغة بنوك. ولا يستطيع جمال أن يعرف هل المشكلة في بطاقته، أم في موقعنا، أم في الإنترنت عنده."}}],"hints":[{"en":"Which message could Gamal explain to a friend?","ar":"أي رسالة يستطيع جمال أن يشرحها لصديق؟"},{"en":"Which one says what he can do next?","ar":"أيّها يقول ما يستطيع فعله بعد ذلك؟"}],"correct":{"en":"Plain words, the real reason, and two ways to pay.","ar":"كلمات بسيطة، والسبب الحقيقي، وطريقتان للدفع."},"explain":{"en":"Translate system codes into the person's words: what happened, why, and what to try next.","ar":"ترجم أكواد النظام إلى كلمات الشخص: ماذا حدث، ولماذا، وماذا يجرّب بعد ذلك."},"speaker":"hana"},{"id":"S07","type":"compare","skill":"SK-P01-U04-03","part":"contrast","rules":["R11","R15"],"value":{"en":"Contrast with S05: both messages here say how to fix it. Error messages (NN/g): don't use phrasing that blames users. The difference is only who the sentence is about.","ar":"مقارنة مع الخطوة 5: الرسالتان هنا تقولان كيف يُصلح الخطأ. رسائل الخطأ (NN/g): لا تستخدم صياغة تلوم المستخدم. والفرق فقط في من تتحدّث عنه الجملة."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Don't use phrasing that blames users or implies they are doing something wrong"},"scenario":{"en":"Asmaa typed her birth date as 09/13/1995, month first. Our form reads day first, so it found month 13. I have two messages to choose from.","ar":"كتبت أسماء تاريخ ميلادها 09/13/1995، الشهر أولًا. ونموذجنا يقرأ اليوم أولًا، فوجد الشهر 13. وأمامي رسالتان أختار بينهما."},"prompt":{"en":"Which message should ship?","ar":"أي رسالة يجب أن تُطلق؟"},"a":{"label":{"en":"About Asmaa","ar":"عن أسماء"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"text":"09/13/1995","tone":"bad","error":{"en":"⚠ You entered the date wrong. Use day/month/year, like 13/09/1995.","ar":"⚠ أدخلتِ التاريخ بشكل خاطئ. استخدمي يوم/شهر/سنة، مثل 13/09/1995."}}]}},"b":{"label":{"en":"About the date","ar":"عن التاريخ"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Date of birth","ar":"تاريخ الميلاد"},"filled":true,"text":"09/13/1995","tone":"bad","error":{"en":"⚠ There's no month 13. Enter day/month/year, like 13/09/1995.","ar":"⚠ لا يوجد شهر 13. اكتبي يوم/شهر/سنة، مثل 13/09/1995."}}]}},"answer":"b","reason":{"prompt":{"en":"What makes B better?","ar":"ما الذي يجعل B أفضل؟"},"options":[{"id":"fix","text":{"en":"Only B gives an example","ar":"B وحدها تعطي مثالًا"}},{"id":"subject","text":{"en":"B talks about the date, not about a mistake Asmaa made","ar":"B تتحدّث عن التاريخ، لا عن خطأ ارتكبته أسماء"}},{"id":"shorter","text":{"en":"B is shorter","ar":"B أقصر"}}],"answer":["subject"],"misconceptions":[{"id":"MC-P01-049","when":["fix","shorter"],"feedback":{"en":"Both give the same example and are about as long. The only difference is \"You entered the date wrong\" versus \"There's no month 13\".","ar":"كلتاهما تعطي المثال نفسه وطولهما متقارب. والفرق الوحيد هو «أدخلتِ التاريخ بشكل خاطئ» مقابل «لا يوجد شهر 13»."}}]},"misconceptions":[{"id":"MC-P01-049","when":["a"],"feedback":{"en":"A is helpful but opens by telling Asmaa she got it wrong. Many countries write month first; she wasn't careless. B says the same fix without the blame.","ar":"A مفيدة لكنها تبدأ بإخبار أسماء أنها أخطأت. وكثير من البلاد تكتب الشهر أولًا؛ فهي لم تكن مهملة. وB تقول الإصلاح نفسه بلا لوم."}}],"hints":[{"en":"Both messages give the fix. What's different in the first few words?","ar":"الرسالتان تعطيان الإصلاح. ما المختلف في الكلمات الأولى؟"}],"correct":{"en":"Same fix, without the blame.","ar":"الإصلاح نفسه، بلا لوم."},"explain":{"en":"When two messages are equally helpful, choose the one about the input. \"There's no month 13\" explains; \"You entered it wrong\" judges.","ar":"حين تتساوى رسالتان في الفائدة، اختر التي تتحدّث عن المُدخل. «لا يوجد شهر 13» تشرح؛ و«أدخلتِه بشكل خاطئ» تحكم."},"speaker":"hana"},{"id":"S08","type":"tune","skill":"SK-P01-U04-03","part":"independent","speaker":"karim","rules":["R14","R19"],"value":{"en":"New case. Error messages (NN/g): don't imply the user did something wrong. A message about the number itself, with where to check it, helps without accusing.","ar":"حالة جديدة. رسائل الخطأ (NN/g): لا توحِ بأن المستخدم أخطأ. والرسالة التي تتحدّث عن الرقم نفسه، مع مكان مراجعته، تساعد دون اتهام."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Don't use phrasing that blames users or implies they are doing something wrong"},"scenario":{"en":"I'm building a bank's transfer screen. Account numbers at this bank have 16 digits. Sherif pasted 12 digits from a chat, and our current message says \"You entered an invalid account number.\"","ar":"أبني شاشة التحويل في تطبيق بنك. وأرقام الحسابات في هذا البنك 16 رقمًا. لصق شريف 12 رقمًا من محادثة، ورسالتنا الحالية تقول «أدخلت رقم حساب غير صالح.»"},"prompt":{"en":"Try each message. Which one should ship?","ar":"جرّب كل رسالة. أيّها يجب أن تُطلق؟"},"start":"you","options":[{"id":"digits","text":{"en":"\"This number has 12 digits. Our account numbers have 16; check the full number with the receiver.\"","ar":"«هذا الرقم فيه 12 رقمًا. أرقام الحسابات عندنا 16؛ راجع الرقم كاملًا مع المستلم.»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Account number","ar":"رقم الحساب"},"filled":true,"text":"⁦1004 2231 9870⁩","tone":"bad","error":{"en":"⚠ This number has 12 digits. Our account numbers have 16; check the full number with the receiver.","ar":"⚠ هذا الرقم فيه 12 رقمًا. أرقام الحسابات عندنا 16؛ راجع الرقم كاملًا مع المستلم."}}]}},{"id":"you","text":{"en":"Keep \"You entered an invalid account number.\"","ar":"أبقِ «أدخلت رقم حساب غير صالح.»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Account number","ar":"رقم الحساب"},"filled":true,"text":"⁦1004 2231 9870⁩","tone":"bad","error":{"en":"⚠ You entered an invalid account number.","ar":"⚠ أدخلت رقم حساب غير صالح."}}]}},{"id":"careful","text":{"en":"\"You made a mistake. Please be more careful with account numbers.\"","ar":"«لقد أخطأت. يُرجى الانتباه أكثر لأرقام الحسابات.»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Account number","ar":"رقم الحساب"},"filled":true,"text":"⁦1004 2231 9870⁩","tone":"bad","error":{"en":"⚠ You made a mistake. Please be more careful with account numbers.","ar":"⚠ لقد أخطأت. يُرجى الانتباه أكثر لأرقام الحسابات."}}]}}],"answer":["digits"],"misconceptions":[{"id":"MC-P01-049","when":["you","careful"],"feedback":{"en":"Both point at Sherif, and neither says what's wrong with the number. The number was cut off in the chat; describe the number, and say where to get the full one.","ar":"الرسالتان تشيران إلى شريف، ولا تقول أيٌّ منهما ما مشكلة الرقم. الرقم انقطع في المحادثة؛ صِف الرقم، وقل أين يجد الرقم كاملًا."}}],"correct":{"en":"It describes the number, not Sherif, and says how to get the right one.","ar":"تصف الرقم، لا شريف، وتقول كيف يحصل على الرقم الصحيح."},"explain":{"en":"Count and compare: \"12 digits, we need 16\" is precise, neutral, and points straight to the fix.","ar":"اعدد وقارن: «12 رقمًا، ونحتاج 16» دقيقة، ومحايدة، وتشير مباشرة إلى الإصلاح."}},{"id":"S09","type":"card","part":"recap","icons":["text","idea","person","ok"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **No codes:** replaced \"Error 403\" with the date the pass ended and two ways forward.\n- **The fix, not just the problem:** turned \"Invalid date\" into the first date that works.\n- **Plain words:** chose low balance and another card over a bank code and \"issuer\".\n- **No blame:** made the class, the date and the account number the subject, not the person.\n\nNext: when to show an error, and what to keep.","ar":"- **بلا أكواد:** استبدلت «Error 403» بتاريخ انتهاء الدعوة وطريقين للمتابعة.\n- **الإصلاح، لا المشكلة فقط:** حوّلت «تاريخ غير صالح» إلى أول تاريخ ينجح.\n- **كلمات بسيطة:** اخترت «عدم كفاية الرصيد» و«بطاقة أخرى» بدل كود البنك و«الجهة المُصدِرة».\n- **بلا لوم:** جعلت الحصة والتاريخ ورقم الحساب فاعل الجملة، لا الشخص.\n\nالتالي: متى تعرض الخطأ، وماذا تحتفظ به."}}]}$uxg$::jsonb),
  ($uxg$P01-U04-L03$uxg$, $uxg$709a1cca43dd0e511fa488698b93b667e624b661e0ccda21e385175c08500e6d$uxg$, $uxg${"id":"P01-U04-L03","mode":"lesson","minutes":8,"title":{"en":"The right moment, and nothing lost","ar":"اللحظة المناسبة، ولا شيء يضيع"},"speaker":"hana","review_labels":{"MC-P01-050":{"en":"Wait until the person leaves the field","ar":"انتظر حتى يغادر الشخص الحقل"},"MC-P01-051":{"en":"Keep what people typed","ar":"احتفظ بما كتبه الناس"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Tamer's sign-up","ar":"تسجيل تامر"},"body":{"en":"Tamer made an account in my gym's app. He typed one letter of his email, and \"Invalid email\" appeared in red. It stayed red the whole time he typed.\n\nThen he tapped Create account. His mobile number was already on another account, and the whole form came back empty, even the parts that were right.","ar":"أنشأ تامر حسابًا في تطبيق نادي. كتب حرفًا واحدًا من بريده، فظهرت «بريد غير صالح» باللون الأحمر. وظلّت حمراء طوال وقت الكتابة.\n\nثم ضغط «أنشئ الحساب». كان رقم موبايله مسجّلًا على حساب آخر، فعاد النموذج كله فارغًا، حتى الأجزاء الصحيحة."},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"focus":true,"text":"t","tone":"bad","error":{"en":"⚠ Invalid email.","ar":"⚠ بريد غير صالح."}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U04-04","part":"try","rules":["R12"],"value":{"en":"Try first. Hostile error messages (NN/g): premature errors appear before the person had a chance to finish. Checking an email after one letter is premature; checking when Tamer moves on is not.","ar":"جرّب أولًا. رسائل الخطأ العدائية (NN/g): الأخطاء المبكّرة تظهر قبل أن يتمكّن الشخص من الإنهاء. والتحقّق من البريد بعد حرف واحد مبكّر؛ أما التحقّق حين ينتقل تامر لما بعده فليس كذلك."},"ref":{"url":"https://www.nngroup.com/articles/hostile-error-messages/","quote":"Premature error messages are error messages that are presented by the system too early"},"prompt":{"en":"Try each timing. Each preview shows two moments. Which one should ship?","ar":"جرّب كل توقيت. كل معاينة تُظهر لحظتين. أيّها يجب أن يُطلق؟"},"start":"typing","options":[{"id":"typing","text":{"en":"Keep checking with every letter","ar":"أبقِ التحقّق مع كل حرف"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"While typing","ar":"أثناء الكتابة"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"focus":true,"text":"tamer.h@","tone":"bad","error":{"en":"⚠ Enter an email like name@example.com.","ar":"⚠ اكتب بريدًا مثل name@example.com."},"gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After moving to the next field","ar":"بعد الانتقال إلى الحقل التالي"},"gap":"l"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"text":"tamer.h@mail","tone":"bad","error":{"en":"⚠ Enter an email like name@example.com.","ar":"⚠ اكتب بريدًا مثل name@example.com."},"gap":"xs"}]}},{"id":"submit","text":{"en":"Check only when he taps Create account","ar":"تحقّق فقط حين يضغط «أنشئ الحساب»"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"While typing","ar":"أثناء الكتابة"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"focus":true,"text":"tamer.h@","gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After moving to the next field","ar":"بعد الانتقال إلى الحقل التالي"},"gap":"l"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"text":"tamer.h@mail","gap":"xs"}]}},{"id":"leave","text":{"en":"Check when he leaves the field","ar":"تحقّق حين يغادر الحقل"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"While typing","ar":"أثناء الكتابة"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"focus":true,"text":"tamer.h@","gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After moving to the next field","ar":"بعد الانتقال إلى الحقل التالي"},"gap":"l"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"text":"tamer.h@mail","tone":"bad","error":{"en":"⚠ Enter an email like name@example.com.","ar":"⚠ اكتب بريدًا مثل name@example.com."},"gap":"xs"}]}}],"answer":["leave"],"misconceptions":[{"id":"MC-P01-050","when":["typing"],"feedback":{"en":"Every email is \"wrong\" until the last letter. Red while Tamer types tells him nothing he doesn't know, and makes the form feel like it's scolding him.","ar":"كل بريد يكون «خاطئًا» حتى آخر حرف. والأحمر أثناء كتابة تامر لا يخبره بشيء لا يعرفه، ويجعل النموذج يبدو كأنه يوبّخه."}},{"id":"MC-P01-050","when":["submit"],"feedback":{"en":"Look at the second moment: the missing \".com\" goes unnoticed, and Tamer only finds out at the end, after moving on to other fields. Check as soon as he leaves the field.","ar":"انظر إلى اللحظة الثانية: «.com» الناقصة لا يلاحظها أحد، ولا يعرف تامر إلا في النهاية، بعد أن انتقل إلى حقول أخرى. تحقّق بمجرّد أن يغادر الحقل."}}],"hints":[{"en":"In the first moment, is Tamer done typing?","ar":"في اللحظة الأولى، هل انتهى تامر من الكتابة؟"},{"en":"In the second moment, he's done but made a typo. Which version tells him right then?","ar":"في اللحظة الثانية، انتهى لكن فيه خطأ. أي نسخة تخبره حينها؟"}],"correct":{"en":"Quiet while he types, clear once he moves on.","ar":"هادئ أثناء الكتابة، وواضح بمجرّد أن ينتقل."},"explain":{"en":"Leaving a field means \"I'm done\". That's the moment to check: early enough to fix while it's fresh, late enough not to interrupt.","ar":"مغادرة الحقل تعني «انتهيت». وهذه لحظة التحقّق: مبكّرة بما يكفي للإصلاح والأمر حاضر في الذهن، ومتأخرة بما يكفي حتى لا تقاطع."}},{"id":"S03","type":"card","part":"concept","icons":["clock","eye","ok","warn"],"title":{"en":"Check at the right time, and keep everything","ar":"تحقّق في الوقت المناسب، واحتفظ بكل شيء"},"body":{"en":"When an error appears matters as much as what it says.\n\n- **Not while typing:** an error after the first letter feels like scolding. People haven't finished yet.\n- **When they leave the field:** that's when they're done with it, so check then, and they can fix it right away.\n- **Keep every answer:** never empty the form after an error. Keep the right answers, and keep the wrong one too, marked, so people can edit it instead of starting over.","ar":"توقيت ظهور الخطأ مهم مثل ما يقوله.\n\n- **ليس أثناء الكتابة:** الخطأ بعد أول حرف يبدو كتوبيخ. الناس لم ينتهوا بعد.\n- **حين يغادرون الحقل:** هذه لحظة انتهائهم منه، فتحقّق حينها، ويستطيعون الإصلاح فورًا.\n- **احتفظ بكل إجابة:** لا تُفرغ النموذج أبدًا بعد خطأ. احتفظ بالإجابات الصحيحة، واحتفظ بالخاطئة أيضًا مع علامة، ليعدّلها الناس بدل أن يبدؤوا من جديد."}},{"id":"S04","type":"tune","skill":"SK-P01-U04-05","part":"guided","rules":["R06","R15"],"value":{"en":"Form usability (NN/g): erroneous input should be preserved so users can correct it, with a specific explanation. Keeping the number lets Tamer see which one he typed.","ar":"سهولة استخدام النماذج (NN/g): يجب الاحتفاظ بالمُدخل الخاطئ ليُصلحه المستخدم، مع شرح محدّد للمشكلة. والاحتفاظ بالرقم يتيح لتامر أن يرى أي رقم كتب."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Erroneous input should be preserved so users can correct it, and accompanied by a specific explanation of the problem."},"scenario":{"en":"Back to Tamer tapping Create account. His mobile number is already on another account: his wife signed up with it last year.","ar":"نعود إلى تامر وهو يضغط «أنشئ الحساب». رقم موبايله مسجّل على حساب آخر: زوجته اشتركت به العام الماضي."},"prompt":{"en":"Try each version of what happens after Create account. Which one should ship?","ar":"جرّب كل نسخة لما يحدث بعد «أنشئ الحساب». أيّها يجب أن تُطلق؟"},"start":"empty","options":[{"id":"keepall","text":{"en":"Keep every answer, and mark the mobile number","ar":"احتفظ بكل الإجابات، وعلّم رقم الموبايل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Tamer Hassan","ar":"تامر حسن"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"text":"tamer.h@mail.com","gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0122 345 6789⁩","tone":"bad","error":{"en":"⚠ This number is already on another account. Use a different number, or sign in to that account.","ar":"⚠ هذا الرقم مسجّل على حساب آخر. استخدم رقمًا مختلفًا، أو سجّل الدخول إلى ذلك الحساب."},"gap":"s"},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"text":"••••••••","gap":"s"}]}},{"id":"empty","text":{"en":"Keep it: show the error on an empty form","ar":"أبقِه: اعرض الخطأ على نموذج فارغ"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"This mobile number is already on another account.","ar":"رقم الموبايل هذا مسجّل على حساب آخر."}},{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"text":"","gap":"s"}]}},{"id":"clearone","text":{"en":"Keep the other answers, but clear the mobile field","ar":"احتفظ بالإجابات الأخرى، لكن امسح حقل الموبايل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Tamer Hassan","ar":"تامر حسن"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"filled":true,"text":"tamer.h@mail.com","gap":"s"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"text":"","tone":"bad","error":{"en":"⚠ This number is already on another account. Use a different number, or sign in to that account.","ar":"⚠ هذا الرقم مسجّل على حساب آخر. استخدم رقمًا مختلفًا، أو سجّل الدخول إلى ذلك الحساب."},"gap":"s"},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"text":"••••••••","gap":"s"}]}}],"answer":["keepall"],"misconceptions":[{"id":"MC-P01-051","when":["empty"],"feedback":{"en":"One field had a problem, and Tamer has to type four again. Many people won't. Keep what he typed.","ar":"حقل واحد فيه مشكلة، وعلى تامر أن يكتب أربعة من جديد. وكثيرون لن يفعلوا. احتفظ بما كتبه."}},{"id":"MC-P01-051","when":["clearone"],"feedback":{"en":"Better, but now the message talks about \"this number\" and the field is empty. Tamer can't see which number we mean. Keep it so he can compare and change it.","ar":"أفضل، لكن الرسالة الآن تتحدّث عن «هذا الرقم» والحقل فارغ. ولا يرى تامر أي رقم نقصد. احتفظ به ليقارن ويغيّره."}}],"hints":[{"en":"How many fields had a problem, and how many does Tamer have to retype in each version?","ar":"كم حقلًا فيه مشكلة، وكم حقلًا على تامر أن يعيد كتابته في كل نسخة؟"},{"en":"To fix a wrong answer, does it help to still see it?","ar":"لإصلاح إجابة خاطئة، هل يفيد أن تظل تراها؟"}],"correct":{"en":"Nothing is lost, and the problem number is right there to change.","ar":"لا شيء يضيع، والرقم الذي فيه المشكلة أمامه ليغيّره."},"explain":{"en":"An error should cost one fix, not a whole form. Keep every answer, including the wrong one, and say what's wrong with it.","ar":"الخطأ يجب أن يكلّف إصلاحًا واحدًا، لا نموذجًا كاملًا. احتفظ بكل إجابة، حتى الخاطئة، وقل ما مشكلتها."},"speaker":"hana"},{"id":"S05","type":"tune","skill":"SK-P01-U04-04","part":"guided","rules":["R06","R15"],"value":{"en":"Hostile error messages (NN/g): showing errors while the person types feels like an unwarranted scolding. For a password, say the rule up front and check when the person leaves the field.","ar":"رسائل الخطأ العدائية (NN/g): عرض الأخطاء أثناء الكتابة يبدو كتوبيخ بلا سبب. وفي كلمة المرور، اذكر القاعدة مسبقًا وتحقّق حين يغادر الشخص الحقل."},"ref":{"url":"https://www.nngroup.com/articles/hostile-error-messages/","quote":"Displaying error messages while the user types feels like an unwarranted scolding and can be irritating."},"scenario":{"en":"Passwords in our app need at least 8 characters. Right now \"Too short\" shows in red from the very first character. Rania said it felt like the app was shouting at her.","ar":"كلمات المرور في تطبيقنا تحتاج 8 أحرف على الأقل. والآن تظهر «قصيرة جدًا» بالأحمر من أول حرف. وقالت رانيا إنها شعرت كأن التطبيق يصرخ فيها."},"prompt":{"en":"Try each version. Each preview shows two moments. Which one should ship?","ar":"جرّب كل نسخة. كل معاينة تُظهر لحظتين. أيّها يجب أن تُطلق؟"},"start":"red","options":[{"id":"red","text":{"en":"Keep \"Too short\" in red from the first character","ar":"أبقِ «قصيرة جدًا» بالأحمر من أول حرف"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"After 3 characters","ar":"بعد 3 أحرف"}},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"focus":true,"text":"•••","tone":"bad","error":{"en":"⚠ Too short.","ar":"⚠ قصيرة جدًا."},"gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After she moves on with 6 characters","ar":"بعد أن تنتقل وفيها 6 أحرف"},"gap":"l"},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"text":"••••••","tone":"bad","error":{"en":"⚠ Too short.","ar":"⚠ قصيرة جدًا."},"gap":"xs"}]}},{"id":"rule","text":{"en":"Show the rule under the label, and check when she leaves the field","ar":"اعرض القاعدة تحت العنوان، وتحقّق حين تغادر الحقل"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"After 3 characters","ar":"بعد 3 أحرف"}},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"hintFirst":true,"hint":{"en":"At least 8 characters","ar":"8 أحرف على الأقل"},"filled":true,"focus":true,"text":"•••","gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After she moves on with 6 characters","ar":"بعد أن تنتقل وفيها 6 أحرف"},"gap":"l"},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"hintFirst":true,"hint":{"en":"At least 8 characters","ar":"8 أحرف على الأقل"},"filled":true,"text":"••••••","tone":"bad","error":{"en":"⚠ This password has 6 characters. Add 2 more.","ar":"⚠ كلمة المرور هذه 6 أحرف. أضيفي حرفين."},"gap":"xs"}]}},{"id":"grey","text":{"en":"Keep checking from the first character, but in grey","ar":"أبقِ التحقّق من أول حرف، لكن بالرمادي"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"After 3 characters","ar":"بعد 3 أحرف"}},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"focus":true,"text":"•••","gap":"xs"},{"kind":"small","color":"pale","text":{"en":"Too short.","ar":"قصيرة جدًا."},"gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After she moves on with 6 characters","ar":"بعد أن تنتقل وفيها 6 أحرف"},"gap":"l"},{"kind":"field","label":{"en":"Password","ar":"كلمة المرور"},"filled":true,"text":"••••••","gap":"xs"},{"kind":"small","color":"pale","text":{"en":"Too short.","ar":"قصيرة جدًا."},"gap":"xs"}]}}],"answer":["rule"],"misconceptions":[{"id":"MC-P01-050","when":["red"],"feedback":{"en":"After 3 characters, Rania is still typing. Telling her it's too short is like correcting a sentence before she finishes it.","ar":"بعد 3 أحرف، ما زالت رانيا تكتب. وإخبارها أنها قصيرة كأنك تصحّح جملة قبل أن تُكملها."}},{"id":"MC-P01-050","when":["grey"],"feedback":{"en":"Grey is softer, but it's still an error while she types, and a grey line is easy to miss when she does move on with 6 characters.","ar":"الرمادي أهدأ، لكنه ما زال خطأ أثناء الكتابة، والسطر الرمادي يسهل أن يفوتها حين تنتقل فعلًا وفيها 6 أحرف."}}],"hints":[{"en":"In which version does Rania know the rule before she types, without being told off?","ar":"في أي نسخة تعرف رانيا القاعدة قبل الكتابة، دون أن تُوبَّخ؟"},{"en":"And which one speaks up clearly once she moves on?","ar":"وأيّها يتكلّم بوضوح حين تنتقل؟"}],"correct":{"en":"The rule comes first; the error comes only when she's done.","ar":"القاعدة تأتي أولًا؛ والخطأ يأتي فقط حين تنتهي."},"explain":{"en":"Separate the rule from the error. The rule helps before and during typing; the error is for when the person finishes and something is still wrong.","ar":"افصل القاعدة عن الخطأ. القاعدة تساعد قبل الكتابة وأثناءها؛ والخطأ لحين ينتهي الشخص ويبقى شيء غير صحيح."},"speaker":"hana"},{"id":"S06","type":"tune","skill":"SK-P01-U04-05","part":"guided","rules":["R06","R15"],"value":{"en":"Error messages (NN/g): let users correct errors by editing what they did, not by starting over. A message that is 62 characters too long should be shortened, not erased.","ar":"رسائل الخطأ (NN/g): دع المستخدم يُصلح الخطأ بتعديل ما فعله، لا بالبدء من جديد. والرسالة الأطول من المسموح بـ 62 حرفًا يجب أن تُختصر، لا أن تُمسح."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Let users correct errors by editing their original action instead of starting over."},"scenario":{"en":"When members book a trainer, they can describe their goals in up to 250 characters. Tamer wrote 312 characters about his knee injury and his goals. When he tapped Send, the box came back empty with \"Text too long\".","ar":"حين يحجز الأعضاء مدرّبًا، يستطيعون وصف أهدافهم في 250 حرفًا كحدّ أقصى. كتب تامر 312 حرفًا عن إصابة ركبته وأهدافه. وحين ضغط «أرسل»، عاد المربع فارغًا مع «النص طويل جدًا»."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"clear","options":[{"id":"clear","text":{"en":"Keep it: empty the box and say \"Text too long\"","ar":"أبقِه: أفرغ المربع وقل «النص طويل جدًا»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Your goals","ar":"أهدافك"},"text":"","tone":"bad","error":{"en":"⚠ Text too long.","ar":"⚠ النص طويل جدًا."}}]}},{"id":"cut","text":{"en":"Cut his text to 250 characters and send it","ar":"اقطع نصّه عند 250 حرفًا وأرسله"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Your goals","ar":"أهدافك"},"filled":true,"text":{"en":"I hurt my left knee last year, so I can't run yet. I want to lose 8 kg before summer and get strong enough to…","ar":"أُصبت في ركبتي اليسرى العام الماضي، فلا أستطيع الجري بعد. أريد أن أنقص 8 كجم قبل الصيف وأن أصبح قويًا بما يكفي…"}},{"kind":"small","color":"green","text":{"en":"✓ Sent","ar":"✓ تم الإرسال"},"gap":"xs"}]}},{"id":"keep","text":{"en":"Keep his text, and say how much to shorten it","ar":"احتفظ بنصّه، وقل كم يختصره"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Your goals","ar":"أهدافك"},"filled":true,"text":{"en":"I hurt my left knee last year, so I can't run yet. I want to lose 8 kg before summer and get strong enough to…","ar":"أُصبت في ركبتي اليسرى العام الماضي، فلا أستطيع الجري بعد. أريد أن أنقص 8 كجم قبل الصيف وأن أصبح قويًا بما يكفي…"},"tone":"bad","error":{"en":"⚠ 312 of 250 characters. Shorten it by 62 to send.","ar":"⚠ 312 من 250 حرفًا. اختصره بـ 62 حرفًا لتُرسله."}}]}}],"answer":["keep"],"misconceptions":[{"id":"MC-P01-051","when":["clear"],"feedback":{"en":"Tamer has to write 250 characters again from memory, just to fix 62 too many. Keep his text so he can trim it.","ar":"على تامر أن يكتب 250 حرفًا من جديد من الذاكرة، فقط ليُصلح 62 حرفًا زائدًا. احتفظ بنصّه ليختصره."}},{"id":"MC-P01-051","when":["cut"],"feedback":{"en":"The end of his text is gone, and he doesn't know which part. The trainer may never read about his goals. Let him choose what to cut.","ar":"نهاية نصّه ضاعت، وهو لا يعرف أي جزء. وقد لا يقرأ المدرّب عن أهدافه أبدًا. دعه يختار ما يحذفه."}}],"hints":[{"en":"What does Tamer need to fix 62 extra characters?","ar":"ماذا يحتاج تامر ليُصلح 62 حرفًا زائدًا؟"},{"en":"In which version does he decide what to remove?","ar":"في أي نسخة يقرّر هو ما يحذفه؟"}],"correct":{"en":"His text stays, and he knows exactly how much to trim.","ar":"نصّه يبقى، ويعرف بالضبط كم يختصر."},"explain":{"en":"Fixing should mean editing, not redoing. Keep the input, and say exactly what has to change.","ar":"الإصلاح يجب أن يعني التعديل، لا الإعادة. احتفظ بالمُدخل، وقل بالضبط ما يجب أن يتغيّر."},"speaker":"hana"},{"id":"S07","type":"compare","skill":"SK-P01-U04-04","part":"contrast","rules":["R11","R15"],"value":{"en":"Contrast with S02 and S05: there the check came too early. Form errors (NN/g): show the error once the person has finished with the field and moved on. Waiting for the final button is too late.","ar":"مقارنة مع الخطوتين 2 و5: هناك جاء التحقّق مبكّرًا جدًا. أخطاء النماذج (NN/g): اعرض الخطأ بعد أن ينتهي الشخص من الحقل وينتقل لما بعده. وانتظار الزر الأخير متأخر جدًا."},"ref":{"url":"https://www.nngroup.com/articles/errors-forms-design-guidelines/","quote":"In most cases, avoid showing an error until the user has finished with the field and moved to the next field."},"scenario":{"en":"Our kids' swimming sign-up has 9 fields. Version A checks everything only when parents tap Register at the end. Version B checks each field as the parent moves to the next one. Ehab, a parent, has just typed his child's age as 2; classes start at 4.","ar":"تسجيل السباحة للأطفال عندنا فيه 9 حقول. النسخة A تتحقّق من كل شيء فقط حين يضغط الوالد «سجّل» في النهاية. والنسخة B تتحقّق من كل حقل حين ينتقل الوالد إلى التالي. وإيهاب، أحد الآباء، كتب للتوّ عمر طفله 2؛ والحصص تبدأ من 4 سنوات."},"prompt":{"en":"Ehab has just moved to the next field. Which version should ship?","ar":"انتقل إيهاب للتوّ إلى الحقل التالي. أي نسخة يجب أن تُطلق؟"},"a":{"label":{"en":"Check at Register","ar":"التحقّق عند «سجّل»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Child's age","ar":"عمر الطفل"},"filled":true,"text":"2"},{"kind":"field","label":{"en":"Preferred class time","ar":"وقت الحصة المفضّل"},"focus":true,"text":"","gap":"s"}]}},"b":{"label":{"en":"Check on leaving","ar":"التحقّق عند المغادرة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Child's age","ar":"عمر الطفل"},"filled":true,"text":"2","tone":"bad","error":{"en":"⚠ Swimming classes start at age 4. See our playtime sessions for younger kids.","ar":"⚠ حصص السباحة تبدأ من عمر 4 سنوات. شاهد جلسات اللعب للأطفال الأصغر."}},{"kind":"field","label":{"en":"Preferred class time","ar":"وقت الحصة المفضّل"},"focus":true,"text":"","gap":"s"}]}},"answer":"b","reason":{"prompt":{"en":"Why is B better here?","ar":"لماذا B أفضل هنا؟"},"options":[{"id":"fresh","text":{"en":"Ehab learns about the age now, before he fills in 7 more fields for nothing","ar":"يعرف إيهاب مشكلة العمر الآن، قبل أن يملأ 7 حقول أخرى بلا فائدة"}},{"id":"always","text":{"en":"Errors should always appear as early as possible","ar":"الأخطاء يجب أن تظهر دائمًا في أبكر وقت ممكن"}},{"id":"red","text":{"en":"B uses more red","ar":"B تستخدم أحمر أكثر"}}],"answer":["fresh"],"misconceptions":[{"id":"MC-P01-050","when":["always"],"feedback":{"en":"Not as early as possible: during typing is too early. The right moment is when the field is finished, which is exactly when B checks.","ar":"ليس في أبكر وقت ممكن: أثناء الكتابة مبكّر جدًا. اللحظة الصحيحة حين ينتهي الحقل، وهذا بالضبط وقت تحقّق B."}}]},"misconceptions":[{"id":"MC-P01-050","when":["a"],"feedback":{"en":"In A, Ehab fills 7 more fields, taps Register, and only then learns his child can't join. Checking when he left the age field would have saved all that.","ar":"في A، يملأ إيهاب 7 حقول أخرى، ويضغط «سجّل»، وعندها فقط يعرف أن طفله لا يستطيع الانضمام. والتحقّق حين غادر حقل العمر كان سيوفّر كل ذلك."}}],"hints":[{"en":"In A, when does Ehab find out about the age?","ar":"في A، متى يعرف إيهاب مشكلة العمر؟"}],"correct":{"en":"Not too early, not too late: when the field is done.","ar":"لا مبكّرًا جدًا، ولا متأخرًا جدًا: حين ينتهي الحقل."},"explain":{"en":"Too early scolds; too late wastes work. Checking on leaving a field catches the problem while it's fresh, before more effort goes in.","ar":"المبكّر جدًا يوبّخ؛ والمتأخر جدًا يُضيّع الجهد. والتحقّق عند مغادرة الحقل يلتقط المشكلة وهي حاضرة، قبل بذل مزيد من الجهد."},"speaker":"hana"},{"id":"S08","type":"tune","skill":"SK-P01-U04-05","part":"independent","speaker":"youssef","rules":["R14","R19"],"value":{"en":"New case. Form usability (NN/g): preserve the input, including the wrong part, and explain the problem. A bad coupon should never cost a customer their address.","ar":"حالة جديدة. سهولة استخدام النماذج (NN/g): احتفظ بالمُدخل، حتى الجزء الخاطئ، واشرح المشكلة. والكوبون غير الصالح يجب ألّا يكلّف العميل عنوانه أبدًا."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Erroneous input should be preserved so users can correct it, and accompanied by a specific explanation of the problem."},"scenario":{"en":"In my online shop's checkout, Sahar typed her address and the coupon \"EID25\". That coupon is for orders over 500 EGP, and hers is 380. The page reloaded with the address empty and \"Coupon not valid\" at the top.","ar":"في صفحة الدفع بمتجري الإلكتروني، كتبت سحر عنوانها والكوبون «EID25». وهذا الكوبون للطلبات فوق 500 جنيه، وطلبها 380. فأُعيد تحميل الصفحة والعنوان فارغ، و«كوبون غير صالح» في الأعلى."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"reload","options":[{"id":"reload","text":{"en":"Keep it: reload the page with the message at the top","ar":"أبقِه: أعد تحميل الصفحة والرسالة في الأعلى"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"Coupon not valid.","ar":"كوبون غير صالح."}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Coupon","ar":"الكوبون"},"text":"","gap":"s"}]}},{"id":"clearcode","text":{"en":"Keep the address, clear the coupon, and explain","ar":"احتفظ بالعنوان، وامسح الكوبون، واشرح"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"7 Tahrir St, Dokki, Giza","ar":"7 شارع التحرير، الدقي، الجيزة"}},{"kind":"field","label":{"en":"Coupon","ar":"الكوبون"},"text":"","tone":"bad","error":{"en":"⚠ EID25 works on orders over 500 EGP. Your order is 380 EGP.","ar":"⚠ الكوبون EID25 يعمل على الطلبات فوق 500 جنيه. وطلبك 380 جنيه."},"gap":"s"}]}},{"id":"keepboth","text":{"en":"Keep the address and the coupon, and explain on the coupon field","ar":"احتفظ بالعنوان والكوبون، واشرح على حقل الكوبون"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"7 Tahrir St, Dokki, Giza","ar":"7 شارع التحرير، الدقي، الجيزة"}},{"kind":"field","label":{"en":"Coupon","ar":"الكوبون"},"filled":true,"text":"EID25","tone":"bad","error":{"en":"⚠ EID25 works on orders over 500 EGP. Your order is 380 EGP.","ar":"⚠ الكوبون EID25 يعمل على الطلبات فوق 500 جنيه. وطلبك 380 جنيه."},"gap":"s"}]}}],"answer":["keepboth"],"misconceptions":[{"id":"MC-P01-051","when":["reload"],"feedback":{"en":"Sahar loses her address over a coupon, and \"not valid\" doesn't say why. Many shoppers would leave right here.","ar":"تفقد سحر عنوانها بسبب كوبون، و«غير صالح» لا تقول لماذا. وكثير من المتسوّقين سيغادرون هنا تحديدًا."}},{"id":"MC-P01-051","when":["clearcode"],"feedback":{"en":"Close. But if she adds items to pass 500, she has to remember and retype the code. Keep it, so it can work as soon as her order qualifies.","ar":"قريب. لكن إن أضافت منتجات لتتجاوز 500، فعليها أن تتذكّر الكود وتكتبه من جديد. احتفظ به، ليعمل بمجرّد أن يستوفي طلبها الشرط."}}],"correct":{"en":"Everything stays, and the message says exactly why the coupon didn't apply.","ar":"كل شيء يبقى، والرسالة تقول بالضبط لماذا لم يُطبَّق الكوبون."},"explain":{"en":"Keep every answer, right or wrong. The wrong one, kept and explained, is the fastest thing to fix.","ar":"احتفظ بكل إجابة، صحيحة أو خاطئة. والإجابة الخاطئة، حين تُحفظ وتُشرح، هي الأسرع في الإصلاح."}},{"id":"S09","type":"card","part":"recap","icons":["clock","ok","eye","list"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Not while typing:** stopped the email and password errors from appearing after the first letters.\n- **When the field is done:** checked on leaving the field, so the child's age was caught before 7 more fields.\n- **Rule first, error later:** showed the password rule up front and the error only when it was still short.\n- **Nothing lost:** kept every answer after an error, even the wrong mobile number, the long text and the coupon.\n\nNext: the skill check for this unit.","ar":"- **ليس أثناء الكتابة:** أوقفت ظهور أخطاء البريد وكلمة المرور بعد الأحرف الأولى.\n- **حين ينتهي الحقل:** تحقّقت عند مغادرة الحقل، فاكتُشفت مشكلة عمر الطفل قبل 7 حقول أخرى.\n- **القاعدة أولًا، والخطأ لاحقًا:** عرضت قاعدة كلمة المرور مسبقًا، والخطأ فقط حين بقيت قصيرة.\n- **لا شيء يضيع:** احتفظت بكل إجابة بعد الخطأ، حتى رقم الموبايل الخاطئ والنص الطويل والكوبون.\n\nالتالي: اختبار المهارة لهذه الوحدة."}}]}$uxg$::jsonb),
  ($uxg$P01-U04-L04$uxg$, $uxg$8a82844653fabd1905d52c1bfc93c70e780fb6865e30c0929ef1fc07b35b5a11$uxg$, $uxg${"id":"P01-U04-L04","mode":"check","minutes":7,"title":{"en":"Skill check: errors people can fix","ar":"اختبار المهارة: أخطاء يستطيع الناس إصلاحها"},"speaker":"tarek","steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Ola renews her car licence","ar":"علا تجدّد رخصة سيارتها"},"body":{"en":"I'm the product manager for a service that renews car licences online. Ola tried it last night. Her renewal failed three times, and each time the error was harder to understand than the last. She drove to the traffic office the next morning.\n\nYour job: fix the errors on each screen so Ola can finish at home.\n\nThis is a skill check: no hints, and you'll see how you did at the end.","ar":"أنا مدير المنتج لخدمة تجديد رخص السيارات عبر الإنترنت. جرّبتها علا ليلة أمس. فشل التجديد ثلاث مرات، وكل مرة كان الخطأ أصعب في الفهم من سابقه. فذهبت بسيارتها إلى إدارة المرور صباح اليوم التالي.\n\nمهمّتك: أصلح الأخطاء في كل شاشة لتُنهي علا التجديد من البيت.\n\nهذا اختبار مهارة: بدون تلميحات، وسترى نتيجتك في النهاية."},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"ERR_VAL_09: Please check the highlighted fields.","ar":"ERR_VAL_09: يُرجى مراجعة الحقول المحدّدة."}},{"kind":"field","label":{"en":"National ID","ar":"الرقم القومي"},"filled":true,"text":"⁦2950 3120 1044 5⁩","tone":"bad","gap":"m"},{"kind":"field","label":{"en":"Plate number","ar":"رقم اللوحة"},"filled":true,"text":{"en":"ABC 4521","ar":"أ ب ج 4521"},"gap":"s"},{"kind":"button","text":{"en":"Renew licence","ar":"جدّد الرخصة"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U04-01","part":"check","rules":["R19"],"value":{"en":"Skill check, error messages (NN/g): display the error close to its source. The national ID problem should be explained on the national ID field.","ar":"اختبار مهارة، رسائل الخطأ (NN/g): اعرض الخطأ قريبًا من مصدره. ومشكلة الرقم القومي يجب أن تُشرح على حقل الرقم القومي."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Display the error message close to the error's source."},"scenario":{"en":"Ola's national ID has 13 digits; it needs 14. Right now the only message is a line at the top of the page.","ar":"الرقم القومي الذي كتبته علا فيه 13 رقمًا؛ ويحتاج 14. والرسالة الوحيدة الآن سطر في أعلى الصفحة."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"top","options":[{"id":"top","text":{"en":"Keep the message at the top, and name the field","ar":"أبقِ الرسالة في الأعلى، واذكر الحقل"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"National ID needs 14 digits.","ar":"الرقم القومي يحتاج 14 رقمًا."}},{"kind":"field","label":{"en":"National ID","ar":"الرقم القومي"},"filled":true,"text":"⁦2950 3120 1044 5⁩","gap":"m"},{"kind":"field","label":{"en":"Plate number","ar":"رقم اللوحة"},"filled":true,"text":{"en":"ABC 4521","ar":"أ ب ج 4521"},"gap":"s"}]}},{"id":"inline","text":{"en":"Put the message under the national ID field","ar":"ضع الرسالة تحت حقل الرقم القومي"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"National ID","ar":"الرقم القومي"},"filled":true,"text":"⁦2950 3120 1044 5⁩","tone":"bad","error":{"en":"⚠ National ID needs 14 digits. This one has 13.","ar":"⚠ الرقم القومي يحتاج 14 رقمًا. هذا الرقم فيه 13."}},{"kind":"field","label":{"en":"Plate number","ar":"رقم اللوحة"},"filled":true,"text":{"en":"ABC 4521","ar":"أ ب ج 4521"},"gap":"s"}]}},{"id":"dialog","text":{"en":"Show the message in a pop-up she has to close","ar":"اعرض الرسالة في نافذة منبثقة يجب أن تغلقها"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"After she closes the pop-up:","ar":"بعد أن تغلق النافذة المنبثقة:"}},{"kind":"field","label":{"en":"National ID","ar":"الرقم القومي"},"filled":true,"text":"⁦2950 3120 1044 5⁩","gap":"s"},{"kind":"field","label":{"en":"Plate number","ar":"رقم اللوحة"},"filled":true,"text":{"en":"ABC 4521","ar":"أ ب ج 4521"},"gap":"s"}]}}],"answer":["inline"],"misconceptions":[{"id":"MC-P01-044","when":["top","dialog"],"feedback":{"en":"Ola has to carry the message from where she read it to the field, and remember it while she counts digits. Put it on the field.","ar":"على علا أن تنقل الرسالة من حيث قرأتها إلى الحقل، وأن تتذكّرها وهي تعدّ الأرقام. ضعها على الحقل."}}],"explain":{"en":"From Lesson 1: the message belongs where the fixing happens, right under the field, and it stays there until the problem is gone.","ar":"من الدرس 1: مكان الرسالة حيث يحدث الإصلاح، تحت الحقل مباشرة، وتبقى هناك حتى تزول المشكلة."},"speaker":"tarek"},{"id":"S03","type":"tune","skill":"SK-P01-U04-06","part":"check","rules":["R19"],"value":{"en":"Skill check, form usability (NN/g): errors should be signaled through several cues, not only color. A red border by itself doesn't say there's an error, or what it is.","ar":"اختبار مهارة، سهولة استخدام النماذج (NN/g): يجب إظهار الأخطاء بعدّة إشارات، لا باللون وحده. والإطار الأحمر وحده لا يقول إن هناك خطأ، ولا ما هو."},"ref":{"url":"https://www.nngroup.com/articles/web-form-design/","quote":"Errors should be signaled through a variety of cues, not solely through color:"},"scenario":{"en":"On the car details screen, the insurance expiry date is in the past. We only turn the field's border red.","ar":"في شاشة بيانات السيارة، تاريخ انتهاء التأمين في الماضي. ونكتفي بتحويل إطار الحقل إلى الأحمر."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"red","options":[{"id":"words","text":{"en":"Add an icon and a message under the field","ar":"أضف أيقونة ورسالة تحت الحقل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Insurance valid until","ar":"التأمين ساري حتى"},"filled":true,"text":"15/10/2026","tone":"bad","error":{"en":"⚠ This insurance ended on 15 October. Renew it first, then come back.","ar":"⚠ انتهى هذا التأمين يوم 15 أكتوبر. جدّديه أولًا، ثم عودي."}}]}},{"id":"red","text":{"en":"Keep the red border only","ar":"أبقِ الإطار الأحمر فقط"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Insurance valid until","ar":"التأمين ساري حتى"},"filled":true,"text":"15/10/2026","tone":"bad"}]}},{"id":"label","text":{"en":"Turn the label red as well","ar":"حوّل العنوان إلى الأحمر أيضًا"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","color":"red","text":{"en":"Insurance valid until","ar":"التأمين ساري حتى"}},{"kind":"field","filled":true,"text":"15/10/2026","tone":"bad","gap":"xs"}]}}],"answer":["words"],"misconceptions":[{"id":"MC-P01-045","when":["red","label"],"feedback":{"en":"More red is still only color. Someone who doesn't see red well sees nothing, and nobody learns that the insurance ended.","ar":"زيادة الأحمر تظل لونًا فقط. ومن لا يرى الأحمر جيدًا لا يرى شيئًا، ولا أحد يعرف أن التأمين انتهى."}}],"explain":{"en":"From Lesson 1: color plus an icon plus words. The words carry the meaning for everyone.","ar":"من الدرس 1: لون وأيقونة وكلمات. والكلمات تحمل المعنى للجميع."},"speaker":"tarek"},{"id":"S04","type":"tune","skill":"SK-P01-U04-07","part":"check","rules":["R19"],"value":{"en":"Skill check, form errors (NN/g): a summary gives a global understanding of all the errors in a form. On a long form, list them at the top and keep each one on its field.","ar":"اختبار مهارة، أخطاء النماذج (NN/g): الملخّص يعطي صورة شاملة عن كل أخطاء النموذج. وفي النموذج الطويل، اعرضها في قائمة بالأعلى وأبقِ كل خطأ على حقله."},"ref":{"url":"https://www.nngroup.com/articles/errors-forms-design-guidelines/","quote":"A validation summary can give the user a global understanding of all the errors in a form"},"scenario":{"en":"The full renewal form has 16 fields. After Ola taps Renew, two fields have problems: Engine number near the top, and Delivery address near the bottom.","ar":"نموذج التجديد الكامل فيه 16 حقلًا. وبعد أن تضغط علا «جدّد»، يكون في حقلين مشكلة: رقم المحرّك قرب الأعلى، وعنوان التوصيل قرب الأسفل."},"prompt":{"en":"Try each version of the top of the page after Renew. Which one should ship?","ar":"جرّب كل نسخة من أعلى الصفحة بعد «جدّد». أيّها يجب أن تُطلق؟"},"start":"general","options":[{"id":"general","text":{"en":"\"There are errors in the form\" at the top, fields marked","ar":"«يوجد أخطاء في النموذج» بالأعلى، مع تعليم الحقول"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"There are errors in the form.","ar":"يوجد أخطاء في النموذج."}},{"kind":"field","label":{"en":"Engine number","ar":"رقم المحرّك"},"filled":true,"text":"E8-1132","tone":"bad","error":{"en":"⚠ Engine numbers have 8 characters, like EA8-11320. Copy it from your licence card.","ar":"⚠ رقم المحرّك 8 خانات، مثل EA8-11320. انسخه من كارت الرخصة."},"gap":"m"},{"kind":"small","color":"muted","text":{"en":"13 more fields below","ar":"13 حقلًا آخر بالأسفل"},"gap":"s"}]}},{"id":"inline","text":{"en":"No summary; mark each field","ar":"بلا ملخّص؛ علّم كل حقل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Engine number","ar":"رقم المحرّك"},"filled":true,"text":"E8-1132","tone":"bad","error":{"en":"⚠ Engine numbers have 8 characters, like EA8-11320. Copy it from your licence card.","ar":"⚠ رقم المحرّك 8 خانات، مثل EA8-11320. انسخه من كارت الرخصة."}},{"kind":"small","color":"muted","text":{"en":"13 more fields below","ar":"13 حقلًا آخر بالأسفل"},"gap":"s"}]}},{"id":"listed","text":{"en":"List both fields at the top, and mark each field","ar":"اذكر الحقلين في قائمة بالأعلى، وعلّم كل حقل"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"2 answers need a fix: Engine number, Delivery address.","ar":"إجابتان تحتاجان إصلاحًا: رقم المحرّك، عنوان التوصيل."}},{"kind":"field","label":{"en":"Engine number","ar":"رقم المحرّك"},"filled":true,"text":"E8-1132","tone":"bad","error":{"en":"⚠ Engine numbers have 8 characters, like EA8-11320. Copy it from your licence card.","ar":"⚠ رقم المحرّك 8 خانات، مثل EA8-11320. انسخه من كارت الرخصة."},"gap":"m"},{"kind":"small","color":"muted","text":{"en":"13 more fields below","ar":"13 حقلًا آخر بالأسفل"},"gap":"s"}]}}],"answer":["listed"],"misconceptions":[{"id":"MC-P01-046","when":["general"],"feedback":{"en":"\"There are errors\" doesn't say how many or where. Ola fixes the engine number and thinks she's done, while the address waits 13 fields below.","ar":"«يوجد أخطاء» لا تقول كم ولا أين. فتُصلح علا رقم المحرّك وتظن أنها انتهت، بينما ينتظرها العنوان بعد 13 حقلًا."}},{"id":"MC-P01-046","when":["inline"],"feedback":{"en":"Ola only sees the engine number on screen. Nothing tells her a second problem is waiting further down.","ar":"لا ترى علا على الشاشة إلا رقم المحرّك. ولا شيء يخبرها أن مشكلة ثانية تنتظرها في الأسفل."}}],"explain":{"en":"From Lesson 1: on long forms, a summary that names the fields is a to-do list, and the message on each field helps with the fix.","ar":"من الدرس 1: في النماذج الطويلة، الملخّص الذي يذكر الحقول قائمة مهام، والرسالة على كل حقل تساعد في الإصلاح."},"speaker":"tarek"},{"id":"S05","type":"tune","skill":"SK-P01-U04-02","part":"check","rules":["R19"],"value":{"en":"Skill check, error messages (NN/g): hide obscure error codes from people and keep them for diagnosis. Ola needs the reason and the fix in her words.","ar":"اختبار مهارة، رسائل الخطأ (NN/g): أخفِ أكواد الخطأ الغامضة عن الناس واحتفظ بها للتشخيص. وعلا تحتاج السبب والإصلاح بكلماتها."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Hide or minimize the use of obscure error codes or abbreviations; show them for technical diagnostic purposes only."},"scenario":{"en":"Our system can't find Ola's plate. She typed the letters in a different order than on her plate. Right now the field says \"ERR_PLATE_404\".","ar":"نظامنا لا يجد لوحة سيارة علا. فقد كتبت الحروف بترتيب مختلف عن اللوحة. والحقل الآن يقول «ERR_PLATE_404»."},"prompt":{"en":"Try each message. Which one should ship?","ar":"جرّب كل رسالة. أيّها يجب أن تُطلق؟"},"start":"code","options":[{"id":"code","text":{"en":"Keep \"ERR_PLATE_404\"","ar":"أبقِ «ERR_PLATE_404»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Plate number","ar":"رقم اللوحة"},"filled":true,"text":{"en":"BAC 4521","ar":"ب أ ج 4521"},"tone":"bad","error":{"en":"⚠ ERR_PLATE_404","ar":"⚠ ERR_PLATE_404"}}]}},{"id":"notfound","text":{"en":"\"Plate not found.\"","ar":"«اللوحة غير موجودة.»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Plate number","ar":"رقم اللوحة"},"filled":true,"text":{"en":"BAC 4521","ar":"ب أ ج 4521"},"tone":"bad","error":{"en":"⚠ Plate not found.","ar":"⚠ اللوحة غير موجودة."}}]}},{"id":"fix","text":{"en":"Say no car in her name has this plate, and what to check","ar":"قل إن لا سيارة باسمها تحمل هذه اللوحة، وماذا تراجع"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Plate number","ar":"رقم اللوحة"},"filled":true,"text":{"en":"BAC 4521","ar":"ب أ ج 4521"},"tone":"bad","error":{"en":"⚠ No car in your name has plate BAC 4521. Check the letters and their order on your licence card.","ar":"⚠ لا توجد سيارة باسمك تحمل اللوحة ب أ ج 4521. راجعي الحروف وترتيبها في كارت الرخصة."}}]}}],"answer":["fix"],"misconceptions":[{"id":"MC-P01-048","when":["code"],"feedback":{"en":"A code means nothing to Ola. Our team can log it; the screen should say what happened and what to do.","ar":"الكود لا يعني شيئًا لعلا. يستطيع فريقنا تسجيله؛ أما الشاشة فيجب أن تقول ماذا حدث وماذا تفعل."}},{"id":"MC-P01-047","when":["notfound"],"feedback":{"en":"Plain words, but no way forward. Ola knows her plate exists. Tell her what to check.","ar":"كلمات بسيطة، لكن بلا طريق للمتابعة. علا تعرف أن لوحتها موجودة. أخبرها بما تراجعه."}}],"explain":{"en":"From Lesson 2: plain words for what happened, and the next step. Codes stay in the logs.","ar":"من الدرس 2: كلمات بسيطة لما حدث، والخطوة التالية. والأكواد تبقى في السجلّات."},"speaker":"tarek"},{"id":"S06","type":"tune","skill":"SK-P01-U04-03","part":"check","rules":["R19"],"value":{"en":"Skill check, error messages (NN/g): don't use phrasing that blames users. Describe the fines, not Ola's failure to pay them.","ar":"اختبار مهارة، رسائل الخطأ (NN/g): لا تستخدم صياغة تلوم المستخدم. صِف المخالفات، لا تقصير علا في دفعها."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Don't use phrasing that blames users or implies they are doing something wrong"},"scenario":{"en":"Ola's car has two unpaid traffic fines, 350 EGP in total. A licence can't be renewed until they're paid. She didn't know about them.","ar":"على سيارة علا مخالفتان مروريتان غير مدفوعتين، مجموعهما 350 جنيهًا. ولا يمكن تجديد الرخصة حتى تُدفعا. ولم تكن تعرف بهما."},"prompt":{"en":"Try each message. Which one should ship?","ar":"جرّب كل رسالة. أيّها يجب أن تُطلق؟"},"start":"failed","options":[{"id":"failed","text":{"en":"\"You failed to pay your fines. You cannot renew.\"","ar":"«لم تدفعي مخالفاتك. لا يمكنك التجديد.»"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"You failed to pay your fines. You cannot renew.","ar":"لم تدفعي مخالفاتك. لا يمكنك التجديد."}},{"kind":"button","tone":"off","text":{"en":"Renew licence","ar":"جدّد الرخصة"},"gap":"m"}]}},{"id":"warning","text":{"en":"\"Warning: violations on record. Renewal blocked.\"","ar":"«تحذير: مخالفات مسجّلة. التجديد موقوف.»"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"Warning: violations on record. Renewal blocked.","ar":"تحذير: مخالفات مسجّلة. التجديد موقوف."}},{"kind":"button","tone":"off","text":{"en":"Renew licence","ar":"جدّد الرخصة"},"gap":"m"}]}},{"id":"neutral","text":{"en":"\"This car has 2 unpaid fines (350 EGP). Pay them here, then renew.\"","ar":"«على هذه السيارة مخالفتان غير مدفوعتين (350 جنيهًا). ادفعيهما هنا، ثم جدّدي.»"},"mock":{"width":300,"blocks":[{"kind":"banner","tone":"bad","text":{"en":"This car has 2 unpaid fines (350 EGP). Pay them here, then renew.","ar":"على هذه السيارة مخالفتان غير مدفوعتين (350 جنيهًا). ادفعيهما هنا، ثم جدّدي."}},{"kind":"button","text":{"en":"Pay 350 EGP","ar":"ادفعي 350 جنيهًا"},"gap":"m"}]}}],"answer":["neutral"],"misconceptions":[{"id":"MC-P01-049","when":["failed","warning"],"feedback":{"en":"\"You failed\" accuses her, and \"Warning: violations\" sounds like a police notice. Neither says how much or how to pay. Describe the fines and offer the next step.","ar":"«لم تدفعي» تتّهمها، و«تحذير: مخالفات» تبدو كإنذار من الشرطة. ولا تقول أيٌّ منهما كم المبلغ ولا كيف تدفع. صِف المخالفات واعرض الخطوة التالية."}}],"explain":{"en":"From Lesson 2: make the thing the subject (\"This car has 2 unpaid fines\"), not the person, and end with what they can do.","ar":"من الدرس 2: اجعل الشيء فاعل الجملة («على هذه السيارة مخالفتان»)، لا الشخص، واختم بما يستطيع فعله."},"speaker":"tarek"},{"id":"S07","type":"tune","skill":"SK-P01-U04-04","part":"check","rules":["R19"],"value":{"en":"Skill check, form errors (NN/g): avoid showing an error until the person has finished with the field and moved to the next one.","ar":"اختبار مهارة، أخطاء النماذج (NN/g): تجنّب عرض الخطأ حتى ينتهي الشخص من الحقل وينتقل إلى التالي."},"ref":{"url":"https://www.nngroup.com/articles/errors-forms-design-guidelines/","quote":"In most cases, avoid showing an error until the user has finished with the field and moved to the next field."},"scenario":{"en":"The mobile number field shows \"Invalid number\" in red from the first digit Ola types until the eleventh.","ar":"حقل رقم الموبايل يعرض «رقم غير صالح» بالأحمر من أول رقم تكتبه علا حتى الحادي عشر."},"prompt":{"en":"Try each timing. Each preview shows two moments. Which one should ship?","ar":"جرّب كل توقيت. كل معاينة تُظهر لحظتين. أيّها يجب أن يُطلق؟"},"start":"typing","options":[{"id":"typing","text":{"en":"Keep checking with every digit","ar":"أبقِ التحقّق مع كل رقم"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"After 4 digits","ar":"بعد 4 أرقام"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"focus":true,"text":"⁦0100⁩","tone":"bad","error":{"en":"⚠ Mobile numbers have 11 digits, starting with 01.","ar":"⚠ أرقام الموبايل 11 رقمًا، تبدأ بـ 01."},"gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After she moves on with 10 digits","ar":"بعد أن تنتقل وفيه 10 أرقام"},"gap":"l"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0100 123 456⁩","tone":"bad","error":{"en":"⚠ Mobile numbers have 11 digits, starting with 01.","ar":"⚠ أرقام الموبايل 11 رقمًا، تبدأ بـ 01."},"gap":"xs"}]}},{"id":"leave","text":{"en":"Check when she leaves the field","ar":"تحقّق حين تغادر الحقل"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"After 4 digits","ar":"بعد 4 أرقام"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"focus":true,"text":"⁦0100⁩","gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After she moves on with 10 digits","ar":"بعد أن تنتقل وفيه 10 أرقام"},"gap":"l"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0100 123 456⁩","tone":"bad","error":{"en":"⚠ Mobile numbers have 11 digits, starting with 01.","ar":"⚠ أرقام الموبايل 11 رقمًا، تبدأ بـ 01."},"gap":"xs"}]}},{"id":"end","text":{"en":"Check only when she taps Renew","ar":"تحقّق فقط حين تضغط «جدّد»"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"After 4 digits","ar":"بعد 4 أرقام"}},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"focus":true,"text":"⁦0100⁩","gap":"xs"},{"kind":"small","color":"muted","text":{"en":"After she moves on with 10 digits","ar":"بعد أن تنتقل وفيه 10 أرقام"},"gap":"l"},{"kind":"field","label":{"en":"Mobile number","ar":"رقم الموبايل"},"filled":true,"text":"⁦0100 123 456⁩","gap":"xs"}]}}],"answer":["leave"],"misconceptions":[{"id":"MC-P01-050","when":["typing"],"feedback":{"en":"Four digits in, Ola is still typing. Red now only scolds her for not being finished.","ar":"بعد أربعة أرقام، ما زالت علا تكتب. والأحمر الآن يوبّخها فقط لأنها لم تنتهِ."}},{"id":"MC-P01-050","when":["end"],"feedback":{"en":"She moved on with a missing digit, and nothing says so until the very end. Check when she leaves the field.","ar":"انتقلت وينقصها رقم، ولا شيء يقول ذلك حتى النهاية. تحقّق حين تغادر الحقل."}}],"explain":{"en":"From Lesson 3: leaving a field means \"done\". Check then: not during typing, and not at the very end.","ar":"من الدرس 3: مغادرة الحقل تعني «انتهيت». تحقّق حينها: لا أثناء الكتابة، ولا في النهاية تمامًا."},"speaker":"tarek"},{"id":"S08","type":"tune","skill":"SK-P01-U04-05","part":"check","rules":["R19"],"value":{"en":"Skill check, error messages (NN/g): let users correct errors by editing what they did, instead of starting over. A declined card shouldn't erase the delivery details.","ar":"اختبار مهارة، رسائل الخطأ (NN/g): دع المستخدم يُصلح الخطأ بتعديل ما فعله، بدل البدء من جديد. والبطاقة المرفوضة يجب ألّا تمسح بيانات التوصيل."},"ref":{"url":"https://www.nngroup.com/articles/error-message-guidelines/","quote":"Let users correct errors by editing their original action instead of starting over."},"scenario":{"en":"Last step: Ola picks home delivery of the new licence, types her address, and pays. Her card is declined. Right now the page goes back to step 1, with everything empty.","ar":"الخطوة الأخيرة: تختار علا توصيل الرخصة الجديدة إلى البيت، وتكتب عنوانها، وتدفع. فتُرفض بطاقتها. والآن تعود الصفحة إلى الخطوة 1، وكل شيء فارغ."},"prompt":{"en":"Try each version of what Ola sees after the card is declined. Which one should ship?","ar":"جرّب كل نسخة لما تراه علا بعد رفض البطاقة. أيّها يجب أن تُطلق؟"},"start":"restart","options":[{"id":"restart","text":{"en":"Keep it: back to step 1, everything empty","ar":"أبقِه: العودة إلى الخطوة 1، وكل شيء فارغ"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"Step 1 of 4","ar":"الخطوة 1 من 4"}},{"kind":"field","label":{"en":"National ID","ar":"الرقم القومي"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Plate number","ar":"رقم اللوحة"},"text":"","gap":"s"}]}},{"id":"stay","text":{"en":"Stay on payment, keep everything, and explain","ar":"ابقَ في الدفع، واحتفظ بكل شيء، واشرح"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"Step 4 of 4","ar":"الخطوة 4 من 4"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"filled":true,"text":{"en":"22 Gamal Abdel Nasser St, Alexandria","ar":"22 شارع جمال عبد الناصر، الإسكندرية"},"gap":"s"},{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"filled":true,"text":"⁦5236 •••• •••• 4410⁩","tone":"bad","error":{"en":"⚠ Your bank declined this card. Try another card, or pay in cash at any traffic office.","ar":"⚠ رفض بنكك هذه البطاقة. جرّبي بطاقة أخرى، أو ادفعي نقدًا في أي إدارة مرور."},"gap":"s"}]}},{"id":"emptypay","text":{"en":"Stay on payment, but clear the address and card","ar":"ابقَ في الدفع، لكن امسح العنوان والبطاقة"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"Step 4 of 4","ar":"الخطوة 4 من 4"}},{"kind":"field","label":{"en":"Delivery address","ar":"عنوان التوصيل"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"text":"","tone":"bad","error":{"en":"⚠ Your bank declined this card. Try another card, or pay in cash at any traffic office.","ar":"⚠ رفض بنكك هذه البطاقة. جرّبي بطاقة أخرى، أو ادفعي نقدًا في أي إدارة مرور."},"gap":"s"}]}}],"answer":["stay"],"misconceptions":[{"id":"MC-P01-051","when":["restart","emptypay"],"feedback":{"en":"Only the card failed. Making Ola retype her address, or all four steps, punishes her for her bank's answer. Keep everything and let her change the card.","ar":"البطاقة وحدها فشلت. وإجبار علا على إعادة كتابة عنوانها، أو الخطوات الأربع كلها، يعاقبها على رد بنكها. احتفظ بكل شيء ودعها تغيّر البطاقة."}}],"explain":{"en":"From Lesson 3: an error should cost one fix. Keep every answer, and let people change only what went wrong.","ar":"من الدرس 3: الخطأ يجب أن يكلّف إصلاحًا واحدًا. احتفظ بكل إجابة، ودع الناس يغيّرون فقط ما حدث فيه الخطأ."},"speaker":"tarek"}]}$uxg$::jsonb),
  ($uxg$P01-U05-L01$uxg$, $uxg$2843bcb9febe165f25d77f33d5f414c12ee6fef8ccdd8c644e5a94a7292841cb$uxg$, $uxg${"id":"P01-U05-L01","mode":"lesson","minutes":8,"title":{"en":"A form you can finish without a mouse","ar":"نموذج تُكمله بلا ماوس"},"speaker":"karim","review_labels":{"MC-P01-052":{"en":"Never remove the focus ring","ar":"لا تحذف إطار التركيز أبدًا"},"MC-P01-053":{"en":"Tab order follows the layout","ar":"ترتيب Tab يتبع ترتيب الصفحة"},"MC-P01-054":{"en":"Every control must be reachable by keyboard","ar":"كل عنصر يجب أن يمكن الوصول إليه بلوحة المفاتيح"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Nabil and the Tab key","ar":"نبيل وزر Tab"},"body":{"en":"I built a booking form for a travel agency. Nabil has a hand tremor, so he uses the keyboard instead of a mouse: Tab to move, Enter to press.\n\nOn our form, he pressed Tab and couldn't see where he was. Then Tab jumped from his name straight to the Pay button. He booked by phone instead.","ar":"بنيت نموذج حجز لوكالة سفر. نبيل عنده رعشة في يده، فيستخدم لوحة المفاتيح بدل الماوس: Tab للتنقّل، وEnter للضغط.\n\nفي نموذجنا، ضغط Tab ولم يستطع أن يرى أين هو. ثم قفز Tab من اسمه مباشرة إلى زر الدفع. فحجز بالهاتف بدلًا من ذلك."},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Nabil Saad","ar":"نبيل سعد"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Travel date","ar":"تاريخ السفر"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Pay","ar":"ادفع"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U05-01","part":"try","rules":["R12"],"value":{"en":"Try first. Keyboard accessibility (NN/g): removing the keyboard focus indicator is catastrophic for keyboard users. Without it, Nabil can't tell which field he's in.","ar":"جرّب أولًا. الإتاحة بلوحة المفاتيح (NN/g): حذف مؤشّر التركيز كارثة لمستخدمي لوحة المفاتيح. وبدونه، لا يعرف نبيل في أي حقل هو."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"Removing the keyboard focus indicator is catastrophic for keyboard users."},"scenario":{"en":"Our designer removed the focus ring because \"it looked messy\". Nabil has pressed Tab twice, so he's in the Email field.","ar":"حذف مصمّمنا إطار التركيز لأنه «بدا غير مرتّب». وضغط نبيل Tab مرتين، فهو الآن في حقل البريد."},"prompt":{"en":"Try each version of what Nabil sees. Which one should ship?","ar":"جرّب كل نسخة لما يراه نبيل. أيّها يجب أن تُطلق؟"},"start":"none","options":[{"id":"none","text":{"en":"Keep it: no focus ring","ar":"أبقِه: بلا إطار تركيز"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Nabil Saad","ar":"نبيل سعد"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Travel date","ar":"تاريخ السفر"},"text":"","gap":"s"}]}},{"id":"ring","text":{"en":"Bring back a clear focus ring","ar":"أعِد إطار تركيز واضحًا"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Nabil Saad","ar":"نبيل سعد"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","focus":true,"gap":"s"},{"kind":"field","label":{"en":"Travel date","ar":"تاريخ السفر"},"text":"","gap":"s"}]}},{"id":"label","text":{"en":"No ring; make the focused field's label purple","ar":"بلا إطار؛ اجعل عنوان الحقل المُركَّز عليه بنفسجيًا"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Nabil Saad","ar":"نبيل سعد"}},{"kind":"small","weight":"bold","color":"brand","text":{"en":"Email","ar":"البريد الإلكتروني"},"gap":"s"},{"kind":"field","text":"","gap":"xs"},{"kind":"field","label":{"en":"Travel date","ar":"تاريخ السفر"},"text":"","gap":"s"}]}}],"answer":["ring"],"misconceptions":[{"id":"MC-P01-052","when":["none"],"feedback":{"en":"Look at the preview: which field is Nabil in? Nothing says. He'd have to type and see where the letters land.","ar":"انظر إلى المعاينة: في أي حقل نبيل؟ لا شيء يقول. سيضطر أن يكتب ويرى أين تظهر الحروف."}},{"id":"MC-P01-052","when":["label"],"feedback":{"en":"A slightly different label color is hard to spot, and gone for people who don't see purple well. A ring around the field is obvious.","ar":"لون العنوان المختلف قليلًا صعب الملاحظة، ولا يراه من لا يميّز البنفسجي جيدًا. أما الإطار حول الحقل فواضح."}}],"hints":[{"en":"Cover the scenario. Can you tell from the preview where Nabil is?","ar":"تجاهل الوصف. هل تعرف من المعاينة أين نبيل؟"},{"en":"Which version marks the field itself, in a way you can't miss?","ar":"أي نسخة تعلّم الحقل نفسه، بطريقة لا تفوتك؟"}],"correct":{"en":"The ring shows Nabil exactly where he is.","ar":"الإطار يُظهر لنبيل أين هو بالضبط."},"explain":{"en":"For keyboard users, the focus ring is the mouse pointer. Remove it and they're lost. Style it to fit the brand if you like, but keep it clear.","ar":"بالنسبة إلى مستخدمي لوحة المفاتيح، إطار التركيز هو مؤشّر الماوس. احذفه فيضيعون. يمكنك تصميمه ليناسب هوية المنتج، لكن أبقِه واضحًا."},"speaker":"karim"},{"id":"S03","type":"card","part":"concept","icons":["eye","order","tap","ok"],"title":{"en":"Some people never touch a mouse","ar":"بعض الناس لا يلمسون الماوس أبدًا"},"body":{"en":"People with a tremor, people who are blind, and fast typists move through forms with the keyboard: Tab to the next thing, Shift+Tab back, Enter or Space to press.\n\n- **Focus you can see:** the thing Tab is on needs a clear ring. Never remove it.\n- **Order that matches the page:** Tab should move the way people read the form, top to bottom.\n- **Everything reachable:** every button, link and field must be on the Tab path.\n- **Pop-ups that close:** Esc and a Close button must work, or people get stuck.","ar":"أصحاب الرعشة، والمكفوفون، ومن يكتبون بسرعة يتنقّلون في النماذج بلوحة المفاتيح: Tab للعنصر التالي، وShift+Tab للرجوع، وEnter أو المسافة للضغط.\n\n- **تركيز ظاهر:** العنصر الذي يقف عنده Tab يحتاج إطارًا واضحًا. لا تحذفه أبدًا.\n- **ترتيب يطابق الصفحة:** يجب أن يتحرّك Tab كما يقرأ الناس النموذج، من أعلى إلى أسفل.\n- **كل شيء في المتناول:** كل زر ورابط وحقل يجب أن يكون في مسار Tab.\n- **نوافذ تُغلق:** يجب أن يعمل Esc وزر الإغلاق، وإلا علق الناس."}},{"id":"S04","type":"tune","skill":"SK-P01-U05-02","part":"guided","rules":["R06","R15"],"value":{"en":"Keyboard accessibility (NN/g): the tab order is normally coded to follow the page layout, top to bottom. When the Pay button comes second, Nabil skips the fields between.","ar":"الإتاحة بلوحة المفاتيح (NN/g): ترتيب Tab يُبرمَج عادةً ليتبع تخطيط الصفحة، من أعلى إلى أسفل. وحين يأتي زر الدفع ثانيًا، يتخطّى نبيل الحقول التي بينهما."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"On most websites the tab order will be coded to reflect the page layout; that is top to bottom and left to right."},"scenario":{"en":"In our code, the Pay button comes right after the name field, because we added it early. On screen it's at the bottom.","ar":"في الكود عندنا، يأتي زر الدفع بعد حقل الاسم مباشرة، لأننا أضفناه مبكّرًا. أما على الشاشة فهو في الأسفل."},"prompt":{"en":"Try each tab order. Which one should ship?","ar":"جرّب كل ترتيب لـ Tab. أيّها يجب أن يُطلق؟"},"start":"code","options":[{"id":"code","text":{"en":"Keep the order of the code","ar":"أبقِ ترتيب الكود"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Nabil Saad","ar":"نبيل سعد"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Travel date","ar":"تاريخ السفر"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Pay","ar":"ادفع"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Full name → Pay → Email → Travel date","ar":"ترتيب Tab: الاسم الكامل ← ادفع ← البريد ← تاريخ السفر"},"gap":"m"}]}},{"id":"page","text":{"en":"Match the page: top to bottom","ar":"طابِق الصفحة: من أعلى إلى أسفل"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Nabil Saad","ar":"نبيل سعد"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Travel date","ar":"تاريخ السفر"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Pay","ar":"ادفع"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Full name → Email → Travel date → Pay","ar":"ترتيب Tab: الاسم الكامل ← البريد ← تاريخ السفر ← ادفع"},"gap":"m"}]}},{"id":"move","text":{"en":"Move Pay up under the name, to match the code","ar":"انقل «ادفع» لأعلى تحت الاسم، ليطابق الكود"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Full name","ar":"الاسم الكامل"},"filled":true,"text":{"en":"Nabil Saad","ar":"نبيل سعد"}},{"kind":"button","text":{"en":"Pay","ar":"ادفع"},"gap":"s"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"m"},{"kind":"field","label":{"en":"Travel date","ar":"تاريخ السفر"},"text":"","gap":"s"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Full name → Pay → Email → Travel date","ar":"ترتيب Tab: الاسم الكامل ← ادفع ← البريد ← تاريخ السفر"},"gap":"m"}]}}],"answer":["page"],"misconceptions":[{"id":"MC-P01-053","when":["code"],"feedback":{"en":"Nabil reads the form top to bottom, but Tab takes him to Pay second. He may pay before filling in his email and date, or think the form is broken.","ar":"يقرأ نبيل النموذج من أعلى إلى أسفل، لكن Tab يأخذه إلى «ادفع» ثانيًا. قد يدفع قبل أن يكتب بريده وتاريخ سفره، أو يظن أن النموذج معطّل."}},{"id":"MC-P01-053","when":["move"],"feedback":{"en":"Now the order matches, but Pay sits above the fields it pays for, for everyone. Fix the order in the code, not the layout.","ar":"الآن الترتيب متطابق، لكن «ادفع» صار فوق الحقول التي يدفع مقابلها، للجميع. أصلح الترتيب في الكود، لا التخطيط."}}],"hints":[{"en":"Read the form with your eyes, then read the Tab line. Do they match?","ar":"اقرأ النموذج بعينيك، ثم اقرأ سطر Tab. هل يتطابقان؟"},{"en":"Which version keeps Pay last on screen and last for Tab?","ar":"أي نسخة تُبقي «ادفع» الأخير على الشاشة والأخير في Tab؟"}],"correct":{"en":"Tab moves the way the form reads.","ar":"Tab يتحرّك كما يُقرأ النموذج."},"explain":{"en":"Keyboard users expect Tab to follow what they see. When the code order and the screen order differ, change the code.","ar":"يتوقّع مستخدمو لوحة المفاتيح أن يتبع Tab ما يرونه. وحين يختلف ترتيب الكود عن ترتيب الشاشة، غيّر الكود."},"speaker":"karim"},{"id":"S05","type":"words","skill":"SK-P01-U05-01","part":"guided","confidence":true,"rules":["R06","R15"],"value":{"en":"Keyboard accessibility (NN/g): removing the focus indicator is catastrophic for keyboard users. A spec note has to protect the ring on every interactive element.","ar":"الإتاحة بلوحة المفاتيح (NN/g): حذف مؤشّر التركيز كارثة لمستخدمي لوحة المفاتيح. وملاحظة المواصفات يجب أن تحمي الإطار على كل عنصر تفاعلي."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"Removing the keyboard focus indicator is catastrophic for keyboard users."},"scenario":{"en":"I'm writing the handoff notes for the next version, so no one removes the ring again.","ar":"أكتب ملاحظات التسليم للنسخة القادمة، حتى لا يحذف أحد الإطار مرة أخرى."},"prompt":{"en":"Which note should go in the spec?","ar":"أي ملاحظة يجب أن تُكتب في المواصفات؟"},"options":[{"id":"hover","text":{"en":"\"Show a ring when the mouse hovers over a field.\"","ar":"«اعرض إطارًا حين يمرّ الماوس فوق الحقل.»"}},{"id":"first","text":{"en":"\"Show a focus ring on the first field, to start people off.\"","ar":"«اعرض إطار تركيز على الحقل الأول، ليبدأ الناس منه.»"}},{"id":"all","text":{"en":"\"Every field, button and link shows a clear focus ring when Tab reaches it.\"","ar":"«كل حقل وزر ورابط يعرض إطار تركيز واضحًا حين يصل إليه Tab.»"}}],"answer":["all"],"misconceptions":[{"id":"MC-P01-052","when":["hover","first"],"feedback":{"en":"Nabil doesn't hover, and he needs the ring on every stop, not just the first. The ring follows Tab everywhere.","ar":"نبيل لا يستخدم الماوس، ويحتاج الإطار في كل محطة، لا في الأولى فقط. الإطار يتبع Tab في كل مكان."}}],"hints":[{"en":"Which note still helps someone who never uses a mouse?","ar":"أي ملاحظة ما زالت تساعد من لا يستخدم الماوس أبدًا؟"},{"en":"Where does Nabil need to see focus: on one field, or on every stop?","ar":"أين يحتاج نبيل أن يرى التركيز: في حقل واحد، أم في كل محطة؟"}],"correct":{"en":"A ring on every stop Tab makes.","ar":"إطار في كل محطة يقف عندها Tab."},"explain":{"en":"Focus is for the keyboard, not the mouse. Every element Tab can reach needs a ring people can see.","ar":"التركيز للوحة المفاتيح، لا للماوس. وكل عنصر يصل إليه Tab يحتاج إطارًا يراه الناس."},"speaker":"karim"},{"id":"S06","type":"tune","skill":"SK-P01-U05-02","part":"guided","rules":["R06","R15"],"value":{"en":"Keyboard accessibility (NN/g): the tab order should reflect the layout. A promo code field that comes first for Tab but last on screen confuses keyboard users.","ar":"الإتاحة بلوحة المفاتيح (NN/g): ترتيب Tab يجب أن يعكس التخطيط. وحقل كود الخصم الذي يأتي أولًا في Tab وأخيرًا على الشاشة يُربك مستخدمي لوحة المفاتيح."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"On most websites the tab order will be coded to reflect the page layout; that is top to bottom and left to right."},"scenario":{"en":"The agency's payment page has the card fields first and a promo code field at the bottom. Because the promo box is a separate piece of code, Tab lands on it before the card number.","ar":"صفحة الدفع في الوكالة فيها حقول البطاقة أولًا وحقل كود الخصم في الأسفل. ولأن مربع الخصم جزء منفصل من الكود، يصل إليه Tab قبل رقم البطاقة."},"prompt":{"en":"Try each tab order. Which one should ship?","ar":"جرّب كل ترتيب لـ Tab. أيّها يجب أن يُطلق؟"},"start":"promo","options":[{"id":"promo","text":{"en":"Keep it: promo code first","ar":"أبقِه: كود الخصم أولًا"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"text":""},{"kind":"field","label":{"en":"Expiry date","ar":"تاريخ الانتهاء"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code (optional)","ar":"كود الخصم (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Pay 6,400 EGP","ar":"ادفع 6,400 جنيه"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Promo code → Card number → Expiry date → Pay","ar":"ترتيب Tab: كود الخصم ← رقم البطاقة ← تاريخ الانتهاء ← ادفع"},"gap":"m"}]}},{"id":"skip","text":{"en":"Take the promo code out of the Tab order","ar":"أخرج كود الخصم من ترتيب Tab"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"text":""},{"kind":"field","label":{"en":"Expiry date","ar":"تاريخ الانتهاء"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code (optional)","ar":"كود الخصم (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Pay 6,400 EGP","ar":"ادفع 6,400 جنيه"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Card number → Expiry date → Pay","ar":"ترتيب Tab: رقم البطاقة ← تاريخ الانتهاء ← ادفع"},"gap":"m"}]}},{"id":"page","text":{"en":"Card number, expiry, promo code, then Pay","ar":"رقم البطاقة، ثم الانتهاء، ثم كود الخصم، ثم ادفع"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Card number","ar":"رقم البطاقة"},"text":""},{"kind":"field","label":{"en":"Expiry date","ar":"تاريخ الانتهاء"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Promo code (optional)","ar":"كود الخصم (اختياري)"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Pay 6,400 EGP","ar":"ادفع 6,400 جنيه"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Card number → Expiry date → Promo code → Pay","ar":"ترتيب Tab: رقم البطاقة ← تاريخ الانتهاء ← كود الخصم ← ادفع"},"gap":"m"}]}}],"answer":["page"],"misconceptions":[{"id":"MC-P01-053","when":["promo"],"feedback":{"en":"Nabil starts typing his card number and it lands in the promo box. The order has to match what he sees.","ar":"يبدأ نبيل كتابة رقم بطاقته فيظهر في مربع الخصم. والترتيب يجب أن يطابق ما يراه."}},{"id":"MC-P01-054","when":["skip"],"feedback":{"en":"Now the order is right, but Nabil can never reach the promo code, so he pays full price. Keep it in the order, in its place.","ar":"الآن الترتيب صحيح، لكن نبيل لا يستطيع الوصول إلى كود الخصم أبدًا، فيدفع السعر كاملًا. أبقِه في الترتيب، في مكانه."}}],"hints":[{"en":"Does the Tab line match the form from top to bottom?","ar":"هل يطابق سطر Tab النموذج من أعلى إلى أسفل؟"},{"en":"Can Nabil still reach every field?","ar":"هل ما زال نبيل يستطيع الوصول إلى كل حقل؟"}],"correct":{"en":"Same order as the screen, and nothing left out.","ar":"الترتيب نفسه الذي على الشاشة، ولا شيء مُستبعد."},"explain":{"en":"Tab order is a path through the whole form. It follows the layout and includes every control, optional ones too.","ar":"ترتيب Tab مسار عبر النموذج كله. يتبع التخطيط ويشمل كل عنصر، والاختيارية أيضًا."},"speaker":"karim"},{"id":"S07","type":"compare","skill":"SK-P01-U05-01","part":"contrast","rules":["R11","R15"],"value":{"en":"Contrast with S02: both versions here mark focus somehow. Keyboard accessibility (NN/g): losing the focus indicator is catastrophic. A ring on the field works; a small color change elsewhere barely counts.","ar":"مقارنة مع الخطوة 2: النسختان هنا تعلّمان التركيز بطريقة ما. الإتاحة بلوحة المفاتيح (NN/g): فقدان مؤشّر التركيز كارثة. والإطار على الحقل ينجح؛ أما تغيير لون صغير في مكان آخر فبالكاد يُحسب."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"Removing the keyboard focus indicator is catastrophic for keyboard users."},"scenario":{"en":"Two designers sent me focus styles for the agency's search form. In both, Nabil has tabbed to the \"Return date\" field.","ar":"أرسل لي مصمّمان شكلين للتركيز في نموذج البحث بالوكالة. وفي الاثنين، وصل نبيل بـ Tab إلى حقل «تاريخ العودة»."},"prompt":{"en":"Which focus style should ship?","ar":"أي شكل للتركيز يجب أن يُطلق؟"},"a":{"label":{"en":"Label tint","ar":"لون العنوان"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Leaving on","ar":"تاريخ الذهاب"},"filled":true,"text":"12/01/2027"},{"kind":"small","weight":"bold","color":"brand","text":{"en":"Return date","ar":"تاريخ العودة"},"gap":"s"},{"kind":"field","text":"","gap":"xs"}]}},"b":{"label":{"en":"Ring","ar":"إطار"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Leaving on","ar":"تاريخ الذهاب"},"filled":true,"text":"12/01/2027"},{"kind":"field","label":{"en":"Return date","ar":"تاريخ العودة"},"text":"","focus":true,"gap":"s"}]}},"answer":"b","reason":{"prompt":{"en":"What makes B work?","ar":"ما الذي يجعل B ناجحًا؟"},"options":[{"id":"brand","text":{"en":"It uses the brand color","ar":"يستخدم لون الهوية"}},{"id":"obvious","text":{"en":"It marks the field itself, big enough to spot at a glance","ar":"يعلّم الحقل نفسه، بحجم يُلاحَظ بنظرة"}},{"id":"both","text":{"en":"Both are just as clear; it's taste","ar":"الاثنان واضحان بالقدر نفسه؛ إنها مسألة ذوق"}}],"answer":["obvious"],"misconceptions":[{"id":"MC-P01-052","when":["brand","both"],"feedback":{"en":"Both use the same purple. The difference is size and place: a thin color change on the label versus a ring around the field Nabil will type in.","ar":"كلاهما يستخدم البنفسجي نفسه. والفرق في الحجم والمكان: تغيير لون رفيع في العنوان، مقابل إطار حول الحقل الذي سيكتب فيه نبيل."}}]},"misconceptions":[{"id":"MC-P01-052","when":["a"],"feedback":{"en":"Squint at A: the empty box looks like every other box. A label tint is easy to miss, so in practice it works like no focus at all.","ar":"انظر إلى A سريعًا: المربع الفارغ يبدو مثل أي مربع. ولون العنوان يسهل أن يفوت، فهو عمليًا كأنه لا تركيز."}}],"hints":[{"en":"Glance at each for one second. In which one do you know where Nabil is?","ar":"انظر إلى كل واحد ثانية واحدة. في أيّهما تعرف أين نبيل؟"}],"correct":{"en":"A ring around the field is focus you can't miss.","ar":"الإطار حول الحقل تركيز لا يفوتك."},"explain":{"en":"Focus has to be found at a glance. Mark the element itself, with enough contrast and size; small color shifts don't do that.","ar":"التركيز يجب أن يُرى بنظرة. علّم العنصر نفسه، بتباين وحجم كافيين؛ وتغيّرات اللون الصغيرة لا تفعل ذلك."},"speaker":"karim"},{"id":"S08","type":"tune","skill":"SK-P01-U05-02","part":"independent","speaker":"nour","rules":["R14","R19"],"value":{"en":"New case. Keyboard accessibility (NN/g): tab order is coded to reflect the page layout, top to bottom. A form built in a different order than it looks sends keyboard users jumping.","ar":"حالة جديدة. الإتاحة بلوحة المفاتيح (NN/g): ترتيب Tab يُبرمَج ليعكس تخطيط الصفحة، من أعلى إلى أسفل. والنموذج المبني بترتيب مختلف عن شكله يجعل مستخدمي لوحة المفاتيح يقفزون."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"On most websites the tab order will be coded to reflect the page layout; that is top to bottom and left to right."},"scenario":{"en":"Patients book appointments on my clinic's website. Our new developer built the date and time first, then moved the patient's name to the top of the screen. Hoda, who is blind, said Tab \"asks for the time before my name\".","ar":"يحجز المرضى مواعيدهم من موقع عيادتي. وبنى المطوّر الجديد التاريخ والوقت أولًا، ثم نقل اسم المريض إلى أعلى الشاشة. وقالت هدى، وهي كفيفة، إن Tab «يسألني عن الوقت قبل اسمي»."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"built","options":[{"id":"built","text":{"en":"Keep it: the order it was built in","ar":"أبقِه: الترتيب الذي بُني به"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Patient name","ar":"اسم المريض"},"text":""},{"kind":"field","label":{"en":"Day","ar":"اليوم"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Time","ar":"الوقت"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Day → Time → Patient name → Book","ar":"ترتيب Tab: اليوم ← الوقت ← اسم المريض ← احجز"},"gap":"m"}]}},{"id":"note","text":{"en":"Keep the order, and add a note: \"Fill in your name last\"","ar":"أبقِ الترتيب، وأضف ملاحظة: «اكتب اسمك في النهاية»"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"Fill in your name last.","ar":"اكتب اسمك في النهاية."}},{"kind":"field","label":{"en":"Patient name","ar":"اسم المريض"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Day","ar":"اليوم"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Time","ar":"الوقت"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Day → Time → Patient name → Book","ar":"ترتيب Tab: اليوم ← الوقت ← اسم المريض ← احجز"},"gap":"m"}]}},{"id":"page","text":{"en":"Order Tab the way the page reads","ar":"رتّب Tab كما تُقرأ الصفحة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Patient name","ar":"اسم المريض"},"text":""},{"kind":"field","label":{"en":"Day","ar":"اليوم"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Time","ar":"الوقت"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Book","ar":"احجز"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Patient name → Day → Time → Book","ar":"ترتيب Tab: اسم المريض ← اليوم ← الوقت ← احجز"},"gap":"m"}]}}],"answer":["page"],"misconceptions":[{"id":"MC-P01-053","when":["built","note"],"feedback":{"en":"The build order is our history, not Hoda's problem. A note asks her to work around our bug. Fix the order so Tab follows the page.","ar":"ترتيب البناء تاريخنا نحن، لا مشكلة هدى. والملاحظة تطلب منها الالتفاف حول خطئنا. أصلح الترتيب ليتبع Tab الصفحة."}}],"correct":{"en":"Tab and the screen now tell the same story.","ar":"الآن Tab والشاشة يحكيان القصة نفسها."},"explain":{"en":"Whatever order the code was written in, Tab should move the way the form reads. Check it by tabbing through before launch.","ar":"أيًّا كان ترتيب كتابة الكود، يجب أن يتحرّك Tab كما يُقرأ النموذج. اختبره بالتنقّل بـ Tab قبل الإطلاق."}},{"id":"S09","type":"card","part":"recap","icons":["eye","order","tap","ok"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Focus you can see:** brought back a clear ring instead of nothing or a label tint.\n- **A spec that protects it:** asked for a ring on every field, button and link.\n- **Tab follows the page:** fixed the order in the code instead of moving Pay up or adding a note.\n- **Nothing left out:** kept the optional promo code on the Tab path, in its place.\n\nNext: controls that the keyboard can't reach, and pop-ups that trap people.","ar":"- **تركيز ظاهر:** أعدت إطارًا واضحًا بدل لا شيء أو لون العنوان.\n- **مواصفات تحميه:** طلبت إطارًا على كل حقل وزر ورابط.\n- **Tab يتبع الصفحة:** أصلحت الترتيب في الكود بدل نقل «ادفع» لأعلى أو إضافة ملاحظة.\n- **لا شيء مُستبعد:** أبقيت كود الخصم الاختياري في مسار Tab، في مكانه.\n\nالتالي: عناصر لا تصل إليها لوحة المفاتيح، ونوافذ تحبس الناس."}}]}$uxg$::jsonb),
  ($uxg$P01-U05-L02$uxg$, $uxg$4497e488762c5c0e5de0d1ee8875348820120061f7132703914ea48408007355$uxg$, $uxg${"id":"P01-U05-L02","mode":"lesson","minutes":8,"title":{"en":"Every control in reach, every pop-up closable","ar":"كل عنصر في المتناول، وكل نافذة تُغلق"},"speaker":"karim","review_labels":{"MC-P01-054":{"en":"Every control must be reachable by keyboard","ar":"كل عنصر يجب أن يمكن الوصول إليه بلوحة المفاتيح"},"MC-P01-055":{"en":"Pop-ups must close by keyboard","ar":"النوافذ المنبثقة يجب أن تُغلق بلوحة المفاتيح"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Nabil gets stuck","ar":"نبيل يعلق"},"body":{"en":"Back to the travel agency's booking form. Nabil wanted to add a bag, but Tab skipped right over the bag options. They look like buttons, but in the code they're just painted boxes.\n\nThen a \"Get our offers\" pop-up opened. The only way out was a tiny × that Tab never reached. He was stuck, and closed the whole tab.","ar":"نعود إلى نموذج الحجز في وكالة السفر. أراد نبيل إضافة حقيبة، لكن Tab تخطّى خيارات الحقائب تمامًا. فهي تبدو كأزرار، لكنها في الكود مجرّد مربعات مرسومة.\n\nثم فُتحت نافذة «احصل على عروضنا». والطريقة الوحيدة للخروج × صغيرة لا يصل إليها Tab أبدًا. فعلق، وأغلق الصفحة كلها."},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"small","color":"muted","text":"×"},{"kind":"heading","text":{"en":"Get our offers","ar":"احصل على عروضنا"},"gap":"xs"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Subscribe","ar":"اشترك"},"gap":"s"}]}]}},{"id":"S02","type":"tune","skill":"SK-P01-U05-03","part":"try","rules":["R12"],"value":{"en":"Try first. Keyboard accessibility (NN/g): keyboard users must be able to reach all interactive elements, not only the main links. Bag options that Tab skips can't be chosen at all.","ar":"جرّب أولًا. الإتاحة بلوحة المفاتيح (NN/g): يجب أن يصل مستخدمو لوحة المفاتيح إلى كل العناصر التفاعلية، لا الروابط الرئيسية فقط. وخيارات الحقائب التي يتخطّاها Tab لا يمكن اختيارها أصلًا."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"Keyboard users must be able to access all interactive elements, not just the main navigation or in-line links."},"prompt":{"en":"Try each version of the bag options. Which one should ship?","ar":"جرّب كل نسخة لخيارات الحقائب. أيّها يجب أن تُطلق؟"},"start":"boxes","options":[{"id":"boxes","text":{"en":"Keep the painted boxes","ar":"أبقِ المربعات المرسومة"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Checked bags","ar":"الحقائب المشحونة"}},{"kind":"button","emphasis":"low","text":{"en":"No bag","ar":"بلا حقيبة"},"gap":"s"},{"kind":"button","emphasis":"low","text":{"en":"1 bag, +900 EGP","ar":"حقيبة واحدة، +900 جنيه"},"gap":"s"},{"kind":"button","text":{"en":"Continue","ar":"تابع"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Continue (the bag options are skipped)","ar":"ترتيب Tab: تابع (خيارات الحقائب يتخطّاها)"},"gap":"m"}]}},{"id":"note","text":{"en":"Keep them, and add \"Use a mouse to choose bags\"","ar":"أبقِها، وأضف «استخدم الماوس لاختيار الحقائب»"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Checked bags","ar":"الحقائب المشحونة"}},{"kind":"small","color":"muted","text":{"en":"Use a mouse to choose bags.","ar":"استخدم الماوس لاختيار الحقائب."},"gap":"xs"},{"kind":"button","emphasis":"low","text":{"en":"No bag","ar":"بلا حقيبة"},"gap":"s"},{"kind":"button","emphasis":"low","text":{"en":"1 bag, +900 EGP","ar":"حقيبة واحدة، +900 جنيه"},"gap":"s"},{"kind":"button","text":{"en":"Continue","ar":"تابع"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Continue (the bag options are skipped)","ar":"ترتيب Tab: تابع (خيارات الحقائب يتخطّاها)"},"gap":"m"}]}},{"id":"radios","text":{"en":"Build them as real radio buttons","ar":"ابنِها كـ Radio buttons حقيقية"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Checked bags","ar":"الحقائب المشحونة"}},{"kind":"radio","selected":true,"text":{"en":"No bag","ar":"بلا حقيبة"},"gap":"s"},{"kind":"radio","text":{"en":"1 bag, +900 EGP","ar":"حقيبة واحدة، +900 جنيه"},"gap":"xs"},{"kind":"button","text":{"en":"Continue","ar":"تابع"},"gap":"m"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Bag options (arrows to choose) → Continue","ar":"ترتيب Tab: خيارات الحقائب (الأسهم للاختيار) ← تابع"},"gap":"m"}]}}],"answer":["radios"],"misconceptions":[{"id":"MC-P01-054","when":["boxes"],"feedback":{"en":"Look at the Tab line: the bags are skipped. To Nabil, the choice doesn't exist.","ar":"انظر إلى سطر Tab: الحقائب يتخطّاها. وبالنسبة إلى نبيل، الاختيار غير موجود."}},{"id":"MC-P01-054","when":["note"],"feedback":{"en":"Nabil can't use a mouse; that's why he's on the keyboard. The note tells him he's locked out instead of letting him in.","ar":"نبيل لا يستطيع استخدام الماوس؛ ولهذا يستخدم لوحة المفاتيح. والملاحظة تخبره أنه ممنوع بدل أن تُدخله."}}],"hints":[{"en":"Read the Tab line under each preview. Where can Nabil choose a bag?","ar":"اقرأ سطر Tab تحت كل معاينة. أين يستطيع نبيل اختيار حقيبة؟"},{"en":"What kind of control does the keyboard already know how to reach?","ar":"أي نوع من العناصر تعرف لوحة المفاتيح الوصول إليه أصلًا؟"}],"correct":{"en":"Real radio buttons are on the Tab path, and arrows pick one.","ar":"الـ Radio buttons الحقيقية في مسار Tab، والأسهم تختار منها."},"explain":{"en":"If something can be clicked, it must be reachable by keyboard. Real controls (buttons, links, fields, checkboxes, radios) get that for free.","ar":"إن كان شيء يمكن الضغط عليه، فيجب أن يُوصَل إليه بلوحة المفاتيح. والعناصر الحقيقية (الأزرار، والروابط، والحقول، والـ Checkboxes، والـ Radios) تحصل على ذلك تلقائيًا."}},{"id":"S03","type":"card","part":"concept","icons":["tap","warn","ok","cut"],"title":{"en":"Real controls, and a way out","ar":"عناصر حقيقية، ومخرج"},"body":{"en":"Two things trap keyboard users more than anything else.\n\n- **Fake controls:** a box, picture or text that only reacts to a mouse click is invisible to Tab. Use real buttons, links and fields, and Tab reaches them by itself.\n- **Looks aren't enough:** making text blue or a box look like a button doesn't put it on the Tab path.\n- **Pop-ups with no exit:** every pop-up needs a Close button that Tab reaches, and Esc should close it too.\n- **Back where they were:** when a pop-up closes, focus returns to what opened it.","ar":"شيئان يحبسان مستخدمي لوحة المفاتيح أكثر من أي شيء آخر.\n\n- **عناصر مزيّفة:** المربع أو الصورة أو النص الذي يستجيب لضغطة الماوس فقط لا يراه Tab. استخدم أزرارًا وروابط وحقولًا حقيقية، ويصل إليها Tab تلقائيًا.\n- **الشكل لا يكفي:** جعل النص أزرق أو المربع يشبه الزر لا يضعه في مسار Tab.\n- **نوافذ بلا مخرج:** كل نافذة منبثقة تحتاج زر إغلاق يصل إليه Tab، ويجب أن يغلقها Esc أيضًا.\n- **العودة إلى المكان نفسه:** حين تُغلق النافذة، يعود التركيز إلى ما فتحها."}},{"id":"S04","type":"tune","skill":"SK-P01-U05-04","part":"guided","rules":["R06","R15"],"value":{"en":"Keyboard accessibility (NN/g): it is extremely important that people can close pop-ups, or they're stuck inside them. A × only a mouse can press is no exit for Nabil.","ar":"الإتاحة بلوحة المفاتيح (NN/g): من المهم جدًا أن يستطيع الناس إغلاق النوافذ المنبثقة، وإلا علقوا بداخلها. والـ × التي لا يضغطها إلا الماوس ليست مخرجًا لنبيل."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"It is extremely important for users to be able to close pop-ups or they will be stuck inside them."},"scenario":{"en":"The client wants to keep the \"Get our offers\" pop-up. My job is to make sure Nabil can get out of it.","ar":"العميل يريد الإبقاء على نافذة «احصل على عروضنا». ومهمّتي أن أتأكّد أن نبيل يستطيع الخروج منها."},"prompt":{"en":"Try each version of the pop-up. Which one should ship?","ar":"جرّب كل نسخة للنافذة. أيّها يجب أن تُطلق؟"},"start":"x","options":[{"id":"x","text":{"en":"Keep the small × that only a mouse can press","ar":"أبقِ الـ × الصغيرة التي لا يضغطها إلا الماوس"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"small","color":"muted","text":"×"},{"kind":"heading","text":{"en":"Get our offers","ar":"احصل على عروضنا"},"gap":"xs"},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Subscribe","ar":"اشترك"},"gap":"s"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Email → Subscribe → Email → … (no way out)","ar":"ترتيب Tab: البريد ← اشترك ← البريد ← … (بلا مخرج)"},"gap":"m"}]}},{"id":"timer","text":{"en":"Close it by itself after 10 seconds","ar":"أغلِقها تلقائيًا بعد 10 ثوانٍ"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"heading","text":{"en":"Get our offers","ar":"احصل على عروضنا"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Subscribe","ar":"اشترك"},"gap":"s"},{"kind":"small","color":"muted","text":{"en":"Closes in 10 seconds","ar":"تُغلق بعد 10 ثوانٍ"},"gap":"s"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Email → Subscribe → … then it vanishes, even mid-typing","ar":"ترتيب Tab: البريد ← اشترك ← … ثم تختفي، حتى أثناء الكتابة"},"gap":"m"}]}},{"id":"close","text":{"en":"A real \"No thanks\" button on the Tab path, and Esc closes it","ar":"زر «لا، شكرًا» حقيقي في مسار Tab، وEsc يغلقها"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"heading","text":{"en":"Get our offers","ar":"احصل على عروضنا"}},{"kind":"field","label":{"en":"Email","ar":"البريد الإلكتروني"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Subscribe","ar":"اشترك"},"gap":"s"},{"kind":"button","style":"plain","text":{"en":"No thanks","ar":"لا، شكرًا"},"gap":"xs"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Email → Subscribe → No thanks. Esc closes it too.","ar":"ترتيب Tab: البريد ← اشترك ← لا، شكرًا. وEsc يغلقها أيضًا."},"gap":"m"}]}}],"answer":["close"],"misconceptions":[{"id":"MC-P01-055","when":["x"],"feedback":{"en":"Tab circles between the email and Subscribe forever. Nabil's only way out is to subscribe or leave the site.","ar":"يدور Tab بين البريد و«اشترك» إلى الأبد. ومخرج نبيل الوحيد أن يشترك أو يغادر الموقع."}},{"id":"MC-P01-055","when":["timer"],"feedback":{"en":"Nabil types slowly. A pop-up that vanishes on its own may close in the middle of his email, and he can't close it when he wants to.","ar":"نبيل يكتب ببطء. والنافذة التي تختفي وحدها قد تُغلق في منتصف بريده، ولا يستطيع إغلاقها حين يريد."}}],"hints":[{"en":"Follow the Tab line. Does it ever reach a way out?","ar":"اتبع سطر Tab. هل يصل إلى مخرج في أي وقت؟"},{"en":"Which version lets Nabil leave when he chooses?","ar":"أي نسخة تتيح لنبيل الخروج حين يختار؟"}],"correct":{"en":"Nabil can leave by Tab or by Esc, whenever he wants.","ar":"يستطيع نبيل الخروج بـ Tab أو بـ Esc، متى أراد."},"explain":{"en":"A pop-up takes over the screen, so it must hand control back. A Close button on the Tab path plus Esc covers every keyboard user.","ar":"النافذة المنبثقة تستولي على الشاشة، فيجب أن تُعيد التحكّم. وزر إغلاق في مسار Tab مع Esc يغطّي كل مستخدمي لوحة المفاتيح."},"speaker":"karim"},{"id":"S05","type":"tune","skill":"SK-P01-U05-03","part":"guided","rules":["R06","R15"],"value":{"en":"Keyboard accessibility (NN/g): using only HTML links, buttons and form fields makes sure every element can be tabbed to. Text that only reacts to a click isn't one of them, however it looks.","ar":"الإتاحة بلوحة المفاتيح (NN/g): استخدام روابط وأزرار وحقول HTML فقط يضمن أن يصل Tab إلى كل عنصر. والنص الذي يستجيب للضغط فقط ليس منها، مهما كان شكله."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"Alternatively, using only HTML links, buttons, and form fields will ensure that all elements can be tabbed to."},"scenario":{"en":"Flight results show 5 flights, then \"Show more flights\". In our code, that's plain text that runs a script when clicked. Tab skips it, so Nabil only ever sees 5 flights.","ar":"نتائج الرحلات تعرض 5 رحلات، ثم «اعرض رحلات أكثر». وفي الكود عندنا، هذا نص عادي يشغّل كودًا عند الضغط. ويتخطّاه Tab، فلا يرى نبيل إلا 5 رحلات دائمًا."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"text","options":[{"id":"text","text":{"en":"Keep the clickable text","ar":"أبقِ النص القابل للضغط"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"5 of 14 flights","ar":"5 من 14 رحلة"}},{"kind":"small","color":"muted","text":{"en":"Show more flights","ar":"اعرض رحلات أكثر"},"gap":"s"},{"kind":"small","color":"brand","text":{"en":"Tab goes: last flight → page footer (skips \"Show more\")","ar":"ترتيب Tab: آخر رحلة ← أسفل الصفحة (يتخطّى «اعرض أكثر»)"},"gap":"m"}]}},{"id":"blue","text":{"en":"Make the text blue and underlined","ar":"اجعل النص أزرق وتحته خط"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"5 of 14 flights","ar":"5 من 14 رحلة"}},{"kind":"link","text":{"en":"Show more flights","ar":"اعرض رحلات أكثر"},"gap":"s"},{"kind":"small","color":"brand","text":{"en":"Tab goes: last flight → page footer (skips \"Show more\")","ar":"ترتيب Tab: آخر رحلة ← أسفل الصفحة (يتخطّى «اعرض أكثر»)"},"gap":"m"}]}},{"id":"button","text":{"en":"Make it a real button","ar":"اجعله زرًا حقيقيًا"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"5 of 14 flights","ar":"5 من 14 رحلة"}},{"kind":"button","emphasis":"low","text":{"en":"Show more flights","ar":"اعرض رحلات أكثر"},"gap":"s"},{"kind":"small","color":"brand","text":{"en":"Tab goes: last flight → Show more flights → page footer","ar":"ترتيب Tab: آخر رحلة ← اعرض رحلات أكثر ← أسفل الصفحة"},"gap":"m"}]}}],"answer":["button"],"misconceptions":[{"id":"MC-P01-054","when":["text","blue"],"feedback":{"en":"Blue and underlined looks like a link, but it's still plain text in the code, so Tab still skips it. What it's built from decides, not how it looks.","ar":"الأزرق مع الخط يبدو رابطًا، لكنه ما زال نصًا عاديًا في الكود، فيظل Tab يتخطّاه. ما بُني منه هو الذي يحدّد، لا شكله."}}],"hints":[{"en":"Compare the Tab lines. Which one changed?","ar":"قارن أسطر Tab. أيّها تغيّر؟"},{"en":"Does changing a color change what the code is?","ar":"هل تغيير اللون يغيّر ما هو الكود؟"}],"correct":{"en":"A real button is on the Tab path by itself.","ar":"الزر الحقيقي في مسار Tab تلقائيًا."},"explain":{"en":"Tab finds links, buttons and fields. Anything else that acts like a control needs to become one of those, not just look like one.","ar":"Tab يجد الروابط والأزرار والحقول. وأي شيء آخر يتصرّف كعنصر تحكّم يجب أن يصبح واحدًا منها، لا أن يشبهها فقط."},"speaker":"karim"},{"id":"S06","type":"words","skill":"SK-P01-U05-04","part":"guided","confidence":true,"rules":["R06","R15"],"value":{"en":"Keyboard accessibility (NN/g): people must be able to close pop-ups, or they're stuck. A good spec says how: a Close button, Esc, and focus going back where it was.","ar":"الإتاحة بلوحة المفاتيح (NN/g): يجب أن يستطيع الناس إغلاق النوافذ المنبثقة، وإلا علقوا. والمواصفات الجيدة تقول كيف: زر إغلاق، وEsc، وعودة التركيز إلى مكانه."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"It is extremely important for users to be able to close pop-ups or they will be stuck inside them."},"scenario":{"en":"The travel date opens a calendar pop-up. I'm writing the spec note for how it closes.","ar":"تاريخ السفر يفتح نافذة تقويم منبثقة. وأكتب ملاحظة المواصفات لكيفية إغلاقها."},"prompt":{"en":"Which note should go in the spec?","ar":"أي ملاحظة يجب أن تُكتب في المواصفات؟"},"options":[{"id":"outside","text":{"en":"\"Clicking outside the calendar closes it.\"","ar":"«الضغط خارج التقويم يغلقه.»"}},{"id":"full","text":{"en":"\"Esc and a Close button close the calendar, and focus goes back to the date field.\"","ar":"«Esc وزر إغلاق يغلقان التقويم، ويعود التركيز إلى حقل التاريخ.»"}},{"id":"pick","text":{"en":"\"The calendar closes once a date is picked.\"","ar":"«يُغلق التقويم بمجرّد اختيار تاريخ.»"}}],"answer":["full"],"misconceptions":[{"id":"MC-P01-055","when":["outside","pick"],"feedback":{"en":"Clicking outside needs a mouse, and \"after picking\" traps anyone who opened it by mistake. Keyboard users need Esc and a Close button.","ar":"الضغط بالخارج يحتاج ماوس، و«بعد الاختيار» يحبس كل من فتحه بالخطأ. ومستخدمو لوحة المفاتيح يحتاجون Esc وزر إغلاق."}}],"hints":[{"en":"Which note still works for someone with only a keyboard, who opened the calendar by mistake?","ar":"أي ملاحظة تعمل لمن يستخدم لوحة المفاتيح فقط، وفتح التقويم بالخطأ؟"},{"en":"Where should Nabil be after the calendar closes?","ar":"أين يجب أن يكون نبيل بعد أن يُغلق التقويم؟"}],"correct":{"en":"Two ways out by keyboard, and Nabil lands back where he was.","ar":"مخرجان بلوحة المفاتيح، ويعود نبيل إلى حيث كان."},"explain":{"en":"A pop-up should open and close on the person's terms. Esc, a reachable Close button, and focus returning to its starting point make that true.","ar":"النافذة المنبثقة يجب أن تُفتح وتُغلق كما يريد الشخص. وEsc، وزر إغلاق يمكن الوصول إليه، وعودة التركيز إلى نقطة البداية تحقّق ذلك."},"speaker":"karim"},{"id":"S07","type":"compare","skill":"SK-P01-U05-03","part":"contrast","rules":["R11","R15"],"value":{"en":"Contrast with S05: here both icons look exactly the same. Keyboard accessibility (NN/g): keyboard users must reach all interactive elements. Only what each one is built from differs.","ar":"مقارنة مع الخطوة 5: الأيقونتان هنا متطابقتان في الشكل. الإتاحة بلوحة المفاتيح (NN/g): يجب أن يصل مستخدمو لوحة المفاتيح إلى كل العناصر التفاعلية. والفرق الوحيد فيما بُنيت منه كل واحدة."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"Keyboard users must be able to access all interactive elements, not just the main navigation or in-line links."},"scenario":{"en":"The sign-in form has a 👁 to show the password. Version A builds it as a picture with a click script. Version B builds it as a real button with the same picture inside.","ar":"نموذج الدخول فيه 👁 لإظهار كلمة المرور. النسخة A تبنيها كصورة مع كود للضغط. والنسخة B تبنيها كزر حقيقي بداخله الصورة نفسها."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"label":{"en":"Picture","ar":"صورة"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Password 👁","ar":"كلمة المرور 👁"},"filled":true,"text":"••••••••"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Password → Sign in","ar":"ترتيب Tab: كلمة المرور ← دخول"},"gap":"s"}]}},"b":{"label":{"en":"Button","ar":"زر"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"Password 👁","ar":"كلمة المرور 👁"},"filled":true,"text":"••••••••"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Password → Show password → Sign in","ar":"ترتيب Tab: كلمة المرور ← أظهر كلمة المرور ← دخول"},"gap":"s"}]}},"answer":"b","reason":{"prompt":{"en":"What decides it?","ar":"ما الذي يحسم الأمر؟"},"options":[{"id":"look","text":{"en":"B's icon is easier to see","ar":"أيقونة B أسهل في الرؤية"}},{"id":"built","text":{"en":"B is a real button, so Tab reaches it","ar":"B زر حقيقي، فيصل إليه Tab"}},{"id":"same","text":{"en":"Nothing; they look the same","ar":"لا شيء؛ شكلهما واحد"}}],"answer":["built"],"misconceptions":[{"id":"MC-P01-054","when":["look","same"],"feedback":{"en":"They look identical. Read the Tab lines: in A, the eye is never reached. Nabil can't check what he typed.","ar":"شكلهما متطابق. اقرأ سطري Tab: في A، لا يصل Tab إلى العين أبدًا. ولا يستطيع نبيل مراجعة ما كتبه."}}]},"misconceptions":[{"id":"MC-P01-054","when":["a"],"feedback":{"en":"A looks fine, but it works for mouse users only. Nabil can't show his password to check it.","ar":"A تبدو جيدة، لكنها تعمل لمستخدمي الماوس فقط. ولا يستطيع نبيل إظهار كلمة مروره ليراجعها."}}],"hints":[{"en":"The pictures match. What's different in the Tab lines?","ar":"الصورتان متطابقتان. ما المختلف في سطري Tab؟"}],"correct":{"en":"Same look; only the real button works by keyboard.","ar":"الشكل نفسه؛ والزر الحقيقي وحده يعمل بلوحة المفاتيح."},"explain":{"en":"You can't see keyboard access in a screenshot. Check by pressing Tab, and build every clickable thing as a real control.","ar":"لا يمكنك رؤية إمكانية الوصول بلوحة المفاتيح في صورة للشاشة. اختبرها بالضغط على Tab، وابنِ كل شيء قابل للضغط كعنصر حقيقي."},"speaker":"karim"},{"id":"S08","type":"tune","skill":"SK-P01-U05-04","part":"independent","speaker":"mona","rules":["R14","R19"],"value":{"en":"New case. Keyboard accessibility (NN/g): people must be able to close pop-ups, or they're stuck inside them. A help panel that opens over a form needs its own way out.","ar":"حالة جديدة. الإتاحة بلوحة المفاتيح (NN/g): يجب أن يستطيع الناس إغلاق النوافذ المنبثقة، وإلا علقوا بداخلها. ولوحة المساعدة التي تُفتح فوق النموذج تحتاج مخرجها الخاص."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"It is extremely important for users to be able to close pop-ups or they will be stuck inside them."},"scenario":{"en":"My team designs an insurance sign-up form. A help panel opens over it when you press \"Need help?\". Zeinab, who uses a screen reader with the keyboard, opened it by mistake and couldn't get back to the form.","ar":"يصمّم فريقي نموذج اشتراك في تأمين. وتُفتح لوحة مساعدة فوقه حين تضغط «تحتاج مساعدة؟». وزينب، التي تستخدم قارئ شاشة مع لوحة المفاتيح، فتحتها بالخطأ ولم تستطع العودة إلى النموذج."},"prompt":{"en":"Try each version of the help panel. Which one should ship?","ar":"جرّب كل نسخة للوحة المساعدة. أيّها يجب أن تُطلق؟"},"start":"none","options":[{"id":"none","text":{"en":"Keep it: no close control","ar":"أبقِه: بلا عنصر إغلاق"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"heading","text":{"en":"How can we help?","ar":"كيف نساعدك؟"}},{"kind":"link","text":{"en":"Which plan is right for me?","ar":"أي باقة تناسبني؟"},"gap":"s"},{"kind":"link","text":{"en":"Call us","ar":"اتصل بنا"},"gap":"s"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Which plan… → Call us → Which plan… (stuck)","ar":"ترتيب Tab: أي باقة… ← اتصل بنا ← أي باقة… (عالقة)"},"gap":"m"}]}},{"id":"close","text":{"en":"A Close button first in the panel, Esc closes it, focus returns to \"Need help?\"","ar":"زر إغلاق أولًا في اللوحة، وEsc يغلقها، ويعود التركيز إلى «تحتاج مساعدة؟»"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"button","style":"plain","text":{"en":"Close help","ar":"أغلق المساعدة"}},{"kind":"heading","text":{"en":"How can we help?","ar":"كيف نساعدك؟"},"gap":"xs"},{"kind":"link","text":{"en":"Which plan is right for me?","ar":"أي باقة تناسبني؟"},"gap":"s"},{"kind":"link","text":{"en":"Call us","ar":"اتصل بنا"},"gap":"s"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Close help → Which plan… → Call us. Esc closes it too.","ar":"ترتيب Tab: أغلق المساعدة ← أي باقة… ← اتصل بنا. وEsc يغلقها أيضًا."},"gap":"m"}]}},{"id":"reload","text":{"en":"Tell people to reload the page to close it","ar":"اطلب من الناس إعادة تحميل الصفحة لإغلاقها"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"heading","text":{"en":"How can we help?","ar":"كيف نساعدك؟"}},{"kind":"link","text":{"en":"Which plan is right for me?","ar":"أي باقة تناسبني؟"},"gap":"s"},{"kind":"link","text":{"en":"Call us","ar":"اتصل بنا"},"gap":"s"},{"kind":"small","color":"muted","text":{"en":"To close, reload the page.","ar":"للإغلاق، أعد تحميل الصفحة."},"gap":"s"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Which plan… → Call us → (reload loses the form)","ar":"ترتيب Tab: أي باقة… ← اتصل بنا ← (إعادة التحميل تُضيّع النموذج)"},"gap":"m"}]}}],"answer":["close"],"misconceptions":[{"id":"MC-P01-055","when":["none","reload"],"feedback":{"en":"Zeinab is either stuck in the panel or loses everything she typed. A pop-up must close by keyboard and leave the form as it was.","ar":"زينب إما عالقة في اللوحة أو تفقد كل ما كتبته. والنافذة المنبثقة يجب أن تُغلق بلوحة المفاتيح وتترك النموذج كما كان."}}],"correct":{"en":"Zeinab can close it two ways and lands back on \"Need help?\".","ar":"تستطيع زينب إغلاقها بطريقتين وتعود إلى «تحتاج مساعدة؟»."},"explain":{"en":"Every panel or pop-up that opens over a form needs a Close button on the Tab path, Esc, and a return to where the person was.","ar":"كل لوحة أو نافذة تُفتح فوق النموذج تحتاج زر إغلاق في مسار Tab، وEsc، والعودة إلى حيث كان الشخص."}},{"id":"S09","type":"card","part":"recap","icons":["tap","ok","cut","eye"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Real controls:** rebuilt painted bag boxes as radio buttons and clickable text as a button.\n- **Looks aren't access:** saw that blue text and an identical icon can still be skipped by Tab.\n- **A way out:** gave pop-ups a Close button on the Tab path, plus Esc.\n- **Back where they were:** sent focus back to what opened the calendar or help panel.\n\nNext: forms on a touch screen, and the button that wipes everything.","ar":"- **عناصر حقيقية:** أعدت بناء مربعات الحقائب المرسومة كـ Radio buttons، والنص القابل للضغط كزر.\n- **الشكل ليس وصولًا:** رأيت أن النص الأزرق والأيقونة المتطابقة قد يتخطّاهما Tab.\n- **مخرج:** أعطيت النوافذ المنبثقة زر إغلاق في مسار Tab، مع Esc.\n- **العودة إلى المكان نفسه:** أعدت التركيز إلى ما فتح التقويم أو لوحة المساعدة.\n\nالتالي: النماذج على شاشات اللمس، والزر الذي يمسح كل شيء."}}]}$uxg$::jsonb),
  ($uxg$P01-U05-L03$uxg$, $uxg$30df000def69456e20a4f3563c008c846bb2fbdf2d4865a960c377f56f4d8059$uxg$, $uxg${"id":"P01-U05-L03","mode":"lesson","minutes":8,"title":{"en":"Big enough to tap, safe to send","ar":"كبير بما يكفي للمس، وآمن للإرسال"},"speaker":"karim","review_labels":{"MC-P01-056":{"en":"Tap targets need size and space","ar":"أهداف اللمس تحتاج حجمًا ومسافة"},"MC-P01-057":{"en":"No Clear or Reset next to Submit","ar":"لا «مسح» ولا Reset بجوار زر الإرسال"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Aziza's lost request","ar":"طلب عزيزة الضائع"},"body":{"en":"I'm building a phone app for a home repair company. Aziza is 68. She filled in a long request for a plumber, then tapped what she thought was Send.\n\nIt was Clear, sitting right beside it. Everything she typed was gone. Earlier, she had also tapped the wrong time slot twice, because the slots are tiny and packed together.","ar":"أبني تطبيق هاتف لشركة صيانة منزلية. عزيزة عمرها 68 عامًا. ملأت طلبًا طويلًا لسبّاك، ثم ضغطت ما ظنّته «أرسل».\n\nكان «مسح»، الموجود بجواره مباشرة. فضاع كل ما كتبته. وقبل ذلك، كانت قد ضغطت موعدًا خاطئًا مرتين، لأن المواعيد صغيرة جدًا ومتلاصقة."},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"What's the problem?","ar":"ما المشكلة؟"},"filled":true,"text":{"en":"Kitchen sink leaks under the cabinet…","ar":"حوض المطبخ يسرّب تحت الدولاب…"}},{"kind":"row","gap":"m","blocks":[{"kind":"button","emphasis":"low","text":{"en":"Clear","ar":"مسح"}},{"kind":"button","text":{"en":"Send","ar":"أرسل"}}]}]}},{"id":"S02","type":"tune","skill":"SK-P01-U05-06","part":"try","rules":["R12"],"value":{"en":"Try first. Reset and Cancel buttons (NN/g): the worst problem with Reset is that people click it by mistake when they meant Submit. Nobody needs to wipe a whole form in one tap.","ar":"جرّب أولًا. أزرار Reset وCancel (NN/g): أسوأ مشكلة في زر Reset أن الناس يضغطونه بالخطأ وهم يقصدون الإرسال. ولا أحد يحتاج أن يمسح نموذجًا كاملًا بضغطة واحدة."},"ref":{"url":"https://www.nngroup.com/articles/reset-and-cancel-buttons/","quote":"The worst problem about Reset is that users click the button by mistake when they wanted to click Submit."},"prompt":{"en":"Try each version of the bottom of the form. Which one should ship?","ar":"جرّب كل نسخة لأسفل النموذج. أيّها يجب أن تُطلق؟"},"start":"both","options":[{"id":"both","text":{"en":"Keep Clear beside Send","ar":"أبقِ «مسح» بجوار «أرسل»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"What's the problem?","ar":"ما المشكلة؟"},"filled":true,"text":{"en":"Kitchen sink leaks under the cabinet…","ar":"حوض المطبخ يسرّب تحت الدولاب…"}},{"kind":"row","gap":"m","blocks":[{"kind":"button","emphasis":"low","text":{"en":"Clear","ar":"مسح"}},{"kind":"button","text":{"en":"Send","ar":"أرسل"}}]}]}},{"id":"link","text":{"en":"Turn Clear into a small grey link under Send","ar":"حوّل «مسح» إلى رابط رمادي صغير تحت «أرسل»"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"What's the problem?","ar":"ما المشكلة؟"},"filled":true,"text":{"en":"Kitchen sink leaks under the cabinet…","ar":"حوض المطبخ يسرّب تحت الدولاب…"}},{"kind":"button","text":{"en":"Send","ar":"أرسل"},"gap":"m"},{"kind":"button","style":"plain","text":{"en":"Clear","ar":"مسح"},"gap":"xs"}]}},{"id":"none","text":{"en":"Remove Clear; keep only Send","ar":"احذف «مسح»؛ وأبقِ «أرسل» فقط"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"What's the problem?","ar":"ما المشكلة؟"},"filled":true,"text":{"en":"Kitchen sink leaks under the cabinet…","ar":"حوض المطبخ يسرّب تحت الدولاب…"}},{"kind":"button","text":{"en":"Send","ar":"أرسل"},"gap":"m"}]}}],"answer":["none"],"misconceptions":[{"id":"MC-P01-057","when":["both"],"feedback":{"en":"One slip and Aziza loses everything, which is exactly what happened. The button's only job is the thing nobody wants.","ar":"زلّة واحدة وتفقد عزيزة كل شيء، وهذا بالضبط ما حدث. والمهمة الوحيدة لهذا الزر هي ما لا يريده أحد."}},{"id":"MC-P01-057","when":["link"],"feedback":{"en":"Smaller and greyer, but still one tap under Send. A thumb that lands a little low still wipes the form. Nobody needs it, so remove it.","ar":"أصغر وأكثر رمادية، لكنه ما زال على بُعد ضغطة تحت «أرسل». والإصبع الذي ينزل قليلًا يمسح النموذج. ولا أحد يحتاجه، فاحذفه."}}],"hints":[{"en":"When does anyone really want to erase every answer at once?","ar":"متى يريد أحد حقًا أن يمسح كل الإجابات دفعة واحدة؟"},{"en":"Which version makes losing the form impossible by mistake?","ar":"أي نسخة تجعل فقدان النموذج بالخطأ مستحيلًا؟"}],"correct":{"en":"No Clear, no accident.","ar":"لا «مسح»، لا حادث."},"explain":{"en":"People change one answer by editing that field. A button that erases everything helps almost no one and hurts anyone who taps it by mistake.","ar":"يغيّر الناس إجابة واحدة بتعديل حقلها. والزر الذي يمسح كل شيء لا يفيد أحدًا تقريبًا، ويؤذي كل من يضغطه بالخطأ."}},{"id":"S03","type":"card","part":"concept","icons":["tap","space","cut","ok"],"title":{"en":"Fingers are bigger than pointers","ar":"الأصابع أكبر من مؤشّر الماوس"},"body":{"en":"On a phone, every button is pressed with a fingertip, often a thumb, often while moving.\n\n- **Big enough:** make each tap target at least 1 cm by 1 cm. The tap area can be bigger than the text or icon inside it.\n- **Spaced apart:** leave room between targets, so a tap lands on one thing, not its neighbour.\n- **Dangerous buttons far away:** Delete next to Edit, or Clear next to Send, turns a small slip into a big loss.\n- **No Clear button:** people fix a form one field at a time. Leave out buttons that wipe it all.","ar":"على الهاتف، كل زر يُضغط بطرف الإصبع، غالبًا بالإبهام، وغالبًا أثناء الحركة.\n\n- **كبير بما يكفي:** اجعل كل هدف لمس 1 سم × 1 سم على الأقل. ومساحة اللمس يمكن أن تكون أكبر من النص أو الأيقونة بداخلها.\n- **متباعد:** اترك مسافة بين الأهداف، لتقع الضغطة على عنصر واحد، لا على جاره.\n- **الأزرار الخطرة بعيدة:** «حذف» بجوار «تعديل»، أو «مسح» بجوار «أرسل»، يحوّلان زلّة صغيرة إلى خسارة كبيرة.\n- **بلا زر مسح:** يُصلح الناس النموذج حقلًا حقلًا. استغنِ عن الأزرار التي تمسح كل شيء."}},{"id":"S04","type":"tune","skill":"SK-P01-U05-05","part":"guided","rules":["R06","R15"],"value":{"en":"Touch targets (NN/g): the minimum size should be 1 cm × 1 cm. Time slots drawn as small tags are about half that, so Aziza's finger covers two at once.","ar":"أهداف اللمس (NN/g): الحد الأدنى للحجم 1 سم × 1 سم. والمواعيد المرسومة كعلامات صغيرة نصف ذلك تقريبًا، فيغطّي إصبع عزيزة موعدين في وقت واحد."},"ref":{"url":"https://www.nngroup.com/articles/touch-target-size/","quote":"its minimum size should be 1cm × 1cm (0.4in x 0.4in)"},"scenario":{"en":"People pick a visit time from small tags, about 5 mm tall. Aziza wanted 11 am and got 10 am, twice.","ar":"يختار الناس موعد الزيارة من علامات صغيرة، ارتفاعها نحو 5 مم. أرادت عزيزة الحادية عشرة فاختارت العاشرة، مرتين."},"prompt":{"en":"Try each version of the time slots. Which one should ship?","ar":"جرّب كل نسخة للمواعيد. أيّها يجب أن تُطلق؟"},"start":"tags","options":[{"id":"tags","text":{"en":"Keep the small tags","ar":"أبقِ العلامات الصغيرة"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Visit time, Tuesday","ar":"موعد الزيارة، الثلاثاء"}},{"kind":"row","gap":"s","blocks":[{"kind":"chip","tone":"off","text":{"en":"9 am","ar":"9 ص"}},{"kind":"chip","tone":"off","text":{"en":"10 am","ar":"10 ص"}},{"kind":"chip","tone":"off","text":{"en":"11 am","ar":"11 ص"}},{"kind":"chip","tone":"off","text":{"en":"12 pm","ar":"12 م"}}]}]}},{"id":"bold","text":{"en":"Keep the tags, with bigger, bold text","ar":"أبقِ العلامات، بنص أكبر وعريض"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Visit time, Tuesday","ar":"موعد الزيارة، الثلاثاء"}},{"kind":"row","gap":"s","blocks":[{"kind":"chip","tone":"off","weight":"bold","text":{"en":"9 am","ar":"9 ص"}},{"kind":"chip","tone":"off","weight":"bold","text":{"en":"10 am","ar":"10 ص"}},{"kind":"chip","tone":"off","weight":"bold","text":{"en":"11 am","ar":"11 ص"}},{"kind":"chip","tone":"off","weight":"bold","text":{"en":"12 pm","ar":"12 م"}}]}]}},{"id":"buttons","text":{"en":"Make each slot a button at least 1 cm tall, two per row","ar":"اجعل كل موعد زرًا ارتفاعه 1 سم على الأقل، اثنين في كل صف"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Visit time, Tuesday","ar":"موعد الزيارة، الثلاثاء"}},{"kind":"row","gap":"s","blocks":[{"kind":"button","emphasis":"low","text":{"en":"9 am","ar":"9 ص"}},{"kind":"button","emphasis":"low","text":{"en":"10 am","ar":"10 ص"}}]},{"kind":"row","gap":"s","blocks":[{"kind":"button","emphasis":"low","text":{"en":"11 am","ar":"11 ص"}},{"kind":"button","emphasis":"low","text":{"en":"12 pm","ar":"12 م"}}]}]}}],"answer":["buttons"],"misconceptions":[{"id":"MC-P01-056","when":["tags","bold"],"feedback":{"en":"Bigger text is easier to read, but the tag is still about 5 mm tall. A fingertip is wider than that, so it still lands on the wrong time.","ar":"النص الأكبر أسهل في القراءة، لكن العلامة ما زالت بارتفاع 5 مم تقريبًا. وطرف الإصبع أعرض من ذلك، فيقع على الموعد الخطأ مرة أخرى."}}],"hints":[{"en":"What did Aziza get wrong: reading the time, or hitting it?","ar":"أين أخطأت عزيزة: في قراءة الموعد، أم في الضغط عليه؟"},{"en":"Which version gives each slot room for a whole fingertip?","ar":"أي نسخة تعطي كل موعد مساحة لطرف إصبع كامل؟"}],"correct":{"en":"Each slot is now big enough for a fingertip.","ar":"كل موعد الآن كبير بما يكفي لطرف إصبع."},"explain":{"en":"Reading size and tapping size are different problems. A target needs about 1 cm in each direction, whatever the text size.","ar":"حجم القراءة وحجم الضغط مشكلتان مختلفتان. والهدف يحتاج نحو 1 سم في كل اتجاه، أيًّا كان حجم النص."},"speaker":"karim"},{"id":"S05","type":"tune","skill":"SK-P01-U05-05","part":"guided","rules":["R06","R15"],"value":{"en":"Touch targets (NN/g): to avoid accidental taps, targets must be big enough and also spaced well enough. A bigger Delete that touches Edit is still one slip away.","ar":"أهداف اللمس (NN/g): لتجنّب الضغطات العرضية، يجب أن تكون الأهداف كبيرة بما يكفي ومتباعدة بما يكفي أيضًا. و«حذف» الأكبر الملاصق لـ «تعديل» ما زال على بُعد زلّة."},"ref":{"url":"https://www.nngroup.com/articles/touch-target-size/","quote":"To avoid accidental taps, targets must first be big enough, and then also spaced well enough"},"scenario":{"en":"Under each saved address there are two buttons: Edit and Delete. Right now they're small and touching. Last week, three customers deleted an address they meant to edit.","ar":"تحت كل عنوان محفوظ زرّان: «تعديل» و«حذف». وهما الآن صغيران ومتلاصقان. والأسبوع الماضي، حذف ثلاثة عملاء عنوانًا كانوا يقصدون تعديله."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"small","options":[{"id":"small","text":{"en":"Keep them small and touching","ar":"أبقِهما صغيرين ومتلاصقين"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Home: 9 Mosaddak St, Dokki","ar":"المنزل: 9 شارع مصدق، الدقي"}},{"kind":"row","gap":"xs","blocks":[{"kind":"chip","tone":"off","text":{"en":"Edit","ar":"تعديل"}},{"kind":"chip","tone":"bad","text":{"en":"Delete","ar":"حذف"}}]}]}},{"id":"big","text":{"en":"Make both full-size buttons, still touching","ar":"اجعلهما زرّين بالحجم الكامل، ما زالا متلاصقين"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Home: 9 Mosaddak St, Dokki","ar":"المنزل: 9 شارع مصدق، الدقي"}},{"kind":"button","emphasis":"low","text":{"en":"Edit","ar":"تعديل"},"gap":"s"},{"kind":"button","style":"danger","text":{"en":"Delete","ar":"حذف"},"gap":"xs"}]}},{"id":"spaced","text":{"en":"Full-size buttons, with clear space between them","ar":"زرّان بالحجم الكامل، مع مسافة واضحة بينهما"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Home: 9 Mosaddak St, Dokki","ar":"المنزل: 9 شارع مصدق، الدقي"}},{"kind":"button","emphasis":"low","text":{"en":"Edit","ar":"تعديل"},"gap":"s"},{"kind":"button","style":"dangerlink","text":{"en":"Delete","ar":"حذف"},"gap":"xl"}]}}],"answer":["spaced"],"misconceptions":[{"id":"MC-P01-056","when":["small"],"feedback":{"en":"Both buttons are smaller than a fingertip and share an edge. A tap meant for Edit easily lands on Delete.","ar":"الزرّان أصغر من طرف الإصبع ويشتركان في حافة. والضغطة المقصودة لـ «تعديل» تقع بسهولة على «حذف»."}},{"id":"MC-P01-056","when":["big"],"feedback":{"en":"Bigger helps, but with no gap, a thumb that lands near the edge still hits Delete. Size and space both matter.","ar":"الحجم الأكبر يساعد، لكن بلا مسافة، يظل الإبهام الذي يقع قرب الحافة يضغط «حذف». الحجم والمسافة كلاهما مهم."}}],"hints":[{"en":"If a thumb lands a few millimetres off, what does it hit in each version?","ar":"لو وقع الإبهام بعيدًا ببضعة ملّيمترات، ماذا يضغط في كل نسخة؟"},{"en":"Which version has both size and space?","ar":"أي نسخة فيها الحجم والمسافة معًا؟"}],"correct":{"en":"Big enough to hit, far enough not to miss into Delete.","ar":"كبير بما يكفي للضغط، وبعيد بما يكفي حتى لا تخطئ إلى «حذف»."},"explain":{"en":"First make targets big enough, then space them out, especially when one of them destroys something.","ar":"اجعل الأهداف كبيرة بما يكفي أولًا، ثم باعِد بينها، خاصة حين يكون أحدها يدمّر شيئًا."},"speaker":"karim"},{"id":"S06","type":"words","skill":"SK-P01-U05-06","part":"guided","confidence":true,"rules":["R06","R15"],"value":{"en":"Reset and Cancel buttons (NN/g): people click Reset by mistake when they meant Submit. The safest spec has no Clear button at all.","ar":"أزرار Reset وCancel (NN/g): يضغط الناس Reset بالخطأ وهم يقصدون الإرسال. وأكثر المواصفات أمانًا لا تضم زر «مسح» أصلًا."},"ref":{"url":"https://www.nngroup.com/articles/reset-and-cancel-buttons/","quote":"The worst problem about Reset is that users click the button by mistake when they wanted to click Submit."},"scenario":{"en":"The client's other app, for booking an electrician, has Clear and Send side by side too. I'm writing one rule for both apps.","ar":"تطبيق العميل الآخر، لحجز كهربائي، فيه «مسح» و«أرسل» متجاوران أيضًا. وأكتب قاعدة واحدة للتطبيقين."},"prompt":{"en":"Which rule should go in the spec?","ar":"أي قاعدة يجب أن تُكتب في المواصفات؟"},"options":[{"id":"confirm","text":{"en":"\"Clear asks 'Are you sure?' before it erases.\"","ar":"«زر المسح يسأل «هل أنت متأكد؟» قبل أن يمسح.»"}},{"id":"none","text":{"en":"\"No Clear button. To change an answer, people edit that field.\"","ar":"«بلا زر مسح. لتغيير إجابة، يعدّل الناس حقلها.»"}},{"id":"color","text":{"en":"\"Clear is grey and Send is purple, so they look different.\"","ar":"«زر المسح رمادي وزر الإرسال بنفسجي، ليبدوا مختلفين.»"}}],"answer":["none"],"misconceptions":[{"id":"MC-P01-057","when":["confirm","color"],"feedback":{"en":"Both keep a button nobody needs right where people tap to finish. Different colors don't stop a thumb; a dialog adds a scary extra step. Leave it out.","ar":"كلاهما يُبقي زرًا لا يحتاجه أحد في المكان الذي يضغط فيه الناس للإنهاء. الألوان المختلفة لا توقف الإبهام؛ ونافذة التأكيد تضيف خطوة مخيفة. استغنِ عنه."}}],"hints":[{"en":"Which rule makes the accident impossible, not just less likely?","ar":"أي قاعدة تجعل الحادث مستحيلًا، لا أقل احتمالًا فقط؟"},{"en":"How do people usually change one answer?","ar":"كيف يغيّر الناس إجابة واحدة عادةً؟"}],"correct":{"en":"Nothing to tap by mistake, and editing still works.","ar":"لا شيء يُضغط بالخطأ، والتعديل ما زال ممكنًا."},"explain":{"en":"The best fix for a dangerous button nobody needs is to remove it. Editing one field covers the real need.","ar":"أفضل إصلاح لزر خطير لا يحتاجه أحد أن تحذفه. وتعديل الحقل الواحد يغطّي الحاجة الحقيقية."},"speaker":"karim"},{"id":"S07","type":"compare","skill":"SK-P01-U05-05","part":"contrast","rules":["R11","R15"],"value":{"en":"Contrast with S04: here the checkbox looks the same in both. Touch targets (NN/g): the target must be at least 1 cm × 1 cm. The tap area can be the whole row, not only the little box.","ar":"مقارنة مع الخطوة 4: هنا شكل الـ Checkbox واحد في النسختين. أهداف اللمس (NN/g): يجب أن يكون الهدف 1 سم × 1 سم على الأقل. ومساحة اللمس يمكن أن تكون الصف كله، لا المربع الصغير فقط."},"ref":{"url":"https://www.nngroup.com/articles/touch-target-size/","quote":"its minimum size should be 1cm × 1cm (0.4in x 0.4in)"},"scenario":{"en":"Before sending, people tick \"I'll be home during the visit\". In version A, only the 4 mm box reacts to a tap. In version B, the whole row reacts, about 1.2 cm tall (shaded here to show it).","ar":"قبل الإرسال، يعلّم الناس «سأكون في المنزل أثناء الزيارة». في النسخة A، المربع الذي حجمه 4 مم وحده يستجيب للمس. وفي النسخة B، الصف كله يستجيب، بارتفاع نحو 1.2 سم (مظلّل هنا لإظهاره)."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"label":{"en":"Box only","ar":"المربع فقط"},"mock":{"width":300,"blocks":[{"kind":"check","text":{"en":"I'll be home during the visit","ar":"سأكون في المنزل أثناء الزيارة"}}]}},"b":{"label":{"en":"Whole row","ar":"الصف كله"},"mock":{"width":300,"blocks":[{"kind":"group","tone":"tint","blocks":[{"kind":"check","text":{"en":"I'll be home during the visit","ar":"سأكون في المنزل أثناء الزيارة"}}]}]}},"answer":"b","reason":{"prompt":{"en":"What makes B better?","ar":"ما الذي يجعل B أفضل؟"},"options":[{"id":"area","text":{"en":"The part that reacts to a tap is about 1 cm or more","ar":"الجزء الذي يستجيب للمس نحو 1 سم أو أكثر"}},{"id":"shade","text":{"en":"The grey background looks nicer","ar":"الخلفية الرمادية أجمل"}},{"id":"bigbox","text":{"en":"Its box is bigger","ar":"مربعه أكبر"}}],"answer":["area"],"misconceptions":[{"id":"MC-P01-056","when":["shade","bigbox"],"feedback":{"en":"The box is the same size, and the shading is only here to show you the tap area. What changed is how much of the row reacts to a finger.","ar":"المربع بالحجم نفسه، والتظليل هنا فقط ليُريك مساحة اللمس. ما تغيّر هو مقدار الصف الذي يستجيب للإصبع."}}]},"misconceptions":[{"id":"MC-P01-056","when":["a"],"feedback":{"en":"A 4 mm box is far below 1 cm. Most taps on the words do nothing, and people think the form is broken.","ar":"مربع 4 مم أقل بكثير من 1 سم. وأغلب الضغطات على الكلمات لا تفعل شيئًا، فيظن الناس أن النموذج معطّل."}}],"hints":[{"en":"Where would most people tap: the tiny box, or the words?","ar":"أين سيضغط أغلب الناس: على المربع الصغير، أم على الكلمات؟"}],"correct":{"en":"The tap area grows; the design doesn't have to.","ar":"مساحة اللمس تكبر؛ والتصميم لا يحتاج أن يكبر."},"explain":{"en":"A target is the area that reacts to touch, not the drawing. Make the label part of the checkbox's tap area, and small controls become easy to hit.","ar":"الهدف هو المساحة التي تستجيب للمس، لا الرسم. اجعل النص جزءًا من مساحة لمس الـ Checkbox، فتصبح العناصر الصغيرة سهلة الضغط."},"speaker":"karim"},{"id":"S08","type":"tune","skill":"SK-P01-U05-06","part":"independent","speaker":"youssef","rules":["R14","R19"],"value":{"en":"New case. Reset and Cancel buttons (NN/g): people hit Reset when they meant Submit. \"Empty cart\" beside \"Checkout\" is the same trap in a shop.","ar":"حالة جديدة. أزرار Reset وCancel (NN/g): يضغط الناس Reset وهم يقصدون الإرسال. و«أفرغ السلّة» بجوار «إتمام الشراء» هو الفخ نفسه في متجر."},"ref":{"url":"https://www.nngroup.com/articles/reset-and-cancel-buttons/","quote":"The worst problem about Reset is that users click the button by mistake when they wanted to click Submit."},"scenario":{"en":"In my online shop, the cart ends with two buttons side by side: \"Empty cart\" and \"Checkout\". Ghada had 9 items in her cart, tapped the wrong one, and closed the app.","ar":"في متجري الإلكتروني، تنتهي السلّة بزرّين متجاورين: «أفرغ السلّة» و«إتمام الشراء». وكان في سلّة غادة 9 منتجات، فضغطت الزر الخطأ، وأغلقت التطبيق."},"prompt":{"en":"Try each version of the bottom of the cart. Which one should ship?","ar":"جرّب كل نسخة لأسفل السلّة. أيّها يجب أن تُطلق؟"},"start":"both","options":[{"id":"both","text":{"en":"Keep both side by side","ar":"أبقِ الزرّين متجاورين"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"9 items · 2,340 EGP","ar":"9 منتجات · 2,340 جنيه"}},{"kind":"row","gap":"m","blocks":[{"kind":"button","emphasis":"low","text":{"en":"Empty cart","ar":"أفرغ السلّة"}},{"kind":"button","text":{"en":"Checkout","ar":"إتمام الشراء"}}]}]}},{"id":"only","text":{"en":"Remove \"Empty cart\"; each item keeps its own Remove","ar":"احذف «أفرغ السلّة»؛ ويبقى لكل منتج زر «إزالة» خاص به"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"Each item: − 1 + · Remove","ar":"كل منتج: − 1 + · إزالة"}},{"kind":"small","weight":"bold","text":{"en":"9 items · 2,340 EGP","ar":"9 منتجات · 2,340 جنيه"},"gap":"s"},{"kind":"button","text":{"en":"Checkout","ar":"إتمام الشراء"},"gap":"m"}]}},{"id":"red","text":{"en":"Keep both, and make \"Empty cart\" red","ar":"أبقِ الزرّين، واجعل «أفرغ السلّة» أحمر"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"9 items · 2,340 EGP","ar":"9 منتجات · 2,340 جنيه"}},{"kind":"row","gap":"m","blocks":[{"kind":"button","style":"danger","text":{"en":"Empty cart","ar":"أفرغ السلّة"}},{"kind":"button","text":{"en":"Checkout","ar":"إتمام الشراء"}}]}]}}],"answer":["only"],"misconceptions":[{"id":"MC-P01-057","when":["both","red"],"feedback":{"en":"Red warns the eye, not the thumb. With both side by side, one slip still throws away 9 items. Shoppers rarely need to empty a cart in one tap.","ar":"الأحمر ينبّه العين، لا الإبهام. ومع تجاور الزرّين، تظل زلّة واحدة ترمي 9 منتجات. ونادرًا ما يحتاج المتسوّق أن يُفرغ السلّة بضغطة."}}],"correct":{"en":"The only button at the end is the one people came for.","ar":"الزر الوحيد في النهاية هو الذي جاء الناس من أجله."},"explain":{"en":"Keep the end of a form or cart for the main action. Anything that wipes the work belongs nowhere near it, and usually nowhere at all.","ar":"اترك نهاية النموذج أو السلّة للإجراء الرئيسي. وأي شيء يمسح العمل لا مكان له بجواره، وغالبًا لا مكان له أصلًا."}},{"id":"S09","type":"card","part":"recap","icons":["tap","space","cut","ok"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **No Clear:** removed Clear from beside Send, instead of shrinking it or asking \"Are you sure?\".\n- **Big enough:** turned 5 mm time tags into buttons at least 1 cm tall.\n- **Spaced apart:** separated Edit from Delete, not only made them bigger.\n- **Tap area, not drawing:** made the whole checkbox row react to touch.\n- **Nothing that wipes the work:** removed \"Empty cart\" from beside Checkout.\n\nNext: the skill check for this unit.","ar":"- **بلا مسح:** حذفت «مسح» من جوار «أرسل»، بدل تصغيره أو سؤال «هل أنت متأكد؟».\n- **كبير بما يكفي:** حوّلت علامات المواعيد ذات 5 مم إلى أزرار ارتفاعها 1 سم على الأقل.\n- **متباعد:** فصلت «تعديل» عن «حذف»، لا كبّرتهما فقط.\n- **مساحة اللمس، لا الرسم:** جعلت صف الـ Checkbox كله يستجيب للمس.\n- **لا شيء يمسح العمل:** حذفت «أفرغ السلّة» من جوار «إتمام الشراء».\n\nالتالي: اختبار المهارة لهذه الوحدة."}}]}$uxg$::jsonb),
  ($uxg$P01-U05-L04$uxg$, $uxg$d5006cd36adfdbc952bd0e116a57d084adc7048f257d7f119d40fed314669acf$uxg$, $uxg${"id":"P01-U05-L04","mode":"check","minutes":7,"title":{"en":"Skill check: forms everyone can finish","ar":"اختبار المهارة: نماذج يستطيع الجميع إكمالها"},"speaker":"sara","steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Ismail books a bus ticket","ar":"إسماعيل يحجز تذكرة أتوبيس"},"body":{"en":"I'm reviewing a bus ticket booking form before it launches. Our tester Ismail is blind and uses a keyboard with a screen reader. Our second tester, Samah, tries the same form on her phone.\n\nBoth got stuck in different places. Your job: fix each one so both of them can finish.\n\nThis is a skill check: no hints, and you'll see how you did at the end.","ar":"أراجع نموذج حجز تذاكر أتوبيس قبل إطلاقه. والمختبر إسماعيل كفيف ويستخدم لوحة المفاتيح مع قارئ شاشة. والمختبرة الثانية، سماح، تجرّب النموذج نفسه على هاتفها.\n\nعلق كلاهما في أماكن مختلفة. مهمّتك: أصلح كل واحدة ليُكمل الاثنان.\n\nهذا اختبار مهارة: بدون تلميحات، وسترى نتيجتك في النهاية."},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"From","ar":"من"},"filled":true,"text":{"en":"Cairo","ar":"القاهرة"}},{"kind":"field","label":{"en":"To","ar":"إلى"},"filled":true,"text":{"en":"Luxor","ar":"الأقصر"},"gap":"s"},{"kind":"field","label":{"en":"Date","ar":"التاريخ"},"text":"","gap":"s"},{"kind":"button","text":{"en":"Find buses","ar":"ابحث عن رحلات"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P01-U05-01","part":"check","rules":["R19"],"value":{"en":"Skill check, keyboard accessibility (NN/g): removing the focus indicator is catastrophic for keyboard users.","ar":"اختبار مهارة، الإتاحة بلوحة المفاتيح (NN/g): حذف مؤشّر التركيز كارثة لمستخدمي لوحة المفاتيح."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"Removing the keyboard focus indicator is catastrophic for keyboard users."},"scenario":{"en":"Ismail works with a sighted colleague, Fathy, who follows his screen to help. Neither can tell which field Tab is on: the form has no focus ring.","ar":"يعمل إسماعيل مع زميل مبصر، فتحي، يتابع شاشته ليساعده. ولا يستطيع أيٌّ منهما معرفة الحقل الذي يقف عنده Tab: النموذج بلا إطار تركيز."},"prompt":{"en":"Tab is on the Date field. Try each version. Which one should ship?","ar":"Tab الآن على حقل التاريخ. جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"none","options":[{"id":"ring","text":{"en":"A clear focus ring on whatever Tab is on","ar":"إطار تركيز واضح على أي عنصر يقف عنده Tab"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"From","ar":"من"},"filled":true,"text":{"en":"Cairo","ar":"القاهرة"}},{"kind":"field","label":{"en":"To","ar":"إلى"},"filled":true,"text":{"en":"Luxor","ar":"الأقصر"},"gap":"s"},{"kind":"field","label":{"en":"Date","ar":"التاريخ"},"text":"","focus":true,"gap":"s"}]}},{"id":"none","text":{"en":"Keep it: no ring","ar":"أبقِه: بلا إطار"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"From","ar":"من"},"filled":true,"text":{"en":"Cairo","ar":"القاهرة"}},{"kind":"field","label":{"en":"To","ar":"إلى"},"filled":true,"text":{"en":"Luxor","ar":"الأقصر"},"gap":"s"},{"kind":"field","label":{"en":"Date","ar":"التاريخ"},"text":"","gap":"s"}]}},{"id":"firstonly","text":{"en":"A ring on the first field only, to show where to start","ar":"إطار على الحقل الأول فقط، ليوضّح نقطة البداية"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"From","ar":"من"},"filled":true,"text":{"en":"Cairo","ar":"القاهرة"},"focus":true},{"kind":"field","label":{"en":"To","ar":"إلى"},"filled":true,"text":{"en":"Luxor","ar":"الأقصر"},"gap":"s"},{"kind":"field","label":{"en":"Date","ar":"التاريخ"},"text":"","gap":"s"}]}}],"answer":["ring"],"misconceptions":[{"id":"MC-P01-052","when":["none","firstonly"],"feedback":{"en":"Tab is on Date, but the preview either shows nothing or points at From. The ring has to follow Tab to every stop.","ar":"Tab على التاريخ، لكن المعاينة إما لا تُظهر شيئًا أو تشير إلى «من». والإطار يجب أن يتبع Tab إلى كل محطة."}}],"explain":{"en":"From Lesson 1: the focus ring is the keyboard's pointer. It must be clear and move with Tab.","ar":"من الدرس 1: إطار التركيز هو مؤشّر لوحة المفاتيح. يجب أن يكون واضحًا ويتحرّك مع Tab."},"speaker":"sara"},{"id":"S03","type":"tune","skill":"SK-P01-U05-02","part":"check","rules":["R19"],"value":{"en":"Skill check, keyboard accessibility (NN/g): the tab order is normally coded to reflect the page layout, top to bottom.","ar":"اختبار مهارة، الإتاحة بلوحة المفاتيح (NN/g): ترتيب Tab يُبرمَج عادةً ليعكس تخطيط الصفحة، من أعلى إلى أسفل."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"On most websites the tab order will be coded to reflect the page layout; that is top to bottom and left to right."},"scenario":{"en":"Ismail's screen reader reads \"To\" before \"From\", because the developer added the \"To\" field first.","ar":"قارئ الشاشة عند إسماعيل يقرأ «إلى» قبل «من»، لأن المطوّر أضاف حقل «إلى» أولًا."},"prompt":{"en":"Try each tab order. Which one should ship?","ar":"جرّب كل ترتيب لـ Tab. أيّها يجب أن يُطلق؟"},"start":"code","options":[{"id":"code","text":{"en":"Keep the order it was built in","ar":"أبقِ الترتيب الذي بُني به"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"From","ar":"من"},"text":""},{"kind":"field","label":{"en":"To","ar":"إلى"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date","ar":"التاريخ"},"text":"","gap":"s"},{"kind":"small","color":"brand","text":{"en":"Tab goes: To → From → Date","ar":"ترتيب Tab: إلى ← من ← التاريخ"},"gap":"m"}]}},{"id":"swap","text":{"en":"Swap the fields on screen so To is on top","ar":"بدّل الحقلين على الشاشة ليكون «إلى» في الأعلى"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"To","ar":"إلى"},"text":""},{"kind":"field","label":{"en":"From","ar":"من"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date","ar":"التاريخ"},"text":"","gap":"s"},{"kind":"small","color":"brand","text":{"en":"Tab goes: To → From → Date","ar":"ترتيب Tab: إلى ← من ← التاريخ"},"gap":"m"}]}},{"id":"page","text":{"en":"Fix the code so Tab goes From, To, Date","ar":"أصلح الكود ليكون Tab: من، إلى، التاريخ"},"mock":{"width":300,"blocks":[{"kind":"field","label":{"en":"From","ar":"من"},"text":""},{"kind":"field","label":{"en":"To","ar":"إلى"},"text":"","gap":"s"},{"kind":"field","label":{"en":"Date","ar":"التاريخ"},"text":"","gap":"s"},{"kind":"small","color":"brand","text":{"en":"Tab goes: From → To → Date","ar":"ترتيب Tab: من ← إلى ← التاريخ"},"gap":"m"}]}}],"answer":["page"],"misconceptions":[{"id":"MC-P01-053","when":["code"],"feedback":{"en":"Ismail hears \"To\" first and types Cairo there. Tab order must match the page.","ar":"يسمع إسماعيل «إلى» أولًا فيكتب القاهرة فيه. وترتيب Tab يجب أن يطابق الصفحة."}},{"id":"MC-P01-053","when":["swap"],"feedback":{"en":"It matches now, but every trip form in the world starts with \"From\". Change the code, not what everyone else expects.","ar":"متطابق الآن، لكن كل نماذج الرحلات تبدأ بـ «من». غيّر الكود، لا ما يتوقّعه الجميع."}}],"explain":{"en":"From Lesson 1: when code order and screen order differ, fix the code so Tab follows the page.","ar":"من الدرس 1: حين يختلف ترتيب الكود عن ترتيب الشاشة، أصلح الكود ليتبع Tab الصفحة."},"speaker":"sara"},{"id":"S04","type":"tune","skill":"SK-P01-U05-03","part":"check","rules":["R19"],"value":{"en":"Skill check, keyboard accessibility (NN/g): keyboard users must be able to access all interactive elements. Painted + and − icons aren't on the Tab path.","ar":"اختبار مهارة، الإتاحة بلوحة المفاتيح (NN/g): يجب أن يصل مستخدمو لوحة المفاتيح إلى كل العناصر التفاعلية. وأيقونتا + و− المرسومتان ليستا في مسار Tab."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"Keyboard users must be able to access all interactive elements, not just the main navigation or in-line links."},"scenario":{"en":"Ismail travels with his son. The number of passengers changes with + and − icons, built as pictures with a click script. Tab skips them, so he can only book one seat.","ar":"يسافر إسماعيل مع ابنه. وعدد الركّاب يتغيّر بأيقونتي + و−، مبنيّتين كصورتين مع كود للضغط. ويتخطّاهما Tab، فلا يستطيع حجز إلا مقعد واحد."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"pics","options":[{"id":"pics","text":{"en":"Keep the picture icons","ar":"أبقِ الأيقونات المصوّرة"},"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Passengers","ar":"الركّاب"},"text":"1"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Date → Find buses (skips − and +)","ar":"ترتيب Tab: التاريخ ← ابحث عن رحلات (يتخطّى − و+)"},"gap":"m"}]}},{"id":"buttons","text":{"en":"Rebuild − and + as real buttons","ar":"أعد بناء − و+ كأزرار حقيقية"},"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Passengers","ar":"الركّاب"},"text":"2"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Date → Fewer (−) → More (+) → Find buses","ar":"ترتيب Tab: التاريخ ← أقل (−) ← أكثر (+) ← ابحث عن رحلات"},"gap":"m"}]}},{"id":"tip","text":{"en":"Add a tip: \"Click + to add passengers\"","ar":"أضف تلميحًا: «اضغط + لإضافة ركّاب»"},"mock":{"width":300,"blocks":[{"kind":"stepper","label":{"en":"Passengers","ar":"الركّاب"},"text":"1"},{"kind":"small","color":"muted","text":{"en":"Click + to add passengers.","ar":"اضغط + لإضافة ركّاب."},"gap":"xs"},{"kind":"small","color":"brand","text":{"en":"Tab goes: Date → Find buses (skips − and +)","ar":"ترتيب Tab: التاريخ ← ابحث عن رحلات (يتخطّى − و+)"},"gap":"m"}]}}],"answer":["buttons"],"misconceptions":[{"id":"MC-P01-054","when":["pics","tip"],"feedback":{"en":"Tab still skips + and −, so telling Ismail to click them doesn't help. Real buttons put them on his path.","ar":"ما زال Tab يتخطّى + و−، فإخبار إسماعيل بالضغط عليهما لا يفيد. والأزرار الحقيقية تضعهما في مساره."}}],"explain":{"en":"From Lesson 2: anything clickable must be a real control, so Tab reaches it.","ar":"من الدرس 2: كل ما يمكن الضغط عليه يجب أن يكون عنصرًا حقيقيًا، ليصل إليه Tab."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P01-U05-04","part":"check","rules":["R19"],"value":{"en":"Skill check, keyboard accessibility (NN/g): people must be able to close pop-ups, or they're stuck inside them.","ar":"اختبار مهارة، الإتاحة بلوحة المفاتيح (NN/g): يجب أن يستطيع الناس إغلاق النوافذ المنبثقة، وإلا علقوا بداخلها."},"ref":{"url":"https://www.nngroup.com/articles/keyboard-accessibility/","quote":"It is extremely important for users to be able to close pop-ups or they will be stuck inside them."},"scenario":{"en":"\"See bus photos\" opens a gallery pop-up. It closes only when you click the dark area around it. Ismail opened it by mistake.","ar":"«شاهد صور الأتوبيس» يفتح معرض صور منبثقًا. ولا يُغلق إلا بالضغط على المساحة الداكنة حوله. وفتحه إسماعيل بالخطأ."},"prompt":{"en":"Try each version of the gallery. Which one should ship?","ar":"جرّب كل نسخة للمعرض. أيّها يجب أن تُطلق؟"},"start":"outside","options":[{"id":"outside","text":{"en":"Keep it: click outside to close","ar":"أبقِه: اضغط بالخارج للإغلاق"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"image","size":"s","text":{"en":"Bus photo 1 of 6","ar":"صورة الأتوبيس 1 من 6"}},{"kind":"button","emphasis":"low","text":{"en":"Next photo","ar":"الصورة التالية"},"gap":"s"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Next photo → Next photo … (no way out)","ar":"ترتيب Tab: الصورة التالية ← الصورة التالية … (بلا مخرج)"},"gap":"m"}]}},{"id":"end","text":{"en":"Close it by itself after the last photo","ar":"أغلِقه تلقائيًا بعد آخر صورة"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"image","size":"s","text":{"en":"Bus photo 1 of 6","ar":"صورة الأتوبيس 1 من 6"}},{"kind":"button","emphasis":"low","text":{"en":"Next photo","ar":"الصورة التالية"},"gap":"s"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Next photo × 6, then it closes","ar":"ترتيب Tab: الصورة التالية 6 مرات، ثم يُغلق"},"gap":"m"}]}},{"id":"close","text":{"en":"A Close button on the Tab path, and Esc closes it","ar":"زر إغلاق في مسار Tab، وEsc يغلقه"},"mock":{"width":300,"blocks":[{"kind":"group","blocks":[{"kind":"button","style":"plain","text":{"en":"Close photos","ar":"أغلق الصور"}},{"kind":"image","size":"s","text":{"en":"Bus photo 1 of 6","ar":"صورة الأتوبيس 1 من 6"},"gap":"xs"},{"kind":"button","emphasis":"low","text":{"en":"Next photo","ar":"الصورة التالية"},"gap":"s"}]},{"kind":"small","color":"brand","text":{"en":"Tab goes: Close photos → Next photo. Esc closes it too.","ar":"ترتيب Tab: أغلق الصور ← الصورة التالية. وEsc يغلقه أيضًا."},"gap":"m"}]}}],"answer":["close"],"misconceptions":[{"id":"MC-P01-055","when":["outside","end"],"feedback":{"en":"Ismail can't click outside, and he shouldn't have to sit through 6 photos he can't see to get out. Give him Close and Esc.","ar":"لا يستطيع إسماعيل الضغط بالخارج، ولا يصح أن يمرّ على 6 صور لا يراها ليخرج. أعطِه زر إغلاق وEsc."}}],"explain":{"en":"From Lesson 2: every pop-up needs a reachable Close button and Esc, so people leave when they choose.","ar":"من الدرس 2: كل نافذة منبثقة تحتاج زر إغلاق يمكن الوصول إليه وEsc، ليخرج الناس متى اختاروا."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P01-U05-05","part":"check","rules":["R19"],"value":{"en":"Skill check, touch targets (NN/g): to avoid accidental taps, targets must be big enough and spaced well enough.","ar":"اختبار مهارة، أهداف اللمس (NN/g): لتجنّب الضغطات العرضية، يجب أن تكون الأهداف كبيرة بما يكفي ومتباعدة بما يكفي."},"ref":{"url":"https://www.nngroup.com/articles/touch-target-size/","quote":"To avoid accidental taps, targets must first be big enough, and then also spaced well enough"},"scenario":{"en":"On her phone, Samah picks a departure time from a list of links, each about 4 mm tall with no space between them. She booked the 6 pm bus instead of the 7 pm.","ar":"على هاتفها، تختار سماح وقت الرحلة من قائمة روابط، ارتفاع كل منها نحو 4 مم بلا مسافات بينها. فحجزت رحلة السادسة بدل السابعة."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"links","options":[{"id":"links","text":{"en":"Keep the small links, packed together","ar":"أبقِ الروابط الصغيرة المتلاصقة"},"mock":{"width":300,"blocks":[{"kind":"link","text":{"en":"6:00 pm · 210 EGP","ar":"6:00 م · 210 جنيه"}},{"kind":"link","text":{"en":"7:00 pm · 210 EGP","ar":"7:00 م · 210 جنيه"},"gap":"xs"},{"kind":"link","text":{"en":"9:30 pm · 180 EGP","ar":"9:30 م · 180 جنيه"},"gap":"xs"}]}},{"id":"rows","text":{"en":"Make each time a full-width button at least 1 cm tall, with space between","ar":"اجعل كل وقت زرًا بعرض الشاشة وارتفاع 1 سم على الأقل، مع مسافة بينها"},"mock":{"width":300,"blocks":[{"kind":"button","emphasis":"low","text":{"en":"6:00 pm · 210 EGP","ar":"6:00 م · 210 جنيه"}},{"kind":"button","emphasis":"low","text":{"en":"7:00 pm · 210 EGP","ar":"7:00 م · 210 جنيه"},"gap":"m"},{"kind":"button","emphasis":"low","text":{"en":"9:30 pm · 180 EGP","ar":"9:30 م · 180 جنيه"},"gap":"m"}]}},{"id":"zoom","text":{"en":"Keep the links, and add \"Pinch to zoom\"","ar":"أبقِ الروابط، وأضف «باعد بإصبعيك للتكبير»"},"mock":{"width":300,"blocks":[{"kind":"small","color":"muted","text":{"en":"Pinch to zoom.","ar":"باعد بإصبعيك للتكبير."}},{"kind":"link","text":{"en":"6:00 pm · 210 EGP","ar":"6:00 م · 210 جنيه"},"gap":"xs"},{"kind":"link","text":{"en":"7:00 pm · 210 EGP","ar":"7:00 م · 210 جنيه"},"gap":"xs"},{"kind":"link","text":{"en":"9:30 pm · 180 EGP","ar":"9:30 م · 180 جنيه"},"gap":"xs"}]}}],"answer":["rows"],"misconceptions":[{"id":"MC-P01-056","when":["links","zoom"],"feedback":{"en":"4 mm with no gap is far below 1 cm, so Samah's thumb lands on the neighbour. Asking her to zoom passes our problem to her.","ar":"4 مم بلا مسافة أقل بكثير من 1 سم، فيقع إبهام سماح على الجار. وطلب التكبير منها ينقل مشكلتنا إليها."}}],"explain":{"en":"From Lesson 3: at least 1 cm per target, and space between them.","ar":"من الدرس 3: 1 سم على الأقل لكل هدف، ومسافة بين الأهداف."},"speaker":"sara"},{"id":"S07","type":"tune","skill":"SK-P01-U05-06","part":"check","rules":["R19"],"value":{"en":"Skill check, Reset and Cancel buttons (NN/g): people click Reset by mistake when they meant Submit.","ar":"اختبار مهارة، أزرار Reset وCancel (NN/g): يضغط الناس Reset بالخطأ وهم يقصدون الإرسال."},"ref":{"url":"https://www.nngroup.com/articles/reset-and-cancel-buttons/","quote":"The worst problem about Reset is that users click the button by mistake when they wanted to click Submit."},"scenario":{"en":"The last screen has \"Start over\" beside \"Book seats\". \"Start over\" empties every step. Samah hit it once while trying to book.","ar":"الشاشة الأخيرة فيها «ابدأ من جديد» بجوار «احجز المقاعد». و«ابدأ من جديد» يُفرغ كل الخطوات. وضغطته سماح مرة وهي تحاول الحجز."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن تُطلق؟"},"start":"both","options":[{"id":"both","text":{"en":"Keep \"Start over\" beside \"Book seats\"","ar":"أبقِ «ابدأ من جديد» بجوار «احجز المقاعد»"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Cairo → Luxor · 2 seats · 420 EGP","ar":"القاهرة ← الأقصر · مقعدان · 420 جنيه"}},{"kind":"row","gap":"m","blocks":[{"kind":"button","emphasis":"low","text":{"en":"Start over","ar":"ابدأ من جديد"}},{"kind":"button","text":{"en":"Book seats","ar":"احجز المقاعد"}}]}]}},{"id":"confirm","text":{"en":"Keep it, but ask \"Are you sure?\" first","ar":"أبقِه، لكن اسأل «هل أنت متأكد؟» أولًا"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Cairo → Luxor · 2 seats · 420 EGP","ar":"القاهرة ← الأقصر · مقعدان · 420 جنيه"}},{"kind":"row","gap":"m","blocks":[{"kind":"button","emphasis":"low","text":{"en":"Start over","ar":"ابدأ من جديد"}},{"kind":"button","text":{"en":"Book seats","ar":"احجز المقاعد"}}]},{"kind":"small","color":"muted","text":{"en":"\"Start over\" opens: Are you sure? Yes / No","ar":"«ابدأ من جديد» يفتح: هل أنت متأكد؟ نعم / لا"},"gap":"s"}]}},{"id":"none","text":{"en":"Remove \"Start over\"; each step keeps its own Edit","ar":"احذف «ابدأ من جديد»؛ ولكل خطوة زر «تعديل» خاص بها"},"mock":{"width":300,"blocks":[{"kind":"small","weight":"bold","text":{"en":"Cairo → Luxor · 2 seats · 420 EGP","ar":"القاهرة ← الأقصر · مقعدان · 420 جنيه"}},{"kind":"small","color":"muted","text":{"en":"Trip · Edit    Seats · Edit","ar":"الرحلة · تعديل    المقاعد · تعديل"},"gap":"xs"},{"kind":"button","text":{"en":"Book seats","ar":"احجز المقاعد"},"gap":"m"}]}}],"answer":["none"],"misconceptions":[{"id":"MC-P01-057","when":["both","confirm"],"feedback":{"en":"A button that wipes everything still sits where Samah taps to finish. A dialog only adds a scary step. Let people edit one step instead.","ar":"زر يمسح كل شيء ما زال حيث تضغط سماح للإنهاء. والنافذة تضيف خطوة مخيفة فقط. دع الناس يعدّلون خطوة واحدة بدلًا من ذلك."}}],"explain":{"en":"From Lesson 3: keep the end of a form for the main action, and let people change one part instead of wiping all of it.","ar":"من الدرس 3: اترك نهاية النموذج للإجراء الرئيسي، ودع الناس يغيّرون جزءًا واحدًا بدل مسح كل شيء."},"speaker":"sara"}]}$uxg$::jsonb),
  ($uxg$P10-U01-L01$uxg$, $uxg$3d5256bf371df9800ac15ca5b2315022c568e396e004c67fb946a825d83b1f4d$uxg$, $uxg${"id":"P10-U01-L01","mode":"lesson","minutes":8,"title":{"en":"Put what decides it first","ar":"ضع ما يحسم القرار أولًا"},"speaker":"sara","review_labels":{"MC-P10-001":{"en":"The biggest thing isn't always the most important","ar":"الأكبر ليس دائمًا الأهم"},"MC-P10-003":{"en":"Make no more than two things big","ar":"لا تكبّر أكثر من عنصرين"},"MC-P10-004":{"en":"The first words carry the decision","ar":"الكلمات الأولى تحمل القرار"},"MC-P10-005":{"en":"The main button goes right after the facts","ar":"الزر الرئيسي يأتي بعد المعلومات مباشرة"},"MC-P10-006":{"en":"The order follows the decision","ar":"الترتيب يتبع القرار"},"MC-P10-015":{"en":"Don't block the decision with promotion","ar":"لا تعرقل القرار بالترويج"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Meet Reem","ar":"تعرّف على ريم"},"body":{"en":"I'm designing the page for a free beginner workshop. Reem wants one next week. She works until 17:00, so she can only come in the evening.\n\nShe opens this page on her phone. Can she tell, quickly, whether the time works for her?","ar":"أصمّم صفحة ورشة مجانية للمبتدئين. تبحث ريم عن ورشة كهذه في الأسبوع القادم. دوامها ينتهي الساعة 17:00، فلا تستطيع الحضور إلا مساءً.\n\nفتحت هذه الصفحة على هاتفها. هل تعرف بسرعة إن كان الموعد يناسبها؟"},"mock":{"blocks":[{"kind":"image","size":"l","text":{"en":"Photo: Learn together","ar":"صورة: نتعلّم معًا"}},{"kind":"banner","text":{"en":"Get the monthly newsletter","ar":"اشترك في النشرة الشهرية"},"gap":"m"},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P10-U01-01","part":"try","rules":["R12"],"value":{"en":"NN/g eyetracking: people spend about 57% of their viewing time above the fold, so the top of the page belongs to what the visitor needs to decide, not to promotion.","ar":"تتبّع العين في NN/g: يقضي الناس نحو 57% من وقت المشاهدة فوق خط الطيّ (Fold)، فأعلى الصفحة لما يحتاجه الزائر ليقرّر، لا للترويج."},"ref":{"url":"https://www.nngroup.com/articles/scrolling-and-attention/","quote":"Reserve the top of the page for high-priority content"},"prompt":{"en":"What should come first on Reem's phone? Try each order.","ar":"ماذا يجب أن يأتي أولًا على هاتف ريم؟ جرّب كل ترتيب."},"mock":{"caption":{"en":"Now","ar":"الآن"},"height":380,"blocks":[{"kind":"image","size":"l","text":{"en":"Photo: Learn together","ar":"صورة: نتعلّم معًا"}},{"kind":"banner","text":{"en":"Get the monthly newsletter","ar":"اشترك في النشرة الشهرية"},"gap":"m"},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]},"options":[{"id":"button","text":{"en":"The Reserve button first, then the rest","ar":"زر الحجز أولًا، ثم الباقي"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"}},{"kind":"image","size":"l","text":{"en":"Photo: Learn together","ar":"صورة: نتعلّم معًا"},"gap":"m"},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"}]}},{"id":"facts","text":{"en":"Title, time, place and price first, then Reserve; the photo and newsletter after","ar":"العنوان والموعد والمكان والسعر أولًا، ثم زر الحجز؛ والصورة والنشرة بعدها"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"},{"kind":"image","size":"m","text":{"en":"Photo: Learn together","ar":"صورة: نتعلّم معًا"},"gap":"l"},{"kind":"banner","text":{"en":"Get the monthly newsletter","ar":"اشترك في النشرة الشهرية"},"gap":"m"}]}},{"id":"bigger","text":{"en":"Keep the photo first, but make it smaller","ar":"أبقِ الصورة أولًا، لكن صغّرها"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"image","size":"s","text":{"en":"Photo: Learn together","ar":"صورة: نتعلّم معًا"}},{"kind":"banner","text":{"en":"Get the monthly newsletter","ar":"اشترك في النشرة الشهرية"},"gap":"m"},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"}]}}],"answer":["facts"],"misconceptions":[{"id":"MC-P10-006","when":["button"],"feedback":{"en":"Now Reem is asked to reserve before she knows the time. Put the facts she decides with first, then the button.","ar":"الآن يُطلب من ريم أن تحجز قبل أن تعرف الموعد. ضع المعلومات التي تقرّر بها أولًا، ثم الزر."}},{"id":"MC-P10-015","when":["bigger"],"feedback":{"en":"The photo and the newsletter banner still come before the time. Smaller promotion is still promotion in the way.","ar":"الصورة وشريط النشرة ما زالا قبل الموعد. الترويج الأصغر ما زال ترويجًا يعترض الطريق."}}],"hints":[{"en":"Reem has one question: does the time work for her? Where would she look first?","ar":"لدى ريم سؤال واحد: هل يناسبها الموعد؟ أين ستنظر أولًا؟"},{"en":"Can she decide to reserve before she knows the time and place?","ar":"هل تستطيع أن تقرّر الحجز قبل أن تعرف الموعد والمكان؟"}],"correct":{"en":"The facts that decide it, then the action.","ar":"المعلومات التي تحسم القرار، ثم الإجراء."},"explain":{"en":"People spend more than half of their viewing time above the fold. Spend that space on what Reem decides with: what, when, where, how much. Then the Reserve button.","ar":"يقضي الناس أكثر من نصف وقت المشاهدة فوق خط الطيّ. اصرف هذه المساحة على ما تقرّر به ريم: ماذا ومتى وأين وبكم. ثم زر الحجز."}},{"id":"S03","type":"card","part":"concept","icons":["fold","size","text","target"],"title":{"en":"The top of the page decides","ar":"أعلى الصفحة يحسم القرار"},"body":{"en":"- **The first screen:** people spend more than half of their viewing time above the fold. Put what the visitor decides with there.\n- **Two big things at most:** make the most important element biggest, and no more than two elements big. If everything stands out, nothing does.\n- **Key fact first:** in every piece of text, the first words should carry the decision. This is the inverted pyramid.\n- **Action after the facts:** the main button comes right after what people need to decide, high on the page.","ar":"- **الشاشة الأولى:** يقضي الناس أكثر من نصف وقت المشاهدة فوق خط الطيّ (Fold). ضع هناك ما يقرّر به الزائر.\n- **عنصران كبيران فقط:** اجعل الأهم هو الأكبر، ولا تكبّر أكثر من عنصرين. إن برز كل شيء، فلن يبرز شيء.\n- **المعلومة الأهم أولًا:** في كل نص، يجب أن تحمل الكلمات الأولى ما يحسم القرار. هذا هو الهرم المقلوب (Inverted pyramid).\n- **الإجراء بعد المعلومات:** الزر الرئيسي يأتي بعد ما يحتاجه الناس للقرار مباشرة، في أعلى الصفحة."}},{"id":"S04","type":"tune","skill":"SK-P10-U01-02","part":"guided","rules":["R06","R13"],"value":{"en":"NN/g: limit big elements to a maximum of 2 so they stand out. When the title, time, place, price and seats are all bold and big, nothing leads.","ar":"NN/g: لا تكبّر أكثر من عنصرين حتى يبرزا فعلًا. حين يكون العنوان والموعد والمكان والسعر والأماكن كلها عريضة وكبيرة، لا شيء يقود."},"ref":{"url":"https://www.nngroup.com/articles/visual-hierarchy-ux-definition/","quote":"Limit how many elements are big to a maximum of 2"},"prompt":{"en":"A teammate made every fact big and bold so \"nothing gets missed\". Try each version. Which one should ship?","ar":"جعل زميلك كل المعلومات كبيرة وعريضة حتى «لا يفوت شيء». جرّب كل نسخة. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"title","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"title","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"title","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"title","text":{"en":"4 places left","ar":"باقي 4 أماكن"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]},"options":[{"id":"photo","text":{"en":"Make a photo the biggest thing, with all the facts small","ar":"اجعل صورة هي الأكبر، وكل المعلومات صغيرة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"image","size":"l","text":{"en":"Photo: Learn together","ar":"صورة: نتعلّم معًا"}},{"kind":"small","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"s"},{"kind":"small","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"xs"},{"kind":"small","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"xs"},{"kind":"small","text":{"en":"Free","ar":"مجاني"},"gap":"xs"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}},{"id":"all","text":{"en":"Keep everything big and bold","ar":"أبقِ كل شيء كبيرًا وعريضًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"title","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"title","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"title","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"title","text":{"en":"4 places left","ar":"باقي 4 أماكن"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}},{"id":"two","text":{"en":"Title biggest, the time second, the rest in regular text","ar":"العنوان الأكبر، ثم الموعد، والباقي بنص عادي"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"heading","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"xs"},{"kind":"chip","text":{"en":"4 places left","ar":"باقي 4 أماكن"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}}],"answer":["two"],"misconceptions":[{"id":"MC-P10-003","when":["all"],"feedback":{"en":"Five big lines compete, so none of them leads and Reem reads them all at the same weight. Choose two to make big.","ar":"خمسة أسطر كبيرة تتنافس، فلا يقود أيّ منها، وتقرؤها ريم كلها بالوزن نفسه. اختر عنصرين فقط لتكبيرهما."}},{"id":"MC-P10-001","when":["photo"],"feedback":{"en":"Now the biggest thing is the one that tells Reem nothing about the time. Size should follow what she decides with.","ar":"الآن الأكبر هو الشيء الذي لا يخبر ريم بشيء عن الموعد. الحجم يجب أن يتبع ما تقرّر به."}}],"hints":[{"en":"If everything is big, what stands out?","ar":"إذا كان كل شيء كبيرًا، فما الذي يبرز؟"},{"en":"How many things should be big at most, and which fact decides it for Reem?","ar":"كم عنصرًا يجب أن يكون كبيرًا على الأكثر، وما المعلومة التي تحسم القرار لريم؟"}],"correct":{"en":"Two levels of big, and the rest calm.","ar":"مستويان من الحجم الكبير، والباقي هادئ."},"explain":{"en":"Make the most important element biggest, and no more than two elements big. The title says what it is; the time says if Reem can come. Everything else can be regular text.","ar":"اجعل الأهم هو الأكبر، ولا تكبّر أكثر من عنصرين. العنوان يقول ما هي الورشة، والموعد يقول إن كانت ريم تستطيع الحضور. والباقي يمكن أن يكون نصًّا عاديًا."}},{"id":"S05","type":"tune","skill":"SK-P10-U01-01","part":"guided","confidence":true,"rules":["R06","R15"],"value":{"en":"NN/g: keep major calls to action above the fold. A Reserve button after a long description is far from the facts that justify it.","ar":"NN/g: أبقِ أزرار الإجراء الرئيسية فوق خط الطيّ. زر الحجز بعد وصف طويل بعيد عن المعلومات التي تبرّره."},"ref":{"url":"https://www.nngroup.com/articles/scrolling-and-attention/","quote":"Keep major CTAs above the fold."},"prompt":{"en":"The page now has a long description, and Reserve sits under it. Where should Reserve go?","ar":"أصبح في الصفحة وصف طويل، وزر الحجز تحته. أين يجب أن يكون الزر؟"},"mock":{"caption":{"en":"Now: first screen","ar":"الآن: الشاشة الأولى"},"height":420,"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"text","text":{"en":"In two hours you'll learn how designers turn an idea into screens. We start with what makes an app easy to use, look at a few real examples, and talk about why some screens confuse people.","ar":"خلال ساعتين ستتعلّم كيف يحوّل المصمّمون الفكرة إلى شاشات. نبدأ بما يجعل التطبيق سهل الاستخدام، ونرى أمثلة حقيقية، ونتحدّث عن سبب ارتباك الناس أمام بعض الشاشات."},"gap":"m"},{"kind":"text","text":{"en":"Then you'll sketch your own app on paper, get feedback from the group, and leave with a plan for your next steps.","ar":"ثم ترسم تطبيقك على الورق، وتحصل على ملاحظات المجموعة، وتخرج بخطة لخطواتك التالية."},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"l"}]},"options":[{"id":"top","text":{"en":"At the very top, above the title","ar":"في أعلى الصفحة، فوق العنوان"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"}},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"text","text":{"en":"In two hours you'll learn how designers turn an idea into screens…","ar":"خلال ساعتين ستتعلّم كيف يحوّل المصمّمون الفكرة إلى شاشات…"},"gap":"m"}]}},{"id":"after","text":{"en":"Right after the time and price, with the description below it","ar":"بعد الموعد والسعر مباشرة، والوصف تحته"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"},{"kind":"text","text":{"en":"In two hours you'll learn how designers turn an idea into screens…","ar":"خلال ساعتين ستتعلّم كيف يحوّل المصمّمون الفكرة إلى شاشات…"},"gap":"l"}]}},{"id":"end","text":{"en":"Keep it under the description, so people read everything first","ar":"أبقِه تحت الوصف، حتى يقرأ الناس كل شيء أولًا"},"mock":{"caption":{"en":"After this change: first screen","ar":"بعد هذا التغيير: الشاشة الأولى"},"height":420,"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"text","text":{"en":"In two hours you'll learn how designers turn an idea into screens. We start with what makes an app easy to use, look at a few real examples, and talk about why some screens confuse people.","ar":"خلال ساعتين ستتعلّم كيف يحوّل المصمّمون الفكرة إلى شاشات. نبدأ بما يجعل التطبيق سهل الاستخدام، ونرى أمثلة حقيقية، ونتحدّث عن سبب ارتباك الناس أمام بعض الشاشات."},"gap":"m"},{"kind":"text","text":{"en":"Then you'll sketch your own app on paper, get feedback from the group, and leave with a plan for your next steps.","ar":"ثم ترسم تطبيقك على الورق، وتحصل على ملاحظات المجموعة، وتخرج بخطة لخطواتك التالية."},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"l"}]}}],"answer":["after"],"misconceptions":[{"id":"MC-P10-005","when":["end"],"feedback":{"en":"On a phone the button drops below the first screen, away from the time and price that made Reem want it. Most people won't read the whole description first.","ar":"على الهاتف ينزل الزر تحت الشاشة الأولى، بعيدًا عن الموعد والسعر اللذين جعلا ريم تريده. ومعظم الناس لن يقرؤوا الوصف كله أولًا."}},{"id":"MC-P10-006","when":["top"],"feedback":{"en":"Now the button asks Reem to commit before she has seen the time. Facts first, then the action.","ar":"الآن يطلب الزر من ريم أن تلتزم قبل أن ترى الموعد. المعلومات أولًا، ثم الإجراء."}}],"hints":[{"en":"When has Reem got what she needs to decide?","ar":"متى تكون لدى ريم كل ما تحتاجه لتقرّر؟"},{"en":"Should she scroll past the whole description to act, or reserve before she knows the time?","ar":"هل يجب أن تمرّ على الوصف كله لتتصرّف، أم تحجز قبل أن تعرف الموعد؟"}],"correct":{"en":"Decide, then act, on the first screen.","ar":"قرّر ثم تصرّف، في الشاشة الأولى."},"explain":{"en":"Keep the main action above the fold. Put Reserve right after the facts that justify it; people who want more can keep reading below.","ar":"أبقِ الإجراء الرئيسي فوق خط الطيّ. ضع زر الحجز بعد المعلومات التي تبرّره مباشرة، ومن يريد المزيد يكمل القراءة تحته."}},{"id":"S06","type":"compare","skill":"SK-P10-U01-03","part":"contrast","rules":["R11","R15"],"value":{"en":"NN/g's inverted pyramid: the first sentence of every paragraph should be the most important, because people scan. A friendly opening that delays the time costs the decision.","ar":"الهرم المقلوب من NN/g: الجملة الأولى في كل فقرة يجب أن تكون الأهم، لأن الناس يتصفّحون بسرعة. والمقدّمة اللطيفة التي تؤخّر الموعد تضيّع القرار."},"ref":{"url":"https://www.nngroup.com/articles/inverted-pyramid/","quote":"The first sentence of every paragraph should be the most important."},"prompt":{"en":"Reem reads only the first line of each description. In which version does that line tell her if she can come?","ar":"تقرأ ريم السطر الأول فقط من كل وصف. في أي نسخة يخبرها هذا السطر إن كانت تستطيع الحضور؟"},"a":{"mock":{"blocks":[{"kind":"heading","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"text","text":{"en":"Join a relaxed, friendly evening where you'll discover how designers think and meet people who love apps as much as you do. It runs from 18:00 to 20:00 and it's free.","ar":"انضم إلى أمسية هادئة وودودة تكتشف فيها كيف يفكّر المصمّمون، وتلتقي بأشخاص يحبّون التطبيقات مثلك. تبدأ الساعة 18:00 وتنتهي الساعة 20:00، وهي مجانية."},"gap":"s"}]}},"b":{"mock":{"blocks":[{"kind":"heading","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"text","text":{"en":"Free, from 18:00 to 20:00 on Tuesday. You'll sketch your first app screens on paper, with no design tool needed, and meet people who love apps as much as you do.","ar":"مجانية، من 18:00 إلى 20:00 يوم الثلاثاء. سترسم أول شاشات تطبيقك على الورق، دون أي أداة تصميم، وتلتقي بأشخاص يحبّون التطبيقات مثلك."},"gap":"s"}]}},"answer":"b","reason":{"prompt":{"en":"What makes B work?","ar":"ما الذي يجعل B تنجح؟"},"options":[{"id":"short","text":{"en":"It's shorter","ar":"لأنها أقصر"}},{"id":"tone","text":{"en":"Its tone is friendlier","ar":"لأن أسلوبها أكثر ودًّا"}},{"id":"first","text":{"en":"The time and price come in its first words","ar":"لأن الموعد والسعر في كلماتها الأولى"}}],"answer":["first"],"misconceptions":[{"id":"MC-P10-004","when":["short","tone"],"feedback":{"en":"Both are about the same length and both are friendly. The difference is where the time and price sit.","ar":"النصّان بالطول نفسه تقريبًا، وكلاهما ودود. الفرق هو مكان الموعد والسعر."}}]},"misconceptions":[{"id":"MC-P10-004","when":["a"],"feedback":{"en":"A's first line is all welcome and no facts. The time only arrives at the end, after Reem has stopped reading.","ar":"السطر الأول في A ترحيب فقط بلا معلومات. والموعد لا يأتي إلا في النهاية، بعد أن تتوقّف ريم عن القراءة."}}],"hints":[{"en":"Read only the first line of each version.","ar":"اقرأ السطر الأول فقط من كل نسخة."},{"en":"Which first line tells her the time?","ar":"أي سطر أول يخبرها بالموعد؟"}],"correct":{"en":"Lead with the facts; the warmth can follow.","ar":"ابدأ بالمعلومات، والودّ يأتي بعدها."},"explain":{"en":"People rarely read carefully on screens, so writing should follow the inverted pyramid: the conclusion first. Same words, better order.","ar":"الناس نادرًا ما يقرؤون بتمعّن على الشاشات، لذلك يجب أن تتبع الكتابة الهرم المقلوب: الخلاصة أولًا. الكلمات نفسها، بترتيب أفضل."}},{"id":"S07","type":"tune","skill":"SK-P10-U01-01","part":"independent","confidence":true,"rules":["R14","R19"],"value":{"en":"New case: on a delivery tracking screen the decision is \"when will it arrive?\". The arrival time leads; a big map and a promo don't.","ar":"حالة جديدة: في شاشة تتبّع التوصيل، السؤال هو «متى يصل الطلب؟». وقت الوصول يتصدّر، لا الخريطة الكبيرة ولا العرض الترويجي."},"ref":{"url":"https://www.nngroup.com/articles/inverted-pyramid/","quote":"the most important information"},"scenario":{"en":"My next project is a food delivery app. Lina ordered dinner, and she opens the tracking screen to see when it will arrive, so she can be at the door.","ar":"مشروعي التالي تطبيق لتوصيل الطعام. طلبت لينا العشاء، وفتحت شاشة التتبّع لتعرف متى يصل، حتى تكون عند الباب."},"prompt":{"en":"Try each version. Which one should ship?","ar":"جرّب كل نسخة. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"blocks":[{"kind":"banner","text":{"en":"20% off your next order","ar":"خصم 20% على طلبك القادم"}},{"kind":"image","size":"l","text":{"en":"Map","ar":"خريطة"},"gap":"m"},{"kind":"meta","text":{"en":"Order A-2291: 2 shawarma, 1 salad","ar":"الطلب A-2291: 2 شاورما، 1 سلطة"},"gap":"m"},{"kind":"meta","text":{"en":"Arriving 19:40","ar":"يصل الساعة 19:40"},"gap":"s"},{"kind":"meta","text":{"en":"Driver: Karim · Call","ar":"السائق: كريم · اتصال"},"gap":"s"}]},"options":[{"id":"map","text":{"en":"Make the map full-screen so she can follow the driver","ar":"اجعل الخريطة بملء الشاشة حتى تتابع السائق"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"image","size":"xl","text":{"en":"Map","ar":"خريطة"}},{"kind":"meta","text":{"en":"Arriving 19:40","ar":"يصل الساعة 19:40"},"gap":"s"}]}},{"id":"promo","text":{"en":"Keep the order, but make the offer smaller","ar":"أبقِ الترتيب، لكن صغّر العرض"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"small","text":{"en":"20% off your next order","ar":"خصم 20% على طلبك القادم"}},{"kind":"image","size":"l","text":{"en":"Map","ar":"خريطة"},"gap":"m"},{"kind":"meta","text":{"en":"Order A-2291: 2 shawarma, 1 salad","ar":"الطلب A-2291: 2 شاورما، 1 سلطة"},"gap":"m"},{"kind":"meta","text":{"en":"Arriving 19:40","ar":"يصل الساعة 19:40"},"gap":"s"}]}},{"id":"time","text":{"en":"The arrival time first and biggest, then the driver, the order and a smaller map; the offer last","ar":"وقت الوصول أولًا وبأكبر حجم، ثم السائق والطلب وخريطة أصغر؛ والعرض في الأخير"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Arriving 19:40","ar":"يصل الساعة 19:40"}},{"kind":"meta","text":{"en":"Driver: Karim · Call","ar":"السائق: كريم · اتصال"},"gap":"s"},{"kind":"meta","text":{"en":"Order A-2291: 2 shawarma, 1 salad","ar":"الطلب A-2291: 2 شاورما، 1 سلطة"},"gap":"s"},{"kind":"image","size":"m","text":{"en":"Map","ar":"خريطة"},"gap":"m"},{"kind":"small","text":{"en":"20% off your next order","ar":"خصم 20% على طلبك القادم"},"gap":"l"}]}}],"answer":["time"],"misconceptions":[{"id":"MC-P10-001","when":["map"],"feedback":{"en":"The map is the biggest thing on screen, but Lina still has to hunt for the one line she came for: when it arrives.","ar":"الخريطة هي الأكبر على الشاشة، لكن لينا ما زالت تبحث عن السطر الوحيد الذي جاءت من أجله: متى يصل الطلب."}},{"id":"MC-P10-015","when":["promo"],"feedback":{"en":"The offer and the map still come before the arrival time. Shrinking the promo doesn't move the answer up.","ar":"العرض والخريطة ما زالا قبل وقت الوصول. تصغير العرض لا يرفع الإجابة إلى الأعلى."}}],"hints":[{"en":"Why did Lina open this screen?","ar":"لماذا فتحت لينا هذه الشاشة؟"},{"en":"Which version answers that question first and biggest?","ar":"أي نسخة تجيب عن هذا السؤال أولًا وبأكبر حجم؟"}],"correct":{"en":"Answer the question she opened the screen for.","ar":"أجب عن السؤال الذي فتحت الشاشة من أجله."},"explain":{"en":"Same rule, new screen: the most important information first, and biggest. For tracking, that's the arrival time. The map supports it; the offer can wait.","ar":"القاعدة نفسها في شاشة جديدة: المعلومة الأهم أولًا وبأكبر حجم. وفي التتبّع هي وقت الوصول. الخريطة تدعمها، والعرض يمكنه الانتظار."},"speaker":"sara"},{"id":"S08","type":"card","part":"recap","icons":["fold","size","text","target"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **First screen:** the facts that decide it, then the action.\n- **Two big things:** the title and the one fact that decides it.\n- **First words:** time and price before the welcome.\n- **New screen, same rule:** a tracking screen leads with the arrival time.\n\nNext lesson: what you can hide, and what you can't.","ar":"- **الشاشة الأولى:** المعلومات التي تحسم القرار، ثم الإجراء.\n- **عنصران كبيران:** العنوان والمعلومة التي تحسم القرار.\n- **الكلمات الأولى:** الموعد والسعر قبل الترحيب.\n- **شاشة جديدة والقاعدة نفسها:** شاشة التتبّع تبدأ بوقت الوصول.\n\nالدرس التالي: ما يمكنك إخفاؤه، وما لا يمكنك."}}]}$uxg$::jsonb),
  ($uxg$P10-U01-L02$uxg$, $uxg$be199dd273922f3b3869d270922519eefda9430e32426c7bb8c42905364e3fde$uxg$, $uxg${"id":"P10-U01-L02","mode":"lesson","minutes":9,"title":{"en":"What you can hide, and what you can't","ar":"ما يمكنك إخفاؤه، وما لا يمكنك"},"speaker":"sara","review_labels":{"MC-P10-002":{"en":"What people often need stays up front","ar":"ما يحتاجه الناس غالبًا يبقى ظاهرًا"},"MC-P10-007":{"en":"A link's label says what's behind it","ar":"اسم الرابط يقول ما خلفه"},"MC-P10-008":{"en":"Don't collapse what everyone needs","ar":"لا تطوِ ما يحتاجه الجميع"},"MC-P10-010":{"en":"Two levels of hiding at most","ar":"مستويان من الإخفاء كحدّ أقصى"},"MC-P10-011":{"en":"Keep what's decided together on one screen","ar":"ما يُقرَّر معًا يبقى في شاشة واحدة"},"MC-P10-016":{"en":"Show the few things most people need first","ar":"اعرض أولًا الأشياء القليلة التي يحتاجها معظم الناس"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"A cleaner page?","ar":"صفحة أنظف؟"},"body":{"en":"A teammate tidied my workshop page. The time, place, price and cancellation rule now sit behind one \"More details\" link. It looks calm.\n\nCan Reem still decide without digging?","ar":"رتّب أحد زملائي صفحة الورشة التي أصمّمها. أصبح الموعد والمكان والسعر وشرط الإلغاء خلف رابط واحد «تفاصيل أكثر». تبدو الصفحة هادئة.\n\nهل ما زالت ريم تستطيع أن تقرّر دون بحث؟"},"mock":{"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"link","text":{"en":"More details","ar":"تفاصيل أكثر"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"l"}]}},{"id":"S02","type":"tune","skill":"SK-P10-U01-04","part":"try","rules":["R12"],"value":{"en":"Progressive disclosure (NN/g): everything people frequently need must be up front; only specialised details go behind a link.","ar":"الإفصاح التدريجي (NN/g): كل ما يحتاجه الناس كثيرًا يجب أن يكون ظاهرًا؛ والتفاصيل المتخصّصة فقط تذهب خلف رابط."},"ref":{"url":"https://www.nngroup.com/articles/progressive-disclosure/","quote":"You have to disclose everything that users frequently need up front"},"prompt":{"en":"Almost every visitor checks the time, place and price before reserving. Few read the full cancellation terms. Try each version. Which one should ship?","ar":"تقريبًا كل زائر يتحقّق من الموعد والمكان والسعر قبل الحجز. وقليلون يقرؤون شروط الإلغاء كاملة. جرّب كل نسخة. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"link","text":{"en":"More details","ar":"تفاصيل أكثر"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"l"}]},"options":[{"id":"price","text":{"en":"Show the price; keep the time and place behind More details","ar":"اعرض السعر، وأبقِ الموعد والمكان خلف «تفاصيل أكثر»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"link","text":{"en":"More details","ar":"تفاصيل أكثر"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"l"}]}},{"id":"often","text":{"en":"Show the time, place and price; keep the full cancellation terms behind a link","ar":"اعرض الموعد والمكان والسعر، وأبقِ شروط الإلغاء الكاملة خلف رابط"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"},{"kind":"link","text":{"en":"Cancellation terms","ar":"شروط الإلغاء"},"gap":"s"}]}},{"id":"clean","text":{"en":"Keep it as it is: one clean link","ar":"أبقِها كما هي: رابط واحد نظيف"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"link","text":{"en":"More details","ar":"تفاصيل أكثر"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"l"}]}}],"answer":["often"],"misconceptions":[{"id":"MC-P10-002","when":["price","clean"],"feedback":{"en":"Almost everyone needs the time and place to decide. Hiding them makes nearly every visitor tap and come back. Hide only what few people need.","ar":"تقريبًا الجميع يحتاج إلى الموعد والمكان ليقرّر. وإخفاؤهما يجعل كل زائر تقريبًا يضغط ثم يعود. أخفِ فقط ما يحتاجه القليلون."}}],"hints":[{"en":"Almost every visitor checks three things. Are they visible?","ar":"كل الزوار تقريبًا يتحقّقون من ثلاثة أشياء. هل هي ظاهرة؟"},{"en":"What do few people read? That's what can sit behind a link.","ar":"ما الذي يقرؤه قليلون؟ هذا ما يمكن وضعه خلف رابط."}],"correct":{"en":"Show what most people need; tuck away what few do.","ar":"اعرض ما يحتاجه معظم الناس، وأخفِ ما يحتاجه القليلون."},"explain":{"en":"A tidy page that hides the facts everyone needs isn't simpler; it just moves the work to every visitor. Decide what goes up front by how often people need it.","ar":"الصفحة المرتّبة التي تُخفي ما يحتاجه الجميع ليست أبسط؛ بل تنقل العمل إلى كل زائر. قرّر ما يظهر أولًا حسب عدد مرات حاجة الناس إليه."}},{"id":"S03","type":"card","part":"concept","icons":["eye","list","text","layers","warn"],"title":{"en":"Show first, the rest on request","ar":"اعرض الأهم أولًا، والباقي عند الطلب"},"body":{"en":"Showing the essentials first and the rest on request is called **progressive disclosure**.\n\n- **Up front:** everything people frequently need, and only that.\n- **On request:** specialised details, behind a link or a section.\n- **Clear labels:** the link says exactly what's behind it.\n- **Two levels at most:** deeper nesting gets people lost.\n- **Collapsed sections:** fine when people need a few of them; bad when they need most of them.","ar":"عرض الأساسيات أولًا والباقي عند الطلب يُسمّى **الإفصاح التدريجي (Progressive disclosure)**.\n\n- **الظاهر أولًا:** كل ما يحتاجه الناس كثيرًا، وهذا فقط.\n- **عند الطلب:** التفاصيل المتخصّصة، خلف رابط أو قسم.\n- **أسماء واضحة:** الرابط يقول بالضبط ما خلفه.\n- **مستويان كحدّ أقصى:** التداخل الأعمق يُضيّع الناس.\n- **الأقسام المطويّة (Accordions):** مناسبة حين يحتاج الناس بعضها فقط؛ وسيّئة حين يحتاجون معظمها."}},{"id":"S04","type":"tune","skill":"SK-P10-U01-05","part":"guided","rules":["R06","R13"],"value":{"en":"NN/g: label the link to the secondary level so it sets clear expectations. \"More\" tells Reem nothing about whether her question is answered there.","ar":"NN/g: سمِّ الرابط إلى المستوى الثاني بما يوضّح ما سيأتي. «المزيد» لا يخبر ريم إن كان سؤالها يُجاب هناك."},"ref":{"url":"https://www.nngroup.com/articles/progressive-disclosure/","quote":"label the button or link in a way that sets clear expectations"},"scenario":{"en":"Reem wants to know if she can cancel and whether the room has step-free access. On my page, both answers are behind the link under Reserve.","ar":"تريد ريم أن تعرف إن كانت تستطيع الإلغاء، وإن كان الدخول إلى القاعة دون سلالم. وفي صفحتي، الإجابتان خلف الرابط تحت زر الحجز."},"prompt":{"en":"Try each label for that link. Which one should ship?","ar":"جرّب كل اسم لهذا الرابط. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"},{"kind":"link","text":{"en":"More","ar":"المزيد"},"gap":"s"}]},"options":[{"id":"more","text":{"en":"\"More\"","ar":"«المزيد»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"},{"kind":"link","text":{"en":"More","ar":"المزيد"},"gap":"s"}]}},{"id":"info","text":{"en":"\"Good to know\"","ar":"«معلومات مفيدة»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"},{"kind":"link","text":{"en":"Good to know","ar":"معلومات مفيدة"},"gap":"s"}]}},{"id":"named","text":{"en":"\"Cancellation and step-free access\"","ar":"«الإلغاء والدخول دون سلالم»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Free","ar":"مجاني"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"},{"kind":"link","text":{"en":"Cancellation and step-free access","ar":"الإلغاء والدخول دون سلالم"},"gap":"s"}]}}],"answer":["named"],"misconceptions":[{"id":"MC-P10-007","when":["more","info"],"feedback":{"en":"Reem can't tell if her questions are answered there until she taps. Name what's behind the link.","ar":"لا تعرف ريم إن كانت أسئلتها مُجابة هناك حتى تضغط. سمِّ ما خلف الرابط."}}],"hints":[{"en":"Before tapping, can Reem tell her answers are behind this link?","ar":"قبل أن تضغط، هل تعرف ريم أن إجاباتها خلف هذا الرابط؟"},{"en":"Which label names what's behind it?","ar":"أي تسمية تذكر ما خلفها؟"}],"correct":{"en":"The label tells her what she'll find.","ar":"الاسم يخبرها بما ستجده."},"explain":{"en":"Hidden content is only as findable as its label. A specific label lets people decide whether to tap, and lets those who need it find it straight away.","ar":"المحتوى المخفي يُوجد بقدر وضوح اسمه فقط. والاسم المحدّد يجعل الناس يقرّرون هل يضغطون، ويجعل من يحتاجه يجده فورًا."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P10-U01-04","part":"guided","rules":["R06","R15"],"value":{"en":"NN/g on accordions: when people need most of the sections, collapsing them adds clicks and hidden content may be missed altogether. Show them open, with headings.","ar":"NN/g عن الـ Accordions: حين يحتاج الناس معظم الأقسام، يضيف طيّها ضغطات، وقد يفوتهم المحتوى المخفي تمامًا. اعرضها مفتوحة بعناوين."},"ref":{"url":"https://www.nngroup.com/articles/accordions-on-desktop/","quote":"Valuable content that is hidden under an accordion may be missed altogether."},"scenario":{"en":"The day before the workshop, every attendee gets a \"Before you come\" page that I'm designing. Everyone needs all four parts of it.","ar":"قبل الورشة بيوم، يصل لكل مشارك صفحة «قبل أن تأتي» التي أصمّمها. والجميع يحتاج إلى أجزائها الأربعة كلها."},"prompt":{"en":"Try each layout. Which one should ship?","ar":"جرّب كل تخطيط. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"blocks":[{"kind":"title","text":{"en":"Before you come","ar":"قبل أن تأتي"}},{"kind":"line","text":{"en":"What to bring ▾","ar":"ماذا تُحضر ▾"},"gap":"m"},{"kind":"line","text":{"en":"How to find the room ▾","ar":"كيف تصل إلى القاعة ▾"},"gap":"xs"},{"kind":"line","text":{"en":"When to arrive ▾","ar":"متى تصل ▾"},"gap":"xs"},{"kind":"line","text":{"en":"If you can't make it ▾","ar":"إن لم تستطع الحضور ▾"},"gap":"xs"}]},"options":[{"id":"open","text":{"en":"All four parts open, each under its own heading","ar":"الأجزاء الأربعة مفتوحة، كلٌّ تحت عنوانه"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Before you come","ar":"قبل أن تأتي"}},{"kind":"heading","text":{"en":"What to bring","ar":"ماذا تُحضر"},"gap":"m"},{"kind":"text","text":{"en":"Pencil and paper. No laptop needed.","ar":"قلم وورق. لا تحتاج إلى Laptop."},"gap":"xs"},{"kind":"heading","text":{"en":"How to find the room","ar":"كيف تصل إلى القاعة"},"gap":"m"},{"kind":"text","text":{"en":"Main entrance, lift to floor 1, Room 2.","ar":"المدخل الرئيسي، ثم المصعد إلى الطابق 1، القاعة 2."},"gap":"xs"},{"kind":"heading","text":{"en":"When to arrive","ar":"متى تصل"},"gap":"m"},{"kind":"text","text":{"en":"10 minutes early; doors close at 18:05.","ar":"قبل 10 دقائق؛ تُغلق الأبواب الساعة 18:05."},"gap":"xs"},{"kind":"heading","text":{"en":"If you can't make it","ar":"إن لم تستطع الحضور"},"gap":"m"},{"kind":"text","text":{"en":"Cancel up to 24 hours before the start","ar":"يمكنك الإلغاء قبل الموعد بـ24 ساعة على الأقل"},"gap":"xs"}]}},{"id":"closed","text":{"en":"Keep the four collapsed sections","ar":"أبقِ الأقسام الأربعة مطويّة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Before you come","ar":"قبل أن تأتي"}},{"kind":"line","text":{"en":"What to bring ▾","ar":"ماذا تُحضر ▾"},"gap":"m"},{"kind":"line","text":{"en":"How to find the room ▾","ar":"كيف تصل إلى القاعة ▾"},"gap":"xs"},{"kind":"line","text":{"en":"When to arrive ▾","ar":"متى تصل ▾"},"gap":"xs"},{"kind":"line","text":{"en":"If you can't make it ▾","ar":"إن لم تستطع الحضور ▾"},"gap":"xs"}]}},{"id":"one","text":{"en":"One \"Read before you come\" link that opens everything","ar":"رابط واحد «اقرأ قبل أن تأتي» يفتح كل شيء"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Before you come","ar":"قبل أن تأتي"}},{"kind":"link","text":{"en":"Read before you come","ar":"اقرأ قبل أن تأتي"},"gap":"m"}]}}],"answer":["open"],"misconceptions":[{"id":"MC-P10-008","when":["closed","one"],"feedback":{"en":"Everyone needs every part, so everyone has to open everything, and some will skip a part they needed. Collapse only what most people don't need.","ar":"الجميع يحتاج إلى كل جزء، فعلى الجميع أن يفتحوا كل شيء، وسيفوت بعضهم جزءًا يحتاجه. اطوِ فقط ما لا يحتاجه معظم الناس."}}],"hints":[{"en":"Who needs these parts, and how many of them?","ar":"من يحتاج هذه الأجزاء، وكم جزءًا منها؟"},{"en":"If everyone needs every part, should they open each one?","ar":"إذا كان الجميع يحتاج كل جزء، فهل يجب أن يفتحوا كل واحد منها؟"}],"correct":{"en":"What everyone needs stays open.","ar":"ما يحتاجه الجميع يبقى مفتوحًا."},"explain":{"en":"Collapsed sections save space when people pick a few, as in a help page. When everyone needs all of them, collapsing only adds taps, and a hidden part can be missed completely. Headings keep the open page easy to scan.","ar":"الأقسام المطويّة توفّر المساحة حين يختار الناس بعضها، كما في صفحة المساعدة. وحين يحتاجها الجميع كلها، فالطيّ يضيف ضغطات فقط، وقد يفوت جزء مخفي تمامًا. والعناوين تُبقي الصفحة المفتوحة سهلة التصفّح."},"speaker":"sara"},{"id":"S06","type":"tune","skill":"SK-P10-U01-05","part":"guided","rules":["R06","R15"],"value":{"en":"NN/g: designs that go beyond 2 disclosure levels typically have low usability because users get lost. Link straight to the rule.","ar":"NN/g: التصميمات التي تتجاوز مستويين من الإفصاح تكون سهولة استخدامها منخفضة عادةً، لأن المستخدمين يضيعون. اربط مباشرة بالشرط."},"ref":{"url":"https://www.nngroup.com/articles/progressive-disclosure/","quote":"beyond 2 disclosure levels typically have low usability"},"prompt":{"en":"To find the cancellation rule now, Reem opens More details, then Policies, then Cancellation. Try each fix. Which one should ship?","ar":"لتجد ريم شرط الإلغاء الآن، تفتح «تفاصيل أكثر»، ثم «السياسات»، ثم «الإلغاء». جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now: three levels deep","ar":"الآن: ثلاثة مستويات"},"blocks":[{"kind":"link","text":{"en":"More details ›","ar":"تفاصيل أكثر ›"}},{"kind":"group","gap":"s","blocks":[{"kind":"link","text":{"en":"Policies ›","ar":"السياسات ›"}},{"kind":"group","gap":"s","blocks":[{"kind":"link","text":{"en":"Cancellation ›","ar":"الإلغاء ›"}},{"kind":"small","text":{"en":"Cancel up to 24 hours before the start","ar":"يمكنك الإلغاء قبل الموعد بـ24 ساعة على الأقل"},"gap":"s"}]}]}]},"options":[{"id":"search","text":{"en":"Keep the levels, and add a search box to Policies","ar":"أبقِ المستويات، وأضف مربّع بحث إلى «السياسات»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"link","text":{"en":"More details ›","ar":"تفاصيل أكثر ›"}},{"kind":"group","gap":"s","blocks":[{"kind":"link","text":{"en":"Policies ›","ar":"السياسات ›"}},{"kind":"field","text":{"en":"Search policies","ar":"ابحث في السياسات"},"gap":"s"},{"kind":"group","gap":"s","blocks":[{"kind":"link","text":{"en":"Cancellation ›","ar":"الإلغاء ›"}},{"kind":"small","text":{"en":"Cancel up to 24 hours before the start","ar":"يمكنك الإلغاء قبل الموعد بـ24 ساعة على الأقل"},"gap":"s"}]}]}]}},{"id":"direct","text":{"en":"One link under Reserve, \"Cancellation terms\", that opens the rule","ar":"رابط واحد تحت زر الحجز، «شروط الإلغاء»، يفتح الشرط مباشرة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"}},{"kind":"link","text":{"en":"Cancellation terms ›","ar":"شروط الإلغاء ›"},"gap":"s"},{"kind":"group","gap":"s","blocks":[{"kind":"small","text":{"en":"Cancel up to 24 hours before the start","ar":"يمكنك الإلغاء قبل الموعد بـ24 ساعة على الأقل"}}]}]}},{"id":"rename","text":{"en":"Keep the levels, but rename Policies to Rules","ar":"أبقِ المستويات، لكن غيّر «السياسات» إلى «القواعد»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"link","text":{"en":"More details ›","ar":"تفاصيل أكثر ›"}},{"kind":"group","gap":"s","blocks":[{"kind":"link","text":{"en":"Rules ›","ar":"القواعد ›"}},{"kind":"group","gap":"s","blocks":[{"kind":"link","text":{"en":"Cancellation ›","ar":"الإلغاء ›"}},{"kind":"small","text":{"en":"Cancel up to 24 hours before the start","ar":"يمكنك الإلغاء قبل الموعد بـ24 ساعة على الأقل"},"gap":"s"}]}]}]}}],"answer":["direct"],"misconceptions":[{"id":"MC-P10-010","when":["search","rename"],"feedback":{"en":"The rule is still three taps deep. Each extra level is another place to get lost. Keep it to two: the page, then the rule.","ar":"ما زال الشرط على بُعد ثلاث ضغطات. كل مستوى إضافي مكان آخر للضياع. اكتفِ بمستويين: الصفحة، ثم الشرط."}}],"hints":[{"en":"Count the taps Reem needs to reach the rule.","ar":"عُدّ الضغطات التي تحتاجها ريم للوصول إلى القاعدة."},{"en":"The fix should remove levels, not make the deep ones easier to search or read.","ar":"يجب أن يزيل الحل مستويات، لا أن يجعل المستويات العميقة أسهل في البحث أو القراءة."}],"correct":{"en":"Two levels: the page, then the detail.","ar":"مستويان: الصفحة، ثم التفاصيل."},"explain":{"en":"Hiding inside hiding gets people lost. Beyond two levels, people forget where they are and give up. Link straight from the page to the detail, with a label that names it.","ar":"الإخفاء داخل الإخفاء يُضيّع الناس. فبعد مستويين ينسون أين هم ويستسلمون. اربط مباشرة من الصفحة إلى التفاصيل، باسم يحدّدها."}},{"id":"S07","type":"compare","skill":"SK-P10-U01-05","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"NN/g on staged disclosure: splitting steps is problematic when they're interdependent and users must alternate between them. A room choice depends on its price, so they share a screen.","ar":"NN/g عن الإفصاح على مراحل: تقسيم الخطوات مشكلة حين تعتمد على بعضها ويضطر المستخدمون إلى التنقّل بينها. اختيار الغرفة يعتمد على سعرها، فمكانهما شاشة واحدة."},"ref":{"url":"https://www.nngroup.com/articles/progressive-disclosure/","quote":"It is problematic when the steps are interdependent and users must alternate between them."},"scenario":{"en":"I'm also designing a hotel booking flow. Dalia will choose the room type partly by its price.","ar":"أصمّم أيضًا خطوات الحجز لفندق. وستختار داليا نوع الغرفة بحسب سعرها جزئيًا."},"prompt":{"en":"Which version should ship?","ar":"أي نسخة يجب أن تُطلق؟"},"a":{"label":{"en":"Step 1 of 2","ar":"الخطوة 1 من 2"},"mock":{"blocks":[{"kind":"heading","text":{"en":"Choose a room","ar":"اختر غرفة"}},{"kind":"radio","text":{"en":"Standard room","ar":"غرفة عادية"},"gap":"s"},{"kind":"radio","text":{"en":"Sea-view room","ar":"غرفة بإطلالة على البحر"},"gap":"xs"},{"kind":"radio","text":{"en":"Family suite","ar":"جناح عائلي"},"gap":"xs"},{"kind":"button","text":{"en":"Next: see the price","ar":"التالي: اعرف السعر"},"gap":"m"}]}},"b":{"label":{"en":"One screen","ar":"شاشة واحدة"},"mock":{"blocks":[{"kind":"heading","text":{"en":"Choose a room","ar":"اختر غرفة"}},{"kind":"radio","text":{"en":"Standard room · EGP 1,800 a night","ar":"غرفة عادية · 1,800 جنيه لليلة"},"gap":"s"},{"kind":"radio","text":{"en":"Sea-view room · EGP 2,600 a night","ar":"غرفة بإطلالة على البحر · 2,600 جنيه لليلة"},"gap":"xs"},{"kind":"radio","text":{"en":"Family suite · EGP 3,900 a night","ar":"جناح عائلي · 3,900 جنيه لليلة"},"gap":"xs"},{"kind":"button","text":{"en":"Continue","ar":"متابعة"},"gap":"m"}]}},"answer":"b","reason":{"prompt":{"en":"Why is B better here?","ar":"لماذا B أفضل هنا؟"},"options":[{"id":"fewer","text":{"en":"Fewer steps are always better","ar":"الخطوات الأقل أفضل دائمًا"}},{"id":"depends","text":{"en":"The choice depends on the price, so they belong on the same screen","ar":"الاختيار يعتمد على السعر، فمكانهما الشاشة نفسها"}},{"id":"price","text":{"en":"Prices should always come first on any page","ar":"الأسعار يجب أن تأتي أولًا في أي صفحة"}}],"answer":["depends"],"misconceptions":[{"id":"MC-P10-011","when":["fewer","price"],"feedback":{"en":"Splitting steps is fine when they don't depend on each other, like payment after choosing. Here, choosing needs the price.","ar":"تقسيم الخطوات مقبول حين لا تعتمد على بعضها، مثل الدفع بعد الاختيار. لكن هنا يحتاج الاختيار إلى السعر."}}]},"misconceptions":[{"id":"MC-P10-011","when":["a"],"feedback":{"en":"In A, Dalia has to pick a room, see its price, go back, pick another, and remember each price. What's decided together should be shown together.","ar":"في A، على داليا أن تختار غرفة، ثم ترى سعرها، ثم تعود، ثم تختار أخرى، وتتذكّر كل سعر. ما يُقرَّر معًا يجب أن يُعرض معًا."}}],"hints":[{"en":"Dalia picks the room partly by its price. Where is the price in each version?","ar":"تختار داليا الغرفة جزئيًا حسب سعرها. أين السعر في كل نسخة؟"},{"en":"Should she have to go to another step to compare room and price?","ar":"هل يجب أن تنتقل إلى خطوة أخرى لتقارن بين الغرفة والسعر؟"}],"correct":{"en":"Show together what's decided together.","ar":"اعرض معًا ما يُقرَّر معًا."},"explain":{"en":"Splitting a task into steps helps when the steps don't depend on each other: choose a room, then pay. It hurts when people must go back and forth to compare. Room and price are one decision.","ar":"تقسيم المهمة إلى خطوات يفيد حين لا تعتمد الخطوات على بعضها: اختر الغرفة، ثم ادفع. ويضرّ حين يضطر الناس إلى الذهاب والعودة للمقارنة. الغرفة والسعر قرار واحد."},"speaker":"sara"},{"id":"S08","type":"tune","skill":"SK-P10-U01-04","part":"independent","rules":["R14","R19"],"value":{"en":"New case. NN/g: initially, show only a few of the most important options, and offer the specialised ones on request. Twelve equal settings bury the two everyone uses.","ar":"حالة جديدة. NN/g: اعرض في البداية بضعة خيارات هي الأهم فقط، وقدّم المتخصّصة عند الطلب. اثنا عشر إعدادًا متساويًا تدفن الإعدادين اللذين يستخدمهما الجميع."},"ref":{"url":"https://www.nngroup.com/articles/progressive-disclosure/","quote":"Initially, show users only a few of the most important options."},"scenario":{"en":"A client's home internet app: most people open it to change the Wi-Fi password or see who's connected. Its settings screen lists all 12 settings in one long list.","ar":"تطبيق الإنترنت المنزلي لأحد عملائي: معظم الناس يفتحونه لتغيير كلمة مرور الـ Wi-Fi أو لمعرفة من المتصل. وشاشة الإعدادات فيه تعرض الإعدادات الـ 12 كلها في قائمة طويلة واحدة."},"prompt":{"en":"Try each layout. Which one should ship?","ar":"جرّب كل تخطيط. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"height":330,"blocks":[{"kind":"title","text":{"en":"Settings","ar":"الإعدادات"}},{"kind":"line","text":{"en":"DNS servers","ar":"خوادم الـ DNS"},"gap":"s"},{"kind":"line","text":{"en":"Port forwarding","ar":"توجيه المنافذ"},"gap":"xs"},{"kind":"line","text":{"en":"Wi-Fi channel","ar":"قناة الـ Wi-Fi"},"gap":"xs"},{"kind":"line","text":{"en":"Firmware update","ar":"تحديث النظام"},"gap":"xs"},{"kind":"line","text":{"en":"Guest network","ar":"شبكة الضيوف"},"gap":"xs"},{"kind":"line","text":{"en":"Wi-Fi password","ar":"كلمة مرور الـ Wi-Fi"},"gap":"xs"},{"kind":"line","text":{"en":"IP settings","ar":"إعدادات الـ IP"},"gap":"xs"},{"kind":"line","text":{"en":"Connected devices","ar":"الأجهزة المتصلة"},"gap":"xs"}]},"options":[{"id":"one","text":{"en":"Put all 12 behind a single \"Settings\" button","ar":"ضع الـ 12 كلها خلف زر واحد «الإعدادات»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Home internet","ar":"الإنترنت المنزلي"}},{"kind":"button","emphasis":"low","text":{"en":"Settings","ar":"الإعدادات"},"gap":"m"}]}},{"id":"few","text":{"en":"Wi-Fi password and connected devices first; the other 10 under \"Advanced settings\"","ar":"كلمة مرور الـ Wi-Fi والأجهزة المتصلة أولًا؛ والعشرة الباقية تحت «إعدادات متقدّمة»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Settings","ar":"الإعدادات"}},{"kind":"line","text":{"en":"Wi-Fi password","ar":"كلمة مرور الـ Wi-Fi"},"gap":"s"},{"kind":"line","text":{"en":"Connected devices","ar":"الأجهزة المتصلة"},"gap":"xs"},{"kind":"link","text":{"en":"Advanced settings (10) ›","ar":"إعدادات متقدّمة (10) ›"},"gap":"m"}]}},{"id":"sort","text":{"en":"Keep all 12 in one list, sorted A to Z","ar":"أبقِ الـ 12 في قائمة واحدة، مرتّبة أبجديًا"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"height":330,"blocks":[{"kind":"title","text":{"en":"Settings","ar":"الإعدادات"}},{"kind":"line","text":{"en":"Connected devices","ar":"الأجهزة المتصلة"},"gap":"s"},{"kind":"line","text":{"en":"DNS servers","ar":"خوادم الـ DNS"},"gap":"xs"},{"kind":"line","text":{"en":"Firmware update","ar":"تحديث النظام"},"gap":"xs"},{"kind":"line","text":{"en":"Guest network","ar":"شبكة الضيوف"},"gap":"xs"},{"kind":"line","text":{"en":"IP settings","ar":"إعدادات الـ IP"},"gap":"xs"},{"kind":"line","text":{"en":"Port forwarding","ar":"توجيه المنافذ"},"gap":"xs"},{"kind":"line","text":{"en":"Wi-Fi channel","ar":"قناة الـ Wi-Fi"},"gap":"xs"},{"kind":"line","text":{"en":"Wi-Fi password","ar":"كلمة مرور الـ Wi-Fi"},"gap":"xs"}]}}],"answer":["few"],"misconceptions":[{"id":"MC-P10-016","when":["sort"],"feedback":{"en":"Sorting doesn't change the problem: the two settings almost everyone needs are still buried among ten that few people touch.","ar":"الترتيب لا يغيّر المشكلة: الإعدادان اللذان يحتاجهما الجميع تقريبًا ما زالا مدفونين بين عشرة لا يلمسها إلا القليلون."}},{"id":"MC-P10-002","when":["one"],"feedback":{"en":"Now everyone, including people who only want the Wi-Fi password, has to open a button first. Keep the frequent settings visible.","ar":"الآن على الجميع، حتى من يريد كلمة مرور الـ Wi-Fi فقط، أن يفتح زرًّا أولًا. أبقِ الإعدادات الشائعة ظاهرة."}}],"hints":[{"en":"Which two settings do most people open the app for?","ar":"ما الإعدادان اللذان يفتح أغلب الناس التطبيق من أجلهما؟"},{"en":"Hide everything, and the common two get lost too. Show everything, and they're hard to find.","ar":"إذا أخفيت كل شيء ضاع الإعدادان الشائعان أيضًا. وإذا أظهرت كل شيء صعب العثور عليهما."}],"correct":{"en":"The few everyone uses, then the rest on request.","ar":"القليل الذي يستخدمه الجميع، ثم الباقي عند الطلب."},"explain":{"en":"Same rule as Reem's page, on a settings screen: show the few things most people need, and put the specialised ones one clearly named tap away.","ar":"القاعدة نفسها في صفحة ريم، لكن على شاشة إعدادات: اعرض الأشياء القليلة التي يحتاجها معظم الناس، وضع المتخصّصة على بُعد ضغطة واحدة باسم واضح."},"speaker":"sara"},{"id":"S09","type":"card","part":"recap","icons":["eye","text","layers","list"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Up front:** what almost everyone needs; only rare details go behind a link.\n- **Labels:** the link names what's behind it.\n- **Open, not collapsed:** when everyone needs every part.\n- **Two levels, one screen:** no hiding inside hiding, and what's decided together stays together.\n\nNext lesson: what people skip without reading.","ar":"- **الظاهر أولًا:** ما يحتاجه الجميع تقريبًا، والتفاصيل النادرة فقط خلف رابط.\n- **الأسماء:** الرابط يسمّي ما خلفه.\n- **مفتوح لا مطويّ:** حين يحتاج الجميع كل جزء.\n- **مستويان وشاشة واحدة:** لا إخفاء داخل إخفاء، وما يُقرَّر معًا يبقى معًا.\n\nالدرس التالي: ما يتخطّاه الناس دون قراءة."}}]}$uxg$::jsonb),
  ($uxg$P10-U01-L03$uxg$, $uxg$318dc646dc1ec6e4b05c4e75c08f2d32db5cfc76239f4e0545a329fb636fe67b$uxg$, $uxg${"id":"P10-U01-L03","mode":"lesson","minutes":8,"title":{"en":"What people skip without reading","ar":"ما يتخطّاه الناس دون قراءة"},"speaker":"sara","review_labels":{"MC-P10-012":{"en":"Generic stock photos get skipped","ar":"صور الـ Stock العامة يتخطّاها الناس"},"MC-P10-013":{"en":"Don't style real content like an ad","ar":"لا تجعل المحتوى الحقيقي يشبه الإعلان"},"MC-P10-014":{"en":"Content next to ads is taken for an ad","ar":"المحتوى بجانب الإعلانات يُعامل كإعلان"},"MC-P10-017":{"en":"Keep content and offers in separate sections","ar":"افصل المحتوى عن العروض في أقسام مختلفة"},"MC-P10-018":{"en":"A photo that shows the real thing is content","ar":"الصورة التي تُظهر الشيء الحقيقي محتوى"}},"steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"\"Make it pop\"","ar":"«اجعلها لافتة»"},"body":{"en":"The marketing team wants my workshop page to feel more exciting. They added a big photo of smiling people and want the important notes in bright colourful strips.\n\nBright things get attention. But do people actually read them?","ar":"يريد فريق التسويق أن تبدو صفحة الورشة التي أصمّمها أكثر حماسًا. أضافوا صورة كبيرة لأشخاص يبتسمون، ويريدون وضع الملاحظات المهمّة في أشرطة ملوّنة لامعة.\n\nالأشياء اللامعة تلفت الانتباه. لكن هل يقرؤها الناس فعلًا؟"},"mock":{"blocks":[{"kind":"image","size":"l","text":{"en":"Photo: smiling people at a laptop","ar":"صورة: أشخاص يبتسمون أمام Laptop"}},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}},{"id":"S02","type":"tune","skill":"SK-P10-U01-07","part":"try","rules":["R12"],"value":{"en":"Photos as web content (NN/g): users ignore stock photos of generic people and other purely decorative images, but study images that carry information relevant to their task.","ar":"الصور كمحتوى (NN/g): يتجاهل المستخدمون صور الـ Stock لأشخاص عامّين وكل صورة للزينة فقط، لكنهم يتأمّلون الصور التي تحمل معلومة تخصّ مهمّتهم."},"ref":{"url":"https://www.nngroup.com/articles/photos-as-web-content/","quote":"users ignore stock photos of generic people"},"prompt":{"en":"The workshop teaches people to sketch app screens on paper. Try each photo change. Which one should ship?","ar":"تعلّم الورشة الناس رسم شاشات التطبيقات على الورق. جرّب كل تغيير في الصورة. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"height":380,"blocks":[{"kind":"image","size":"l","text":{"en":"Photo: smiling people at a laptop","ar":"صورة: أشخاص يبتسمون أمام Laptop"}},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]},"options":[{"id":"bigger","text":{"en":"Make the smiling-people photo bigger so the page feels warmer","ar":"كبّر صورة الأشخاص المبتسمين حتى تبدو الصفحة أدفأ"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"height":380,"blocks":[{"kind":"image","size":"l","height":250,"text":{"en":"Photo: smiling people at a laptop","ar":"صورة: أشخاص يبتسمون أمام Laptop"}},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}},{"id":"caption","text":{"en":"Keep the photo and add a caption on it: \"Join us!\"","ar":"أبقِ الصورة وأضف عليها عبارة: «انضم إلينا!»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"height":380,"blocks":[{"kind":"image","size":"l","text":{"en":"Photo: smiling people at a laptop · \"Join us!\"","ar":"صورة: أشخاص يبتسمون أمام Laptop · «انضم إلينا!»"}},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}},{"id":"real","text":{"en":"Replace it with a smaller photo of paper sketches made in last month's class, under the facts","ar":"استبدلها بصورة أصغر لرسومات ورقية صنعها المشاركون في ورشة الشهر الماضي، تحت المعلومات"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"height":380,"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"},{"kind":"image","size":"m","text":{"en":"Photo: app sketches from last month's class","ar":"صورة: رسومات تطبيقات من ورشة الشهر الماضي"},"gap":"m"}]}}],"answer":["real"],"misconceptions":[{"id":"MC-P10-012","when":["bigger","caption"],"feedback":{"en":"A photo of generic smiling people tells Reem nothing about the workshop, so people scroll past it. A bigger photo or a slogan only pushes the facts further down.","ar":"صورة أشخاص عامّين يبتسمون لا تخبر ريم بشيء عن الورشة، لذلك يتخطّاها الناس. وتكبيرها أو إضافة شعار عليها يدفع المعلومات إلى الأسفل أكثر."}}],"hints":[{"en":"What does the workshop actually teach?","ar":"ماذا تعلّم الورشة فعلًا؟"},{"en":"Which photo shows Reem what she'll do there?","ar":"أي صورة تُري ريم ما ستفعله هناك؟"}],"correct":{"en":"A photo that shows what she'll actually do.","ar":"صورة تُظهر ما ستفعله فعلًا."},"explain":{"en":"People skip decorative photos of generic people. A photo of real sketches from the class shows what Reem will make, so it carries information, and it doesn't push the facts down.","ar":"يتخطّى الناس الصور التزيينية لأشخاص عامّين. أما صورة رسومات حقيقية من الورشة فتُظهر ما ستصنعه ريم، فهي تحمل معلومة، ولا تدفع المعلومات إلى الأسفل."}},{"id":"S03","type":"card","part":"concept","icons":["eye","warn","layers","ok"],"title":{"en":"What eyes skip","ar":"ما تتخطّاه العيون"},"body":{"en":"People have learned to skip anything that looks like an ad, without reading it. This is called **banner blindness**.\n\n- **Decorative photos:** generic smiling people get skipped; photos that show the real thing get studied.\n- **Ad-like style:** a bright box that looks different from the rest of the page reads as an ad, even if it's important.\n- **Ad places:** content placed next to ads, or in the side column where ads usually sit, gets ignored too.\n- **What works:** keep important content in the main column, in the page's own style, and separate from offers.","ar":"تعلّم الناس أن يتخطّوا كل ما يشبه الإعلان دون قراءته. وهذا يُسمّى **عمى الإعلانات (Banner blindness)**.\n\n- **الصور التزيينية:** صور الأشخاص العامّين المبتسمين يتخطّاها الناس؛ والصور التي تُظهر الشيء الحقيقي يتأمّلونها.\n- **شكل الإعلان:** الصندوق اللامع المختلف عن باقي الصفحة يُقرأ كإعلان، حتى لو كان مهمًّا.\n- **أماكن الإعلانات:** المحتوى الموضوع بجانب الإعلانات، أو في العمود الجانبي حيث تكون الإعلانات عادةً، يُتجاهل أيضًا.\n- **ما ينجح:** أبقِ المحتوى المهم في العمود الرئيسي، بشكل الصفحة نفسه، ومنفصلًا عن العروض."}},{"id":"S04","type":"tune","skill":"SK-P10-U01-06","part":"guided","rules":["R06","R13"],"value":{"en":"Banner blindness (NN/g): do not make content look like ads. Making it look different from the rest of the site to raise its salience often has the opposite effect.","ar":"عمى الإعلانات (NN/g): لا تجعل المحتوى يشبه الإعلانات. جعله مختلفًا عن باقي الموقع لزيادة بروزه يأتي غالبًا بعكس النتيجة."},"ref":{"url":"https://www.nngroup.com/articles/banner-blindness-old-and-new-findings/","quote":"Do not make content look like ads."},"scenario":{"en":"Every attendee must bring pencil and paper; there are none at the venue. Marketing put this note in a bright strip at the top of my page.","ar":"يجب أن يُحضر كل مشارك قلمًا وورقًا، فلا يوجد منها شيء في المكان. وضع فريق التسويق هذه الملاحظة في شريط لامع أعلى صفحتي."},"prompt":{"en":"Try each version of the note. Which one should ship?","ar":"جرّب كل نسخة من الملاحظة. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"blocks":[{"kind":"banner","text":{"en":"★ Bring pencil and paper! ★","ar":"★ أحضر قلمًا وورقًا! ★"}},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]},"options":[{"id":"louder","text":{"en":"Make the strip brighter, with an animated star","ar":"اجعل الشريط أكثر لمعانًا، مع نجمة متحرّكة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"banner","tone":"bad","text":{"en":"✨ Bring pencil and paper! ✨","ar":"✨ أحضر قلمًا وورقًا! ✨"}},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}},{"id":"plain","text":{"en":"A plain line with the other facts: \"Bring pencil and paper; none at the venue\"","ar":"سطر عادي مع باقي المعلومات: «أحضر قلمًا وورقًا؛ لا توجد في المكان»"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"meta","text":{"en":"Bring pencil and paper; none at the venue","ar":"أحضر قلمًا وورقًا؛ لا توجد في المكان"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}},{"id":"image","text":{"en":"Turn it into a picture of a pencil with the words on it","ar":"حوّلها إلى صورة قلم مكتوب عليها الملاحظة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"image","size":"m","text":{"en":"✏️ Bring pencil and paper!","ar":"✏️ أحضر قلمًا وورقًا!"}},{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"},"gap":"m"},{"kind":"meta","text":{"en":"Tuesday 17 November, 18:00–20:00","ar":"الثلاثاء 17 نوفمبر، من 18:00 إلى 20:00"},"gap":"s"},{"kind":"meta","text":{"en":"Downtown Learning Hub, Room 2","ar":"مركز التعلّم بوسط البلد، قاعة 2"},"gap":"s"},{"kind":"button","text":{"en":"Reserve a place","ar":"احجز مكانك"},"gap":"m"}]}}],"answer":["plain"],"misconceptions":[{"id":"MC-P10-013","when":["louder","image"],"feedback":{"en":"A bright strip or a picture at the top looks like an ad, so people skip it. Put the note with the facts, in the same style.","ar":"الشريط اللامع أو الصورة في الأعلى يشبهان الإعلان، فيتخطّاهما الناس. ضع الملاحظة مع المعلومات، بالشكل نفسه."}}],"hints":[{"en":"What do people do with things that look like ads?","ar":"ماذا يفعل الناس بالأشياء التي تبدو كإعلانات؟"},{"en":"Which version looks like the rest of the page's facts?","ar":"أي نسخة تبدو مثل بقية المعلومات في الصفحة؟"}],"correct":{"en":"In the page's own style, with the facts.","ar":"بشكل الصفحة نفسه، مع المعلومات."},"explain":{"en":"Making something look different to get attention often backfires: people take it for an ad and skip it. A plain line among the facts is read along with them.","ar":"جعل الشيء مختلفًا ليلفت الانتباه يأتي غالبًا بعكس النتيجة: يظنّه الناس إعلانًا ويتخطّونه. أما السطر العادي بين المعلومات فيُقرأ معها."},"speaker":"sara"},{"id":"S05","type":"tune","skill":"SK-P10-U01-06","part":"guided","rules":["R06","R15"],"value":{"en":"Banner blindness (NN/g): do not mix content and ads in the same visual section; content placed with ads is often taken for an ad and ignored.","ar":"عمى الإعلانات (NN/g): لا تخلط المحتوى بالإعلانات في القسم البصري نفسه؛ فالمحتوى الموضوع مع الإعلانات يُعامل غالبًا كإعلان ويُتجاهل."},"ref":{"url":"https://www.nngroup.com/articles/banner-blindness-old-and-new-findings/","quote":"Do not mix content and ads in the same visual section."},"scenario":{"en":"Tuesday's workshop is now full, and the next session is a week later. My page also shows two partner offers. Right now, the next session sits in one row with the offers.","ar":"اكتملت ورشة الثلاثاء، والجلسة التالية بعد أسبوع. وتعرض صفحتي أيضًا عرضين من شركاء. الآن، الجلسة التالية في صف واحد مع العروض."},"prompt":{"en":"Try each layout. Which one should ship?","ar":"جرّب كل تخطيط. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Fully booked","ar":"اكتمل الحجز"},"gap":"s"},{"kind":"heading","text":{"en":"You may also like","ar":"قد يعجبك أيضًا"},"gap":"m"},{"kind":"row","gap":"s","blocks":[{"kind":"banner","text":{"en":"Partner: drawing tablets 20% off","ar":"شريك: خصم 20% على ألواح الرسم"}},{"kind":"banner","text":{"en":"Next session: Tuesday 24 November, 18:00","ar":"الجلسة التالية: الثلاثاء 24 نوفمبر، 18:00"}},{"kind":"banner","text":{"en":"Partner: online design course","ar":"شريك: كورس تصميم أونلاين"}}]}]},"options":[{"id":"big","text":{"en":"Keep the row, but make the next-session card bigger than the offers","ar":"أبقِ الصف، لكن اجعل بطاقة الجلسة التالية أكبر من العروض"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Fully booked","ar":"اكتمل الحجز"},"gap":"s"},{"kind":"heading","text":{"en":"You may also like","ar":"قد يعجبك أيضًا"},"gap":"m"},{"kind":"banner","px":18,"text":{"en":"Next session: Tuesday 24 November, 18:00","ar":"الجلسة التالية: الثلاثاء 24 نوفمبر، 18:00"},"gap":"s"},{"kind":"row","gap":"s","blocks":[{"kind":"banner","text":{"en":"Partner: drawing tablets 20% off","ar":"شريك: خصم 20% على ألواح الرسم"}},{"kind":"banner","text":{"en":"Partner: online design course","ar":"شريك: كورس تصميم أونلاين"}}]}]}},{"id":"apart","text":{"en":"Next session and the waiting list right under \"Fully booked\"; the offers in their own section further down","ar":"الجلسة التالية وقائمة الانتظار تحت «اكتمل الحجز» مباشرة؛ والعروض في قسم خاص بها في الأسفل"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Fully booked","ar":"اكتمل الحجز"},"gap":"s"},{"kind":"meta","text":{"en":"Next session: Tuesday 24 November, 18:00","ar":"الجلسة التالية: الثلاثاء 24 نوفمبر، 18:00"},"gap":"s"},{"kind":"button","text":{"en":"Join the waiting list","ar":"انضم إلى قائمة الانتظار"},"gap":"m"},{"kind":"heading","text":{"en":"Partner offers","ar":"عروض الشركاء"},"gap":"l"},{"kind":"row","gap":"s","blocks":[{"kind":"banner","text":{"en":"Partner: drawing tablets 20% off","ar":"شريك: خصم 20% على ألواح الرسم"}},{"kind":"banner","text":{"en":"Partner: online design course","ar":"شريك: كورس تصميم أونلاين"}}]}]}},{"id":"first","text":{"en":"Keep the row, but move the next-session card to the start of it","ar":"أبقِ الصف، لكن انقل بطاقة الجلسة التالية إلى أوّله"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"blocks":[{"kind":"title","text":{"en":"Sketch Your First App","ar":"ارسم تطبيقك الأول"}},{"kind":"meta","text":{"en":"Fully booked","ar":"اكتمل الحجز"},"gap":"s"},{"kind":"heading","text":{"en":"You may also like","ar":"قد يعجبك أيضًا"},"gap":"m"},{"kind":"row","gap":"s","blocks":[{"kind":"banner","text":{"en":"Next session: Tuesday 24 November, 18:00","ar":"الجلسة التالية: الثلاثاء 24 نوفمبر، 18:00"}},{"kind":"banner","text":{"en":"Partner: drawing tablets 20% off","ar":"شريك: خصم 20% على ألواح الرسم"}},{"kind":"banner","text":{"en":"Partner: online design course","ar":"شريك: كورس تصميم أونلاين"}}]}]}}],"answer":["apart"],"misconceptions":[{"id":"MC-P10-017","when":["big","first"],"feedback":{"en":"As long as the next session sits in the same row as the offers, people treat the whole row as ads and skip it. Give it its own place, with the facts.","ar":"ما دامت الجلسة التالية في صف واحد مع العروض، سيعامل الناس الصف كله كإعلانات ويتخطّونه. ضعها في مكانها الخاص، مع المعلومات."}}],"hints":[{"en":"What does Reem see next to the next session? Does it look like an offer too?","ar":"ماذا ترى ريم بجانب الموعد التالي؟ هل يبدو هو أيضًا كعرض؟"},{"en":"Making the card bigger or moving it first keeps it in the same row. What separates it?","ar":"تكبير البطاقة أو نقلها للأول يبقيها في الصف نفسه. ما الذي يفصلها؟"}],"correct":{"en":"Content with content, offers with offers.","ar":"المحتوى مع المحتوى، والعروض مع العروض."},"explain":{"en":"When content shares a section with ads, people judge the whole section as ads. The next session is what a visitor needs after \"Fully booked\", so it goes right there, apart from the offers.","ar":"حين يشارك المحتوى الإعلانات في قسم واحد، يحكم الناس على القسم كله بأنه إعلانات. والجلسة التالية هي ما يحتاجه الزائر بعد «اكتمل الحجز»، فمكانها هناك مباشرة، بعيدًا عن العروض."},"speaker":"sara"},{"id":"S06","type":"compare","skill":"SK-P10-U01-07","part":"contrast","confidence":true,"rules":["R11","R15"],"value":{"en":"Contrast with S02 and Lesson 1: photos aren't always decoration. NN/g: users pay attention to information-carrying images relevant to the task. When the photos are what the person judges, they lead.","ar":"مقارنة مع الخطوة 2 والدرس الأول: الصور ليست دائمًا للزينة. NN/g: ينتبه المستخدمون للصور التي تحمل معلومة تخصّ مهمّتهم. وحين تكون الصور هي ما يحكم به الشخص، تأتي أولًا."},"ref":{"url":"https://www.nngroup.com/articles/photos-as-web-content/","quote":"users pay attention to information-carrying images"},"scenario":{"en":"On a rental app I'm designing, Reham is looking for a flat. She already filtered by area and price; now she's judging whether the rooms are bright and big enough.","ar":"في تطبيق إيجار أصمّمه، تبحث رهام عن شقة. سبق أن صفّت النتائج حسب المنطقة والسعر؛ والآن تحكم إن كانت الغرف مضيئة وواسعة بما يكفي."},"prompt":{"en":"Which version of the listing should ship?","ar":"أي نسخة من الإعلان العقاري يجب أن تُطلق؟"},"a":{"label":{"en":"Facts first","ar":"المعلومات أولًا"},"mock":{"blocks":[{"kind":"title","text":{"en":"Two-bedroom flat, 3rd floor","ar":"شقة بغرفتي نوم، الطابق الثالث"}},{"kind":"meta","text":{"en":"EGP 9,000 a month · 95 m²","ar":"9,000 جنيه في الشهر · 95 م²"},"gap":"s"},{"kind":"button","text":{"en":"Contact the owner","ar":"تواصل مع المالك"},"gap":"m"},{"kind":"image","size":"m","text":{"en":"Photo: a happy family on a sofa","ar":"صورة: عائلة سعيدة على أريكة"},"gap":"m"}]}},"b":{"label":{"en":"Room photos first","ar":"صور الغرف أولًا"},"mock":{"blocks":[{"kind":"row","blocks":[{"kind":"image","size":"m","text":{"en":"Photo: this flat's living room","ar":"صورة: صالة هذه الشقة"}},{"kind":"image","size":"m","text":{"en":"Photo: this flat's bedroom","ar":"صورة: غرفة النوم في هذه الشقة"}}]},{"kind":"title","text":{"en":"Two-bedroom flat, 3rd floor","ar":"شقة بغرفتي نوم، الطابق الثالث"},"gap":"m"},{"kind":"meta","text":{"en":"EGP 9,000 a month · 95 m²","ar":"9,000 جنيه في الشهر · 95 م²"},"gap":"s"},{"kind":"button","text":{"en":"Contact the owner","ar":"تواصل مع المالك"},"gap":"m"}]}},"answer":"b","reason":{"prompt":{"en":"Why do the photos lead here?","ar":"لماذا تأتي الصور أولًا هنا؟"},"options":[{"id":"pretty","text":{"en":"Photos make any page more attractive","ar":"الصور تجعل أي صفحة أكثر جاذبية"}},{"id":"people","text":{"en":"Photos without people always work better","ar":"الصور التي ليس فيها أشخاص تنجح دائمًا أكثر"}},{"id":"info","text":{"en":"These photos are the information Reham is deciding with","ar":"هذه الصور هي المعلومة التي تقرّر بها رهام"}}],"answer":["info"],"misconceptions":[{"id":"MC-P10-018","when":["pretty","people"],"feedback":{"en":"It's not about looks or about people in the picture. These photos show the actual rooms, which is exactly what Reham is judging.","ar":"الأمر لا يتعلّق بالجمال ولا بوجود أشخاص في الصورة. هذه الصور تُظهر الغرف الفعلية، وهذا بالضبط ما تحكم عليه رهام."}}]},"misconceptions":[{"id":"MC-P10-018","when":["a"],"feedback":{"en":"In A, the only photo is a generic family that tells Reham nothing about the flat. Photos of the real rooms are her main facts, so they come first.","ar":"في A، الصورة الوحيدة لعائلة عامّة لا تخبر رهام بشيء عن الشقة. أما صور الغرف الحقيقية فهي أهم معلوماتها، لذلك تأتي أولًا."}}],"hints":[{"en":"What is Reham judging now that she has filtered?","ar":"ماذا تقيّم رهام الآن بعد أن استخدمت الفلاتر؟"},{"en":"Can text tell her how bright a room is?","ar":"هل يستطيع النص أن يخبرها بمدى إضاءة الغرفة؟"}],"correct":{"en":"When the photo is the fact, it leads.","ar":"حين تكون الصورة هي المعلومة، تأتي أولًا."},"explain":{"en":"On Reem's page, the photo was decoration, so the facts went first. Here, the photos of the rooms are what Reham decides with. Ask whether a photo carries information for this decision, not whether photos are good or bad.","ar":"في صفحة ريم كانت الصورة للزينة، فجاءت المعلومات أولًا. أما هنا فصور الغرف هي ما تقرّر به رهام. اسأل: هل تحمل الصورة معلومة لهذا القرار؟ لا: هل الصور جيدة أم سيئة؟"},"speaker":"sara"},{"id":"S07","type":"tune","skill":"SK-P10-U01-06","part":"independent","rules":["R14","R19"],"value":{"en":"New case. Banner blindness (NN/g): content placed in the same part of the screen as an ad is often considered an ad and ignored; the side column is a typical ad location.","ar":"حالة جديدة. عمى الإعلانات (NN/g): المحتوى الموضوع في جزء الشاشة نفسه مع الإعلان يُعامل غالبًا كإعلان ويُتجاهل؛ والعمود الجانبي مكان معتاد للإعلانات."},"ref":{"url":"https://www.nngroup.com/articles/banner-blindness-old-and-new-findings/","quote":"Content placed in the same part of the screen as an advertisement is often considered to be an ad and is also ignored."},"scenario":{"en":"On a hotel site I'm reviewing, Omar is booking on his laptop. He'll only book if he can cancel for free. The free-cancellation note sits in the side column, under two ads.","ar":"في موقع فندق أراجعه، يحجز عمر من الـ Laptop. ولن يحجز إلا إذا استطاع الإلغاء مجانًا. وملاحظة الإلغاء المجاني في العمود الجانبي، تحت إعلانين."},"prompt":{"en":"Try each fix. Which one should ship?","ar":"جرّب كل إصلاح. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"frame":"wide","blocks":[{"kind":"row","blocks":[{"kind":"group","tone":"plain","blocks":[{"kind":"title","text":{"en":"Garden Hotel · 2 nights","ar":"فندق الحديقة · ليلتان"}},{"kind":"meta","text":{"en":"EGP 4,200 total","ar":"4,200 جنيه إجمالًا"},"gap":"s"},{"kind":"button","text":{"en":"Book now","ar":"احجز الآن"},"gap":"m"}]},{"kind":"group","tone":"tint","blocks":[{"kind":"image","size":"s","text":{"en":"Ad: rent a car","ar":"إعلان: استأجر سيارة"}},{"kind":"image","size":"s","text":{"en":"Ad: city tours","ar":"إعلان: جولات في المدينة"},"gap":"s"},{"kind":"small","text":{"en":"Free cancellation until 1 March","ar":"إلغاء مجاني حتى 1 مارس"},"gap":"s"}]}]}]},"options":[{"id":"red","text":{"en":"Keep it in the side column, in a red box","ar":"أبقِها في العمود الجانبي، داخل صندوق أحمر"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"frame":"wide","blocks":[{"kind":"row","blocks":[{"kind":"group","tone":"plain","blocks":[{"kind":"title","text":{"en":"Garden Hotel · 2 nights","ar":"فندق الحديقة · ليلتان"}},{"kind":"meta","text":{"en":"EGP 4,200 total","ar":"4,200 جنيه إجمالًا"},"gap":"s"},{"kind":"button","text":{"en":"Book now","ar":"احجز الآن"},"gap":"m"}]},{"kind":"group","tone":"tint","blocks":[{"kind":"image","size":"s","text":{"en":"Ad: rent a car","ar":"إعلان: استأجر سيارة"}},{"kind":"image","size":"s","text":{"en":"Ad: city tours","ar":"إعلان: جولات في المدينة"},"gap":"s"},{"kind":"banner","tone":"bad","text":{"en":"Free cancellation until 1 March","ar":"إلغاء مجاني حتى 1 مارس"},"gap":"s"}]}]}]}},{"id":"top","text":{"en":"Move it to the top of the side column, above the ads","ar":"انقلها إلى أعلى العمود الجانبي، فوق الإعلانات"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"frame":"wide","blocks":[{"kind":"row","blocks":[{"kind":"group","tone":"plain","blocks":[{"kind":"title","text":{"en":"Garden Hotel · 2 nights","ar":"فندق الحديقة · ليلتان"}},{"kind":"meta","text":{"en":"EGP 4,200 total","ar":"4,200 جنيه إجمالًا"},"gap":"s"},{"kind":"button","text":{"en":"Book now","ar":"احجز الآن"},"gap":"m"}]},{"kind":"group","tone":"tint","blocks":[{"kind":"small","text":{"en":"Free cancellation until 1 March","ar":"إلغاء مجاني حتى 1 مارس"}},{"kind":"image","size":"s","text":{"en":"Ad: rent a car","ar":"إعلان: استأجر سيارة"},"gap":"s"},{"kind":"image","size":"s","text":{"en":"Ad: city tours","ar":"إعلان: جولات في المدينة"},"gap":"s"}]}]}]}},{"id":"move","text":{"en":"Move it into the main column, right under the price","ar":"انقلها إلى العمود الرئيسي، تحت السعر مباشرة"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"frame":"wide","blocks":[{"kind":"row","blocks":[{"kind":"group","tone":"plain","blocks":[{"kind":"title","text":{"en":"Garden Hotel · 2 nights","ar":"فندق الحديقة · ليلتان"}},{"kind":"meta","text":{"en":"EGP 4,200 total","ar":"4,200 جنيه إجمالًا"},"gap":"s"},{"kind":"meta","text":{"en":"Free cancellation until 1 March","ar":"إلغاء مجاني حتى 1 مارس"},"gap":"s"},{"kind":"button","text":{"en":"Book now","ar":"احجز الآن"},"gap":"m"}]},{"kind":"group","tone":"tint","blocks":[{"kind":"image","size":"s","text":{"en":"Ad: rent a car","ar":"إعلان: استأجر سيارة"}},{"kind":"image","size":"s","text":{"en":"Ad: city tours","ar":"إعلان: جولات في المدينة"},"gap":"s"}]}]}]}}],"answer":["move"],"misconceptions":[{"id":"MC-P10-014","when":["top"],"feedback":{"en":"It's still in the side column with the ads, where people expect ads and don't look. Move it next to the price Omar is checking.","ar":"ما زالت في العمود الجانبي مع الإعلانات، حيث يتوقّع الناس إعلانات فلا ينظرون. انقلها بجانب السعر الذي يتحقّق منه عمر."}},{"id":"MC-P10-013","when":["red"],"feedback":{"en":"A red box next to ads looks even more like an ad. Making it louder doesn't help; moving it out of the ad area does.","ar":"الصندوق الأحمر بجانب الإعلانات يشبه الإعلان أكثر. جعلها أعلى صوتًا لا يفيد؛ ما يفيد هو إخراجها من منطقة الإعلانات."}}],"hints":[{"en":"Where is the note now, and what sits around it?","ar":"أين الملاحظة الآن، وما الذي حولها؟"},{"en":"Will a red box or a higher place in the same column stop it looking like an ad?","ar":"هل سيمنع مربع أحمر أو مكان أعلى في العمود نفسه أن تبدو كإعلان؟"}],"correct":{"en":"Next to the price, away from the ads.","ar":"بجانب السعر، بعيدًا عن الإعلانات."},"explain":{"en":"Same idea as the next-session card, on a laptop screen: content in the ad area is taken for an ad. The cancellation rule is part of Omar's decision, so it belongs with the price, in the main column.","ar":"الفكرة نفسها في بطاقة الجلسة التالية، لكن على شاشة Laptop: المحتوى في منطقة الإعلانات يُعامل كإعلان. وشرط الإلغاء جزء من قرار عمر، فمكانه مع السعر في العمود الرئيسي."},"speaker":"sara"},{"id":"S08","type":"card","part":"recap","icons":["eye","warn","layers","ok"],"title":{"en":"What you did","ar":"ماذا تعلّمت"},"body":{"en":"- **Decorative photos:** swapped a generic photo for one that shows the real thing.\n- **Ad-like style:** put an important note in the page's own style, not in a bright strip.\n- **Separate sections:** kept the next session away from the partner offers.\n- **Ad places:** moved a key rule out of the side column, next to the price.\n\nNext: a skill check on a new page.","ar":"- **الصور التزيينية:** استبدلت صورة عامّة بصورة تُظهر الشيء الحقيقي.\n- **شكل الإعلان:** وضعت ملاحظة مهمّة بشكل الصفحة نفسه، لا في شريط لامع.\n- **أقسام منفصلة:** أبعدت الجلسة التالية عن عروض الشركاء.\n- **أماكن الإعلانات:** نقلت شرطًا مهمًّا من العمود الجانبي إلى جانب السعر.\n\nالتالي: اختبار مهارة على صفحة جديدة."}}]}$uxg$::jsonb),
  ($uxg$P10-U01-L04$uxg$, $uxg$9d3d3de46207366bbaa06c57f00f20f124785758f3069721493f0fa0b96d75ae$uxg$, $uxg${"id":"P10-U01-L04","mode":"check","minutes":7,"title":{"en":"Skill check: put the decision first","ar":"اختبار المهارة: ضع القرار أولًا"},"speaker":"nour","steps":[{"id":"S01","type":"card","part":"hook","title":{"en":"Huda's appointment","ar":"موعد هدى"},"body":{"en":"Huda needs a dermatologist for her eczema on Saturday morning, and her insurance is MedCare. She's booking at my clinic from her phone during a break. You're reviewing our booking page before launch.\n\nThis is a skill check: no hints, and you'll see how you did at the end.","ar":"تحتاج هدى إلى طبيبة جلدية لعلاج الإكزيما صباح السبت، وتأمينها الصحي من MedCare. تحجز في عيادتي من هاتفها في وقت الاستراحة. وأنت تراجع صفحة الحجز عندنا قبل إطلاقها.\n\nهذا اختبار مهارة: بدون تلميحات، وسترى نتيجتك في النهاية."},"mock":{"height":380,"blocks":[{"kind":"banner","text":{"en":"Read our skin-care blog","ar":"اقرأ مدوّنتنا عن العناية بالبشرة"}},{"kind":"image","size":"l","text":{"en":"Clinic photo","ar":"صورة العيادة"},"gap":"m"},{"kind":"title","text":{"en":"Dr. Mona Adel, Dermatology","ar":"د. منى عادل، الأمراض الجلدية"},"gap":"m"},{"kind":"meta","text":{"en":"Saturday 21 November, 10:30","ar":"السبت 21 نوفمبر، 10:30"},"gap":"s"},{"kind":"button","text":{"en":"Book this slot","ar":"احجز هذا الموعد"},"gap":"m"},{"kind":"small","text":{"en":"Visit fee: 450 EGP","ar":"رسوم الكشف: 450 جنيهًا"},"gap":"s"},{"kind":"small","text":{"en":"Insurance accepted: MedCare, Allianz","ar":"التأمين المقبول: MedCare وAllianz"},"gap":"s"}]}},{"id":"S02","type":"tune","skill":"SK-P10-U01-01","part":"check","rules":["R19"],"value":{"en":"Skill check, page order (NN/g): reserve the top of the page for high-priority content; the button comes after the facts it depends on.","ar":"اختبار مهارة، ترتيب الصفحة (NN/g): خصّص أعلى الصفحة للمحتوى الأهم؛ ويأتي الزر بعد المعلومات التي يعتمد عليها."},"ref":{"url":"https://www.nngroup.com/articles/scrolling-and-attention/","quote":"Reserve the top of the page for high-priority content"},"prompt":{"en":"Try each order. Which one should ship?","ar":"جرّب كل ترتيب. أيّها يجب أن يُطلق؟"},"mock":{"caption":{"en":"Now","ar":"الآن"},"height":380,"blocks":[{"kind":"banner","text":{"en":"Read our skin-care blog","ar":"اقرأ مدوّنتنا عن العناية بالبشرة"}},{"kind":"image","size":"l","text":{"en":"Clinic photo","ar":"صورة العيادة"},"gap":"m"},{"kind":"title","text":{"en":"Dr. Mona Adel, Dermatology","ar":"د. منى عادل، الأمراض الجلدية"},"gap":"m"},{"kind":"meta","text":{"en":"Saturday 21 November, 10:30","ar":"السبت 21 نوفمبر، 10:30"},"gap":"s"},{"kind":"button","text":{"en":"Book this slot","ar":"احجز هذا الموعد"},"gap":"m"},{"kind":"small","text":{"en":"Visit fee: 450 EGP","ar":"رسوم الكشف: 450 جنيهًا"},"gap":"s"},{"kind":"small","text":{"en":"Insurance accepted: MedCare, Allianz","ar":"التأمين المقبول: MedCare وAllianz"},"gap":"s"}]},"options":[{"id":"button","text":{"en":"Book this slot at the very top, then everything else","ar":"زر «احجز هذا الموعد» في الأعلى تمامًا، ثم كل شيء آخر"},"mock":{"caption":{"en":"After this change","ar":"بعد هذا التغيير"},"height":380,"blocks":[{"kind":"button","text":{"en":"Book this slot","ar":"احجز هذا الموعد"}},{"kind":"banner","text":{"en":"Read our skin-care blog","ar":"اقرأ مدوّنتنا عن العناية بالبشرة"},"gap":"m"},{"kind":"image","size":"l","text":{"en":"Clinic photo","ar":"صورة العيادة"},"gap":"m"},{"kind":"title","text":{"en":"Dr. Mona Adel, Dermatology","ar":"د. منى عادل، الأمراض الجلدية"},"gap":"m"},{"kind":"meta","text":{"en":"Saturday 21 November, 10:30","ar":"السبت 21 نوفمبر، 10:30"},"gap":"s"},{"kind":"small","text":{"en":"Visit fee: 450 EGP","ar":"رسوم الكشف: 450 جنيهًا"},"gap":"s"},{"kind":"small","text":{"en":"Insurance accepted: MedCare, Allianz","ar":"التأمين المقبول: MedCare وAllianz"},"gap":"s"}]}},{"id":"facts","text":{"en":"Doctor, time, insurance and fee first, then Book; the blog and photo after","ar":"الطبيبة 